function openProjectSpace(projectId, space) {
  try {
    const project = readProjects().find((item) => String(item.id) === String(projectId));
    if (!project) return JSON.stringify({ ok: false, message: '未找到学习项目。' });
    const ensured = project.status === 'sealed' ? normalizeProject(project) : ensureProjectWorkspace(project);
    const targets = {
      root: { path: ensured.projectRootPath, label: '项目根目录' },
      workspace: { path: ensured.workspacePath, label: '项目工作空间' },
      raw: { path: ensured.rawPath, label: '项目原始资料库' },
      knowledge: { path: ensured.knowledgeRootPath, label: '项目知识空间' },
    };
    const selected = targets[String(space || '')];
    if (!selected?.path) return JSON.stringify({ ok: false, message: '不支持打开该项目目录。' });
    const target = selected.path;
    if (!fs.existsSync(target) && project.status === 'sealed') return JSON.stringify({ ok: false, message: '封存项目的目录不存在，需先恢复项目后才能补建。' });
    fs.mkdirSync(target, { recursive: true });
    shell.openPath(target).catch(() => {});
    return JSON.stringify({
      ok: true,
      path: target,
      message: `已打开${selected.label}。`,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `打开项目空间失败：${error.message}` });
  }
}

function migrateStudentWorkspace(studentId, newName) {
  try {
    const students = readStudentsIndex();
    const index = students.findIndex((item) => String(item.id) === String(studentId));
    if (index < 0) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const student = students[index];
    const cleanName = sanitizeName(newName || student.name);
    const oldRoot = student.rootPath || getStudentRootDir(student.name);
    const oldRaw = student.rawPath || getRawDir(student.name);
    const oldSummary = student.summaryPath || getSummaryDir(student.name);
    const newRoot = getStudentRootDir(cleanName);
    const newRaw = getRawDir(cleanName);
    const newSummary = getSummaryDir(cleanName);

    if (!fs.existsSync(oldRoot) || !fs.statSync(oldRoot).isDirectory()) {
      return JSON.stringify({ ok: false, message: `原知识库目录不存在，已停止迁移且未创建空目录：${oldRoot}。请使用“目录绑定与路径修复”重新选择真实知识库。` });
    }
    if (!fs.existsSync(oldRaw) || !fs.existsSync(oldSummary)) {
      return JSON.stringify({ ok: false, message: '原知识库缺少原始资料库或学情分析汇总，已停止迁移。请先核对并重新绑定真实目录。' });
    }

    if (path.resolve(oldRoot) !== path.resolve(newRoot)) {
      if (fs.existsSync(newRoot)) return JSON.stringify({ ok: false, message: `目标知识库目录已存在：${newRoot}` });
      fs.mkdirSync(path.dirname(newRoot), { recursive: true });
      fs.renameSync(oldRoot, newRoot);
    }

    const movedOldRaw = path.join(newRoot, path.basename(oldRaw));
    const movedOldSummary = path.join(newRoot, path.basename(oldSummary));
    if (path.resolve(movedOldRaw) !== path.resolve(newRaw) && fs.existsSync(movedOldRaw) && !fs.existsSync(newRaw)) {
      fs.renameSync(movedOldRaw, newRaw);
    }
    if (path.resolve(movedOldSummary) !== path.resolve(newSummary) && fs.existsSync(movedOldSummary) && !fs.existsSync(newSummary)) {
      fs.renameSync(movedOldSummary, newSummary);
    }
    fs.mkdirSync(newRaw, { recursive: true });
    fs.mkdirSync(newSummary, { recursive: true });

    const nextStudent = {
      ...student,
      name: cleanName,
      rootPath: newRoot,
      rawPath: newRaw,
      summaryPath: newSummary,
      agentPath: path.join(newRoot, 'AGENT.md'),
      outputPath: path.join(newRoot, '输出结果'),
    };
    fs.mkdirSync(nextStudent.outputPath, { recursive: true });
    ensureStudentWorkspaceConfig(nextStudent);
    students[index] = nextStudent;
    writeStudentsIndex(students);
    notify('onNativeHostServiceChanged', getHostServiceStatus());
    return JSON.stringify({ ok: true, name: cleanName, rootPathLabel: newRoot, rawPath: newRaw, summaryPath: newSummary, agentPath: nextStudent.agentPath, outputPath: nextStudent.outputPath });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `迁移知识库目录失败：${error.message}` });
  }
}

function remapAdoptedStudentMetadata(student, oldRoots, newRoot) {
  const remap = (value) => remapStorageTreeFromRoots(
    value,
    oldRoots,
    newRoot,
    { platform: process.platform },
  );
  const changedFiles = [];
  const warnings = [];
  const metadataFiles = [
    studentMaterialsPath(student),
    studentRawDiscoveryStatePath(student),
    studentDigestStatePath(student),
    studentDigestManifestPath(student),
    studentDigestBatchPath(student),
    studentDigestReviewReceiptPath(student),
    studentDigestReviewRequestPath(student),
    studentDigestAuditPath(student),
    studentScheduleLedgerPath(student),
    agentSourceRegistryPath(student),
  ];
  for (const filePath of metadataFiles) {
    if (!fs.existsSync(filePath)) continue;
    try {
      const current = safeReadJson(filePath, null);
      if (!current || typeof current !== 'object') continue;
      const result = remap(current);
      if (!result.changed) continue;
      writeJsonAtomic(filePath, result.value);
      changedFiles.push(filePath);
    } catch (error) {
      warnings.push(`${path.basename(filePath)}：${error.message}`);
    }
  }

  try {
    const records = readUploadRecords();
    let changed = 0;
    const next = records.map((record) => {
      if (String(record.studentId || '') !== String(student.id || '')) return record;
      const result = remap(record);
      changed += result.changed;
      return result.value;
    });
    if (changed) {
      writeUploadRecords(next);
      changedFiles.push(uploadRecordsPath());
    }
  } catch (error) {
    warnings.push(`上传记录：${error.message}`);
  }

  try {
    const assets = assetStore().queryDetails({ studentId: String(student.id || '') });
    let changed = 0;
    for (const asset of assets) {
      const result = remap(asset);
      changed += result.changed;
      if (result.changed) assetStore().upsertAsset(result.value, result.value.references, result.value.aliases || []);
    }
    if (changed) {
      changedFiles.push(assetDatabasePath());
    }
  } catch (error) {
    warnings.push(`资料资产索引：${error.message}`);
  }
  return { changedFiles, warnings };
}

function escapeRegexText(value) {
  return String(value || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function updateAdoptedAgentDirectoryStructure(student, oldRoots) {
  const agentPath = student.agentPath || path.join(student.rootPath || '', 'AGENT.md');
  if (!agentPath || !fs.existsSync(agentPath)) {
    return { updated: false, backupPath: '', warning: '新的接管目录中未找到 AGENT.md，未更新目录结构。' };
  }
  try {
    const current = fs.readFileSync(agentPath, 'utf8');
    const paths = studentWorkspacePathmap(student);
    const block = `## 教育管家当前目录结构

本区块由教育管家在迁移或重新定位接管目录后自动维护。Agent 应优先使用以下逻辑路径；物理路径变化时不要继续使用旧盘符。

- \`@KB_ROOT\`：\`${paths['@KB_ROOT']}\`
- \`@AGENT_FILE\`：\`${paths['@AGENT_FILE']}\`
- \`@RAW_DIR\`：\`${paths['@RAW_DIR']}\`
- \`@SUMMARY_DIR\`：\`${paths['@SUMMARY_DIR']}\`
- \`@OUTPUT_DIR\`：\`${paths['@OUTPUT_DIR']}\`
- \`@GROWTH_DIR\`：\`${paths['@GROWTH_DIR']}\`
- \`@ASSET_ROOT\`：\`${paths['@ASSET_ROOT']}\``;
    const next = replaceManagedBlock(current, 'CURRENT-PATHS', block);
    if (next === current) return { updated: false, backupPath: '', warning: '' };
    const backupPath = `${agentPath}.pre-rebind-${timestampForFilename()}.bak`;
    fs.copyFileSync(agentPath, backupPath);
    fs.writeFileSync(agentPath, next, 'utf8');
    return { updated: true, backupPath, warning: '' };
  } catch (error) {
    return { updated: false, backupPath: '', warning: `AGENT.md 目录结构更新失败：${error.message}` };
  }
}

async function rebindAdoptedStudentWorkspace(studentId, selectionMode = 'knowledge') {
  try {
    const students = readStudentsIndex();
    const index = students.findIndex((item) => String(item.id) === String(studentId));
    if (index < 0) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const student = toHostStudent(students[index]);
    let selectedBinding;
    if (selectionMode === 'raw') {
      const rawResult = await dialog.showOpenDialog(mainWindow, {
        title: `为「${student.name}」选择现有原始资料库`,
        defaultPath: fs.existsSync(student.rawPath || '') ? student.rawPath : student.rootPath,
        properties: ['openDirectory'],
      });
      const rawPath = rawResult?.filePaths?.[0] || '';
      if (rawResult?.canceled || !rawPath) return JSON.stringify({ ok: false, cancelled: true, message: '已取消选择原始资料库，未修改任何配置。' });
      const rawValidation = validateExistingBinding({ rootPath: rawPath, rejectEmpty: true });
      if (!rawValidation.ok) return JSON.stringify({ ok: false, message: `原始资料库校验失败：${rawValidation.errors.join(' ')}`, inventory: rawValidation });
      selectedBinding = {
        selectedPath: path.resolve(rawPath),
        rootPath: student.rootPath,
        rawPath: path.resolve(rawPath),
        summaryPath: student.summaryPath,
        selectedRole: 'raw',
        inventory: rawValidation,
      };
    } else {
      const selectedResult = await dialog.showOpenDialog(mainWindow, {
        title: `为「${student.name}」选择现有学生知识库或 wiki/汇总目录`,
        defaultPath: fs.existsSync(student.summaryPath || '') ? student.summaryPath : student.rootPath,
        properties: ['openDirectory'],
      });
      const selected = selectedResult?.filePaths || [];
      if (selectedResult?.canceled || !selected[0]) return JSON.stringify({ ok: false, cancelled: true, message: '已取消选择知识库，未修改任何配置。' });
      selectedBinding = classifyStudentBindingSelection(selected[0], student);
      if (selectedBinding.selectedRole === 'raw') {
        return JSON.stringify({ ok: false, message: '当前操作用于选择学生知识库，所选目录看起来是原始资料库。请使用“手工选择原始资料库”。' });
      }
      selectedBinding.rawPath = student.rawPath;
      selectedBinding.selectedRole = selectedBinding.selectedRole === 'summary' ? 'summary' : 'knowledge';
    }
    const newRoot = selectedBinding.rootPath;
    if (!fs.existsSync(newRoot) || !fs.statSync(newRoot).isDirectory()) {
      return JSON.stringify({ ok: false, message: `未找到新的知识库目录：${newRoot}` });
    }
    const oldRoots = adoptedStorageRootCandidates(student, { platform: process.platform });
    const scanned = JSON.parse(scanExistingKnowledgeBase(newRoot, student.name));
    if (!scanned.ok) return JSON.stringify(scanned);
    const existingRebasedPath = (candidate, detected, fallbackName, allowMissing = true) => {
      for (const oldRoot of oldRoots) {
        const rebased = rebaseStoragePath(candidate, oldRoot, newRoot, { platform: process.platform });
        if (rebased && rebased !== candidate && fs.existsSync(rebased)) return rebased;
      }
      const sameName = candidate ? path.join(newRoot, path.basename(String(candidate))) : '';
      if (sameName && fs.existsSync(sameName)) return sameName;
      if (detected && fs.existsSync(detected)) return detected;
      return allowMissing ? path.join(newRoot, fallbackName) : '';
    };
    const rawPath = selectedBinding.rawPath || existingRebasedPath(student.rawPath, scanned.rawPath, `${student.name}原始资料库`, false);
    const summaryPath = selectedBinding.summaryPath || existingRebasedPath(student.summaryPath, scanned.summaryPath, `${student.name}学情分析汇总`, false);
    if (!fs.existsSync(rawPath) || !fs.statSync(rawPath).isDirectory()) {
      return JSON.stringify({ ok: false, message: '所选目录及其同级目录中未找到现有原始资料库。绑定操作不会自动新建目录；请选择学生知识库上级目录，或先确认原始资料库实际位置。' });
    }
    if (!fs.existsSync(summaryPath) || !fs.statSync(summaryPath).isDirectory()) {
      return JSON.stringify({ ok: false, message: '所选目录中未找到现有学情汇总知识库。绑定操作不会自动新建目录；可直接选择现有 wiki/汇总目录，或选择同时包含原始资料库和汇总目录的上级目录。' });
    }
    const bindingValidation = selectedBinding.inventory || validateExistingBinding({
      rootPath: newRoot,
      requiredPaths: [summaryPath],
      rejectEmpty: true,
    });
    if (!bindingValidation.ok) return JSON.stringify({ ok: false, message: bindingValidation.errors.join(' '), inventory: bindingValidation });
    const confirmation = await dialog.showMessageBox(mainWindow, {
      type: 'warning',
      buttons: ['取消', '确认绑定并修复路径'],
      defaultId: 0,
      cancelId: 0,
      noLink: true,
      title: selectedBinding.selectedRole === 'raw' ? '确认原始资料库绑定' : '确认学生知识库绑定',
      message: `确认修改“${student.name}”的${selectedBinding.selectedRole === 'raw' ? '原始资料库' : '学生知识库'}路径？`,
      detail: `本次选择：${selectedBinding.selectedPath}\n修改项目：${selectedBinding.selectedRole === 'raw' ? '原始资料库' : '学生知识库'}\n知识库根目录：${newRoot}\n原始资料库：${rawPath}\n学生知识库（学情汇总/wiki）：${summaryPath}\n文件：${bindingValidation.fileCount} 个\n容量：${bindingValidation.totalBytes} 字节\n关键文件：${bindingValidation.keyFiles.slice(0, 8).join('、') || '未识别'}\n\n本操作只更新所选路径和受控路径区块，不新建、移动、复制或删除资料目录。`,
    });
    if (confirmation.response !== 1) return JSON.stringify({ ok: false, cancelled: true, message: '已取消目录绑定，未修改任何配置。' });
    const agentPath = existingRebasedPath(student.agentPath, scanned.agentPath, 'AGENT.md');
    const outputPath = existingRebasedPath(student.outputPath, scanned.outputPath, '输出结果');
    const remapRoots = selectedBinding.selectedRole === 'raw' ? [student.rawPath].filter(Boolean) : oldRoots;
    const remapTarget = selectedBinding.selectedRole === 'raw' ? rawPath : newRoot;
    const remappedStudent = remapStorageTreeFromRoots(
      students[index],
      remapRoots,
      remapTarget,
      { platform: process.platform },
    ).value;
    const nextStudent = {
      ...remappedStudent,
      knowledgeBaseMode: 'adopted',
      rootPath: newRoot,
      rootPathLabel: newRoot,
      rawPath,
      summaryPath,
      agentPath,
      outputPath,
      adoptedReboundAt: new Date().toISOString(),
      adoptedPreviousRoots: oldRoots,
      pathBindingHistory: [...(Array.isArray(student.pathBindingHistory) ? student.pathBindingHistory : []), {
        id: `student-rebind-${Date.now()}`,
        at: new Date().toISOString(),
        oldBinding: {
          knowledgeBaseMode: student.knowledgeBaseMode,
          rootPath: student.rootPath,
          rootPathLabel: student.rootPathLabel,
          rawPath: student.rawPath,
          summaryPath: student.summaryPath,
          agentPath: student.agentPath,
          outputPath: student.outputPath,
        },
        oldPath: selectedBinding.selectedRole === 'raw' ? (student.rawPath || '') : (student.rootPath || ''),
        newPath: selectedBinding.selectedRole === 'raw' ? rawPath : newRoot,
        status: 'active',
        inventory: {
          fileCount: bindingValidation.fileCount,
          totalBytes: bindingValidation.totalBytes,
          fingerprint: bindingValidation.fingerprint,
        },
      }].slice(-20),
    };
    ensureStudentWorkspaceConfig(nextStudent);
    const agentUpdate = updateAdoptedAgentDirectoryStructure(nextStudent, oldRoots);
    const metadataRemap = remapAdoptedStudentMetadata(nextStudent, remapRoots, remapTarget);
    if (agentUpdate.warning) metadataRemap.warnings.push(agentUpdate.warning);
    students[index] = nextStudent;
    writeStudentsIndex(students);
    const indexPath = path.join(summaryPath, 'index.md');
    if (fs.existsSync(indexPath) && fs.statSync(indexPath).isFile()) {
      const currentIndex = fs.readFileSync(indexPath, 'utf8');
      const indexBlock = `## 当前主机逻辑目录\n\n- 学生知识库：\`@KB_ROOT\`\n- 原始资料库：\`@RAW_DIR\`\n- 学情分析汇总：\`@SUMMARY_DIR\`\n- 成长模型：\`@GROWTH_DIR\`\n- 输出结果：\`@OUTPUT_DIR\`\n\n真实路径由 \`@KB_ROOT/.ai-manager/pathmap.json\` 维护。`;
      const nextIndex = replaceManagedBlock(currentIndex, 'INDEX-PATHS', indexBlock);
      if (nextIndex !== currentIndex) {
        fs.copyFileSync(indexPath, `${indexPath}.pre-path-repair-${timestampForFilename()}.bak`);
        fs.writeFileSync(indexPath, nextIndex, 'utf8');
      }
    }
    const logPath = path.join(summaryPath, 'log.md');
    if (fs.existsSync(logPath) && fs.statSync(logPath).isFile()) {
      const currentLog = fs.readFileSync(logPath, 'utf8');
      const nextLog = appendPathChangeLog(currentLog, {
        scope: selectedBinding.selectedRole === 'raw' ? '学生原始资料库' : '学生知识库',
        oldPath: selectedBinding.selectedRole === 'raw' ? (student.rawPath || '') : (student.rootPath || ''),
        newPath: selectedBinding.selectedRole === 'raw' ? rawPath : newRoot,
      });
      if (nextLog !== currentLog) {
        fs.copyFileSync(logPath, `${logPath}.pre-path-repair-${timestampForFilename()}.bak`);
        fs.writeFileSync(logPath, nextLog, 'utf8');
      }
    }
    invalidateArchiveAccessCache();
    refreshStudentArchiveSyncWatchers();
    notify('onNativeHostServiceChanged', getHostServiceStatus());
    const agentMessage = agentUpdate.updated
      ? `；AGENT.md 的教育管家受控路径区块已更新，原文件已备份为 ${path.basename(agentUpdate.backupPath)}`
      : '';
    return JSON.stringify({
      ok: true,
      student: toHostStudent(nextStudent),
      rootPathLabel: newRoot,
      rawPath,
      summaryPath,
      agentPath,
      outputPath,
      metadataFilesUpdated: metadataRemap.changedFiles.length,
      inventory: bindingValidation,
      agentPathUpdated: agentUpdate.updated,
      agentBackupPath: agentUpdate.backupPath,
      warnings: metadataRemap.warnings,
      message: metadataRemap.warnings.length
        ? `已完成${selectedBinding.selectedRole === 'raw' ? '原始资料库' : '知识库'}路径绑定：${selectedBinding.selectedRole === 'raw' ? rawPath : newRoot}${agentMessage}；${metadataRemap.warnings.length} 项结构化索引未能自动更新，可稍后重试。`
        : `已完成${selectedBinding.selectedRole === 'raw' ? '原始资料库' : '知识库'}路径绑定：${selectedBinding.selectedRole === 'raw' ? rawPath : newRoot}${agentMessage}`,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `目录绑定与路径修复失败：${error.message}` });
  }
}

function hashDeviceToken(token) {
  return crypto.createHash('sha256').update(String(token || '')).digest('hex');
}

function createDeviceToken() {
  return `edt_${crypto.randomBytes(24).toString('hex')}`;
}

function normalizeTerminalDeviceRole(value, capabilities = []) {
  const requested = String(value || '').trim().toLowerCase();
  if (requested === 'teacher' || requested === 'teacher_terminal') return 'teacher';
  if ((Array.isArray(capabilities) ? capabilities : []).map(String).includes('teacher-terminal-v1')) return 'teacher';
  return 'student';
}

function publicDevice(device) {
  const records = readUploadRecords().filter((record) => String(record.deviceId || '') === String(device.id || ''));
  const lastSeenAt = device.lastSeenAt || '';
  const lastSeenMs = lastSeenAt ? Date.now() - Date.parse(lastSeenAt) : 0;
  return {
    id: device.id,
    name: device.name || (device.platform === 'windows' ? 'Windows 学生终端' : 'Android 学生终端'),
    machineCode: device.machineCode || machineCode('tablet', device.id),
    platform: device.platform || 'android',
    deviceRole: normalizeTerminalDeviceRole(device.deviceRole, device.capabilities),
    tokenPreview: device.tokenPreview || '',
    terminalMode: normalizeTerminalMode(device.terminalMode, 'shared'),
    boundStudentId: String(device.boundStudentId || ''),
    agentCaptureEnabled: Boolean(device.agentCaptureEnabled),
    agentCaptureStudentId: String(device.agentCaptureStudentId || ''),
    agentCaptureAuthorizedAt: String(device.agentCaptureAuthorizedAt || ''),
    activeStudentId: activeStudentIdForDevice(device.id),
    capabilities: Array.isArray(device.capabilities) ? device.capabilities : [],
    allowedStudentIds: Array.isArray(device.allowedStudentIds) ? device.allowedStudentIds : [],
    allowedAllStudents: Boolean(device.allowedAllStudents),
    autoAuthorizeNewStudents: Boolean(device.autoAuthorizeNewStudents),
    authorizationStatus: device.revoked
      ? 'revoked'
      : (device.allowedAllStudents || (Array.isArray(device.allowedStudentIds) && device.allowedStudentIds.length > 0) ? 'approved' : 'pending'),
    revoked: Boolean(device.revoked),
    createdAt: device.createdAt || '',
    lastSeenAt,
    lastSeenAgoMs: Number.isFinite(lastSeenMs) ? lastSeenMs : 0,
    online: Boolean(!device.revoked && Number.isFinite(lastSeenMs) && lastSeenMs >= 0 && lastSeenMs <= 2 * 60 * 1000),
    lastIp: device.lastIp || '',
    lastUserAgent: device.lastUserAgent || '',
    pairedProtocolVersion: Number(device.pairedProtocolVersion || 1),
    uploadCount: records.length,
    lastUploadAt: records[0]?.uploadedAt || '',
  };
}

function createPairCode() {
  return String(crypto.randomInt(100000, 1000000));
}

function getPairSession(forceNew = false) {
  const now = Date.now();
  if (!forceNew && activePairSession && activePairSession.expiresAtMs > now) return activePairSession;
  activePairSession = {
    pairCode: createPairCode(),
    createdAt: new Date(now).toISOString(),
    expiresAtMs: now + 10 * 60 * 1000,
  };
  activePairSession.expiresAt = new Date(activePairSession.expiresAtMs).toISOString();
  return activePairSession;
}

function getPairPayload() {
  const info = getConnectionInfo();
  const session = getPairSession();
  const identity = getHostIdentity();
  return {
    type: 'AI_EDU_MANAGER_PAIR',
    version: APP_VERSION,
    hostId: identity.hostId,
    hostMachineCode: identity.machineCode,
    hostDisplayName: identity.displayName,
    dataGeneration: hostDataGenerationId(),
    serverUrl: info.serverUrl,
    lanUrls: info.lanUrls,
    tailscaleUrl: info.tailscaleUrl,
    tailscaleUrls: info.tailscaleUrls,
    connectionMode: info.connectionMode,
    port: info.port,
    pairCode: session.pairCode,
    expiresAt: session.expiresAt,
  };
}

function discoveryPayload(protocolVersion = PAIR_PROTOCOL_VERSION) {
  const info = getConnectionInfo();
  const identity = getHostIdentity();
  return {
    type: 'AI_EDU_MANAGER_DISCOVERY',
    protocolVersion,
    role: 'host',
    deviceId: identity.hostId,
    machineCode: identity.machineCode,
    displayName: identity.displayName,
    hostName: identity.displayName,
    appVersion: APP_VERSION,
    port: info.port,
    serverUrl: info.serverUrl,
    lanUrls: info.lanUrls,
    tailscaleUrls: info.tailscaleUrls,
    capabilities: protocolVersion >= 2 ? ['pair-request-v2', 'bidirectional-discovery-v2', 'device-pairing-v1'] : [],
  };
}

function latestCompatibilityProjectManifestIds(store, targetNodeId) {
  const selected = new Set();
  const latestByLineage = new Map();
  for (const record of Object.values(normalizeDeliveryStore(store).deliveries)) {
    if (record.status !== 'compatibility_queue' || record.targetNodeId !== targetNodeId || !record.packageRoot) continue;
    const manifest = safeReadJson(path.join(record.packageRoot, 'manifest.json'), null);
    if (!manifest?.manifestId) continue;
    const envelope = (manifest.files || []).find((item) => item.objectType === 'project_publication');
    if (!envelope) {
      selected.add(record.manifestId);
      continue;
    }
    const publicationPath = path.join(record.packageRoot, 'content', envelope.relativePath);
    const publication = safeReadJson(publicationPath, null);
    const lineageId = String(publication?.lineageId || publication?.publicationId || record.manifestId);
    const version = Math.max(1, Number(publication?.version || envelope.version || 1));
    const current = latestByLineage.get(lineageId);
    if (!current || version > current.version || (version === current.version && String(record.updatedAt) > String(current.updatedAt))) {
      latestByLineage.set(lineageId, { manifestId: record.manifestId, version, updatedAt: record.updatedAt });
    }
  }
  for (const item of latestByLineage.values()) selected.add(item.manifestId);
  return selected;
}

function promoteCompatibilityQueueForPeer(peerNodeId, binding) {
  const baseUrls = collaborationDirectTargets(binding, peerNodeId);
  const secret = collaborationDirectSecret(binding);
  if (!baseUrls.length || !secret) return [];
  const current = readDirectDeliveryStore();
  const eligible = latestCompatibilityProjectManifestIds(current, peerNodeId);
  const promoted = promoteCompatibilityDeliveries(current, {
    targetNodeId: peerNodeId,
    bindingId: binding.bindingId,
    baseUrls,
    packageExists: (packageRoot) => {
      const manifest = safeReadJson(path.join(packageRoot, 'manifest.json'), null);
      return Boolean(manifest?.manifestId && eligible.has(manifest.manifestId));
    },
  });
  if (!promoted.promotedManifestIds.length) return [];
  writeDirectDeliveryStore(promoted.store);
  reconcileDirectDeliveryStore();
  appendHostTimeline({
    type: 'collaboration_direct_queue_upgraded',
    title: 'Compatibility packages promoted to direct delivery',
    detail: `${peerNodeId}: ${promoted.promotedManifestIds.length}`,
  });
  setImmediate(() => { void processDirectDeliveryQueue(); });
  notify('onNativeCollaborationChanged', JSON.stringify({
    peerNodeId,
    status: 'direct_queue_upgraded',
    manifestIds: promoted.promotedManifestIds,
  }));
  return promoted.promotedManifestIds;
}

function rememberDiscoveredCollaborationHost(payload, remote) {
  const state = readCollaborationState();
  const peerNodeId = String(payload?.deviceId || '').trim();
  if (payload?.role !== 'host' || !peerNodeId || peerNodeId === state.node.nodeId) return false;
  const port = Number(payload.port || DEFAULT_HOST_PORT);
  const endpoints = routeDirectEndpoints([
    ...(Array.isArray(payload.lanUrls) ? payload.lanUrls : []),
    ...(Array.isArray(payload.tailscaleUrls) ? payload.tailscaleUrls : []),
    remote?.address && port ? `http://${remote.address}:${port}` : '',
  ].filter(Boolean));
  if (!endpoints.length) return false;
  const now = new Date().toISOString();
  discoveredCollaborationHosts.set(peerNodeId, {
    nodeId: peerNodeId,
    machineCode: String(payload.machineCode || ''),
    displayName: String(payload.displayName || payload.hostName || '协作主机'),
    endpoints,
    lastSeenAt: now,
  });
  let changed = false;
  let upgradedBinding = null;
  const bindings = state.bindings.map((binding) => {
    if (
      binding.status !== 'active'
      || binding.revokedAt
      || !binding.participantNodeIds?.includes(state.node.nodeId)
      || !binding.participantNodeIds?.includes(peerNodeId)
    ) return binding;
    const merged = mergeBindingDirectOffer(binding, peerNodeId, {
      transportId: LAN_DIRECT_TRANSPORT_ID,
      protocolVersion: DIRECT_PROTOCOL_VERSION,
      endpoints,
      preferred: true,
      lastSeenAt: now,
    });
    if (merged.changed) changed = true;
    upgradedBinding = merged.binding;
    return merged.binding;
  });
  if (changed) writeCollaborationState({ ...state, bindings });
  if (upgradedBinding) promoteCompatibilityQueueForPeer(peerNodeId, upgradedBinding);
  return Boolean(upgradedBinding);
}

function rememberDiscoveredTablet(payload, remote) {
  if (payload?.role !== 'tablet' || !payload.deviceId) return false;
  const identityKey = `tablet:${payload.deviceId}`;
  const existing = discoveredLanTablets.get(identityKey);
  const next = {
    role: 'tablet',
    deviceId: String(payload.deviceId),
    machineCode: String(payload.machineCode || machineCode('tablet', payload.deviceId)),
    displayName: String(payload.displayName || payload.deviceName || 'Android 平板').slice(0, 80),
    platform: String(payload.platform || 'android').toLowerCase() === 'windows' ? 'windows' : 'android',
    appVersion: String(payload.appVersion || ''),
    capabilities: Array.isArray(payload.capabilities) ? payload.capabilities : [],
    address: String(remote.address || ''),
    discoveryPort: Number(payload.discoveryPort || remote.port || HOST_DISCOVERY_PORT),
    lastSeenAt: new Date().toISOString(),
  };
  discoveredLanTablets.set(identityKey, { ...existing, ...next });
  return true;
}

function sendHostDiscoveryResponse(socket, remote, protocolVersion = PAIR_PROTOCOL_VERSION) {
  const payload = Buffer.from(JSON.stringify(discoveryPayload(protocolVersion)), 'utf8');
  socket.send(payload, remote.port, remote.address, () => {});
}

function handleHostDiscoveryMessage(socket, message, remote) {
  const text = String(message || '').trim();
  if (text === HOST_DISCOVERY_REQUEST_V1) {
    sendHostDiscoveryResponse(socket, remote, 1);
    return;
  }
  let payload;
  try { payload = JSON.parse(text); } catch { return; }
  if (payload.type === HOST_DISCOVERY_REQUEST_V2 && Number(payload.protocolVersion || 0) >= 2) {
    if (['host', 'all'].includes(String(payload.searchRole || 'host'))) {
      sendHostDiscoveryResponse(socket, remote, PAIR_PROTOCOL_VERSION);
    }
    return;
  }
  if (payload.type === 'AI_EDU_MANAGER_DISCOVERY' && Number(payload.protocolVersion || 0) >= 2) {
    if (rememberDiscoveredCollaborationHost(payload, remote)) {
      notify('onNativeCollaborationChanged', JSON.stringify({ peerNodeId: payload.deviceId, status: 'direct_peer_discovered' }));
    }
    if (rememberDiscoveredTablet(payload, remote)) notify('onNativeHostServiceChanged', getHostServiceStatus());
  }
}

function requestCollaborationPeerDiscovery(force = false) {
  if (!hostDiscoverySocket) return false;
  const now = Date.now();
  if (!force && now - lastCollaborationDiscoveryAt < 30_000) return false;
  lastCollaborationDiscoveryAt = now;
  const request = Buffer.from(JSON.stringify({
    type: HOST_DISCOVERY_REQUEST_V2,
    protocolVersion: PAIR_PROTOCOL_VERSION,
    requestId: `collaboration-discover-${crypto.randomUUID()}`,
    searchRole: 'host',
  }), 'utf8');
  for (const target of lanDiscoveryBroadcastTargets()) {
    hostDiscoverySocket.send(request, HOST_DISCOVERY_PORT, target, () => {});
  }
  return true;
}

function startHostDiscovery() {
  if (hostDiscoverySocket) return;
  const socket = dgram.createSocket({ type: 'udp4', reuseAddr: true });
  hostDiscoverySocket = socket;
  socket.on('message', (message, remote) => {
    handleHostDiscoveryMessage(socket, message, remote);
  });
  socket.on('error', (error) => {
    hostServiceLastError = `局域网发现服务异常：${error.message}`;
    try { socket.close(); } catch {}
    if (hostDiscoverySocket === socket) hostDiscoverySocket = null;
    notify('onNativeHostServiceChanged', getHostServiceStatus());
  });
  socket.bind(HOST_DISCOVERY_PORT, '0.0.0.0', () => {
    try { socket.setBroadcast(true); } catch {}
    setTimeout(() => requestCollaborationPeerDiscovery(true), 250);
  });
}

function findLanTablets() {
  if (!hostDiscoverySocket) return JSON.stringify({ ok: false, message: '请先启动主机服务，再查找局域网学生终端。' });
  discoveredLanTablets.clear();
  lastTabletDiscoveryAt = new Date().toISOString();
  const requestId = `discover-${crypto.randomUUID()}`;
  const request = Buffer.from(JSON.stringify({
    type: HOST_DISCOVERY_REQUEST_V2,
    protocolVersion: PAIR_PROTOCOL_VERSION,
    requestId,
    searchRole: 'tablet',
  }), 'utf8');
  try {
    const targets = lanDiscoveryBroadcastTargets();
    for (const target of targets) {
      hostDiscoverySocket.send(request, HOST_DISCOVERY_PORT, target, (error) => {
        if (error) {
          hostServiceLastError = `向 ${target} 发送平板发现广播失败：${error.message}`;
          notify('onNativeHostServiceChanged', getHostServiceStatus());
        }
      });
    }
    appendHostTimeline({ type: 'tablet_discovery_started', title: 'Tablet discovery started', detail: `${requestId} -> ${targets.join(', ')}` });
    return JSON.stringify({ ok: true, requestId, broadcastTargets: targets, message: `已通过 ${targets.length} 个广播地址查找 Android/Windows 学生终端，请让终端停留在连接主机页面。`, status: JSON.parse(getHostServiceStatus()) });
  } catch (error) {
    hostServiceLastError = `发送局域网学生终端发现广播失败：${error.message}`;
    return JSON.stringify({ ok: false, message: hostServiceLastError, status: JSON.parse(getHostServiceStatus()) });
  }
}

function stopHostDiscovery() {
  const socket = hostDiscoverySocket;
  hostDiscoverySocket = null;
  if (!socket) return;
  try { socket.close(); } catch {}
}

function deviceByBearerToken(token) {
  const tokenHash = hashDeviceToken(token);
  return readDevices().find((device) => device.tokenHash === tokenHash && !device.revoked);
}

const STUDENT_SESSION_IDLE_MS = 10 * 60 * 1000;

function cleanupStudentSessions() {
  const now = Date.now();
  for (const [tokenHash, session] of studentSessions.entries()) {
    if (now - Number(session.lastSeenAtMs || session.createdAtMs || 0) > STUDENT_SESSION_IDLE_MS) studentSessions.delete(tokenHash);
  }
}

function studentSessionByBearerToken(token, touch = true) {
  cleanupStudentSessions();
  const tokenHash = hashDeviceToken(token);
  const session = studentSessions.get(tokenHash);
  if (!session) return null;
  const device = readDevices().find((item) => String(item.id) === String(session.deviceId) && !item.revoked);
  const student = readStudentsIndex().find((item) => String(item.id) === String(session.studentId));
  if (!device || !student) {
    studentSessions.delete(tokenHash);
    return null;
  }
  if (touch) session.lastSeenAtMs = Date.now();
  return { ...session, tokenHash, device, student };
}

function clearStudentSessionsForDevice(deviceId) {
  for (const [tokenHash, session] of studentSessions.entries()) {
    if (String(session.deviceId) === String(deviceId)) studentSessions.delete(tokenHash);
  }
}

function activeStudentIdForDevice(deviceId) {
  cleanupStudentSessions();
  const active = [...studentSessions.values()].find((session) => String(session.deviceId) === String(deviceId));
  return active ? String(active.studentId) : '';
}

function createStudentSession(device, student) {
  clearStudentSessionsForDevice(device.id);
  const token = `eds_${crypto.randomBytes(24).toString('hex')}`;
  const tokenHash = hashDeviceToken(token);
  const now = Date.now();
  const session = {
    sessionId: `student-session-${crypto.randomUUID()}`,
    deviceId: String(device.id),
    studentId: String(student.id),
    terminalMode: normalizeTerminalMode(device.terminalMode, 'shared'),
    createdAt: new Date(now).toISOString(),
    createdAtMs: now,
    lastSeenAtMs: now,
  };
  studentSessions.set(tokenHash, session);
  return { token, session };
}

function publicStudentSession(session) {
  return {
    sessionId: session.sessionId,
    deviceId: session.deviceId,
    studentId: session.studentId,
    terminalMode: session.terminalMode,
    createdAt: session.createdAt,
    idleTimeoutSeconds: Math.floor(STUDENT_SESSION_IDLE_MS / 1000),
  };
}

function requestClientIp(request) {
  const forwarded = String(request?.headers?.['x-forwarded-for'] || '').split(',')[0].trim();
  const remote = String(request?.socket?.remoteAddress || '').replace(/^::ffff:/, '');
  return forwarded || remote;
}

function requestUserAgent(request) {
  return String(request?.headers?.['user-agent'] || '').slice(0, 160);
}

function touchDevice(deviceId, request) {
  const devices = readDevices();
  const index = devices.findIndex((device) => device.id === deviceId);
  if (index < 0) return;
  const lastIp = requestClientIp(request);
  const lastUserAgent = requestUserAgent(request);
  devices[index] = {
    ...devices[index],
    lastSeenAt: new Date().toISOString(),
    lastIp: lastIp || devices[index].lastIp || '',
    lastUserAgent: lastUserAgent || devices[index].lastUserAgent || '',
  };
  writeDevices(devices);
}

function getHostDevices() {
  return JSON.stringify({ ok: true, devices: readDevices().map(publicDevice) });
}

function revokeHostDevice(deviceId) {
  const devices = readDevices();
  const index = devices.findIndex((device) => String(device.id) === String(deviceId));
  if (index < 0) return JSON.stringify({ ok: false, message: '未找到设备。' });
  devices[index] = { ...devices[index], revoked: true, revokedAt: new Date().toISOString() };
  clearStudentSessionsForDevice(deviceId);
  writeDevices(devices);
  notify('onNativeHostServiceChanged', getHostServiceStatus());
  return JSON.stringify({ ok: true, message: '设备已撤销。', devices: devices.map(publicDevice), status: JSON.parse(getHostServiceStatus()) });
}

function restoreHostDevice(deviceId) {
  const devices = readDevices();
  const index = devices.findIndex((device) => String(device.id) === String(deviceId));
  if (index < 0) return JSON.stringify({ ok: false, message: '未找到设备。' });
  if (!devices[index].revoked) return JSON.stringify({ ok: false, message: '设备当前未撤销。' });
  const license = publicLicenseStatus();
  const activeCount = devices.filter((device) => !device.revoked).length;
  if (license.deviceLimit && activeCount >= Number(license.deviceLimit)) {
    return JSON.stringify({ ok: false, message: `授权设备数已达上限（${license.deviceLimit} 台），请先撤销其他设备。` });
  }
  devices[index] = {
    ...devices[index],
    revoked: false,
    revokedAt: '',
    restoredAt: new Date().toISOString(),
  };
  writeDevices(devices);
  appendHostTimeline({ type: 'device_restored', title: 'Device restored', detail: devices[index].name || devices[index].id });
  notify('onNativeHostServiceChanged', getHostServiceStatus());
  return JSON.stringify({ ok: true, message: '设备已恢复。', devices: devices.map(publicDevice), status: JSON.parse(getHostServiceStatus()) });
}

function deleteHostDevice(deviceId) {
  const devices = readDevices();
  const target = devices.find((device) => String(device.id) === String(deviceId));
  if (!target) return JSON.stringify({ ok: false, message: '未找到设备。' });
  if (!target.revoked) return JSON.stringify({ ok: false, message: '请先撤销设备，再删除设备记录。' });
  const nextDevices = devices.filter((device) => String(device.id) !== String(deviceId));
  clearStudentSessionsForDevice(deviceId);
  writeDevices(nextDevices);
  appendHostTimeline({ type: 'device_deleted', title: 'Revoked device record deleted', detail: target.name || target.id });
  notify('onNativeHostServiceChanged', getHostServiceStatus());
  return JSON.stringify({ ok: true, message: '已删除撤销设备记录。', devices: nextDevices.map(publicDevice), status: JSON.parse(getHostServiceStatus()) });
}

function renameHostDevice(deviceId, name) {
  const cleanName = String(name || '').trim().slice(0, 40);
  if (!cleanName) return JSON.stringify({ ok: false, message: '设备名称不能为空。' });
  const devices = readDevices();
  const index = devices.findIndex((device) => String(device.id) === String(deviceId));
  if (index < 0) return JSON.stringify({ ok: false, message: '未找到设备。' });
  devices[index] = { ...devices[index], name: cleanName };
  writeDevices(devices);
  notify('onNativeHostServiceChanged', getHostServiceStatus());
  return JSON.stringify({ ok: true, message: '设备已重命名。', devices: devices.map(publicDevice), status: JSON.parse(getHostServiceStatus()) });
}

function setHostDeviceStudentAccess(deviceId, studentIdsJson) {
  let studentIds = [];
  try {
    const parsed = JSON.parse(studentIdsJson || '[]');
    studentIds = Array.isArray(parsed) ? parsed.map(String) : [];
  } catch {
    return JSON.stringify({ ok: false, message: '学生授权范围格式错误。' });
  }
  const validIds = new Set(readStudentsIndex().map((student) => String(student.id)));
  const allowedStudentIds = studentIds.filter((id) => validIds.has(String(id)));
  const devices = readDevices();
  const index = devices.findIndex((device) => String(device.id) === String(deviceId));
  if (index < 0) return JSON.stringify({ ok: false, message: '未找到设备。' });
  const terminalMode = allowedStudentIds.length === 1 ? 'personal' : 'shared';
  devices[index] = {
    ...devices[index],
    terminalMode,
    boundStudentId: terminalMode === 'personal' ? allowedStudentIds[0] : '',
    allowedStudentIds: terminalMode === 'personal' ? allowedStudentIds : [],
    allowedAllStudents: terminalMode === 'shared',
    autoAuthorizeNewStudents: terminalMode === 'shared',
  };
  writeDevices(devices);
  notify('onNativeHostServiceChanged', getHostServiceStatus());
  return JSON.stringify({ ok: true, devices: devices.map(publicDevice), status: JSON.parse(getHostServiceStatus()) });
}

function setHostDeviceAccessMode(deviceId, optionsJson) {
  let options = {};
  try {
    options = JSON.parse(optionsJson || '{}');
  } catch {
    return JSON.stringify({ ok: false, message: '设备授权选项格式错误。' });
  }
  const devices = readDevices();
  const index = devices.findIndex((device) => String(device.id) === String(deviceId));
  if (index < 0) return JSON.stringify({ ok: false, message: '未找到设备。' });
  const validIds = readStudentsIndex().map((student) => String(student.id));
  const requestedMode = options.terminalMode || (options.allowedAllStudents || options.autoAuthorizeNewStudents ? 'shared' : 'personal');
  const terminalMode = normalizeTerminalMode(requestedMode, 'shared');
  const requestedBoundStudentId = String(options.boundStudentId || devices[index].boundStudentId || '');
  const boundStudentId = terminalMode === 'personal' && validIds.includes(requestedBoundStudentId) ? requestedBoundStudentId : '';
  devices[index] = {
    ...devices[index],
    terminalMode,
    boundStudentId,
    allowedAllStudents: terminalMode === 'shared',
    autoAuthorizeNewStudents: terminalMode === 'shared',
    allowedStudentIds: boundStudentId ? [boundStudentId] : [],
    modeUpdatedAt: new Date().toISOString(),
  };
  clearStudentSessionsForDevice(deviceId);
  writeDevices(devices);
  notify('onNativeHostServiceChanged', getHostServiceStatus());
  return JSON.stringify({ ok: true, devices: devices.map(publicDevice), status: JSON.parse(getHostServiceStatus()) });
}

function setHostDeviceTerminalMode(deviceId, terminalMode, boundStudentId = '') {
  return setHostDeviceAccessMode(deviceId, JSON.stringify({ terminalMode, boundStudentId }));
}

function getHostServicePort() {
  const settings = readSettings();
  const port = Number(settings.hostServicePort || DEFAULT_HOST_PORT);
  return Number.isInteger(port) && port >= 1024 && port <= 65535 ? port : DEFAULT_HOST_PORT;
}

function setHostServicePort(port) {
  const locked = licenseRequiredJson('主机服务');
  if (locked) return locked;
  const nextPort = Number(port);
  if (!Number.isInteger(nextPort) || nextPort < 1024 || nextPort > 65535) {
    return JSON.stringify({ ok: false, message: '端口必须是 1024-65535 之间的数字' });
  }
  const settings = readSettings();
  settings.hostServicePort = nextPort;
  writeSettings(settings);
  if (hostServer) {
    const server = hostServer;
    hostServer = null;
    server.close(() => {
      startHostService();
    });
    return JSON.stringify({ ok: true, status: JSON.parse(getHostServiceStatus()), message: '端口已保存，主机服务正在重启。' });
  }
  return JSON.stringify({ ok: true, status: JSON.parse(getHostServiceStatus()) });
}

function sanitizeName(value) {
  return String(value || '学生').trim().replace(/[\\/:*?"<>|]/g, '').slice(0, 24) || '学生';
}

function notify(callbackName, payload) {
  if (['onNativeTaskCenterChanged', 'onNativeDigestWorkflowChanged'].includes(callbackName) && taskStoreGuard.pending()) {
    void taskStoreGuard.flush().then(() => notify(callbackName, payload)).catch(error => console.warn('Task change not published:', error.message));
    return;
  }
  if (!mainWindow || mainWindow.isDestroyed()) return;
  mainWindow.webContents.executeJavaScript(
    `window.${callbackName} && window.${callbackName}(${JSON.stringify(payload)})`,
  ).catch(() => {});
}

function courseViewBounds() {
  if (!mainWindow || mainWindow.isDestroyed()) return { x: 286, y: 150, width: 900, height: 620 };
  const [width, height] = mainWindow.getContentSize();
  const top = courseCaptureSetupVisible ? (courseFullscreen ? 164 : 232) : (courseFullscreen ? 88 : 150);
  const left = courseFullscreen ? 12 : courseSidebarCollapsed ? 24 : 286;
  const right = courseFullscreen ? 12 : 24;
  return {
    x: Math.min(left, Math.max(0, width - 360)),
    y: top,
    width: Math.max(360, width - left - right),
    height: Math.max(260, height - top - (courseFullscreen ? 12 : 24)),
  };
}

function setCourseViewLayout(layoutJson) {
  try {
    const layout = typeof layoutJson === 'string' ? JSON.parse(layoutJson) : (layoutJson || {});
    courseSidebarCollapsed = Boolean(layout.sidebarCollapsed);
    courseFullscreen = Boolean(activeCourse && layout.fullscreen);
    if (mainWindow && !mainWindow.isDestroyed() && mainWindow.isFullScreen() !== courseFullscreen) {
      mainWindow.setFullScreen(courseFullscreen);
    }
    if (courseView) courseView.setBounds(courseViewBounds());
    return JSON.stringify({ ok: true, sidebarCollapsed: courseSidebarCollapsed, fullscreen: courseFullscreen });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `课程布局调整失败：${error.message}` });
  }
}

function exitCourseFullscreen(reason = 'user') {
  if (!courseFullscreen) return JSON.stringify({ ok: true, fullscreen: false });
  courseFullscreen = false;
  courseSidebarCollapsed = false;
  if (mainWindow && !mainWindow.isDestroyed() && mainWindow.isFullScreen()) mainWindow.setFullScreen(false);
  if (courseView) courseView.setBounds(courseViewBounds());
  notify('onNativeCourseBrowserChanged', {
    open: Boolean(activeCourse),
    courseId: activeCourse?.courseId || '',
    name: activeCourse?.name || '',
    fullscreen: false,
    sidebarCollapsed: false,
    reason,
  });
  return JSON.stringify({ ok: true, fullscreen: false, sidebarCollapsed: false });
}

function handleCourseFullscreenEscape(event, input) {
  if (courseFullscreen && input?.type === 'keyDown' && input?.key === 'Escape') {
    event.preventDefault();
    exitCourseFullscreen('escape');
  }
}

function setCourseCaptureSetupVisible(visible) {
  courseCaptureSetupVisible = Boolean(activeCourse && visible && !activeCaptureRuntime);
  if (courseView) courseView.setBounds(courseViewBounds());
  return JSON.stringify({ ok: true, visible: courseCaptureSetupVisible });
}

function closeCourseView(reason = 'user') {
  if (courseView && mainWindow && !mainWindow.isDestroyed()) {
    try { mainWindow.contentView.removeChildView(courseView); } catch {}
    try { courseView.webContents.close(); } catch {}
  }
  courseView = null;
  const closed = activeCourse;
  activeCourse = null;
  courseCaptureSetupVisible = false;
  courseSidebarCollapsed = false;
  if (courseFullscreen && mainWindow && !mainWindow.isDestroyed()) mainWindow.setFullScreen(false);
  courseFullscreen = false;
  notify('onNativeCourseBrowserChanged', { open: false, reason, courseId: closed?.courseId || '' });
  return JSON.stringify({ ok: true, open: false });
}

function courseAllowedByCurrentPlan(course) {
  return course?.type !== 'tenant_custom' || canImportCustomCourses(publicLicenseStatus());
}

function openCourseView(courseId) {
  try {
    const course = courseCatalogStore().findCourse(courseId);
    if (!course) return JSON.stringify({ ok: false, message: '课程不存在、未生效或已紧急下架。' });
    if (!courseAllowedByCurrentPlan(course)) {
      return JSON.stringify({ ok: false, message: '机构自选课程仅向已激活的专业版和机构版开放。' });
    }
    closeCourseView('switch');
    const partition = coursePartition(course.courseId);
    const courseSession = session.fromPartition(partition, { cache: true });
    courseView = new WebContentsView({ webPreferences: secureCourseWebPreferences(partition) });
    installCourseGuards(courseView.webContents, course, courseSession, (blocked) => {
      notify('onNativeCourseBrowserChanged', { open: true, blocked: true, courseId: course.courseId, ...blocked });
    });
    mainWindow.contentView.addChildView(courseView);
    courseCaptureSetupVisible = !activeCaptureRuntime;
    courseView.setBounds(courseViewBounds());
    courseView.setBackgroundColor('#ffffff');
    activeCourse = course;
    courseView.webContents.on('render-process-gone', () => closeCourseView('render_process_gone'));
    courseView.webContents.on('before-input-event', handleCourseFullscreenEscape);
    void courseView.webContents.loadURL(course.url);
    notify('onNativeCourseBrowserChanged', { open: true, courseId: course.courseId, name: course.name, url: course.url });
    return JSON.stringify({ ok: true, open: true, course });
  } catch (error) {
    closeCourseView('error');
    return JSON.stringify({ ok: false, message: `无法安全打开课程：${error.message}` });
  }
}

function getCourseCatalogState() {
  const state = courseCatalogStore().state();
  const license = publicLicenseStatus();
  const managementAllowed = canImportCustomCourses(license);
  const canEditPlatform = hasCapability(license, 'platform_course_edit');
  const canPublishPlatform = hasCapability(license, 'platform_course_publish');
  const canRollbackPlatform = hasCapability(license, 'platform_course_rollback');
  const platformDrafts = canEditPlatform
    ? platformCourseDraftStore().list().map((draft) => {
      const draftAsset = platformCourseDraftStore().assetPath(draft.course?.coverAsset);
      const publishedAsset = courseCatalogStore().assetPath(draft.course?.coverAsset);
      return {
        ...draft,
        course: {
          ...draft.course,
          coverUrl: draftAsset || publishedAsset ? pathToFileURL(draftAsset || publishedAsset).toString() : draft.course?.coverAsset,
        },
      };
    })
    : [];
  const platformDeletions = canEditPlatform ? platformCourseDraftStore().listDeletions() : [];
  return JSON.stringify({
    ...state,
    management: {
      allowed: managementAllowed,
      plan: String(license.plan || ''),
      planLabel: String(license.planLabel || ''),
      message: managementAllowed
        ? '当前专业版、机构版或平台版授权可以使用课程管理。'
        : '课程管理仅向已激活的专业版、机构版和平台版开放。',
    },
    platformAuthoring: {
      canEdit: canEditPlatform,
      canPublish: canPublishPlatform,
      canRollback: canRollbackPlatform,
      signingConfigured: true,
      message: canEditPlatform ? '当前平台版授权可以编辑并发布平台精选课程，无需另行配置发布凭据。' : '平台课程编辑与发布仅向有效的平台版授权开放。',
    },
    platformDrafts,
    platformDeletions,
    customImport: {
      allowed: managementAllowed,
      plan: String(license.plan || ''),
      planLabel: String(license.planLabel || ''),
      message: managementAllowed
        ? '当前专业版或机构版授权可以导入自选课程 Excel。'
        : '自选课程 Excel 导入仅向已激活的专业版和机构版开放。',
    },
    catalog: state.catalog ? {
      ...state.catalog,
      courses: state.catalog.courses.map((course) => {
        const customAssetPath = courseCatalogStore().assetPath(course.coverAsset);
        return {
          ...course,
          coverUrl: customAssetPath ? pathToFileURL(customAssetPath).toString() : course.coverAsset,
        };
      }),
    } : null,
  });
}

function courseManagementRequiredJson(code = 'COURSE_MANAGEMENT_PLAN_REQUIRED') {
  const license = publicLicenseStatus();
  if (canImportCustomCourses(license)) return null;
  return JSON.stringify({
    ok: false,
    code,
    license,
    message: '课程管理仅向已激活的专业版、机构版和平台版开放。',
  });
}

function platformCourseCapabilityRequiredJson(capability, code) {
  const license = publicLicenseStatus();
  if (hasCapability(license, capability)) return null;
  return JSON.stringify({
    ok: false,
    code,
    license,
    message: '当前 License 不是有效的平台版授权。',
  });
}

function saveCourseInstitutionPolicy(policyJson) {
  const locked = courseManagementRequiredJson();
  if (locked) return locked;
  try {
    const policy = courseCatalogStore().savePolicy(JSON.parse(policyJson || '{}'));
    notify('onNativeCourseCatalogChanged', { action: 'policy_updated', policyVersion: policy.policyVersion });
    return JSON.stringify({ ok: true, policy, state: JSON.parse(getCourseCatalogState()) });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `保存课程设置失败：${error.message}` });
  }
}

function importOfflineCourseCatalog() {
  const locked = courseManagementRequiredJson();
  if (locked) return locked;
  const selected = dialog.showOpenDialogSync(mainWindow, {
    title: '导入离线平台课程包',
    properties: ['openFile'],
    filters: [
      { name: '平台课程包', extensions: ['edu-coursepkg'] },
      { name: '兼容课程目录 JSON', extensions: ['json'] },
    ],
  });
  if (!selected?.[0]) return JSON.stringify({ ok: false, cancelled: true, message: '已取消导入。' });
  const result = selected[0].toLowerCase().endsWith('.edu-coursepkg')
    ? courseCatalogStore().importCoursePackage(selected[0])
    : courseCatalogStore().importFile(selected[0]);
  if (result.ok && activeCourse && !courseCatalogStore().findCourse(activeCourse.courseId)) closeCourseView('catalog_withdrawal');
  notify('onNativeCourseCatalogChanged', { action: 'offline_import', ok: result.ok, catalogVersion: result.catalog?.catalogVersion || '' });
  return JSON.stringify(result);
}

let platformLocalPublishPending;
function platformPublishItems(){return [...platformCourseDraftStore().list().map(d=>({id:d.courseId,title:d.course.name,kind:'draft',draft:d})),...platformCourseDraftStore().listDeletions().map(d=>({id:d.courseId,title:d.courseId,kind:'deletion',deletion:d}))];}
async function publishPlatformCoursesLocally(input={}) {
  if(platformLocalPublishPending)throw Error('平台课程正在发布，请等待当前发布完成');
  const locked=platformCourseCapabilityRequiredJson('platform_course_publish','PLATFORM_COURSE_PUBLISH_REQUIRED');
  if(locked)throw Error(JSON.parse(locked).message);
  platformLocalPublishPending=(async()=>{
    const people=readStudentsIndex().map(toHostStudent),id=String(input.studentId||'');
    if(!people.some(s=>String(s.id)===id))throw Error('请选择当前学生');
    const audience=require('./publication-policy.cjs').normalizeAudience(input.audience,people,id);
    const requestId=String(input.requestId||'');if(!/^[A-Za-z0-9_-]{8,100}$/.test(requestId))throw Error('发布事务编号无效');
    const directory=path.join(app.getPath('userData'),'platform-course-authoring','local-published');
    const result=await require('./publication-batch.cjs').runPublicationBatch({directory,requestId,audience,studentId:id,items:platformPublishItems(),expectedHash:input.expectedBatchHash,
      checkCurrent:item=>{
        const current=platformPublishItems().find(v=>v.id===item.id&&v.kind===item.kind);
        if(current&&JSON.stringify(current)!==JSON.stringify(item))throw Error('草稿内容已变化，请重新开始发布');
        if(item.kind==='draft'&&!item.draft.validation?.ok)throw Error('草稿未通过校验，请修正后重新发布');
        if(!current){const installed=courseCatalogStore().state().platformCatalog?.courses.find(c=>c.courseId===item.id),hash=require('./course-publications.cjs').courseContentHash;
          if(item.kind==='draft'?(!installed||hash(installed)!==hash({...item.draft.course,coverAsset:`platform-assets/${path.basename(item.draft.course.coverAsset)}`})):!!installed)throw Error('原草稿已移除或内容已变化，请重新开始发布');}
      },
      execute:async(item,itemRequest)=>{
        const lockedNow=platformCourseCapabilityRequiredJson('platform_course_publish','PLATFORM_COURSE_PUBLISH_REQUIRED');if(lockedNow)throw Error(JSON.parse(lockedNow).message);
        const store=courseCatalogStore(),drafts=item.kind==='draft'?[item.draft]:[],deletedCourseIds=item.kind==='deletion'?[item.id]:[];
        store.publications.registerDrafts(drafts.map(d=>d.course));
        const baseCatalog=store.state().platformCatalog||{catalogVersion:'',courses:[]};
        const baseHash=crypto.createHash('sha256').update(JSON.stringify(baseCatalog)).digest('hex').slice(0,16);
        const outputPath=path.join(directory,`${itemRequest}-${baseHash}.edu-coursepkg`),assets={};
        for(const course of [...(store.state().platformCatalog?.courses||[]),...drafts.map(d=>d.course)])assets[course.coverAsset]=platformCourseDraftStore().assetPath(course.coverAsset)||store.assetPath(course.coverAsset);
        const built=await require('./course-publish-worker.cjs').runCoursePublishWorker({options:{drafts,deletedCourseIds,baseCatalog,issuedAt:new Date().toISOString(),hostVersion:APP_VERSION,minHostVersion:APP_VERSION,outputPath,releaseNotes:input.releaseNotes||''},assets,storeOptions:{userDataDir:app.getPath('userData'),appVersion:APP_VERSION,resourceRoots:[path.join(__dirname,'..','dist'),path.join(__dirname,'..','public')]}});
        if(store.state().platformCatalog?.catalogVersion!==built.catalogVersion)throw Error('课程目录已变化，请刷新核对');
        if(item.kind==='draft'){
          const source=store.combinedCatalog()?.courses.find(c=>c.courseId===item.id);if(!source)throw Error('发布后的课程缺失');
          store.publications.publish(source,{audience,requestId:itemRequest},readStudentsIndex().map(toHostStudent),id);
          const current=platformCourseDraftStore().list().find(d=>d.courseId===item.id);if(current?.draftRevision===item.draft.draftRevision)platformCourseDraftStore().remove(item.id);
        }else platformCourseDraftStore().cancelDeletion(item.id);
      }});
    notify('onNativeCourseCatalogChanged',{action:'local_published'});
    return {...result,message:result.complete?'课程已发布给所选学生。':'部分课程未完成，请查看逐项结果并重试失败项。'};
  })().finally(()=>{platformLocalPublishPending=null;});return platformLocalPublishPending;
}
function publishPlatformCourseCatalog(releaseNotes = '') {
  const locked = platformCourseCapabilityRequiredJson('platform_course_publish', 'PLATFORM_COURSE_PUBLISH_REQUIRED');
  if (locked) return locked;
  const drafts = platformCourseDraftStore().list();
  const deletions = platformCourseDraftStore().listDeletions();
  if (!drafts.length && !deletions.length) return JSON.stringify({ ok: false, code: 'PLATFORM_COURSE_CHANGES_EMPTY', message: '当前没有可发布的平台课程新增、修改或删除。' });
  const invalid = drafts.filter((draft) => draft.validation?.ok !== true);
  if (invalid.length) return JSON.stringify({ ok: false, code: 'PLATFORM_COURSE_DRAFTS_INVALID', message: `仍有 ${invalid.length} 门草稿未通过版权或字段校验，不能发布。` });
  try {
    const store = courseCatalogStore();
    const preview = changeSummary(drafts, store.state().platformCatalog || { catalogVersion: '', courses: [] }, deletions.map((item) => item.courseId));
    const issuedAt = new Date().toISOString();
    const suggested = `AI教育管家-平台课程-${issuedAt.slice(0, 10)}.edu-coursepkg`;
    let outputPath = dialog.showSaveDialogSync(mainWindow, {
      title: '生成并保存平台课程包',
      defaultPath: path.join(app.getPath('downloads') || os.tmpdir(), suggested),
      filters: [{ name: 'AI教育管家平台课程包', extensions: ['edu-coursepkg'] }],
    });
    if (!outputPath) return JSON.stringify({ ok: false, cancelled: true, message: '已取消平台课程发布。' });
    if (!outputPath.toLowerCase().endsWith('.edu-coursepkg')) outputPath += '.edu-coursepkg';
    const built = createCoursePackage({
      drafts,
      deletedCourseIds: deletions.map((item) => item.courseId),
      baseCatalog: store.state().platformCatalog || { catalogVersion: '', courses: [] },
      issuedAt,
      hostVersion: APP_VERSION,
      minHostVersion: APP_VERSION,
      outputPath,
      releaseNotes,
      resolveAssetPath: (assetName) => platformCourseDraftStore().assetPath(assetName) || store.assetPath(assetName),
    });
    const imported = store.importCoursePackage(outputPath);
    if (!imported.ok) throw new Error(`课程包已生成但本机完整性回验安装失败：${imported.message || '未知错误'}`);
    const license = publicLicenseStatus();
    for (const draft of drafts) platformCourseDraftStore().remove(draft.courseId, { updatedBy: license.licenseId || '' });
    for (const deletion of deletions) platformCourseDraftStore().cancelDeletion(deletion.courseId, { updatedBy: license.licenseId || '' });
    if (activeCourse && !store.findCourse(activeCourse.courseId)) closeCourseView('catalog_withdrawal');
    notify('onNativeCourseCatalogChanged', { action: 'platform_catalog_published', ok: true, catalogVersion: built.catalog.catalogVersion });
    appendHostTimeline({ type: 'platform_course_catalog_published', title: 'Platform course catalog published', detail: built.catalog.catalogVersion, catalogVersion: built.catalog.catalogVersion, packageSha256: built.sha256, licenseId: license.licenseId || '', edition: 'PLATFORM', releaseNotes: String(releaseNotes || '').slice(0, 500), changeDigest: preview.digest });
    return JSON.stringify({
      ok: true,
      outputPath,
      catalogVersion: built.catalog.catalogVersion,
      sha256: built.sha256,
      bytes: built.bytes,
      state: JSON.parse(getCourseCatalogState()),
      message: `平台课程目录 ${built.catalog.catalogVersion} 已完成版本、文件哈希和完整性回验并应用到本机；课程包已保存。`,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, code: 'PLATFORM_COURSE_PUBLISH_FAILED', message: `平台课程发布失败：${error.message}` });
  }
}

function reExportPlatformCourseCatalog() {
  const locked = platformCourseCapabilityRequiredJson('platform_course_publish', 'PLATFORM_COURSE_PUBLISH_REQUIRED');
  if (locked) return locked;
  try {
    const store = courseCatalogStore();
    const currentPackage = store.state().currentPlatformPackage;
    if (!currentPackage?.canReExport) {
      return JSON.stringify({ ok: false, code: 'PLATFORM_COURSE_PACKAGE_NOT_ARCHIVED', message: '当前已发布版本没有可重新导出的原始课程包；请先发布或导入一次平台课程包。' });
    }
    const suggested = `AI教育管家-平台课程-${currentPackage.catalogVersion}.edu-coursepkg`;
    let outputPath = dialog.showSaveDialogSync(mainWindow, {
      title: '重新导出当前平台课程包',
      defaultPath: path.join(app.getPath('downloads') || os.tmpdir(), suggested),
      filters: [{ name: 'AI教育管家平台课程包', extensions: ['edu-coursepkg'] }],
    });
    if (!outputPath) return JSON.stringify({ ok: false, cancelled: true, message: '已取消重新导出。' });
    if (!outputPath.toLowerCase().endsWith('.edu-coursepkg')) outputPath += '.edu-coursepkg';
    const exported = store.exportCurrentCoursePackage(outputPath);
    const license = publicLicenseStatus();
    appendHostTimeline({ type: 'platform_course_package_reexported', title: 'Platform course package re-exported', detail: exported.catalogVersion, catalogVersion: exported.catalogVersion, packageSha256: exported.sha256, licenseId: license.licenseId || '', edition: 'PLATFORM' });
    return JSON.stringify({
      ok: true,
      ...exported,
      state: JSON.parse(getCourseCatalogState()),
      message: `平台课程包 ${exported.catalogVersion} 已按原版本和原 SHA-256 重新导出到 ${exported.outputPath}。`,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, code: 'PLATFORM_COURSE_PACKAGE_REEXPORT_FAILED', message: `重新导出平台课程包失败：${error.message}` });
  }
}

function rollbackPlatformCourseCatalog() {
  const locked = platformCourseCapabilityRequiredJson('platform_course_rollback', 'PLATFORM_COURSE_ROLLBACK_REQUIRED');
  if (locked) return locked;
  const selected = dialog.showOpenDialogSync(mainWindow, {
    title: '选择要恢复的平台课程包',
    properties: ['openFile'],
    filters: [{ name: 'AI教育管家平台课程包', extensions: ['edu-coursepkg'] }],
  });
  if (!selected?.[0]) return JSON.stringify({ ok: false, cancelled: true, message: '已取消课程目录回滚。' });
  const answer = dialog.showMessageBoxSync(mainWindow, {
    type: 'warning',
    buttons: ['取消', '确认显式回滚'],
    defaultId: 0,
    cancelId: 0,
    noLink: true,
    title: '确认课程目录回滚',
    message: '回滚会立即替换本机当前平台课程目录，并可能关闭正在打开的已撤回课程。',
    detail: `课程包：${path.basename(selected[0])}\n机构自选课程、学生分配和历史审计不会删除。`,
  });
  if (answer !== 1) return JSON.stringify({ ok: false, cancelled: true, message: '未确认回滚，当前目录保持不变。' });
  const previousVersion = courseCatalogStore().state().platformCatalog?.catalogVersion || '';
  const result = courseCatalogStore().importCoursePackage(selected[0], { allowRollback: true });
  if (result.ok && activeCourse && !courseCatalogStore().findCourse(activeCourse.courseId)) closeCourseView('catalog_rollback');
  notify('onNativeCourseCatalogChanged', { action: 'platform_catalog_rollback', ok: result.ok, catalogVersion: result.catalog?.catalogVersion || '' });
  if (result.ok) {
    const license = publicLicenseStatus();
    appendHostTimeline({ type: 'platform_course_catalog_rollback', title: 'Platform course catalog rollback', detail: `${previousVersion} -> ${result.catalog?.catalogVersion || ''}`, previousVersion, catalogVersion: result.catalog?.catalogVersion || '', packageSha256: crypto.createHash('sha256').update(fs.readFileSync(selected[0])).digest('hex'), licenseId: license.licenseId || '', edition: 'PLATFORM' });
  }
  return JSON.stringify({
    ...result,
    state: result.ok ? JSON.parse(getCourseCatalogState()) : undefined,
    message: result.ok ? `已显式恢复平台课程目录 ${result.catalog?.catalogVersion || ''}。` : result.message,
  });
}

