function prunePendingCustomCourseImages(now = Date.now()) {
  for (const [token, entry] of pendingCustomCourseImages.entries()) {
    if (!entry || now - Number(entry.createdAt || 0) > 30 * 60 * 1000) {
      pendingCustomCourseImages.delete(token);
    }
  }
}

