function agentLifecycleQueueDir() {
  return path.join(activeAgentKnowledgeAccessDir(), 'lifecycle-queue');
}

function purgeQueuedAgentLifecycleSession(studentId, sessionIds) {
  const targets = new Set((sessionIds || []).map(String).filter(Boolean));
  const directory = agentLifecycleQueueDir();
  if (!targets.size || !fs.existsSync(directory)) return 0;
  let removed = 0;
  for (const entry of fs.readdirSync(directory, { withFileTypes: true })) {
    if (!entry.isFile() || !entry.name.endsWith('.json')) continue;
    const filePath = path.join(directory, entry.name);
    try {
      if (fs.statSync(filePath).size > 1024 * 1024) continue;
      const event = normalizeLifecycleEnvelope(JSON.parse(fs.readFileSync(filePath, 'utf8')));
      if (!event || String(event.scopeId) !== String(studentId) || !targets.has(String(event.sessionId))) continue;
      fs.unlinkSync(filePath);
      removed += 1;
    } catch {
      // A malformed or locked queue entry remains for the bounded drain/recovery path.
    }
  }
  return removed;
}

function quoteHookCommandArgument(value) {
  return `"${String(value || '').replace(/"/g, '\\"')}"`;
}

function managedLifecycleHookCommand(sourceAgent, descriptorPath = activeAgentKnowledgeDescriptorPath()) {
  return buildManagedLifecycleHookCommand(
    sourceAgent,
    activeAgentLifecycleHookPath(),
    descriptorPath,
    sourceAgent === 'codex' ? activeAgentLifecycleHookExecutablePath() : '',
  );
}

function upsertLifecycleCommandHooks(configPath, sourceAgent) {
  let config = {};
  if (fs.existsSync(configPath)) {
    config = parseJsoncObject(fs.readFileSync(configPath, 'utf8'));
    if (!config || typeof config !== 'object' || Array.isArray(config)) throw new Error('Hook 配置不是有效对象。');
  }
  config.hooks = config.hooks && typeof config.hooks === 'object' && !Array.isArray(config.hooks) ? config.hooks : {};
  const command = managedLifecycleHookCommand(sourceAgent);
  const eventNames = lifecycleAdapter(sourceAgent)?.hookEvents
    || ['SessionStart', 'UserPromptSubmit', 'Stop', 'SessionEnd'];
  for (const eventName of eventNames) {
    const groups = Array.isArray(config.hooks[eventName]) ? config.hooks[eventName] : [];
    const cleaned = groups.map((group) => ({
      ...group,
      hooks: (Array.isArray(group?.hooks) ? group.hooks : []).filter((hook) => !String(hook?.command || '').includes('EDU-MANAGER-LIFECYCLE')),
    })).filter((group) => group.hooks.length);
    const handler = { type: 'command', command, timeout: 3 };
    if (sourceAgent === 'claude-code' && !['SessionEnd', 'Interrupt'].includes(eventName)) handler.async = true;
    config.hooks[eventName] = [...cleaned, { hooks: [handler] }];
  }
  writeJsonAtomic(configPath, config);
  const verified = safeReadJson(configPath, {});
  return ['SessionStart', 'UserPromptSubmit', 'Stop', 'SessionEnd'].every((eventName) => (
    (verified?.hooks?.[eventName] || []).some((group) => (
      (group?.hooks || []).some((hook) => String(hook?.command || '').includes('EDU-MANAGER-LIFECYCLE'))
    ))
  ));
}

function setLifecycleCommandHooksEnabled(configPath, enabled) {
  if (enabled || !fs.existsSync(configPath)) return;
  const config = parseJsoncObject(fs.readFileSync(configPath, 'utf8'));
  if (!config?.hooks || typeof config.hooks !== 'object') return;
  for (const eventName of Object.keys(config.hooks)) {
    if (!Array.isArray(config.hooks[eventName])) continue;
    config.hooks[eventName] = config.hooks[eventName].map((group) => ({
      ...group,
      hooks: (Array.isArray(group?.hooks) ? group.hooks : []).filter((hook) => !String(hook?.command || '').includes('EDU-MANAGER-LIFECYCLE')),
    })).filter((group) => group.hooks.length);
    if (!config.hooks[eventName].length) delete config.hooks[eventName];
  }
  writeJsonAtomic(configPath, config);
}

function openClawLifecyclePluginSource(sourceAgent) {
  return `import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const descriptorPath = ${JSON.stringify(activeAgentKnowledgeDescriptorPath())};
const sourceAgent = ${JSON.stringify(sourceAgent)};

function enqueue(hookEventName, event, context) {
  try {
    const descriptor = JSON.parse(fs.readFileSync(descriptorPath, "utf8"));
    const capture = descriptor.lifecycleCapture || {};
    if (capture.enabled !== true || !capture.captureEpoch || !Array.isArray(capture.allowedAgents) || !capture.allowedAgents.includes(sourceAgent)) return;
    const queueDir = String(capture.queueDir || "");
    if (!queueDir) return;
    fs.mkdirSync(queueDir, { recursive: true });
    const capturedAt = new Date().toISOString();
    const envelope = {
      schema: "edu-manager.agent-lifecycle-event.v1",
      sourceAgent,
      scopeId: String(descriptor.defaults?.scopeId || ""),
      grantId: String(descriptor.authentication?.grantId || ""),
      captureEpoch: String(capture.captureEpoch),
      capturedAt,
      payload: { hook_event_name: hookEventName, event, context },
    };
    const stamp = capturedAt.replace(/\\D/g, "");
    const target = path.join(queueDir, stamp + "-" + crypto.randomUUID() + ".json");
    const temp = target + ".tmp";
    fs.writeFileSync(temp, JSON.stringify(envelope), "utf8");
    fs.renameSync(temp, target);
  } catch { /* Conversation flow must not be affected by capture. */ }
}

export default {
  id: "edu-manager-lifecycle",
  name: "Education Manager Lifecycle Capture",
  register(api) {
    const hookNames = sourceAgent === "qclaw"
      ? ["session_start", "message_received", "llm_output", "session_end"]
      : ["session_start", "message_received", "message_sent", "session_end"];
    for (const hookName of hookNames) {
      api.on(hookName, async (event, context) => enqueue(hookName, event, context), { timeoutMs: 1000 });
    }
  },
};
`;
}

function installOpenClawLifecyclePlugin(configPath, sourceAgent) {
  const stateDir = path.dirname(configPath);
  const pluginDir = path.join(stateDir, 'plugins', 'edu-manager-lifecycle');
  fs.mkdirSync(pluginDir, { recursive: true });
  fs.writeFileSync(path.join(pluginDir, 'index.ts'), openClawLifecyclePluginSource(sourceAgent), 'utf8');
  writeJsonAtomic(path.join(pluginDir, 'openclaw.plugin.json'), {
    id: 'edu-manager-lifecycle',
    name: 'Education Manager Lifecycle Capture',
    version: '1.0.0',
    description: 'Captures only newly emitted, student-authorized conversation lifecycle events.',
    main: 'index.ts',
    configSchema: { type: 'object', additionalProperties: false, properties: {} },
  });
  let config = fs.existsSync(configPath) ? parseJsoncObject(fs.readFileSync(configPath, 'utf8')) : {};
  config.plugins = config.plugins && typeof config.plugins === 'object' && !Array.isArray(config.plugins) ? config.plugins : {};
  config.plugins.load = config.plugins.load && typeof config.plugins.load === 'object' && !Array.isArray(config.plugins.load) ? config.plugins.load : {};
  config.plugins.load.paths = mergeUnique([...(Array.isArray(config.plugins.load.paths) ? config.plugins.load.paths : []), pluginDir]);
  config.plugins.entries = config.plugins.entries && typeof config.plugins.entries === 'object' && !Array.isArray(config.plugins.entries) ? config.plugins.entries : {};
  config.plugins.entries['edu-manager-lifecycle'] = {
    ...(config.plugins.entries['edu-manager-lifecycle'] || {}),
    enabled: true,
    hooks: {
      ...(config.plugins.entries['edu-manager-lifecycle']?.hooks || {}),
      allowConversationAccess: true,
    },
  };
  if (Array.isArray(config.plugins.allow)) config.plugins.allow = mergeUnique([...config.plugins.allow, 'edu-manager-lifecycle']);
  writeJsonAtomic(configPath, config);
  const verified = safeReadJson(configPath, {});
  return Boolean(
    verified?.plugins?.entries?.['edu-manager-lifecycle']?.enabled
    && verified?.plugins?.entries?.['edu-manager-lifecycle']?.hooks?.allowConversationAccess === true
    && (verified?.plugins?.load?.paths || []).includes(pluginDir),
  );
}

function setOpenClawLifecyclePluginEnabled(configPath, enabled) {
  if (!fs.existsSync(configPath)) return;
  const config = parseJsoncObject(fs.readFileSync(configPath, 'utf8'));
  if (!config?.plugins?.entries?.['edu-manager-lifecycle']) return;
  config.plugins.entries['edu-manager-lifecycle'].enabled = Boolean(enabled);
  writeJsonAtomic(configPath, config);
}

function hermesHomeDir() {
  const candidates = [
    process.env.HERMES_HOME,
    path.join(os.homedir(), '.hermes'),
    process.env.LOCALAPPDATA ? path.join(process.env.LOCALAPPDATA, 'hermes') : '',
    path.join(os.homedir(), 'AppData', 'Local', 'hermes'),
  ].filter(Boolean);
  const configured = candidates.find((candidate) => fs.existsSync(path.join(candidate, 'config.yaml')));
  return configured || candidates.find((candidate) => fs.existsSync(candidate)) || candidates[0];
}

function hermesLifecyclePluginDir() {
  return path.join(hermesHomeDir(), 'plugins', 'edu-manager-lifecycle');
}

function hermesLifecyclePluginSource() {
  return `"""Education Manager lifecycle capture for authorized, newly emitted Hermes turns."""
import json
import uuid
from datetime import datetime, timezone
from pathlib import Path

DESCRIPTOR_PATH = Path(${JSON.stringify(activeAgentKnowledgeDescriptorPath())})
SOURCE_AGENT = "hermes"


def _enqueue(hook_event_name, **kwargs):
    try:
        if not DESCRIPTOR_PATH.exists():
            return None
        descriptor = json.loads(DESCRIPTOR_PATH.read_text(encoding="utf-8-sig"))
        capture = descriptor.get("lifecycleCapture") or {}
        if capture.get("enabled") is not True or SOURCE_AGENT not in (capture.get("allowedAgents") or []):
            return None
        session_id = str(kwargs.get("session_id") or "").strip()
        queue_dir = Path(str(capture.get("queueDir") or ""))
        if not session_id or not str(queue_dir):
            return None
        payload = {
            "hook_event_name": hook_event_name,
            "session_id": session_id,
            "model": str(kwargs.get("model") or "")[:240],
            "platform": str(kwargs.get("platform") or "")[:120],
        }
        if hook_event_name == "pre_llm_call":
            payload["user_message"] = str(kwargs.get("user_message") or "")[:20000]
            payload["is_first_turn"] = bool(kwargs.get("is_first_turn"))
        elif hook_event_name == "post_llm_call":
            payload["assistant_response"] = str(kwargs.get("assistant_response") or "")[:20000]
        elif hook_event_name == "on_session_finalize":
            payload["completed"] = True
        captured_at = datetime.now(timezone.utc).isoformat()
        envelope = {
            "schema": "edu-manager.agent-lifecycle-event.v1",
            "sourceAgent": SOURCE_AGENT,
            "scopeId": str((descriptor.get("defaults") or {}).get("scopeId") or ""),
            "grantId": str((descriptor.get("authentication") or {}).get("grantId") or ""),
            "capturedAt": captured_at,
            "payload": payload,
        }
        queue_dir.mkdir(parents=True, exist_ok=True)
        target = queue_dir / (datetime.now(timezone.utc).strftime("%Y%m%d%H%M%S%f") + "-" + uuid.uuid4().hex + ".json")
        temporary = Path(str(target) + ".tmp")
        temporary.write_text(json.dumps(envelope, ensure_ascii=False, separators=(",", ":")), encoding="utf-8")
        temporary.replace(target)
    except Exception:
        return None
    return None


def _on_session_start(session_id=None, model=None, platform=None, **kwargs):
    return _enqueue("on_session_start", session_id=session_id, model=model, platform=platform, **kwargs)


def _pre_llm_call(session_id=None, user_message=None, conversation_history=None, is_first_turn=False, model=None, platform=None, **kwargs):
    return _enqueue("pre_llm_call", session_id=session_id, user_message=user_message, is_first_turn=is_first_turn, model=model, platform=platform, **kwargs)


def _post_llm_call(session_id=None, user_message=None, assistant_response=None, conversation_history=None, is_first_turn=False, model=None, platform=None, **kwargs):
    return _enqueue("post_llm_call", session_id=session_id, assistant_response=assistant_response, model=model, platform=platform, **kwargs)


def _on_session_finalize(session_id=None, platform=None, **kwargs):
    return _enqueue("on_session_finalize", session_id=session_id, platform=platform, **kwargs)


def register(ctx):
    ctx.register_hook("on_session_start", _on_session_start)
    ctx.register_hook("pre_llm_call", _pre_llm_call)
    ctx.register_hook("post_llm_call", _post_llm_call)
    ctx.register_hook("on_session_finalize", _on_session_finalize)
`;
}

function runHermesPluginCommand(action) {
  const executable = findAgentToolInstall('hermes').exePath;
  if (!executable || !fs.existsSync(executable)) return { ok: false, message: '未找到 Hermes CLI。' };
  const result = spawnSync(executable, ['plugins', action, 'edu-manager-lifecycle'], {
    encoding: 'utf8',
    timeout: 15_000,
    windowsHide: true,
    shell: process.platform === 'win32' && /\.(cmd|bat)$/i.test(executable),
  });
  return {
    ok: result.status === 0,
    message: String(result.stderr || result.stdout || '').trim().slice(0, 1000),
  };
}

function installHermesLifecyclePlugin() {
  if (!findAgentToolInstall('hermes').installed) return false;
  const pluginDir = hermesLifecyclePluginDir();
  fs.mkdirSync(pluginDir, { recursive: true });
  fs.writeFileSync(path.join(pluginDir, 'plugin.yaml'), [
    'name: edu-manager-lifecycle',
    'version: 1.0.0',
    'description: Captures only newly emitted student-authorized conversation turns.',
    'provides_hooks:',
    '  - on_session_start',
    '  - pre_llm_call',
    '  - post_llm_call',
    '  - on_session_finalize',
    '',
  ].join('\n'), 'utf8');
  fs.writeFileSync(path.join(pluginDir, '__init__.py'), hermesLifecyclePluginSource(), 'utf8');
  const enabled = runHermesPluginCommand('enable');
  if (!enabled.ok) throw new Error(enabled.message || 'Hermes 插件启用失败。');
  return fs.existsSync(path.join(pluginDir, 'plugin.yaml')) && fs.existsSync(path.join(pluginDir, '__init__.py'));
}

function setHermesLifecyclePluginEnabled(enabled) {
  if (!fs.existsSync(hermesLifecyclePluginDir())) return;
  runHermesPluginCommand(enabled ? 'enable' : 'disable');
}

function replaceManagedTextBlock(filePath, markerStart, markerEnd, block, initialHeading = '') {
  let current = '';
  try { current = fs.existsSync(filePath) ? fs.readFileSync(filePath, 'utf8') : initialHeading; } catch { current = initialHeading; }
  const withoutManaged = current.replace(new RegExp(`${markerStart}[\\s\\S]*?${markerEnd}\\s*`, 'g'), '').trimEnd();
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, `${withoutManaged}${withoutManaged ? '\n\n' : ''}${block.trim()}\n`, 'utf8');
  return filePath;
}

function agentKnowledgeServerName(student, generic = false) {
  if (generic) return 'edu-manager-knowledge';
  const suffix = crypto.createHash('sha1')
    .update(String(student.id || student.name || 'student'))
    .digest('hex')
    .slice(0, 10);
  return `edu-manager-knowledge-${suffix}`;
}

function parseJsoncObject(value) {
  const source = String(value || '');
  let output = '';
  let inString = false;
  let escaped = false;
  let lineComment = false;
  let blockComment = false;
  for (let index = 0; index < source.length; index += 1) {
    const current = source[index];
    const next = source[index + 1];
    if (lineComment) {
      if (current === '\n') {
        lineComment = false;
        output += current;
      }
      continue;
    }
    if (blockComment) {
      if (current === '*' && next === '/') {
        blockComment = false;
        index += 1;
      }
      continue;
    }
    if (!inString && current === '/' && next === '/') {
      lineComment = true;
      index += 1;
      continue;
    }
    if (!inString && current === '/' && next === '*') {
      blockComment = true;
      index += 1;
      continue;
    }
    output += current;
    if (inString) {
      if (escaped) escaped = false;
      else if (current === '\\') escaped = true;
      else if (current === '"') inString = false;
    } else if (current === '"') {
      inString = true;
    }
  }
  // mcporter accepts trailing commas. Removing them after comments are
  // stripped keeps existing user configuration compatible with JSON.parse.
  return JSON.parse(output.replace(/,\s*([}\]])/g, '$1'));
}

function upsertMcporterServer(configPath, serverName, server, options = {}) {
  let config = { mcpServers: {} };
  if (fs.existsSync(configPath)) {
    config = parseJsoncObject(fs.readFileSync(configPath, 'utf8'));
    if (!config || typeof config !== 'object' || Array.isArray(config)) config = { mcpServers: {} };
  }
  config.mcpServers = config.mcpServers && typeof config.mcpServers === 'object'
    ? config.mcpServers
    : {};
  if (options.replaceEducationManagerServers) {
    for (const key of Object.keys(config.mcpServers)) {
      if (key === 'edu-manager-knowledge' || key.startsWith('edu-manager-knowledge-')) {
        delete config.mcpServers[key];
      }
    }
  }
  config.mcpServers[serverName] = server;
  writeJsonAtomic(configPath, config);
  const verified = safeReadJson(configPath, {});
  return Boolean(verified?.mcpServers?.[serverName]);
}

function upsertOpenClawMcpServer(configPath, serverName, server, options = {}) {
  let config = {};
  if (fs.existsSync(configPath)) {
    config = parseJsoncObject(fs.readFileSync(configPath, 'utf8'));
    if (!config || typeof config !== 'object' || Array.isArray(config)) throw new Error('OpenClaw 配置不是有效对象。');
  }
  config.mcp = config.mcp && typeof config.mcp === 'object' && !Array.isArray(config.mcp) ? config.mcp : {};
  config.mcp.servers = config.mcp.servers && typeof config.mcp.servers === 'object' && !Array.isArray(config.mcp.servers)
    ? config.mcp.servers
    : {};
  if (options.replaceEducationManagerServers) {
    for (const key of Object.keys(config.mcp.servers)) {
      if (key === 'edu-manager-knowledge' || key.startsWith('edu-manager-knowledge-')) delete config.mcp.servers[key];
    }
  }
  config.mcp.servers[serverName] = {
    command: server.command,
    args: server.args,
    enabled: true,
  };
  writeJsonAtomic(configPath, config);
  const verified = safeReadJson(configPath, {});
  return Boolean(verified?.mcp?.servers?.[serverName]);
}

function installCodexMcpServer(configPath, serverName, command, args, options = {}) {
  if (serverName === 'edu-manager-knowledge' && fs.existsSync(configPath)) {
    const current = fs.readFileSync(configPath, 'utf8');
    let migrated = current.replace(
      /# EDU-MANAGER-KNOWLEDGE-MCP:START[\s\S]*?# EDU-MANAGER-KNOWLEDGE-MCP:END\s*/g,
      '',
    );
    if (options.replaceEducationManagerServers) {
      migrated = migrated.replace(
        /# EDU-MANAGER-KNOWLEDGE-MCP:edu-manager-knowledge-[^:\r\n]+:START[\s\S]*?# EDU-MANAGER-KNOWLEDGE-MCP:edu-manager-knowledge-[^:\r\n]+:END\s*/g,
        '',
      );
    }
    if (migrated !== current) fs.writeFileSync(configPath, migrated.trimEnd() ? `${migrated.trimEnd()}\n` : '', 'utf8');
  }
  const markerStart = `# EDU-MANAGER-KNOWLEDGE-MCP:${serverName}:START`;
  const markerEnd = `# EDU-MANAGER-KNOWLEDGE-MCP:${serverName}:END`;
  const tomlArgs = args.map((item) => JSON.stringify(String(item))).join(', ');
  const block = `${markerStart}
[mcp_servers.${serverName}]
command = ${JSON.stringify(command)}
args = [${tomlArgs}]
startup_timeout_sec = 10
tool_timeout_sec = 30
enabled = true
${markerEnd}`;
  replaceManagedTextBlock(configPath, markerStart, markerEnd, block);
  return fs.readFileSync(configPath, 'utf8').includes(`[mcp_servers.${serverName}]`);
}

function agentKnowledgeWorkspaceRule(student) {
  return `<!-- EDU-MANAGER-KNOWLEDGE-TOOL:START -->
## 教育管家知识工具

回答“${student.name}”的学生档案、学情、成长或关联学习项目问题时，调用教育管家 MCP 工具 \`query_education_knowledge\`。可以直接传入用户的完整自然语言问题；工具会先查询本机学生档案及其关联项目知识，依据不足时自动使用局域网或 Tailscale 查询当前协作范围。QClaw 0.2.34 及以上会从自身 MCP 注册表直接加载该工具，不要只检查 mcporter 的默认服务器。回答必须保留返回的 \`edu://\` 来源；没有依据时明确说明，不要编造。

当用户在教育管家开启“自动会话记忆”后，教育管家会通过 Agent 生命周期 Hook 自动采集授权后的会话事件；已打开的 Codex 会话仅从授权后下一条用户提问开始。无需且不得由模型主动调用会话采集工具。不得读取启用前历史、其他会话、系统提示、缓存、工具密钥或未获授权内容；不要把教育管家任务中心的任务执行上下文当作会话采集来源。

仅当用户明确要求“保存当前对话”“发送到教育管家”或同等意思时，调用 \`submit_education_conversation\`。只提交当前对话或用户明确选择的消息和附件，不读取或发送其他会话、私有历史、缓存、系统提示或密钥。用户明确指定学习项目时，必须把项目名称传入 \`targetProject\`；如果工具报告项目未唯一匹配，不得退回学生档案。
<!-- EDU-MANAGER-KNOWLEDGE-TOOL:END -->`;
}

function installAgentKnowledgeMcpRegistrations(student, options = {}) {
  const activateGlobal = options.activateGlobal !== false;
  const root = student.rootPath || getStudentRootDir(student.name);
  const descriptorPath = agentKnowledgeDescriptorPath(student);
  const bridgePath = agentKnowledgeMcpBridgePath(student);
  const activeDescriptorPath = activeAgentKnowledgeDescriptorPath();
  const activeBridgePath = activeAgentKnowledgeMcpBridgePath();
  const activeLifecycleHookPath = activeAgentLifecycleHookPath();
  fs.writeFileSync(
    bridgePath,
    fs.readFileSync(path.join(__dirname, 'agent-knowledge-mcp.ps1'), 'utf8'),
    'utf8',
  );
  fs.mkdirSync(path.dirname(activeBridgePath), { recursive: true });
  fs.writeFileSync(
    activeBridgePath,
    fs.readFileSync(path.join(__dirname, 'agent-knowledge-mcp.ps1'), 'utf8'),
    'utf8',
  );
  fs.writeFileSync(
    activeLifecycleHookPath,
    fs.readFileSync(path.join(__dirname, 'agent-lifecycle-hook.ps1'), 'utf8'),
    'utf8',
  );
  const activeLifecycleExecutablePath = activeAgentLifecycleHookExecutablePath();
  if (!fs.existsSync(activeLifecycleExecutablePath)) {
    fs.copyFileSync(path.join(__dirname, 'agent-lifecycle-hook.exe'), activeLifecycleExecutablePath);
  }

  const command = 'powershell.exe';
  const args = ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', bridgePath, '-Descriptor', descriptorPath];
  const activeArgs = ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', activeBridgePath, '-Descriptor', activeDescriptorPath];
  const toolNames = ['query_education_knowledge', 'submit_education_conversation', 'list_education_archive', 'get_education_task_status', 'execute_education_write', 'get_education_write_status', 'get_recent_education_context', 'start_education_session', 'record_authorized_education_turn', 'finalize_education_session', 'accept_education_handoff', 'cancel_education_handoff'];
  const projectServer = {
    description: `${student.name}的教育管家知识查询与当前授权 Agent 会话采集`,
    type: 'stdio',
    command,
    args,
    allowedTools: toolNames,
  };
  const activeServer = {
    description: '教育管家当前学生的知识查询与当前授权 Agent 会话采集',
    type: 'stdio',
    command,
    args: activeArgs,
    allowedTools: toolNames,
  };
  const qclawConfigPaths = new Set([path.join(root, 'config', 'mcporter.json')]);
  const qclawRuntime = discoverQClawRuntime(findAgentToolInstall('qclaw').exePath || '');
  const qclawAgentId = selectQClawAgentId(qclawRuntime, {
    sourceName: student.name,
    input: { knowledgeRoot: root },
  });
  const qclawAgent = (qclawRuntime.agents || []).find((agent) => agent.id === qclawAgentId);
  if (qclawAgent?.workspace) qclawConfigPaths.add(path.join(qclawAgent.workspace, 'config', 'mcporter.json'));
  const qclawGlobalConfigPath = path.join(os.homedir(), '.mcporter', 'mcporter.json');
  const qclawConfigPath = path.join(root, 'config', 'mcporter.json');
  let qclawRegistered = false;
  let qclawNativeRegistered = false;
  let qclawLifecycleRegistered = false;
  let qclawWarning = '';
  try {
    for (const configPath of qclawConfigPaths) {
      qclawRegistered = upsertMcporterServer(configPath, agentKnowledgeServerName(student, true), projectServer)
        || qclawRegistered;
    }
    if (activateGlobal) {
      qclawRegistered = upsertMcporterServer(
        qclawGlobalConfigPath,
        agentKnowledgeServerName(student, true),
        activeServer,
        { replaceEducationManagerServers: true },
      ) || qclawRegistered;
    }
    if (activateGlobal && qclawRuntime.configPath && fs.existsSync(qclawRuntime.configPath)) {
      qclawNativeRegistered = upsertQClawNativeMcpServer(
        qclawRuntime.configPath,
        agentKnowledgeServerName(student, true),
        activeServer,
        { replaceEducationManagerServers: true },
      );
      qclawLifecycleRegistered = installOpenClawLifecyclePlugin(qclawRuntime.configPath, 'qclaw');
    }
  } catch (error) {
    qclawWarning = `QClaw 已有无法安全合并的 MCP 配置：${error.message}`;
  }

  const codexConfigPath = path.join(root, '.codex', 'config.toml');
  const codexGlobalConfigPath = path.join(os.homedir(), '.codex', 'config.toml');
  const codexManaged = Boolean(unifiedKnowledgeRegistrations().codex);
  const codexProjectRegistered = !codexManaged && installCodexMcpServer(
    codexConfigPath,
    agentKnowledgeServerName(student, true),
    command,
    unifiedKnowledgeArgs('codex', args),
  );
  const codexGlobalRegistered = activateGlobal && !codexManaged
    ? installCodexMcpServer(
      codexGlobalConfigPath,
      agentKnowledgeServerName(student, true),
      command,
      unifiedKnowledgeArgs('codex', activeArgs),
      { replaceEducationManagerServers: true },
    )
    : false;
  const codexHooksPath = path.join(os.homedir(), '.codex', 'hooks.json');
  const codexLifecycleRegistered = activateGlobal && !codexManaged
    ? upsertLifecycleCommandHooks(codexHooksPath, 'codex')
    : false;
  const codexHookIdentity = currentCodexHookIdentity();
  if (activateGlobal && codexLifecycleRegistered) {
    configureCodexHookOnboarding(codexHookOnboardingPath(), {
      hookIdentity: codexHookIdentity,
      hookPath: activeLifecycleExecutablePath,
    });
  }
  const claudeCodeHooksPath = path.join(os.homedir(), '.claude', 'settings.json');
  let claudeCodeLifecycleRegistered = false;
  let claudeCodeWarning = '';
  if (activateGlobal && findAgentToolInstall('claude-code').installed) {
    try {
      claudeCodeLifecycleRegistered = upsertLifecycleCommandHooks(claudeCodeHooksPath, 'claude-code');
    } catch (error) {
      claudeCodeWarning = `Claude Code 已有无法安全合并的 Hook 配置：${error.message}`;
    }
  }

  const workbuddyConfigPath = path.join(os.homedir(), '.workbuddy', 'mcp.json');
  const codebuddyConfigPath = path.join(os.homedir(), '.codebuddy', '.mcp.json');
  const traeProjectConfigPath = path.join(root, '.trae', 'mcp.json');
  const qoderProjectConfigPath = path.join(root, '.mcp.json');
  const openclawConfigPath = path.join(os.homedir(), '.openclaw', 'openclaw.json');
  let workbuddyRegistered = false;
  let workbuddyLifecycleRegistered = false;
  let workbuddyWarning = '';
  let openclawRegistered = false;
  let openclawLifecycleRegistered = false;
  let openclawWarning = '';
  let hermesLifecycleRegistered = false;
  let hermesWarning = '';
  let traeRegistered = false;
  let traeWarning = '';
  let qoderRegistered = false;
  let qoderWarning = '';
  if (activateGlobal) {
    try {
      if (!unifiedKnowledgeRegistrations().workbuddy) {
      workbuddyRegistered = upsertMcporterServer(
        workbuddyConfigPath,
        agentKnowledgeServerName(student, true),
        unifiedKnowledgeServer('workbuddy', activeServer),
        { replaceEducationManagerServers: true },
      );
      workbuddyRegistered = upsertMcporterServer(
        codebuddyConfigPath,
        agentKnowledgeServerName(student, true),
        unifiedKnowledgeServer('workbuddy', activeServer),
        { replaceEducationManagerServers: true },
      ) || workbuddyRegistered;
      workbuddyLifecycleRegistered = upsertLifecycleCommandHooks(path.join(os.homedir(), '.workbuddy', 'settings.json'), 'workbuddy');
      workbuddyLifecycleRegistered = upsertLifecycleCommandHooks(path.join(os.homedir(), '.codebuddy', 'settings.json'), 'workbuddy') || workbuddyLifecycleRegistered;
      }
    } catch (error) {
      workbuddyWarning = `WorkBuddy 已有无法安全合并的 MCP 配置：${error.message}`;
    }
    try {
      openclawRegistered = upsertOpenClawMcpServer(
        openclawConfigPath,
        agentKnowledgeServerName(student, true),
        activeServer,
        { replaceEducationManagerServers: true },
      );
      openclawLifecycleRegistered = installOpenClawLifecyclePlugin(openclawConfigPath, 'openclaw');
    } catch (error) {
      openclawWarning = `OpenClaw 已有无法安全合并的 MCP 配置：${error.message}`;
    }
    if (findAgentToolInstall('hermes').installed) {
      try {
        hermesLifecycleRegistered = installHermesLifecyclePlugin();
      } catch (error) {
        hermesWarning = `Hermes 生命周期插件暂未接通：${error.message}`;
      }
    }
    try {
      // TRAE officially loads project MCP servers from .trae/mcp.json.
      traeRegistered = upsertMcporterServer(
        traeProjectConfigPath,
        agentKnowledgeServerName(student, true),
        projectServer,
        { replaceEducationManagerServers: true },
      );
    } catch (error) {
      traeWarning = `TRAE 项目 MCP 配置无法安全合并：${error.message}`;
    }
    try {
      // Qoder CLI officially loads project MCP servers from .mcp.json.
      qoderRegistered = upsertMcporterServer(
        qoderProjectConfigPath,
        agentKnowledgeServerName(student, true),
        projectServer,
        { replaceEducationManagerServers: true },
      );
    } catch (error) {
      qoderWarning = `Qoder 项目 MCP 配置无法安全合并：${error.message}`;
    }
  }

  const agentsPath = path.join(root, 'AGENTS.md');
  const agentsBlock = agentKnowledgeWorkspaceRule(student);
  replaceManagedTextBlock(
    agentsPath,
    '<!-- EDU-MANAGER-KNOWLEDGE-TOOL:START -->',
    '<!-- EDU-MANAGER-KNOWLEDGE-TOOL:END -->',
    agentsBlock,
    `# ${student.name} 教育管家 Agent 规则\n`,
  );
  if (qclawAgent?.workspace && path.resolve(qclawAgent.workspace) !== path.resolve(root)) {
    replaceManagedTextBlock(
      path.join(qclawAgent.workspace, 'AGENTS.md'),
      '<!-- EDU-MANAGER-KNOWLEDGE-TOOL:START -->',
      '<!-- EDU-MANAGER-KNOWLEDGE-TOOL:END -->',
      agentsBlock,
      `# ${student.name} QClaw Agent 规则\n`,
    );
  }

  return {
    bridgePath,
    activeBridgePath,
    activeLifecycleHookPath,
    activeDescriptorPath,
    qclawConfigPath,
    qclawConfigPaths: [...qclawConfigPaths],
    qclawGlobalConfigPath,
    qclawAgentId,
    qclawWorkspace: qclawAgent?.workspace || '',
    qclawRegistered,
    qclawNativeRegistered,
    qclawLifecycleRegistered,
    qclawWarning,
    codexConfigPath,
    codexGlobalConfigPath,
    codexRegistered: Boolean(codexProjectRegistered && (!activateGlobal || codexGlobalRegistered)),
    codexHooksPath,
    codexLifecycleRegistered,
    codexHookIdentity,
    claudeCodeHooksPath,
    claudeCodeLifecycleRegistered,
    claudeCodeWarning,
    codexRulePath: agentsPath,
    workbuddyConfigPath,
    codebuddyConfigPath,
    workbuddyRegistered,
    workbuddyLifecycleRegistered,
    workbuddyWarning,
    openclawConfigPath,
    openclawRegistered,
    openclawLifecycleRegistered,
    openclawWarning,
    hermesLifecycleRegistered,
    hermesPluginDir: hermesLifecyclePluginDir(),
    hermesWarning,
    traeProjectConfigPath,
    traeRegistered,
    traeWarning,
    qoderProjectConfigPath,
    qoderRegistered,
    qoderWarning,
    toolName: 'query_education_knowledge',
    toolNames,
  };
}

function installManagedAgentKnowledgeRule(student) {
  const root = student.rootPath || getStudentRootDir(student.name);
  const agentPath = student.agentPath || path.join(root, 'AGENT.md');
  if (!fs.existsSync(agentPath)) return '';
  const markerStart = '<!-- EDU-MANAGER-REMOTE-KNOWLEDGE:START -->';
  const markerEnd = '<!-- EDU-MANAGER-REMOTE-KNOWLEDGE:END -->';
  const descriptor = agentKnowledgeDescriptorPath(student);
  const block = `${markerStart}
## 教育管家知识查询

回答学生档案或学习项目问题时，优先调用 MCP 工具 \`query_education_knowledge\`，可以直接传入用户的完整自然语言问题。工具注册信息由教育管家自动维护，也可从 \`${descriptor}\` 查看当前只读能力；服务会自动选择本机、局域网或 Tailscale，并返回带 \`edu://\` 引用和更新时间的最小知识片段。不要遍历远程文件系统，不要把离线快照表述为实时信息。

用户在教育管家开启“自动会话记忆”后，教育管家通过 Agent 生命周期 Hook 自动采集授权后的会话事件；已打开的 Codex 会话仅从授权后下一条用户提问开始。无需且不得由模型主动调用会话采集工具。不得读取启用前历史、其他会话、系统提示、缓存、工具密钥或教育管家任务中心的任务执行上下文。

外部能力调用应先确定唯一学生 ID；项目问题还需明确项目 ID。只读资料目录和任务状态可通过 MCP 工具 \`list_education_archive\`、\`get_education_task_status\` 或描述符中的本机 API 调用。主机按授权能力与学生/项目双重隔离，不得把无结果或拒绝当作可退回其他学生的许可。报告仅作为有权限的呈现结果，保留 \`edu://\` 来源、时间和证据不足说明。写入应先预览并获得主机批准；不得绕过主机直接改写知识库、正式报告或任务状态。不要把令牌、原始私密资料放入提示词或日志。

仅当用户明确要求保存当前对话时，调用 \`submit_education_conversation\` 生成预览意图；由主机审核通过后才调用 \`execute_education_write\`。只提交当前对话或用户明确选择的 user/assistant 消息，不读取其他会话、私有历史、缓存、系统提示或密钥。附件须走独立受控资料流程。用户指定项目时必须通过 \`targetProject\` 传入准确项目名称；未唯一匹配时不得退回学生档案。
${markerEnd}`;
  return replaceManagedTextBlock(agentPath, markerStart, markerEnd, block);
}

function prepareAgentKnowledgeAccess(studentId, options = {}) {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const directory = agentKnowledgeAccessDir(student);
    fs.mkdirSync(directory, { recursive: true });
    const linkedProjects = readProjects()
      .filter((project) => (project.studentIds || []).map(String).includes(String(student.id)))
      .map(normalizeProjectMetadata)
      .map((project) => ({ id: String(project.id), name: String(project.name || project.id) }));
    const access = ensureStudentAgentAccessToken(student, linkedProjects.map((project) => project.id), options);
    const tokenPath = access.tokenPath;
    const registration = installAgentKnowledgeMcpRegistrations(student, options);
    let memorySettings = agentMemoryStore().getSettings(String(student.id));
    const automationEnabled = options.captureEnabled === undefined
      ? memorySettings.automationEnabled
      : Boolean(options.captureEnabled);
    if (automationEnabled && (!memorySettings.captureEpoch || !memorySettings.captureAuthorizedAt)) {
      memorySettings = agentMemoryStore().updateSettings(String(student.id), {
        captureEpoch: crypto.randomUUID(),
        captureAuthorizedAt: new Date().toISOString(),
      });
    }
    const descriptor = {
      schema: AGENT_KNOWLEDGE_QUERY_SCHEMA,
      mode: 'local_first_then_remote_on_demand',
      teamQueryPolicy: teamKnowledgePolicy(),
      endpoint: `http://127.0.0.1:${getHostServicePort()}/api/agent/knowledge/query`,
      capabilityEndpoint: `http://127.0.0.1:${getHostServicePort()}/api/agent/invoke`,
      capabilityCatalogEndpoint: `http://127.0.0.1:${getHostServicePort()}/api/agent/capabilities`,
      conversationEndpoint: `http://127.0.0.1:${getHostServicePort()}/api/agent/conversation/submit`,
      memoryEndpoints: {
        start: `http://127.0.0.1:${getHostServicePort()}/api/agent/memory/session/start`,
        append: `http://127.0.0.1:${getHostServicePort()}/api/agent/memory/session/append`,
        observe: `http://127.0.0.1:${getHostServicePort()}/api/agent/memory/session/observe`,
        finalize: `http://127.0.0.1:${getHostServicePort()}/api/agent/memory/session/finalize`,
        recent: `http://127.0.0.1:${getHostServicePort()}/api/agent/memory/recent`,
        acceptHandoff: `http://127.0.0.1:${getHostServicePort()}/api/agent/memory/handoff/accept`,
        cancelHandoff: `http://127.0.0.1:${getHostServicePort()}/api/agent/memory/handoff/cancel`,
      },
      method: 'POST',
      authentication: {
        type: 'bearer_token_file',
        tokenFile: tokenPath,
        grantType: 'student_scoped',
        grantId: access.grant.grantId,
      },
      agentCapabilities: access.grant.capabilities,
      lifecycleCapture: {
        schema: 'edu-manager.agent-lifecycle-capture.v1',
        enabled: automationEnabled,
        captureEpoch: automationEnabled ? memorySettings.captureEpoch : '',
        authorizedAt: automationEnabled ? memorySettings.captureAuthorizedAt : '',
        mode: 'event_queue',
        queueDir: agentLifecycleQueueDir(),
        allowedAgents: AUTO_CAPTURE_AGENT_IDS,
        excludes: ['historical_sessions', 'system_prompts', 'tool_secrets', 'task_center_context'],
      },
      defaults: {
        scopeType: 'student',
        scopeId: String(student.id),
        scopeName: String(student.name),
        scopePolicy: 'fixed_student',
        projects: linkedProjects,
      },
      ordinaryUserConfigurationRequired: false,
      capabilities: ['search', 'context_bundle', 'citations', 'offline_snapshot', 'submit_selected_conversation', 'authorized_conversation_capture', 'incremental_turn_capture', 'full_conversation_archive', 'recent_context', 'session_summary', 'handoff'],
      nativeTool: {
        name: registration.toolName,
        names: registration.toolNames,
        protocol: 'mcp_stdio',
        qclawRegistered: registration.qclawRegistered,
        qclawNativeRegistered: registration.qclawNativeRegistered,
        qclawConfig: registration.qclawConfigPath,
        codexConfig: registration.codexConfigPath,
        codexRegistered: registration.codexRegistered,
        codexLifecycleRegistered: registration.codexLifecycleRegistered,
        codexHookIdentity: registration.codexHookIdentity,
        claudeCodeLifecycleRegistered: registration.claudeCodeLifecycleRegistered,
        workbuddyConfig: registration.workbuddyConfigPath,
        workbuddyRegistered: registration.workbuddyRegistered,
        workbuddyLifecycleRegistered: registration.workbuddyLifecycleRegistered,
        openclawConfig: registration.openclawConfigPath,
        openclawRegistered: registration.openclawRegistered,
        openclawLifecycleRegistered: registration.openclawLifecycleRegistered,
        qclawLifecycleRegistered: registration.qclawLifecycleRegistered,
        hermesLifecycleRegistered: registration.hermesLifecycleRegistered,
        traeConfig: registration.traeProjectConfigPath,
        traeRegistered: registration.traeRegistered,
        qoderConfig: registration.qoderProjectConfigPath,
        qoderRegistered: registration.qoderRegistered,
        bridge: registration.bridgePath,
        lifecycleHook: registration.activeLifecycleHookPath,
      },
      updatedAt: new Date().toISOString(),
    };
    writeJsonAtomic(agentKnowledgeDescriptorPath(student), descriptor);
    if (options.activateGlobal !== false) {
      writeJsonAtomic(registration.activeDescriptorPath, {
        ...descriptor,
        defaults: {
          ...descriptor.defaults,
          scopePolicy: 'fixed_student',
        },
      });
    }
    const rulePath = installManagedAgentKnowledgeRule(student);
    return JSON.stringify({
      ok: true,
      descriptorPath: agentKnowledgeDescriptorPath(student),
      rulePath,
      registration,
      message: `已为现有 Agent 准备知识工具；Codex、QClaw、WorkBuddy、OpenClaw、Claude Code、Hermes 支持生命周期采集，TRAE 与 Qoder 已接入项目级 MCP 和统一任务回写。${[registration.qclawWarning, registration.workbuddyWarning, registration.openclawWarning, registration.claudeCodeWarning, registration.hermesWarning, registration.traeWarning, registration.qoderWarning].filter(Boolean).join('；')}`,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `准备 Agent 知识调用失败：${error.message}` });
  }
}

function prepareAllAgentKnowledgeAccess() {
  let prepared = 0;
  const activeDescriptor = safeReadJson(activeAgentKnowledgeDescriptorPath(), {});
  const activeStudentId = String(activeDescriptor?.defaults?.scopeId || '');
  for (const student of readStudentsIndex().map(toHostStudent)) {
    try {
      const result = parseJsonObject(prepareAgentKnowledgeAccess(student.id, {
        activateGlobal: Boolean(activeStudentId && activeStudentId === String(student.id)),
      }));
      if (result.ok) prepared += 1;
    } catch {
      // One unavailable adopted knowledge root must not block the host service.
    }
  }
  return prepared;
}

function refreshAgentKnowledgeAccessForStudents(studentIds) {
  const activeDescriptor = safeReadJson(activeAgentKnowledgeDescriptorPath(), {});
  const activeStudentId = String(activeDescriptor?.defaults?.scopeId || '');
  let refreshed = 0;
  for (const studentId of mergeUnique((studentIds || []).map(String).filter(Boolean))) {
    try {
      const result = parseJsonObject(prepareAgentKnowledgeAccess(studentId, {
        activateGlobal: Boolean(activeStudentId && activeStudentId === String(studentId)),
      }));
      if (result.ok) refreshed += 1;
    } catch {
      // Project binding itself has already succeeded. A later student selection
      // can safely rebuild an unavailable Agent descriptor.
    }
  }
  return refreshed;
}

let agentMemoryStoreInstance = null;
let agentLifecycleDrainTimer = null;
let agentLifecycleInstallMonitorTimer = null;
let agentLifecycleInstallFingerprint = '';
let lastAgentLifecycleStaleSweepAt = 0;
let agentCaptureSwitchInProgress = false;

function agentMemoryStore() {
  if (!agentMemoryStoreInstance) {
    agentMemoryStoreInstance = createAgentMemoryStore({
      rootDir: path.join(app.getPath('userData'), 'agent-memory-v1'),
      resolveSettings: (_studentId, saved) => {
        const global = agentControlStore().read().global;
        return global ? { ...saved, automationEnabled: global.enabled,
          allowedAgents: aiExecutorRegistry().filter(p => p.capture && !global.disabledProviders.includes(p.id)).map(p => p.id),
          captureEpoch: global.captureEpoch, captureAuthorizedAt: global.authorizedAt } : saved;
      },
    });
  }
  return agentMemoryStoreInstance;
}

function finalizeStoredLifecycleSession(student, session, options = {}) {
  const store = agentMemoryStore();
  if (!session || session.finalizedAt || !Array.isArray(session.messages) || !session.messages.length) return false;
  const finalizationKey = String(options.finalizationKey || `lifecycle-stale:${session.sessionId}`);
  const archived = persistAgentConversationSubmission({
    sourceAgent: session.agentId,
    sourceNodeId: session.sourceNodeId,
    sessionId: session.sessionId,
    title: session.title || `${session.agentId} 授权会话`,
    scopeType: 'student',
    scopeId: String(student.id),
    studentHint: String(student.id),
    messages: session.messages.map((message) => ({
      messageId: message.eventId,
      role: message.role,
      content: message.content,
      occurredAt: message.occurredAt,
    })),
    submittedAt: String(options.occurredAt || new Date().toISOString()),
  }, { lifecycleCapture: true, sessionStartedAt: session.startedAt });
  store.finalizeSession({
    studentId: String(student.id),
    projectId: '',
    sessionId: session.sessionId,
    status: options.status || 'completed',
    idempotencyKey: finalizationKey,
  });
  store.attachConversationReceipt({ studentId: String(student.id), projectId: '', sessionId: session.sessionId, receipt: archived.receipt });
  return true;
}

function processAgentLifecycleEnvelope(rawEnvelope) {
  const event = normalizeLifecycleEnvelope(rawEnvelope);
  if (!event) return { ok: true, ignored: true };
  if (!globalConversationCaptureAuthorized()) return { ok: false, discard: true, message: 'Global Agent authorization is disabled.' };
  if (unifiedKnowledgeRegistrations()[event.sourceAgent]) return { ok: true, ignored: true, message: 'Unified connector uses explicit session scope; legacy active-student capture is disabled.' };
  const student = findStudentByKey(event.scopeId);
  if (!student) return { ok: false, discard: true, message: 'Lifecycle student scope no longer exists.' };
  if (studentConversationCaptureBlocked(student)) return { ok: false, discard: true, message: 'Lifecycle capture stopped because the student is inactive or archived.' };
  const descriptor = safeReadJson(agentKnowledgeDescriptorPath(student), {});
  if (
    String(descriptor?.defaults?.scopeId || '') !== String(student.id)
    || String(descriptor?.authentication?.grantId || '') !== event.grantId
  ) return { ok: false, discard: true, message: 'Lifecycle authorization no longer matches.' };
  const activeDescriptor = safeReadJson(activeAgentKnowledgeDescriptorPath(), {});
  if (
    !captureEpochMatches(rawEnvelope, descriptor.lifecycleCapture)
    || !captureEpochMatches(rawEnvelope, activeDescriptor.lifecycleCapture)
    || String(activeDescriptor?.defaults?.scopeId || '') !== String(student.id)
  ) return { ok: false, discard: true, message: 'Lifecycle capture epoch is no longer active.' };
  const store = agentMemoryStore();
  const settings = store.getSettings(String(student.id));
  if (!settings.automationEnabled || !lifecycleCaptureAllowed(descriptor, event.sourceAgent)) {
    return { ok: false, deferred: true, message: 'Lifecycle capture is disabled.' };
  }
  return {
    ...applyNormalizedLifecycleEvent(student, event, event.grantId),
    sourceAgent: event.sourceAgent,
    scopeId: String(student.id),
    capturedAt: String(rawEnvelope?.capturedAt || event.occurredAt || ''),
  };
}

function applyNormalizedLifecycleEvent(student, event, sourceNodeId) {
  const store = agentMemoryStore();
  const scope = { studentId: String(student.id), projectId: '' };
  if (event.action === 'start') {
    store.startSession({
      ...scope,
      sessionId: event.sessionId,
      idempotencyKey: `lifecycle:${event.sourceAgent}:${event.nativeSessionId}:${event.captureEpoch}`,
      agentId: event.sourceAgent,
      origin: 'authorized_agent',
      sourceNodeId,
      title: event.title,
    });
    return { ok: true, action: 'start' };
  }
  if (event.action === 'append') {
    let session = store.readSession(scope.studentId, event.sessionId);
    if (!codexTurnAllowed(event, session)) return { ok: true, ignored: true, action: 'unpaired_codex_turn' };
    if (!session) {
      session = store.startSession({
        ...scope,
        sessionId: event.sessionId,
        idempotencyKey: `lifecycle:${event.sourceAgent}:${event.nativeSessionId}:${event.captureEpoch}`,
        agentId: event.sourceAgent,
        origin: 'authorized_agent',
        sourceNodeId,
        title: event.title,
      }).session;
    }
    if (session.finalizedAt) return { ok: true, ignored: true, action: 'append_after_finalize' };
    store.appendMessages({
      ...scope,
      sessionId: event.sessionId,
      messages: [{ ...event.message, eventId: event.eventId }],
    });
    return { ok: true, action: 'append' };
  }
  if (event.action === 'finalize') {
    const session = store.readSession(scope.studentId, event.sessionId);
    if (!session || !Array.isArray(session.messages) || !session.messages.length) return { ok: true, ignored: true, action: 'empty_finalize' };
    if (session.finalizedAt && session.finalizationKey === event.finalizationKey) return { ok: true, ignored: true, action: 'duplicate_finalize' };
    if (session.finalizedAt) return { ok: true, ignored: true, action: 'already_finalized' };
    finalizeStoredLifecycleSession(student, session, {
      status: event.status,
      finalizationKey: event.finalizationKey,
      occurredAt: event.occurredAt,
    });
    return { ok: true, action: 'finalize' };
  }
  return { ok: true, ignored: true };
}

function studentTerminalCaptureDevice(request) {
  const auth = request.authContext;
  if (auth?.type !== 'student_session' || auth.terminalMode !== 'personal') {
    throw new Error('只有已登录的个人 Windows 学生终端可以使用自动会话采集。');
  }
  const device = readDevices().find((item) => String(item.id) === String(auth.deviceId));
  if (
    !device
    || String(device.platform || '').toLowerCase() !== 'windows'
    || normalizeTerminalDeviceRole(device.deviceRole, device.capabilities) !== 'student'
    || normalizeTerminalMode(device.terminalMode, 'shared') !== 'personal'
    || String(device.boundStudentId || '') !== String(auth.studentId)
  ) throw new Error('个人终端设备与当前学生绑定不一致。');
  return device;
}

function processStudentTerminalLifecycleEnvelope(request, rawEnvelope) {
  if (!globalConversationCaptureAuthorized()) throw new Error('全局 Agent 授权已停用，新的自动会话采集已停止。');
  const device = studentTerminalCaptureDevice(request);
  if (!device.agentCaptureEnabled || String(device.agentCaptureStudentId || '') !== String(request.authContext.studentId)) {
    throw new Error('当前个人终端尚未授权自动会话采集。');
  }
  if (
    String(rawEnvelope?.scopeId || '') !== String(request.authContext.studentId)
    || String(rawEnvelope?.grantId || '') !== `terminal-device:${device.id}`
  ) throw new Error('学生终端生命周期事件范围不匹配。');
  if (!captureEpochMatches(rawEnvelope, {
    enabled: device.agentCaptureEnabled,
    captureEpoch: device.agentCaptureEpoch,
    authorizedAt: device.agentCaptureAuthorizedAt,
  })) throw new Error('学生终端生命周期事件不属于当前采集授权。');
  const event = normalizeLifecycleEnvelope(rawEnvelope);
  if (!event) return { ok: true, ignored: true };
  const student = findStudentByKey(request.authContext.studentId);
  if (!student) throw new Error('当前学生已经不存在。');
  if (studentConversationCaptureBlocked(student)) throw new Error('当前学生不活跃或已归档，已停止新的自动会话采集。');
  const settings = agentMemoryStore().getSettings(String(student.id));
  if (!settings.automationEnabled || !settings.allowedAgents.includes(event.sourceAgent)) {
    throw new Error('当前学生尚未开启授权 Agent 自动会话采集。');
  }
  return applyNormalizedLifecycleEvent(student, event, `student-terminal:${device.id}`);
}

function drainAgentLifecycleQueue(limit = 200) {
  if (!projectArchiveRuntime.status().ready) return { processed: 0, deferred: 0, discarded: 0, reason: 'archive_busy' };
  const directory = agentLifecycleQueueDir();
  if (!fs.existsSync(directory)) return { processed: 0, deferred: 0, discarded: 0 };
  const files = fs.readdirSync(directory, { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith('.json'))
    .map((entry) => entry.name)
    .sort()
    .slice(0, Math.max(1, Math.min(1000, Number(limit || 200))));
  const result = { processed: 0, deferred: 0, discarded: 0 };
  const changedStudents = new Map();
  for (const name of files) {
    const filePath = path.join(directory, name);
    try {
      const envelope = JSON.parse(fs.readFileSync(filePath, 'utf8'));
      const outcome = processAgentLifecycleEnvelope(envelope);
      if (outcome.deferred) {
        result.deferred += 1;
        continue;
      }
      fs.unlinkSync(filePath);
      if (outcome.discard) result.discarded += 1;
      else {
        result.processed += 1;
        if (outcome.ok && !outcome.ignored && outcome.scopeId) {
          let reason = 'lifecycle_event';
          if (outcome.sourceAgent === 'codex') {
            const verification = markCodexHookVerified(codexHookOnboardingPath(), {
              hookIdentity: currentCodexHookIdentity(),
              eventAt: outcome.capturedAt,
            });
            if (verification.changed) reason = 'codex_hook_verified';
          }
          changedStudents.set(String(outcome.scopeId), reason);
        }
      }
    } catch {
      // A partial write or temporarily unavailable archive is retried later.
    }
  }
  finalizeStaleLifecycleSessions();
  for (const [studentId, reason] of changedStudents) {
    notify('onNativeAgentMemoryChanged', JSON.stringify({ studentId, reason }));
  }
  return result;
}

function finalizeStaleLifecycleSessions(options = {}) {
  if (!projectArchiveRuntime.status().ready) return 0;
  const now = Number(options.now || Date.now());
  if (!options.force && now - lastAgentLifecycleStaleSweepAt < 60_000) return 0;
  lastAgentLifecycleStaleSweepAt = now;
  const staleBefore = now - Math.max(5 * 60_000, Number(options.staleAfterMs || 30 * 60_000));
  let finalized = 0;
  const store = agentMemoryStore();
  for (const student of readStudentsIndex().map(toHostStudent)) {
    const sessions = store.listSessions({ studentId: String(student.id), limit: 100 });
    for (const session of sessions) {
      if (
        session.status !== 'active'
        || session.origin !== 'authorized_agent'
        || !String(session.idempotencyKey || '').startsWith('lifecycle:')
        || Date.parse(session.updatedAt || session.startedAt || '') > staleBefore
      ) continue;
      try {
        if (Array.isArray(session.messages) && session.messages.length) {
          if (finalizeStoredLifecycleSession(student, session, {
            status: 'failed',
            finalizationKey: `lifecycle-stale:${session.sessionId}`,
            occurredAt: new Date(now).toISOString(),
          })) finalized += 1;
        } else {
          store.finalizeSession({
            studentId: String(student.id),
            projectId: '',
            sessionId: session.sessionId,
            status: 'cancelled',
            idempotencyKey: `lifecycle-stale-empty:${session.sessionId}`,
          });
          store.deleteEmptySessions({ studentId: String(student.id), sessionId: session.sessionId });
          finalized += 1;
        }
      } catch {
        // Keep the active session for the next sweep if archival is unavailable.
      }
    }
  }
  return finalized;
}

function startAgentLifecycleDrainMonitor() {
  if (agentLifecycleDrainTimer) return;
  fs.mkdirSync(agentLifecycleQueueDir(), { recursive: true });
  drainAgentLifecycleQueue();
  agentLifecycleDrainTimer = setInterval(() => drainAgentLifecycleQueue(), 2_000);
  agentLifecycleDrainTimer.unref?.();
}

function stopAgentLifecycleDrainMonitor() {
  if (agentLifecycleDrainTimer) clearInterval(agentLifecycleDrainTimer);
  agentLifecycleDrainTimer = null;
}

function currentLifecycleInstallFingerprint(options = {}) {
  if (options.force === true) {
    for (const agentId of AUTO_CAPTURE_AGENT_IDS) agentToolInstallCache.delete(agentId);
  }
  return AUTO_CAPTURE_AGENT_IDS.map((agentId) => {
    const install = findAgentToolInstall(agentId);
    return `${agentId}:${install.installed ? '1' : '0'}:${install.exePath || ''}`;
  }).join('|');
}

function reconcileAuthorizedLifecycleAdapters(options = {}) {
  if (!projectArchiveRuntime.status().ready) return false;
  try {
    // Do not probe installed Agent applications until lifecycle capture is
    // actually authorized; these probes may launch synchronous OS processes.
    const descriptor = safeReadJson(activeAgentKnowledgeDescriptorPath(), {});
    if (descriptor?.lifecycleCapture?.enabled !== true) return false;
    const studentId = String(descriptor?.defaults?.scopeId || '');
    if (!studentId || !findStudentByKey(studentId)) return false;
    const fingerprint = currentLifecycleInstallFingerprint(options);
    // An incomplete background discovery is not evidence of an uninstall.
    if (installProbeCache.pending) return false;
    if (!options.force && fingerprint === agentLifecycleInstallFingerprint) return false;
    agentLifecycleInstallFingerprint = fingerprint;
    const prepared = parseJsonObject(prepareAgentKnowledgeAccess(studentId, { activateGlobal: true, captureEnabled: true }));
    if (!prepared.ok) return false;
    notify('onNativeAgentMemoryChanged', JSON.stringify({ studentId, reason: 'adapter_reconciled' }));
    return true;
  } catch {
    return false;
  }
}

function startAgentLifecycleInstallMonitor() {
  if (agentLifecycleInstallMonitorTimer) return;
  reconcileAuthorizedLifecycleAdapters({ force: true });
  agentLifecycleInstallMonitorTimer = setInterval(() => reconcileAuthorizedLifecycleAdapters({ force: true }), 2 * 60 * 1000);
  agentLifecycleInstallMonitorTimer.unref?.();
}

function stopAgentLifecycleInstallMonitor() {
  if (agentLifecycleInstallMonitorTimer) clearInterval(agentLifecycleInstallMonitorTimer);
  agentLifecycleInstallMonitorTimer = null;
}

function agentMemoryState(studentId) {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const store = agentMemoryStore();
    const activeDescriptor = safeReadJson(activeAgentKnowledgeDescriptorPath(), {});
    const captureTarget = studentCaptureStatus(activeDescriptor, student.id);
    const authorizedSessions = store.listSessions({ studentId: String(student.id), limit: 100 })
      .filter((item) => item.origin === 'authorized_agent');
    const visibleSessions = [
      ...authorizedSessions.filter((item) => (item.messages || []).length || item.conversationReceipt),
      ...authorizedSessions.filter((item) => !(item.messages || []).length && !item.conversationReceipt),
    ];
    const visibleAssetIds = new Set(visibleSessions.map((session) => String(session.conversationReceipt?.assetId || '')).filter(Boolean));
    const imports = visibleAssetIds.size ? (readJsonFile(conversationIndexPath(student), { imports: [] }).imports || []) : [];
    const importByAssetId = new Map(imports.map((item) => [String(item.assetId || ''), item]));
    const deliveries = visibleAssetIds.size ? (readConversationDeliveries(student).deliveries || []) : [];
    const candidates = visibleAssetIds.size ? (readConversationCandidateRegistry(student).candidates || []) : [];
    const deliveryCountByAssetId = new Map();
    const deliveryHistoryByAssetId = new Map();
    const candidateCountByAssetId = new Map();
    const promotedCountByAssetId = new Map();
    for (const delivery of deliveries) {
      const assetId = String(delivery.assetId || '');
      if (!visibleAssetIds.has(assetId)) continue;
      if (delivery.sourceScopeType !== 'student' || String(delivery.sourceScopeId || '') !== String(student.id)) continue;
      deliveryCountByAssetId.set(assetId, (deliveryCountByAssetId.get(assetId) || 0) + 1);
      const history = deliveryHistoryByAssetId.get(assetId) || [];
      history.push({ targetType: String(delivery.targetType || ''), targetId: String(delivery.targetId || ''),
        targetName: String(delivery.targetName || ''), deliveredAt: String(delivery.deliveredAt || '') });
      deliveryHistoryByAssetId.set(assetId, history);
    }
    for (const candidate of candidates) {
      const assetId = String(candidate?.source?.assetId || '');
      if (visibleAssetIds.has(assetId)) {
        candidateCountByAssetId.set(assetId, (candidateCountByAssetId.get(assetId) || 0) + 1);
        if (candidate.status === 'promoted' || candidate.promotionTransactionId) {
          promotedCountByAssetId.set(assetId, (promotedCountByAssetId.get(assetId) || 0) + 1);
        }
      }
    }
    const sessions = visibleSessions.map((session) => {
      const assetId = String(session.conversationReceipt?.assetId || '');
      const imported = importByAssetId.get(assetId);
      const deliveryCount = deliveryCountByAssetId.get(assetId) || 0;
      const candidateCount = candidateCountByAssetId.get(assetId) || 0;
      const promotedCount = promotedCountByAssetId.get(assetId) || 0;
      return {
        sessionId: session.sessionId,
        agentId: session.agentId,
        origin: session.origin,
        title: session.title,
        projectId: session.projectId,
        status: session.status,
        startedAt: session.startedAt,
        updatedAt: session.updatedAt,
        messages: Array.isArray(session.messages) ? session.messages : [],
        capturedChars: session.capturedChars,
        conversationReceipt: session.conversationReceipt,
        summary: session.summary,
        handoff: session.handoff,
        materialLifecycleStatus: imported?.lifecycleStatus || session.materialLifecycleStatus || 'active',
        materialAvailable: Boolean(assetId && imported),
        materialDeliveries: (deliveryHistoryByAssetId.get(assetId) || [])
          .sort((a, b) => b.deliveredAt.localeCompare(a.deliveredAt)).slice(0, 20),
        materialDependencies: {
          deliveryCount,
          candidateCount,
          promotedCount,
          canPermanentlyDelete: deliveryCount === 0 && promotedCount === 0,
        },
      };
    });
    const descriptor = safeReadJson(agentKnowledgeDescriptorPath(student), {});
    const registration = descriptor.nativeTool || {};
    const lifecycleConfigured = {
      codex: registration.codexLifecycleRegistered,
      qclaw: registration.qclawLifecycleRegistered,
      workbuddy: registration.workbuddyLifecycleRegistered,
      openclaw: registration.openclawLifecycleRegistered,
      'claude-code': registration.claudeCodeLifecycleRegistered,
      hermes: registration.hermesLifecycleRegistered,
    };
    const lifecycleHealth = Object.fromEntries(Object.entries(lifecycleConfigured).map(([agentId, configured]) => {
      const latestSession = authorizedSessions.find((item) => (
        item.agentId === agentId && String(item.idempotencyKey || '').startsWith(`lifecycle:${agentId}:`)
      ));
      return [agentId, {
        configured: Boolean(configured),
        eventReceived: Boolean(latestSession),
        active: latestSession?.status === 'active',
        lastEventAt: latestSession?.updatedAt || '',
      }];
    }));
    const codexHookOnboarding = publicCodexHookOnboarding(codexHookOnboardingPath(), {
      hookIdentity: currentCodexHookIdentity(),
      configured: lifecycleConfigured.codex,
      cliAvailable: Boolean(findPreferredCodexCliInstall().exePath),
    });
    return JSON.stringify({
      ok: true,
      schema: 'edu-manager.agent-memory.v1',
      studentId: String(student.id),
      settings: store.getSettings(String(student.id)),
      captureTarget,
      sessions,
      registration,
      lifecycleHealth,
      codexHookOnboarding,
      summary: {
        total: sessions.length,
        active: sessions.filter((item) => item.status === 'active').length,
        empty: authorizedSessions.filter((item) => item.status !== 'active' && !(item.messages || []).length && !item.conversationReceipt).length,
        pendingHandoffs: sessions.filter((item) => item.handoff?.status === 'pending').length,
      },
      message: '已读取智能体会话记忆。',
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `读取智能体会话记忆失败：${error.message}` });
  }
}

function openCodexHookReview() {
  try {
    const hookIdentity = currentCodexHookIdentity();
    const current = publicCodexHookOnboarding(codexHookOnboardingPath(), {
      hookIdentity,
      configured: true,
      cliAvailable: Boolean(findPreferredCodexCliInstall().exePath),
    });
    if (!current.configured || !fs.existsSync(current.hookPath)) {
      return JSON.stringify({ ok: false, message: 'Codex Hook 尚未安装，请先开启 Agent 会话自动采集。' });
    }
    const cli = findPreferredCodexCliInstall();
    if (!cli.exePath || !fs.existsSync(cli.exePath)) {
      return JSON.stringify({ ok: false, message: '未找到 Codex CLI。请先安装或修复 Codex CLI，再进行一次 Hook 确认。' });
    }
    clipboard.writeText('/hooks');
    const script = buildCodexHookReviewPowerShell(cli.exePath, defaultStudentBaseDir());
    const child = spawn('powershell.exe', [
      '-NoLogo',
      '-NoProfile',
      '-NoExit',
      '-ExecutionPolicy',
      'Bypass',
      '-Command',
      script,
    ], { detached: true, stdio: 'ignore', windowsHide: false });
    child.unref();
    markCodexHookReviewOpened(codexHookOnboardingPath(), { hookIdentity });
    const onboarding = publicCodexHookOnboarding(codexHookOnboardingPath(), {
      hookIdentity,
      configured: true,
      cliAvailable: true,
    });
    return JSON.stringify({
      ok: true,
      onboarding,
      message: 'Codex CLI 已打开，/hooks 已复制。粘贴并回车，完成一次信任后发送下一条消息；AI教育管家会自动验证并开始后续采集。',
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `无法打开 Codex Hook 审查：${error.message}` });
  }
}

function deleteEmptyAgentMemorySessions(studentId, sessionId = '') {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const result = agentMemoryStore().deleteEmptySessions({ studentId: String(student.id), sessionId: String(sessionId || '') });
    return JSON.stringify({ ok: true, ...result, message: result.deleted
      ? `已清理 ${result.deleted} 条无授权消息的已结束会话。${result.remaining ? `仍有 ${result.remaining} 条，可再次清理。` : ''}`
      : '没有可清理的空会话；采集中的会话不会被删除。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `清理空会话失败：${error.message}` });
  }
}

function setLifecycleDescriptorEnabled(student, enabled) {
  for (const descriptorPath of [agentKnowledgeDescriptorPath(student), activeAgentKnowledgeDescriptorPath()]) {
    const descriptor = safeReadJson(descriptorPath, null);
    if (!descriptor || String(descriptor?.defaults?.scopeId || '') !== String(student.id)) continue;
    writeJsonAtomic(descriptorPath, {
      ...descriptor,
      lifecycleCapture: {
        ...(descriptor.lifecycleCapture || {}),
        enabled: Boolean(enabled),
        updatedAt: new Date().toISOString(),
      },
      updatedAt: new Date().toISOString(),
    });
  }
}

function disableAgentLifecycleRegistrations() {
  // Keep the previously trusted Codex hook installed but dormant. Its descriptor
  // is disabled before this point, so an already-open session can resume capture
  // from its next authorized user turn without reading earlier conversation text.
  setLifecycleCommandHooksEnabled(path.join(os.homedir(), '.workbuddy', 'settings.json'), false);
  setLifecycleCommandHooksEnabled(path.join(os.homedir(), '.codebuddy', 'settings.json'), false);
  setLifecycleCommandHooksEnabled(path.join(os.homedir(), '.claude', 'settings.json'), false);
  setOpenClawLifecyclePluginEnabled(path.join(os.homedir(), '.openclaw', 'openclaw.json'), false);
  setOpenClawLifecyclePluginEnabled(path.join(os.homedir(), '.qclaw', 'openclaw.json'), false);
  setHermesLifecyclePluginEnabled(false);
}

function activeLifecycleSessionsForStudent(studentId) {
  return agentMemoryStore().listSessions({ studentId: String(studentId), limit: 100 })
    .filter((session) => (
      session.status === 'active'
      && session.origin === 'authorized_agent'
      && String(session.idempotencyKey || '').startsWith('lifecycle:')
    ));
}

function finalizeActiveLifecycleSessionsForStudent(student, reason = 'disabled') {
  let finalized = 0;
  const store = agentMemoryStore();
  for (const session of activeLifecycleSessionsForStudent(student.id)) {
    const finalizationKey = `lifecycle-${reason}:${session.sessionId}`;
    if (Array.isArray(session.messages) && session.messages.length) {
      if (finalizeStoredLifecycleSession(student, session, {
        status: 'cancelled',
        finalizationKey,
      })) finalized += 1;
    } else {
      store.finalizeSession({
        studentId: String(student.id),
        projectId: '',
        sessionId: session.sessionId,
        status: 'cancelled',
        idempotencyKey: `${finalizationKey}:empty`,
      });
      store.deleteEmptySessions({ studentId: String(student.id), sessionId: session.sessionId });
      finalized += 1;
    }
  }
  return finalized;
}

function activateAgentMemoryCapture(studentId) {
  if (agentCaptureSwitchInProgress) {
    return JSON.stringify({ ok: false, code: 'SWITCH_IN_PROGRESS', message: '正在切换采集对象，请稍后重试。' });
  }
  agentCaptureSwitchInProgress = true;
  const previousDescriptorExists = fs.existsSync(activeAgentKnowledgeDescriptorPath());
  const previousDescriptor = safeReadJson(activeAgentKnowledgeDescriptorPath(), null);
  try {
    if (!globalConversationCaptureAuthorized()) return JSON.stringify({ ok: false, code: 'GLOBAL_AUTH_DISABLED', message: '请先在 AI 接入与调度中心启用全局授权。' });
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, code: 'STUDENT_NOT_FOUND', message: '未找到学生。' });
    const settings = agentMemoryStore().getSettings(String(student.id));
    if (!settings.automationEnabled) {
      return JSON.stringify({ ok: false, code: 'NOT_AUTHORIZED', message: `请先授权采集「${student.name}」的后续会话。` });
    }
    drainAgentLifecycleQueue();
    const currentTarget = activeCaptureTarget(previousDescriptor || {});
    const currentStudent = currentTarget.studentId ? findStudentByKey(currentTarget.studentId) : null;
    const decision = captureSwitchDecision({
      currentTarget,
      targetStudentId: String(student.id),
      activeSessions: currentStudent ? activeLifecycleSessionsForStudent(currentStudent.id) : [],
    });
    if (!decision.allowed) {
      const names = decision.blockingSessions
        .map((session) => lifecycleAdapter(session.agentId)?.name || session.agentId)
        .filter(Boolean);
      return JSON.stringify({
        ok: false,
        code: decision.code,
        blockingSessionCount: decision.blockingSessions.length,
        message: `当前采集对象「${currentTarget.studentName || currentStudent?.name || currentTarget.studentId}」仍有 ${decision.blockingSessions.length} 个 Agent 会话进行中${names.length ? `（${mergeUnique(names).join('、')}）` : ''}。请先结束这些会话，再切换到「${student.name}」。`,
      });
    }
    const prepared = parseJsonObject(prepareAgentKnowledgeAccess(String(student.id), {
      activateGlobal: true,
      captureEnabled: true,
    }));
    if (!prepared.ok) throw new Error(prepared.message || '无法完成 Agent 会话采集注册。');
    const reason = decision.code === 'ALREADY_ACTIVE' ? 'capture_target_refreshed' : 'capture_target_changed';
    appendHostTimeline({
      type: 'agent_memory_capture_target_changed',
      title: 'Agent memory capture target changed',
      detail: `${currentTarget.studentId || 'none'} -> ${student.id}`,
      studentId: String(student.id),
    });
    if (currentTarget.studentId && currentTarget.studentId !== String(student.id)) {
      notify('onNativeAgentMemoryChanged', JSON.stringify({ studentId: currentTarget.studentId, reason }));
    }
    notify('onNativeAgentMemoryChanged', JSON.stringify({ studentId: String(student.id), reason }));
    return JSON.stringify({
      ok: true,
      code: decision.code,
      captureTarget: studentCaptureStatus(safeReadJson(activeAgentKnowledgeDescriptorPath(), {}), student.id),
      registration: prepared.registration || {},
      message: decision.code === 'ALREADY_ACTIVE'
        ? `「${student.name}」已经是当前采集对象，接入状态已刷新。`
        : `已将本机 Agent 后续会话采集对象切换为「${student.name}」。`,
    });
  } catch (error) {
    if (previousDescriptor) {
      try { writeJsonAtomic(activeAgentKnowledgeDescriptorPath(), previousDescriptor); } catch { /* Preserve the original failure. */ }
    } else if (!previousDescriptorExists) {
      try { fs.unlinkSync(activeAgentKnowledgeDescriptorPath()); } catch { /* The failed switch may not have written a descriptor. */ }
    }
    return JSON.stringify({ ok: false, code: 'SWITCH_FAILED', message: `切换自动会话采集对象失败：${error.message}` });
  } finally {
    agentCaptureSwitchInProgress = false;
  }
}

function setAgentMemoryAutomation(studentId, enabled) {
  if (agentControlStore().read().global) return JSON.stringify({ ok: false, message: '会话采集已纳入全局授权，请在 AI 接入与调度中心管理。' });
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const activeDescriptor = safeReadJson(activeAgentKnowledgeDescriptorPath(), {});
    const currentTarget = activeCaptureTarget(activeDescriptor);
    if (!enabled && currentTarget.studentId === String(student.id)) {
      drainAgentLifecycleQueue();
      finalizeActiveLifecycleSessionsForStudent(student, 'authorization-disabled');
    }
    const previousSettings = agentMemoryStore().getSettings(String(student.id));
    const newEpoch = Boolean(enabled) && (
      !previousSettings.automationEnabled
      || !previousSettings.captureEpoch
      || !previousSettings.captureAuthorizedAt
    );
    const settings = agentMemoryStore().updateSettings(String(student.id), {
      automationEnabled: Boolean(enabled),
      allowedAgents: AUTO_CAPTURE_AGENT_IDS,
      captureEpoch: enabled ? (newEpoch ? crypto.randomUUID() : previousSettings.captureEpoch) : '',
      captureAuthorizedAt: enabled ? (newEpoch ? new Date().toISOString() : previousSettings.captureAuthorizedAt) : '',
    });
    let prepared;
    if (settings.automationEnabled) {
      const shouldActivate = !currentTarget.enabled || currentTarget.studentId === String(student.id);
      prepared = parseJsonObject(prepareAgentKnowledgeAccess(String(student.id), {
        activateGlobal: shouldActivate,
        captureEnabled: true,
      }));
    } else {
      setLifecycleDescriptorEnabled(student, false);
      if (currentTarget.studentId === String(student.id)) disableAgentLifecycleRegistrations();
      prepared = { ok: true, registration: safeReadJson(agentKnowledgeDescriptorPath(student), {}).nativeTool || {} };
    }
    if (!prepared.ok) throw new Error(prepared.message || '无法完成 Agent 会话采集注册。');
    if (settings.automationEnabled) drainAgentLifecycleQueue();
    appendHostTimeline({
      type: 'agent_memory_automation_changed',
      title: 'Agent memory automation changed',
      detail: `${student.id}: ${settings.automationEnabled ? 'enabled' : 'disabled'}`,
      studentId: String(student.id),
    });
    return JSON.stringify({
      ok: true,
      settings,
      registration: prepared.registration || {},
      message: settings.automationEnabled
        ? (!currentTarget.enabled || currentTarget.studentId === String(student.id)
          ? `已授权并将「${student.name}」设为当前采集对象；旧会话从授权后的下一条提问开始采集，不扫描历史。`
          : `已授权采集「${student.name}」的后续轮次；本机当前采集对象仍为「${currentTarget.studentName || currentTarget.studentId}」，可在本页明确切换。`)
        : (currentTarget.studentId === String(student.id)
          ? '已停止当前学生的生命周期采集；进行中的采集记录已安全结束，已有归档不会删除。'
          : `已撤销「${student.name}」的采集授权；当前采集对象未受影响。`),
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `更新自动会话记忆失败：${error.message}` });
  }
}

function agentMemoryRequestScope(request, incoming = {}, capability = '') {
  const studentId = String(incoming.studentId || incoming.scopeId || '');
  if (!studentId || !isStudentAllowed(request, studentId)) throw new Error('当前调用方没有访问该学生会话记忆的权限。');
  if (capability && request.authContext?.type === 'agent_grant' && !(request.authContext.capabilities || []).includes(capability)) {
    throw new Error('当前 Agent 授权不包含所需的会话记忆能力。');
  }
  const projectId = String(incoming.projectId || '');
  if (projectId) {
    const project = readProjects().map(normalizeProject).find((item) => String(item.id) === projectId);
    if (!project || !(project.studentIds || []).map(String).includes(studentId) || !projectAllowed(request, project)) {
      throw new Error('当前调用方没有访问该学生项目会话记忆的权限。');
    }
  }
  return { studentId, projectId };
}

async function handleAgentMemoryRequest(request, response, action) {
  try {
    if (!requireAuth(request, response)) return;
    const body = JSON.parse((await readRequestBuffer(request, 512 * 1024)).toString('utf8') || '{}');
    const capability = action === 'recent' ? 'memory:read' : action.includes('handoff') ? 'handoff:manage' : 'memory:write';
    let scope = agentMemoryRequestScope(request, body, capability);
    const store = agentMemoryStore();
    if (['append', 'finalize'].includes(action)) {
      const existingSession = store.readSession(scope.studentId, body.sessionId);
      if (existingSession?.projectId && scope.projectId && existingSession.projectId !== scope.projectId) {
        throw new Error('授权 Agent 会话项目范围不匹配。');
      }
      if (existingSession?.projectId && !scope.projectId) {
        scope = agentMemoryRequestScope(request, { studentId: scope.studentId, projectId: existingSession.projectId }, capability);
      }
    }
    const agentId = String(body.sourceAgent || body.agentId || '').trim().toLowerCase();
    const captureAction = ['start', 'append', 'finalize'].includes(action);
    if (captureAction) {
      if (!globalConversationCaptureAuthorized()) throw new Error('全局 Agent 授权已停用，新的自动会话采集已停止。');
      const captureStudent = findStudentByKey(scope.studentId);
      if (studentConversationCaptureBlocked(captureStudent)) throw new Error('当前学生不活跃或已归档，已停止新的自动会话采集。');
      const settings = store.getSettings(scope.studentId);
      if (!settings.automationEnabled) throw new Error('当前学生尚未开启授权 Agent 自动会话采集。');
      if (!AUTO_CAPTURE_AGENT_IDS.includes(agentId) || !settings.allowedAgents.includes(agentId)) {
        throw new Error('当前 Agent 不在授权会话采集范围内。');
      }
      if (request.authContext?.type === 'agent_grant' && !(request.authContext.capabilities || []).includes('conversation:submit')) {
        throw new Error('当前 Agent 授权不包含对话投递能力。');
      }
      if (request.authContext?.type === 'student_session') {
        const captureDevice = studentTerminalCaptureDevice(request);
        if (!captureDevice.agentCaptureEnabled || String(captureDevice.agentCaptureStudentId || '') !== scope.studentId) {
          throw new Error('当前个人终端尚未授权自动会话采集。');
        }
      }
    }
    let result;
    if (action === 'start') result = store.startSession({
      ...body,
      ...scope,
      agentId,
      origin: 'authorized_agent',
      sourceNodeId: String(body.sourceNodeId || request.authContext?.grantId || 'agent-mcp'),
    });
    else if (action === 'append') {
      const session = store.readSession(scope.studentId, body.sessionId);
      if (!session || session.agentId !== agentId || session.origin !== 'authorized_agent') throw new Error('授权 Agent 会话身份不匹配。');
      result = store.appendMessages({ ...body, ...scope, agentId });
    }
    else if (action === 'observe') result = store.appendObservation({ ...body, ...scope });
    else if (action === 'finalize') {
      let session = store.readSession(scope.studentId, body.sessionId);
      if (!session || session.agentId !== agentId || session.origin !== 'authorized_agent') throw new Error('授权 Agent 会话身份不匹配。');
      const finalizationKey = String(body.idempotencyKey || `authorized-agent-finalize:${session.sessionId}`);
      if (session.finalizedAt && session.finalizationKey === finalizationKey) {
        result = { session, reused: true, receipt: session.conversationReceipt };
      } else {
        if (Array.isArray(body.messages) && body.messages.length) {
          store.appendMessages({ ...body, ...scope, agentId });
          session = store.readSession(scope.studentId, body.sessionId);
        }
        if (!Array.isArray(session.messages) || !session.messages.length) throw new Error('当前授权会话没有可归档的用户或助手消息。');
        const archived = await persistAgentConversationSubmission({
          sourceAgent: agentId,
          sourceNodeId: session.sourceNodeId || request.authContext?.grantId || 'agent-mcp',
          sessionId: session.sessionId,
          title: body.title || session.title || `${agentId} 授权会话`,
          scopeType: scope.projectId ? 'project' : 'student',
          scopeId: scope.projectId || scope.studentId,
          studentHint: scope.studentId,
          targetProject: scope.projectId,
          messages: session.messages.map((message) => ({
            messageId: message.eventId,
            role: message.role,
            content: message.content,
            occurredAt: message.occurredAt,
          })),
          contentSummary: body.contentSummary || body.summary?.objective || session.summary?.objective,
          submittedAt: body.submittedAt || new Date().toISOString(),
        }, { lifecycleCapture: true, sessionStartedAt: session.startedAt });
        const finalized = store.finalizeSession({ ...body, ...scope, agentId, idempotencyKey: finalizationKey });
        store.attachConversationReceipt({ ...scope, sessionId: session.sessionId, receipt: archived.receipt });
        result = {
          ...finalized,
          session: store.readSession(scope.studentId, session.sessionId),
          receipt: archived.receipt,
          archived: true,
        };
      }
    }
    else if (action === 'recent') result = store.recentContext({ ...body, ...scope });
    else if (action === 'handoff-accept') result = store.acceptHandoff({ ...body, ...scope });
    else if (action === 'handoff-cancel') result = store.cancelHandoff({ ...body, ...scope });
    else throw new Error('不支持的会话记忆操作。');
    sendJson(response, 200, { ok: true, result });
  } catch (error) {
    sendJson(response, /没有访问|授权|范围|身份不匹配/.test(error.message) ? 403 : 400, { ok: false, message: error.message });
  }
}

function isAutoPublishReportTask(task) {
  return Boolean(
    (task?.kind === 'weekly_action' || PERIODIC_REPORT_TASKS[task?.kind])
    && String(task?.completionPolicy || '') === 'auto_after_validation'
  );
}

function reportProjectsForStudent(student) {
  return readProjects()
    .filter((project) => (project.studentIds || []).map(String).includes(String(student.id)))
    .map(normalizeProjectMetadata);
}

function reportEvidenceSourceValues(student, projects, evidence) {
  if (requiresFixedReportEvidence(evidence, projects)) return [];
  const values = [];
  const append = (value) => {
    if (Array.isArray(value)) value.forEach(append);
    else String(value || '').split(/[；;]/u).map((item) => item.trim()).filter(Boolean).forEach((item) => values.push(item));
  };
  append(evidence?.sourceUri);
  append(evidence?.sourcePath);
  append(evidence?.sourcePaths);
  append(evidence?.systemVerification?.sourcePaths);
  append(evidence?.migratedFrom);
  const project = projects.find((item) => (
    (evidence?.projectId && String(item.id) === String(evidence.projectId))
    || (evidence?.projectName && String(item.name) === String(evidence.projectName))
  ));
  if (project) append(project.promotionPath);
  return [...new Set(values)];
}

function reportEligibleEvidence(student) {
  const projects = reportProjectsForStudent(student);
  const growthIndex = safeReadJson(growthIndexPath(student), {});
  const allEvidence = Array.isArray(growthIndex.evidence) ? growthIndex.evidence : [];
  const evidence = allEvidence.filter((item) => {
    const status = String(item?.status || '');
    const hasConflict = String(item?.riskLevel || '') === 'high'
      || Boolean(item?.risk?.blocked)
      || (Array.isArray(item?.conflicts) && item.conflicts.length > 0);
    return ['confirmed', 'watching'].includes(status)
      && !hasConflict
      && (requiresFixedReportEvidence(item, projects)
        ? fixedReportEvidenceSources(student, projects, item).length > 0
        : reportEvidenceSourceValues(student, projects, item).some((source) => reportEvidenceSourceResolver(student, projects, source).available));
  });
  return {
    ids: evidence.map((item) => String(item.id || '')).filter(Boolean),
    items: evidence.map((item) => ({
      id: String(item.id || ''),
      status: String(item.status || ''),
      title: String(item.title || ''),
      ability: String(item.ability || ''),
      projectName: String(item.projectName || ''),
      observation: String(item.observation || item.content || '').slice(0, 1200),
    })),
    blockedCount: Math.max(0, allEvidence.length - evidence.length),
  };
}

function reportEvidenceSourceAccessible(task, evidence, context = null) {
  const scopedContext = context && String(context.student?.id) === String(task.sourceId) ? context : null;
  const student = scopedContext?.student || readStudentsIndex().map(toHostStudent).find((item) => String(item.id) === String(task.sourceId));
  if (!student) return false;
  const projects = scopedContext?.projects || reportProjectsForStudent(student);
  if (requiresFixedReportEvidence(evidence, projects)) {
    const key = JSON.stringify([evidence.id, evidence.sourceBinding, evidence.content, evidence.ability]);
    if (scopedContext?.fixedResults?.has(key)) return scopedContext.fixedResults.get(key);
    const available = fixedReportEvidenceSources(student, projects, evidence, Boolean(scopedContext?.verifyFixedBytes), scopedContext?.fixedBudget).length > 0;
    scopedContext?.fixedResults?.set(key, available);
    return available;
  }
  return reportEvidenceSourceValues(student, projects, evidence)
    .some((source) => reportEvidenceSourceResolver(student, projects, source).available);
}

function validateReportAutoPublication(task, content) {
  const student = readStudentsIndex().map(toHostStudent)
    .find((item) => String(item.id) === String(task.sourceId));
  if (!student) {
    return {
      valid: false,
      errors: ['报告对应的学生档案不存在'],
      conservative: false,
      citedEvidenceIds: [],
      contentFingerprint: reportContentFingerprint(content),
      studentId: '',
      growthFingerprint: '',
    };
  }
  const growthIndex = safeReadJson(growthIndexPath(student), {});
  const eligibleIds = Array.isArray(task.input?.eligibleEvidenceIds) ? new Set(task.input.eligibleEvidenceIds.map(String)) : null;
  const validationGrowthIndex = eligibleIds
    ? { ...growthIndex, evidence: (Array.isArray(growthIndex.evidence) ? growthIndex.evidence : []).filter((item) => eligibleIds.has(String(item.id || ''))) }
    : growthIndex;
  // One synchronous validation uses one student-scoped metadata snapshot;
  // still resolve/check each citation rather than caching access decisions.
  const sourceContext = { student, projects: reportProjectsForStudent(student), verifyFixedBytes: true,
    fixedBudget: { remaining: 256 * 1024 * 1024 }, fixedResults: new Map() };
  return validateReportDraftForAutoPublish({
    content,
    studentId: String(task.sourceId || ''),
    expectedFingerprint: String(task.input?.growthFingerprint || ''),
    growthIndex: validationGrowthIndex,
    sourceAccessible: (evidence) => reportEvidenceSourceAccessible(task, evidence, sourceContext),
  });
}

function repairReportAutoPublicationDraft(task, content) {
  const student = readStudentsIndex().map(toHostStudent)
    .find((item) => String(item.id) === String(task.sourceId));
  if (!student) return { changed: false, content, corrections: [], reason: 'student_missing' };
  const growthIndex = safeReadJson(growthIndexPath(student), {});
  const eligibleIds = Array.isArray(task.input?.eligibleEvidenceIds) ? new Set(task.input.eligibleEvidenceIds.map(String)) : null;
  const validationGrowthIndex = eligibleIds
    ? { ...growthIndex, evidence: (Array.isArray(growthIndex.evidence) ? growthIndex.evidence : []).filter((item) => eligibleIds.has(String(item.id || ''))) }
    : growthIndex;
  const sourceContext = { student, projects: reportProjectsForStudent(student), verifyFixedBytes: true,
    fixedBudget: { remaining: 256 * 1024 * 1024 }, fixedResults: new Map() };
  return repairReportDraftForAutoPublish({
    content,
    studentId: String(task.sourceId || ''),
    expectedFingerprint: String(task.input?.growthFingerprint || ''),
    growthIndex: validationGrowthIndex,
    requiredSections: task.expectedOutput?.requiredSections || [],
    weekly: task.kind === 'weekly_action',
    expectedDate: String(task.input?.date || taskToday()),
    now: taskNow(),
    sourceAccessible: (evidence) => reportEvidenceSourceAccessible(task, evidence, sourceContext),
  });
}

function reportIssuePath(task) {
  return path.join(taskCenterDirPath(), 'report-issues', `${safeFilename(task.id)}.json`);
}

function persistReportIssue(task, validation) {
  if (!isAutoPublishReportTask(task)) return '';
  const file = reportIssuePath(task);
  const reasons = Array.isArray(validation?.schemaErrors) && validation.schemaErrors.length
    ? validation.schemaErrors
    : Array.isArray(validation?.reportValidation?.errors) && validation.reportValidation.errors.length
      ? validation.reportValidation.errors
      : [validation?.message || '报告校验未通过。'];
  writeJsonAtomic(file, {
    version: 1,
    updatedAt: taskNow(),
    taskId: task.id,
    studentId: task.sourceId,
    reportKind: task.kind,
    status: 'needs_input',
    message: '报告暂未更新，上一版仍可使用；需要补充依据。',
    reasons,
  });
  return file;
}

function autoPublishValidatedReport(task, validation) {
  if (!isAutoPublishReportTask(task) || !validation?.valid) return { ok: false, message: '报告尚未通过自动发布校验。' };
  const draftPath = task.expectedOutput?.draftPath;
  const publishPath = task.expectedOutput?.publishPath;
  if (!draftPath || !publishPath || !fs.existsSync(draftPath)) return { ok: false, message: '报告生成结果不存在。' };
  const draftContent = fs.readFileSync(draftPath, 'utf8');
  const publishedContent = fs.existsSync(publishPath) ? fs.readFileSync(publishPath, 'utf8') : '';
  const periodStart = String(task.input?.periodStart || task.input?.weekStart || task.input?.date || '');
  const publishedStatus = frontmatterValue(publishedContent, 'status').toLowerCase();
  const publishedUpdated = frontmatterValue(publishedContent, 'updated') || frontmatterValue(publishedContent, 'date');
  const unchangedInCurrentPeriod = Boolean(
    publishedContent
    && isPublishableLearningReportStatus(publishedStatus)
    && publishedUpdated >= periodStart
    && reportContentFingerprint(publishedContent) === reportContentFingerprint(draftContent)
  );
  if (unchangedInCurrentPeriod) {
    try { fs.unlinkSync(draftPath); } catch { /* A stale staging file is safe to clean on the next run. */ }
    return { ok: true, unchanged: true, path: publishPath, message: '报告内容无实质变化，保留当前版本。' };
  }
  const published = publishValidatedReport({
    stagingPath: draftPath,
    publishPath,
    updated: taskToday(),
    type: task.kind,
  });
  if (!published.ok) return published;
  try { fs.unlinkSync(draftPath); } catch { /* Publication is already durable; cleanup is best effort. */ }
  return { ...published, unchanged: false, message: '报告已通过自动校验并发布。' };
}

function validateTaskArtifacts(task, startedAt = '', resultPayload = null) {
  const payloadPaths = Array.isArray(resultPayload?.artifacts)
    ? resultPayload.artifacts.map((item) => typeof item === 'string' ? item : item?.path).filter(Boolean)
    : [];
  const paths = [...new Set([
    task.expectedOutput?.draftPath,
    task.expectedOutput?.publishPath,
    task.expectedOutput?.path,
    ...payloadPaths,
  ].filter(Boolean))];
  const artifacts = paths.map((file) => {
    const exists = fs.existsSync(file);
    const stat = exists ? fs.statSync(file) : null;
    return { path: file, exists, size: stat?.size || 0, modifiedAt: stat?.mtime?.toISOString() || '' };
  });
  let valid = artifacts.some((item) => item.exists && item.size > 0 && (!startedAt || Date.parse(item.modifiedAt) >= Date.parse(startedAt) - 1000));
  const schemaErrors = [];
  let reportValidation = null;
  let autoCorrections = [];
  if (task.kind === 'weekly_action' || PERIODIC_REPORT_TASKS[task.kind]) {
    const draft = artifacts.find((item) => item.path === task.expectedOutput?.draftPath);
    valid = Boolean(draft?.exists && draft.size > 0 && (!startedAt || Date.parse(draft.modifiedAt) >= Date.parse(startedAt) - 1000));
    if (valid) {
      let content = fs.readFileSync(draft.path, 'utf8');
      if (task.kind === 'weekly_action') {
        const schema = validateDailyActionDocument(content, {
          expectedDate: String(task.input?.date || ''),
          requiredSections: task.expectedOutput?.requiredSections || [],
        });
        schemaErrors.push(...schema.errors);
      } else {
        schemaErrors.push(...validateSectionedReport(content, task.expectedOutput?.requiredSections || []).errors);
      }
      if (!schemaErrors.length && isAutoPublishReportTask(task)) {
        reportValidation = validateReportAutoPublication(task, content);
        schemaErrors.push(...reportValidation.errors);
      }
      const budget = recoveryBudget(task);
      if (schemaErrors.length && isAutoPublishReportTask(task)
        && budget.correctionAttempts < budget.limits.correctionAttempts) {
        const repaired = repairReportAutoPublicationDraft(task, content);
        if (repaired.changed) {
          const temporaryPath = `${draft.path}.auto-repair-${process.pid}-${Date.now()}`;
          try {
            fs.writeFileSync(temporaryPath, repaired.content, 'utf8');
            fs.renameSync(temporaryPath, draft.path);
          } finally {
            if (fs.existsSync(temporaryPath)) try { fs.unlinkSync(temporaryPath); } catch {}
          }
          content = repaired.content;
          autoCorrections = repaired.corrections;
          task.recoveryBudget = { ...budget, correctionAttempts: budget.correctionAttempts + 1 };
          schemaErrors.length = 0;
          if (task.kind === 'weekly_action') schemaErrors.push(...validateDailyActionDocument(content, {
            expectedDate: String(task.input?.date || ''), requiredSections: task.expectedOutput?.requiredSections || [],
          }).errors);
          else schemaErrors.push(...validateSectionedReport(content, task.expectedOutput?.requiredSections || []).errors);
          if (!schemaErrors.length) {
            reportValidation = validateReportAutoPublication(task, content);
            schemaErrors.push(...reportValidation.errors);
          }
        }
      }
      valid = schemaErrors.length === 0;
    }
  }
  return { valid, artifacts, schemaErrors, reportValidation, autoCorrections, checkedAt: taskNow(), message: valid
    ? autoCorrections.length ? `系统已自动修正 ${autoCorrections.length} 项安全问题，产物校验通过。` : '产物与输出结构校验通过。'
    : schemaErrors.length ? `输出结构校验失败：${schemaErrors.join('；')}。` : '未检测到符合要求的新产物。' };
}

function normalizeTaskResult(task, payload = {}, validation = null, defaults = {}) {
  const artifacts = Array.isArray(payload.artifacts) ? payload.artifacts : (validation?.artifacts || []);
  const startedAt = String(task.startedAt || defaults.startedAt || '');
  const completedAt = String(payload.completedAt || defaults.completedAt || taskNow());
  const durationMs = startedAt ? Math.max(0, Date.parse(completedAt) - Date.parse(startedAt)) : 0;
  return {
    protocolVersion: TASK_PROTOCOL_VERSION,
    taskId: task.id,
    executionId: String(payload.executionId || task.executionId || defaults.executionId || ''),
    status: String(payload.status || defaults.status || 'reviewing'),
    adapterId: String(payload.adapterId || task.adapterId || defaults.adapterId || task.executor || 'manual'),
    summary: String(payload.summary || payload.message || defaults.summary || '任务已返回结果。'),
    message: String(payload.message || defaults.message || ''),
    output: payload.output ?? defaults.output ?? '',
    errorOutput: payload.errorOutput ?? defaults.errorOutput ?? '',
    structuredOutput: payload.structuredOutput ?? payload.data ?? validation?.structuredOutput ?? defaults.structuredOutput ?? null,
    artifacts,
    fileChanges: Array.isArray(payload.fileChanges) ? payload.fileChanges : artifacts.filter((item) => item?.exists !== false && item?.path).map((item) => ({ path: item.path, operation: 'created_or_updated', modifiedAt: item.modifiedAt || '' })),
    logReference: String(payload.logReference || payload.logPath || defaults.logReference || task.result?.logPath || ''),
    validation: validation || payload.validation || { valid: false, message: '尚未校验。' },
    failureReason: payload.failureReason || defaults.failureReason || null,
    retry: { attempt: task.attempt, maxAttempts: task.maxAttempts, nextRetryAt: task.nextRetryAt || '', ...(payload.retry || {}) },
    metrics: { durationMs, estimatedCost: Number(payload.metrics?.estimatedCost || defaults.estimatedCost || 0), qualityScore: validation?.valid ? 100 : 0, ...(payload.metrics || {}) },
    completedAt,
    importedFrom: payload.importedFrom || defaults.importedFrom || '',
    handoffState: String(defaults.handoffState || ''),
    requiresUserAction: Boolean(defaults.requiresUserAction),
  };
}

function commitValidatedTaskResult(store, task, result, validation, options = {}) {
  const successful = Boolean(options.successful && validation?.valid);
  if (!successful) {
    const issuePath = persistReportIssue(task, validation);
    const failedResult = { ...result, status: 'failed' };
    return transitionTaskInStore(store, task.id, options.recoveryUnresolved ? task.status : 'failed', {
      result: { ...failedResult, issuePath },
      error: options.error || { code: 'RESULT_INVALID', message: failedResult.summary || validation?.message || '结果校验未通过。' },
      lastHeartbeatAt: taskNow(),
    }, options.event || 'task_result_failed');
  }
  const reviewingResult = { ...result, status: 'reviewing' };
  const reviewing = transitionTaskInStore(store, task.id, 'reviewing', { result: reviewingResult, error: null, lastHeartbeatAt: taskNow(),
    recoveryState: task.recoveryState === 'unknown' ? 'result_validated' : task.recoveryState || '', nextRetryAt: '', retryRecovery: null,
  }, options.event || 'task_result_validated');
  if (!reviewing.ok) return reviewing;
  if (isAutoPublishReportTask(task)) {
    const publication = autoPublishValidatedReport(task, validation);
    if (!publication.ok) {
      const issuePath = persistReportIssue(task, { ...validation, schemaErrors: [publication.message] });
      return transitionTaskInStore(store, task.id, 'failed', {
        result: { ...reviewingResult, status: 'failed', issuePath },
        error: { code: 'REPORT_AUTO_PUBLICATION_FAILED', message: publication.message },
      }, 'report_auto_publication_failed');
    }
    if (!publication.unchanged) scheduleEducationArchiveVersion(task.sourceId);
    const acceptedAt = taskNow();
    return transitionTaskInStore(store, task.id, 'succeeded', {
      result: { ...reviewingResult, status: 'succeeded', validatedAt: acceptedAt, publishedAt: publication.unchanged ? '' : acceptedAt, publication, summary: publication.message },
      approval: { ...(task.approval || {}), required: false, status: 'not_required', reviewedAt: '', reviewedBy: '' },
      completedAt: acceptedAt,
    }, publication.unchanged ? 'report_unchanged_auto_accepted' : 'report_auto_published');
  }
  if (task.kind === 'publication_enhancement') {
    const acceptedAt = taskNow();
    return transitionTaskInStore(store, task.id, 'succeeded', {
      result: { ...reviewingResult, status: 'succeeded', autoAcceptedAt: acceptedAt, summary: 'Agent 草稿已通过原文依据校验。' },
      approval: { ...(task.approval || {}), required: false, status: 'not_required', reviewedAt: acceptedAt, reviewedBy: 'system_grounding_validation' },
      completedAt: acceptedAt,
    }, 'publication_enhancement_auto_accepted');
  }
  if (!shouldAutoAccept(task, validation) && !RESEARCH_KINDS.has(task.kind)) return reviewing;
  const acceptedAt = taskNow();
  return transitionTaskInStore(store, task.id, 'succeeded', {
    result: { ...reviewingResult, status: 'succeeded', autoAcceptedAt: acceptedAt, summary: options.autoSummary || reviewingResult.summary || '资料处理完成。' },
    approval: { ...(task.approval || {}), required: false, status: 'not_required', reviewedAt: acceptedAt, reviewedBy: 'system_validation' },
    completedAt: acceptedAt,
  }, 'digest_result_auto_accepted');
}

function estimatedAdapterCost(adapterId, durationMs = 0) {
  const base = { internal: 0, manual: 0, qclaw: 0.1, workbuddy: 0.2, openclaw: 0.2, codex: 0.4 }[String(adapterId || '')] ?? 0.2;
  return Number((base + Math.max(0, durationMs) / 3600000 * base).toFixed(4));
}

function digestPayloadLooksUsable(payload) {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return false;
  const hasItems = ['processed', 'digestedFiles', 'digestFiles', 'items', 'processedFiles', 'completedFiles', 'successfulFiles', 'files', 'results', 'failed']
    .some((key) => Array.isArray(payload[key]));
  const status = String(payload.status || payload.digestStatus || payload.state || '');
  const message = String(payload.message || payload.summary || payload.content || '');
  return hasItems
    || /completed|complete|success|succeeded|done|finished|已完成|完成|成功/i.test(status)
    || /(消化完成|处理完成|已完成|完成消化|全部完成)/i.test(message);
}

function extractDigestReceiptPayload(value, depth = 0, seen = new Set()) {
  if (depth > 6 || value === null || value === undefined) return null;
  if (typeof value === 'string') {
    const source = value.trim();
    if (!source) return null;
    const parsed = parseDigestReceipt(source);
    if (parsed.ok) {
      const nested = extractDigestReceiptPayload(parsed.value, depth + 1, seen);
      if (nested) return nested;
    }
    try {
      const envelope = parseAgentResultInput(source, { kind: 'digest' });
      if (digestPayloadLooksUsable(envelope.payload)) return envelope.payload;
    } catch {
      return null;
    }
    return null;
  }
  if (typeof value !== 'object' || seen.has(value)) return null;
  seen.add(value);
  if (digestPayloadLooksUsable(value)) return value;
  const priorityKeys = ['digestResult', 'structuredOutput', 'data', 'result', 'payload', 'response', 'output', 'text', 'message', 'content', 'payloads', 'messages'];
  for (const key of priorityKeys) {
    if (value[key] === undefined) continue;
    const nested = extractDigestReceiptPayload(value[key], depth + 1, seen);
    if (nested) return nested;
  }
  if (Array.isArray(value)) {
    for (const item of value) {
      const nested = extractDigestReceiptPayload(item, depth + 1, seen);
      if (nested) return nested;
    }
  }
  return null;
}

function materializeDigestReceiptFromTaskPayload(task, payload) {
  if (!isDigestTask(task) || !payload) return { ok: false, skipped: true };
  const receipt = extractDigestReceiptPayload(payload);
  if (!receipt) return { ok: false, skipped: true };
  if (task.kind === 'student_digest') {
    const student = readStudentsIndex().map(toHostStudent).find((item) => String(item.id) === String(task.sourceId));
    const batch = student ? readDigestBatch(studentDigestBatchPath(student)) : null;
    if (!student || !batch) return { ok: false, skipped: true, message: '当前学生没有可结算的资料批次。' };
    writeJsonAtomic(studentDigestReceiptPath(student), { ...receipt, schema: receipt.schema || 'edu-manager.digest-result.v1', studentId: String(student.id), digestBatchId: batch.batchId });
    return { ok: true, path: studentDigestReceiptPath(student) };
  }
  const project = readProjects().map(normalizeProject).find((item) => String(item.id) === String(task.sourceId));
  const request = project ? safeReadJson(projectDigestRequestPath(project), {}) : {};
  if (!project) return { ok: false, skipped: true, message: '当前项目不存在。' };
  const digestedFiles = Array.isArray(receipt.digestedFiles) ? receipt.digestedFiles
    : Array.isArray(receipt.processed) ? receipt.processed
      : Array.isArray(receipt.digestFiles) ? receipt.digestFiles
        : Array.isArray(receipt.processedFiles) ? receipt.processedFiles
          : Array.isArray(receipt.items) ? receipt.items
            : [];
  writeJsonAtomic(projectDigestReceiptPath(project), {
    ...receipt,
    status: receipt.status || receipt.digestStatus || (digestedFiles.length ? 'partial' : 'completed'),
    projectId: String(project.id),
    digestBatchId: String(request.digestBatchId || receipt.digestBatchId || receipt.batchId || ''),
    digestedFiles,
  });
  return { ok: true, path: projectDigestReceiptPath(project) };
}

function validateTaskCompletion(task, startedAt = '', resultPayload = null) {
  materializeDigestReceiptFromTaskPayload(task, resultPayload);
  if (task.kind === 'publication_enhancement') {
    const student = findStudentByKey(task.sourceId);
    const source = student ? educationPublicationSource(student, task.input?.sourceType, task.input?.publicationSourceId) : { ok: false };
    const resultPath = String(task.expectedOutput?.path || '');
    let candidate = resultPayload;
    if (resultPath && fs.existsSync(resultPath)) {
      try { candidate = fs.readFileSync(resultPath, 'utf8'); } catch {}
    }
    const validation = source.ok
      ? validateEnhancementCandidate(candidate, source.content, {
        templateId: task.input?.templateId,
        fallbackTitle: source.title,
        fallbackSubtitle: task.input?.sourceType === 'learning_report' ? '学情报告要点' : '教育档案要点',
      })
      : { valid: false, errors: ['出版来源已不存在。'], draft: null, coverage: 0, grounded: 0, total: 0 };
    const droppedSummary = validation.dropped
      ? `已自动剔除 ${validation.dropped} 条无法逐字溯源的内容，保留 ${validation.grounded} 条安全摘录。`
      : '全部条目均已逐字匹配原文。';
    return {
      valid: validation.valid,
      artifacts: resultPath && fs.existsSync(resultPath) ? [{ path: resultPath, exists: true }] : [],
      checkedAt: taskNow(),
      message: validation.valid ? `Agent 草稿已通过证据优先校验。${droppedSummary}` : `Agent 草稿未通过依据校验：${validation.errors.join('；')}`,
      structuredOutput: validation.valid ? {
        schema: EDUCATION_PUBLICATION_ENHANCEMENT_SCHEMA,
        draft: validation.draft,
        coverage: validation.coverage,
        grounded: validation.grounded,
        total: validation.total,
        dropped: validation.dropped,
        warnings: validation.warnings,
      } : null,
    };
  }
  if (task.kind === 'collaboration_assignment' && task.input?.remoteLocalExecution) {
    const output = typeof resultPayload === 'string'
      ? resultPayload
      : String(resultPayload?.output || resultPayload?.message || resultPayload?.summary || '');
    const artifacts = Array.isArray(resultPayload?.artifacts)
      ? resultPayload.artifacts.filter((item) => item?.path && fs.existsSync(item.path))
      : [];
    const valid = Boolean(output.trim() || artifacts.length);
    return {
      valid,
      artifacts,
      checkedAt: taskNow(),
      message: valid ? '远程任务本机执行结果校验通过。' : 'Agent 未返回可回传的结果或附件。',
    };
  }
  if (task.kind === 'project_digest') {
    let domainSync;
    try { domainSync = JSON.parse(syncProjectDigestResult(task.sourceId)); }
    catch { domainSync = { ok: false, message: '项目消化结果同步失败。' }; }
    const status = String(domainSync?.digestState?.status || '');
    return { valid: Boolean(domainSync?.ok && ['completed', 'partial', 'idle'].includes(status)), artifacts: [], checkedAt: taskNow(), message: domainSync?.message || '项目消化结果同步完成。', domainSync };
  }
  if (task.kind === 'student_digest') {
    let domainSync;
    try { domainSync = JSON.parse(syncStudentDigestResult(task.sourceId, { forceSubmitted: true })); }
    catch { domainSync = { ok: false, message: '学生消化结果同步失败。' }; }
    const status = String(domainSync?.state?.status || '');
    const expectedBatchId = String(task.input?.digestBatchId || '');
    const settledBatchId = String(domainSync?.validation?.result?.digestBatchId || domainSync?.state?.lastDigestBatchId || '');
    const strictValid = Boolean(
      domainSync?.ok
      && domainSync?.strict
      && domainSync?.validation?.ok
      && ['completed', 'partial'].includes(status)
      && (!expectedBatchId || settledBatchId === expectedBatchId)
    );
    return {
      valid: strictValid,
      artifacts: [],
      checkedAt: taskNow(),
      message: strictValid
        ? domainSync?.message || domainSync?.state?.message || '学生消化结果同步完成。'
        : domainSync?.message || domainSync?.state?.message || '当前任务尚未取得与批次匹配的逐文件结果。',
      domainSync,
    };
  }
  return validateTaskArtifacts(task, startedAt, resultPayload);
}

function adapterRuntimeFailureMessage(adapterId, output, errorOutput = '') {
  const combined = `${String(output || '')}\n${String(errorOutput || '')}`;
  if (String(adapterId) === 'workbuddy' && workBuddyAuthenticationRequired(output, errorOutput)) {
    return 'WorkBuddy CLI 尚未登录，请先在 WorkBuddy 中完成 CLI 登录后重试。';
  }
  if (String(adapterId) === 'codex' && /requires a newer version of Codex/i.test(combined)) {
    return '当前 Codex CLI 版本过旧，不能运行已配置模型。请升级 Codex 后重试。';
  }
  if (String(adapterId) === 'codex' && /setup refresh had errors|helper_unknown_error/i.test(combined)) {
    return 'Codex 工作区隔离助手初始化失败；任务将保留并按单任务串行方式重试。';
  }
  if (/unsupported model|model .* (?:is not supported|not found)|invalid_request_error/i.test(combined)) {
    return '当前 Agent 无法使用已配置模型，请检查模型配置或升级 Agent 后重试。';
  }
  return '';
}

async function finalizeAdapterExecution(taskId, executionId, adapterId, code, output, errorOutput = '', executionStopped = false) {
  const store = readTaskStore();
  const task = store.tasks.find((item) => item.id === taskId);
  if (!task || task.executionId !== executionId || !['running', 'waiting_result'].includes(task.status)) return;
  const runtimeFailure = adapterRuntimeFailureMessage(adapterId, output, errorOutput);
  const hostDraft = Number(code) === 0 && !runtimeFailure && adapterId === 'codex'
    ? persistHostValidatedCodexDraft(task, output)
    : { attempted: false, ok: true };
  const hostDraftFailure = hostDraft.attempted && !hostDraft.ok ? hostDraft.message : '';
  const completionFailure = runtimeFailure || hostDraftFailure;
  const failureCode = runtimeFailure ? 'AGENT_RUNTIME_INCOMPATIBLE' : hostDraftFailure ? 'HOST_DRAFT_INVALID' : `EXIT_${code}`;
  const validation = Number(code) === 0 && !completionFailure
    ? validateTaskCompletion(task, task.startedAt, String(output || ''))
    : { valid: false, artifacts: [], checkedAt: taskNow(), message: completionFailure || `Agent 退出码 ${code}。` };
  const successful = Number(code) === 0 && !completionFailure && validation.valid;
  store.runtime ||= {}; store.runtime.circuits ||= {};
  store.runtime.circuits[adapterId] = recordCircuitOutcome(store.runtime.circuits[adapterId], {
    success: successful, executionId, failure: { code: failureCode,
      message: `${completionFailure || errorOutput || ''}\n${validation.message || ''}`, category: Number(code) === 0 ? 'validation' : '' },
  });
  const result = normalizeTaskResult(task, {
    executionId,
    status: successful ? 'reviewing' : 'failed',
    adapterId,
    summary: completionFailure || (Number(code) === 0 ? (validation.valid ? ((shouldAutoAccept(task, validation) || isAutoPublishReportTask(task)) ? '任务完成并已通过自动校验。' : 'Agent 执行完成，等待审核。') : validation.message) : `Agent 退出码 ${code}。`),
    output: String(output || '').slice(-20000),
    errorOutput: String(errorOutput || '').slice(-10000),
    structuredOutput: validation.structuredOutput || validation.domainSync || null,
    artifacts: validation.artifacts,
    logReference: task.result?.logPath || '',
    failureReason: successful ? null : { category: runtimeFailure ? 'compatibility' : Number(code) === 0 ? 'validation' : code === -1 ? 'launch' : 'process', code: failureCode, detail: String(completionFailure || errorOutput || validation.message || '').slice(-2000) },
  }, validation, { estimatedCost: estimatedAdapterCost(adapterId, task.startedAt ? Date.now() - Date.parse(task.startedAt) : 0) });
  const retryPlan = successful ? null : taskRetryDecision(task, {
    code: failureCode, message: `${completionFailure || errorOutput || ''}\n${validation.message || ''}`,
    category: Number(code) === 0 ? 'validation' : '',
  }, { stopConfirmed: executionStopped, retryAfter: /(?:^|\n)\s*Retry-After:\s*([^\r\n]+)/i.exec(errorOutput)?.[1] });
  const committed = commitValidatedTaskResult(store, task, result, validation, {
    successful,
    recoveryUnresolved: retryPlan?.recoveryState === 'unknown',
    error: successful ? null : { code: failureCode, message: result.summary },
    event: 'adapter_completed',
    autoSummary: isAutoPublishReportTask(task) ? '报告已通过自动校验。' : '资料处理完成并已通过自动校验。',
  });
  const nextStatus = committed.task?.status || (successful ? 'reviewing' : 'failed');
  if (!successful) {
    const failedTask = store.tasks.find((item) => item.id === taskId);
    if (failedTask) Object.assign(failedTask, retryPlan);
  }
  (await writeTaskStoreDurably(store));
  if (successful) publishCompletedRemoteCollaborationTask(taskId);
  notify('onNativeTaskCenterChanged', JSON.stringify({ taskId, status: nextStatus }));
  if (isDigestTask(task)) notify('onNativeDigestWorkflowChanged', JSON.stringify({ scopeType: task.sourceType, scopeId: task.sourceId, status: nextStatus, taskId }));
  if (retryPlan?.nextRetryAt) scheduleBusinessTaskRetry(store.tasks.find(item => item.id === taskId));
}

function scheduleBusinessTaskRetry(task) {
  if (!taskRetryEligible(task, Infinity)) return;
  businessTaskRetryQueue.schedule(String(task.id), task.adapterId, Math.max(0, Date.parse(task.nextRetryAt) - Date.now()));
}

function restoreBusinessTaskRetries() {
  // Only resume explicitly persisted, versioned decisions. Do not restart old failures.
  for (const task of readTaskStore().tasks) scheduleBusinessTaskRetry(task);
}

function resumeBusinessTaskRetry(taskId, adapterId) {
  if (!taskAutomationEnabled() || !publicLicenseStatus().active || !projectArchiveRuntime.status().ready || taskStoreGuard.status()) {
    businessTaskRetryQueue.schedule(taskId, adapterId, 60000);
    return;
  }
  const task = readTaskStore().tasks.find(item => item.id === String(taskId));
  if (!taskRetryEligible(task)) return;
  if (automaticStudentTaskBlocked(task, findStudentByKey(task.sourceId))) return;
  fallbackTaskAfterFailure(task.id, adapterId, task.error?.message || '计划重试');
}

function fallbackTaskAfterFailure(taskId, failedAdapter, reason = '') {
  try {
    const store = readTaskStore();
    const task = store.tasks.find((item) => item.id === String(taskId));
    if (!task || !['failed', 'timed_out', 'blocked'].includes(task.status)) return { ok: false, skipped: true };
    if (!taskRetryEligible(task)) return { ok: false, skipped: true, message: '尚未到达安全重试时间，或上次执行需要核对。' };
    if (task.automaticExecution !== false && automaticStudentTaskBlocked(task,findStudentByKey(task.sourceId))) return {ok:true,skipped:true,reason:'student_automation_paused'};
    if (task.autoRetry === false || Number(task.attempt || 0) >= Number(task.maxAttempts || 1)) {
      task.nextRetryAt = '';
      task.autoRetry = false;
      task.updatedAt = taskNow();
      writeTaskStore(store);
      appendTaskEvent(task.id, 'automatic_retry_stopped', { attempt: task.attempt, maxAttempts: task.maxAttempts, reason: reason || task.error?.message || '' }, task.executionId);
      return { ok: false, skipped: true, exhausted: true, message: `自动重试已停止（${task.attempt}/${task.maxAttempts}）。` };
    }
    const attempted = [...new Set([...(task.routeAttempts || []), String(failedAdapter || '')].filter(Boolean))];
    const decision = routeTask(task, 'auto', attempted);
    const nextAdapter = selectFallbackAdapter(decision, attempted, task.attempt, task.maxAttempts);
    const prepared = transitionTaskInStore(store, task.id, 'approved', {
      routeDecision: { ...decision, selectedAdapter: nextAdapter, reason: `${reason || '执行失败'}；自动降级为 ${adapterCapabilities()[nextAdapter]?.label || '人工执行'}。` },
      routeAttempts: attempted,
      nextRetryAt: '', retryRecovery: null,
      error: null,
      completedAt: '',
    }, 'runtime_fallback_prepared');
    if (!prepared.ok) return prepared;
    writeTaskStore(store);
    appendTaskEvent(task.id, 'runtime_fallback', { failedAdapter, nextAdapter, reason, attempt: task.attempt }, task.executionId);
    return JSON.parse(executeTaskByAdapter(task.id, nextAdapter, {automatic:task.automaticExecution!==false}));
  } catch (error) {
    appendTaskEvent(taskId, 'runtime_fallback_failed', { failedAdapter, reason, error: error.message });
    return { ok: false, message: error.message };
  }
}

function commandWrapperPath() {
  if (app.isPackaged) return path.join(process.resourcesPath, 'app.asar.unpacked', 'electron', 'invoke-agent.ps1');
  return path.join(__dirname, 'invoke-agent.ps1');
}

function ensureCommandWrapper() {
  const file = commandWrapperPath();
  if (!fs.existsSync(file)) throw new Error(`Agent 参数桥接器不存在：${file}`);
  return file;
}

function resolveNodeCommandShim(executable, args) {
  if (!/\.cmd$/i.test(executable) || !fs.existsSync(executable)) return null;
  const content = fs.readFileSync(executable, 'utf8');
  const match = content.match(/"%dp0%\\([^"\r\n]+\.(?:mjs|cjs|js))"\s+%\*/i);
  if (!match) return null;
  const script = path.resolve(path.dirname(executable), match[1].replace(/\\/g, path.sep));
  if (!fs.existsSync(script)) return null;
  const bundledNode = path.join(path.dirname(executable), 'node.exe');
  return { executable: fs.existsSync(bundledNode) ? bundledNode : process.execPath, args: [script, ...args] };
}

function spawnAdapterProcess(executable, args, options = {}) {
  const nodeShim = resolveNodeCommandShim(executable, args);
  if (nodeShim) return spawn(nodeShim.executable, nodeShim.args, { ...options, shell: false });
  if (/\.(cmd|bat|ps1)$/i.test(executable)) {
    const encodedArgs = Buffer.from(JSON.stringify(args), 'utf8').toString('base64');
    return spawn('powershell.exe', ['-NoProfile', '-NonInteractive', '-ExecutionPolicy', 'Bypass', '-File', ensureCommandWrapper(), '-Executable', executable, '-ArgsBase64', encodedArgs], { ...options, shell: false });
  }
  return spawn(executable, args, { ...options, shell: false });
}

function heartbeatTask(taskId, executionId, detail = '', recordEvent = true) {
  const running = taskChildProcesses.get(String(taskId));
  if (!running || running.executionId !== String(executionId)) return;
  const meaningful = ['extracted', 'batch_completed', 'result_validated', 'committed'].includes(detail);
  taskProgressBuffer.record(String(taskId), String(executionId), taskNow(), String(detail), meaningful);
  if (!taskProgressTimer) {
    taskProgressTimer = setTimeout(() => {
      taskProgressTimer = null;
      try {
        const entries = taskProgressBuffer.entries();
        if (entries.length) taskStoreGuard.writeProgress(taskStorePath(), entries);
        taskProgressBuffer.clear();
      } catch (error) { console.warn('Task progress persistence failed:', error.message); }
    }, 15000);
    taskProgressTimer.unref?.();
  }
}

function clearTaskProcessHeartbeat(taskId) {
  const running = taskChildProcesses.get(String(taskId));
  if (running?.heartbeatTimer) clearInterval(running.heartbeatTimer);
}

function activeAdapterTask(adapterId, excludeTaskId = '') {
  return [...taskChildProcesses.entries()].find(([taskId, run]) => String(taskId) !== String(excludeTaskId)
    && String(run?.adapterId || '') === String(adapterId || '')) || null;
}

function deferTaskForAdapter(task, adapterId, message) {
  const deferredStore = readTaskStore();
  const deferredTask = deferredStore.tasks.find((item) => String(item.id) === String(task.id));
  if (deferredTask) {
    deferredTask.resourceDeferredAt ||= taskNow();
    deferredTask.resourceRetryAt = new Date(Date.now() + 15_000).toISOString();
    deferredTask.resourceAdapterId = adapterId;
    deferredTask.updatedAt = taskNow();
    writeTaskStore(deferredStore);
  }
  scheduleHeavyTaskRetry(task.id, adapterId);
  return { ok: true, deferred: true, taskId: task.id, task: deferredTask || task, retryAfterMs: 15_000, message };
}

function scheduleHeavyTaskRetry(taskId, adapterId) {
  heavyTaskRetryQueue.schedule(String(taskId || ''), adapterId);
}

function resumeResourceDeferredTask(key, adapterId) {
    const task = readTaskStore().tasks.find((item) => String(item.id) === key);
    if (!task || !['pending', 'approved', 'queued'].includes(String(task.status || ''))) return;
    if (task.automaticExecution !== false && !taskAutomationEnabled()) return;
    if (!projectArchiveRuntime.status().ready) { scheduleHeavyTaskRetry(key, adapterId); return; }
    // Do not re-run routing, batch freezing, or capability reads while the
    // foreground is capturing or the shared heavy-work capacity is full.
    if ((adapterId === 'codex' && activeAdapterTask('codex', key))
      || (adapterId === 'workbuddy' && readTaskStore().tasks.some(item => item.id !== key
        && item.adapterId === 'workbuddy' && item.executionMode === 'desktop_handoff'
        && ['running', 'waiting_result'].includes(item.status)))
      || captureHeavyWorkGate.state().length >= adaptiveConcurrency(captureTimelineResourceSnapshot())) {
      scheduleHeavyTaskRetry(key, adapterId);
      return;
    }
    executeTaskByAdapter(key, adapterId, {automatic:task.automaticExecution!==false});
}

function restoreHeavyTaskRetries() {
  for (const task of readTaskStore().tasks) {
    if (['pending', 'approved', 'queued'].includes(String(task.status || '')) && task.resourceDeferredAt && task.resourceAdapterId) {
      scheduleHeavyTaskRetry(task.id, task.resourceAdapterId);
    }
  }
}

async function launchCommandAdapter(task, adapterId, executable, args, cwd, stdinText = '', processOptions = {}) {
  if (adapterId === 'codex' && activeAdapterTask('codex', task.id)) {
    return deferTaskForAdapter(task, adapterId, '已有一个 Codex 任务在执行；本任务已排队，将在前一任务结束后自动启动。');
  }
  const releaseHeavyPermit = captureHeavyWorkGate.tryAcquire({
    kind: `agent_${adapterId}`,
    studentId: task.sourceType === 'student' ? String(task.sourceId || '') : `project:${String(task.sourceId || task.id)}`,
    sessionId: String(task.input?.digestBatchId || task.id),
    snapshot: captureTimelineResourceSnapshot(),
  });
  if (!releaseHeavyPermit) {
    const deferredStore = readTaskStore();
    const deferredTask = deferredStore.tasks.find((item) => String(item.id) === String(task.id));
    if (deferredTask) {
      deferredTask.resourceDeferredAt ||= taskNow();
      deferredTask.resourceRetryAt = new Date(Date.now() + 15_000).toISOString();
      deferredTask.resourceAdapterId = adapterId;
      deferredTask.updatedAt = taskNow();
      (await writeTaskStoreDurably(deferredStore));
    }
    scheduleHeavyTaskRetry(task.id, adapterId);
    return { ok: true, deferred: true, taskId: task.id, retryAfterMs: 15_000, message: '后台资源繁忙，任务已排队并将在资源恢复后自动重试。' };
  }
  heavyTaskRetryQueue.delete(String(task.id));
  const executionId = `run-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`;
  const logDir = path.join(taskExecutionDirPath(), task.id);
  const logPath = path.join(logDir, `${executionId}.log`);
  let store, transition;
  try {
    store = readTaskStore();
    fs.mkdirSync(logDir, { recursive: true });
    transition = transitionTaskInStore(store, task.id, 'running', { executionId, adapterId, executor: adapterId,
    executionMode: 'automatic', attempt: task.attempt + 1, startedAt: taskNow(), lastHeartbeatAt: taskNow(),
    resourceDeferredAt: '', resourceRetryAt: '', resourceAdapterId: '', error: null, result: { logPath } }, 'adapter_started');
  } catch (error) { releaseHeavyPermit(); throw error; }
  if (!transition.ok) { releaseHeavyPermit(); return transition; }
  try {
    (await writeTaskStoreDurably(store));
    fs.writeFileSync(logPath, `task: ${task.id}\nexecution: ${executionId}\nadapter: ${adapterId}\nstarted: ${taskNow()}\n\n`, 'utf8');
  } catch (error) { releaseHeavyPermit(); throw error; }
  let child;
  try {
    assertTaskDispatchCurrent(task.id, executionId);
    child = spawnAdapterProcess(executable, args, {
      cwd: cwd || taskCenterDirPath(),
      windowsHide: true,
      stdio: ['pipe', 'pipe', 'pipe'],
      ...(processOptions.env ? { env: processOptions.env } : {}),
    });
  } catch (error) {
    releaseHeavyPermit();
    (await finalizeAdapterExecution(task.id, executionId, adapterId, -1, '', error.message, true));
    return { ok: false, message: `启动 ${adapterId} 失败：${error.message}` };
  }
  const heartbeatTimer = setInterval(() => heartbeatTask(task.id, executionId, 'process_alive', false), 30 * 1000);
  heartbeatTimer.unref?.();
  taskChildProcesses.set(task.id, { child, executionId, adapterId, startedAt: taskNow(), lastHeartbeatWrite: Date.now(), heartbeatTimer, releaseHeavyPermit });
  let stdout = '';
  let stderr = '';
  const outputLimit = 4 * 1024 * 1024;
  const errorLimit = 512 * 1024;
  const logStream = fs.createWriteStream(logPath, { flags: 'a' });
  let logWritable = true;
  logStream.on('error', () => {
    logWritable = false;
    child.stdout?.resume();
    child.stderr?.resume();
  });
  const collectOutput = (source, chunk, kind) => {
    const value = chunk.toString();
    if (kind === 'stdout') stdout = (stdout + value).slice(-outputLimit);
    else stderr = (stderr + value).slice(-errorLimit);
    if (logWritable && !logStream.write(chunk)) {
      source.pause();
      logStream.once('drain', () => source.resume());
    }
    heartbeatTask(task.id, executionId, kind);
  };
  child.stdout?.on('data', (chunk) => collectOutput(child.stdout, chunk, 'stdout'));
  child.stderr?.on('data', (chunk) => collectOutput(child.stderr, chunk, 'stderr'));
  if (stdinText) child.stdin?.end(stdinText, 'utf8');
  else child.stdin?.end();
  let finalized = false;
  const finish = async (code, error = null) => {
    if (finalized) return;
    finalized = true;
    logWritable = false;
    logStream.end();
    clearTaskProcessHeartbeat(task.id);
    taskChildProcesses.delete(task.id);
    releaseHeavyPermit();
    // A local launcher exiting does not prove remote tool work stopped. Only a
    // failure before a process existed is a confirmed non-execution here.
    (await finalizeAdapterExecution(task.id, executionId, adapterId, Number(code), stdout, error ? `${stderr}\n${error.message}` : stderr, Boolean(error && !child.pid)));
  };
  const settle = (code, error) => { void finish(code, error).catch(failure => console.error('Task completion retained in execution log:', failure.message)); };
  child.on('error', (error) => settle(-1, error));
  child.on('close', (code) => settle(code == null ? -1 : code));
  return { ok: true, task: transition.task, executionId, logPath, message: `已通过 ${adapterId} 启动任务。` };
}

function submitOpenClawTask(task, command) {
  const capability = adapterCapabilities().openclaw;
  if (!capability.available || !capability.exePath) return { ok: false, unavailable: true, message: 'OpenClaw CLI 不可用。' };
  const sessionKey = `agent:main:edu-task-${task.id.replace(/[^a-zA-Z0-9_-]/g, '').slice(-40)}`;
  const modeArgs = capability.gatewayHealthy ? [] : ['--local'];
  return launchCommandAdapter(task, 'openclaw', capability.exePath, ['agent', ...modeArgs, '--message', command, '--json', '--timeout', String(task.timeoutSeconds), '--session-key', sessionKey], task.input?.knowledgeRoot || taskCenterDirPath());
}

async function submitProjectMaterialTask(task, project, requestedExecutor = '', controlledScope = null) {
  let projectExecutionScope = controlledScope?.projectExecutionScope || task.input?.projectExecutionScope || null;
  const globalPolicy = !controlledScope?.student && typeof globalProjectAgentPolicy === 'function'
    ? globalProjectAgentPolicy(project, DIGEST_PROFILE) : null;
  if (!controlledScope?.student && globalPolicy?.enabled) {
    try {
      if (!projectExecutionScope) projectExecutionScope = freezeGlobalProjectExecutionScope(project, DIGEST_PROFILE);
      else if (!currentGlobalProjectExecutionScope(projectExecutionScope, DIGEST_PROFILE)) {
        return { ok: false, code: 'PROJECT_SCOPE_CHANGED', stage: 'not_sent',
          message: '项目成员、知识空间或全局授权已变化，本批次未发送。请由最新项目范围创建新任务。' };
      }
    } catch (error) {
      return { ok: false, code: error.code || 'PROJECT_SCOPE_INVALID', stage: 'not_sent', message: error.message };
    }
  }
  const projectScoped = projectExecutionScope?.contractVersion === 'edu-manager.agent-capabilities.v2';
  const student = controlledScope?.student || (!projectScoped && project.studentIds?.length === 1 ? findStudentByKey(String(project.studentIds[0])) : null);
  if (!student && !projectScoped) return { ok: false, code: 'AGENT_SCOPE_DENIED', message: '旧版授权只允许单学生项目；请先迁移到全局授权。' };
  const routeProject = controlledScope?.student ? null : project;
  const policy = projectScoped ? globalPolicy : agentControlPolicy(student, DIGEST_PROFILE, routeProject);
  if (!policy?.enabled) return { ok: false, code: 'AGENT_SCOPE_DENIED', stage: 'not_sent', message: '全局 Agent 授权未启用，项目任务未发送。' };
  const identity = JSON.stringify(policy);
  const current = () => {
    if (projectScoped) {
      const latestPolicy = globalProjectAgentPolicy(project, DIGEST_PROFILE);
      return Boolean(currentGlobalProjectExecutionScope(projectExecutionScope, DIGEST_PROFILE)
        && JSON.stringify(latestPolicy) === identity);
    }
    const latestStudent = findStudentByKey(String(student.id));
    const latestProject = routeProject ? readProjects().map(normalizeProject).find(p => String(p.id) === String(project.id)) : null;
    return latestStudent && !latestStudent.archived && latestStudent.status !== 'archived'
      && (!routeProject || latestProject?.studentIds?.length === 1 && String(latestProject.studentIds[0]) === String(student.id) && !['archived', 'sealed'].includes(latestProject.status))
      && JSON.stringify(agentControlPolicy(latestStudent, DIGEST_PROFILE, latestProject)) === identity;
  };
  const effectiveScope = { ...(controlledScope || {}), projectExecutionScope, policyCurrent: current };
  if (projectScoped) {
    const scopeStore = readTaskStore(), scopedTask = scopeStore.tasks.find(item => item.id === task.id);
    if (!scopedTask) return { ok: false, code: 'TASK_NOT_FOUND', stage: 'not_sent', message: '任务已移除。' };
    if (scopedTask.input?.projectExecutionScope
      && scopedTask.input.projectExecutionScope.scopeFingerprint !== projectExecutionScope.scopeFingerprint) {
      return { ok: false, code: 'PROJECT_SCOPE_CHANGED', stage: 'not_sent', message: '任务已冻结为其他项目范围，本批次未发送。' };
    }
    scopedTask.input = { ...scopedTask.input, projectExecutionScope };
    scopedTask.permissions = projectScopePermissions(projectExecutionScope);
    task = structuredClone(scopedTask);
    await writeTaskStoreDurably(scopeStore);
  }
  const recovery = task.input?.materialExecution;
  if (policy.enabled && recovery?.batchId && ['output_ready', 'committing', 'committed', 'conflict'].includes(recovery.phase)) {
    return submitProjectMaterialAttempt(task, project, task.adapterId || task.executor || policy.primary, { ...effectiveScope, commitRecovery: true });
  }
  const previous = new Set(task.routeAttempts || []);
  const remaining = require('./agent-control-plane.cjs').providersFor(policy, DIGEST_PROFILE).filter(id => !previous.has(id));
  const dispatchPolicy = { ...policy, global: true, providers: remaining };
  const result = await require('./agent-control-plane.cjs').dispatchAgent({ policy: dispatchPolicy, profile: DIGEST_PROFILE,
    requested: requestedExecutor, current,
    attempt: providerId => submitProjectMaterialAttempt(task, project, providerId, effectiveScope),
    handoff: async () => {
      const store = readTaskStore(), currentTask = store.tasks.find(t => t.id === task.id);
      if (currentTask?.status === 'waiting_result') return { ok: true, task: currentTask };
      const transition = transitionTaskInStore(store, task.id, 'waiting_result', { executionId: `handoff-select-${crypto.randomUUID()}`,
        adapterId: 'manual', executor: 'manual', executionMode: 'manual', autoRetry: false, nextRetryAt: '', result: null,
        message: '后台通道不可用；请在同一任务选择一个手工交接目标，尚未发送资料。' }, 'handoff_target_required');
      if (transition.ok) await writeTaskStoreDurably(store);
      return { ...transition, message: '等待选择手工交接目标，未自动打开任何应用。' };
    },
    record: async decision => {
      const store = readTaskStore(), item = store.tasks.find(t => t.id === task.id);
      if (!item) throw Error('任务已移除');
      item.routeDecision = { mode: 'smart', selectedAdapter: decision.providerId, profile: DIGEST_PROFILE,
        policyVersion: policy.version, reason: decision.stage === 'desktop_handoff' ? '后台不可用，按授权转桌面手工发送' : '按中心授权顺序选择执行器',
        attempts: decision.attempts, stage: decision.stage, decidedAt: taskNow() };
      await writeTaskStoreDurably(store);
    },
  });
  if (!result.ok) {
    const store = readTaskStore(), item = store.tasks.find(t => t.id === task.id);
    if (item && ['approved', 'queued', 'pending', 'blocked'].includes(item.status)) {
      transitionTaskInStore(store, task.id, 'blocked', {
        ...(['possibly_sent', 'unknown'].includes(result.stage) || result.code === 'EXECUTION_UNRESOLVED' ? { recoveryState: 'unknown', autoRetry: false } : {}),
        error: { code: result.code || 'AGENT_ROUTE_BLOCKED', message: result.message },
        nextRetryAt: '', autoRetry: false, message: result.message }, 'agent_route_blocked');
      await writeTaskStoreDurably(store);
      if (controlledScope?.student) writeStudentDigestState(student, { status: 'failed', message: result.message });
      notify('onNativeTaskCenterChanged', JSON.stringify({ taskId: task.id, status: 'blocked' }));
    }
  }
  return result;
}

async function submitProjectMaterialAttempt(task, project, requestedExecutor = '', controlledScope = null) {
  const commitRecovery = controlledScope?.commitRecovery === true;
  const controlledStudent = controlledScope?.student || null;
  const controlledBatch = controlledScope?.batch || null;
  const projectExecutionScope = controlledScope?.projectExecutionScope || task.input?.projectExecutionScope || null;
  const projectScoped = projectExecutionScope?.contractVersion === 'edu-manager.agent-capabilities.v2';
  const policyStudent = controlledStudent || (!projectScoped && project.studentIds?.length === 1 ? findStudentByKey(String(project.studentIds[0])) : null);
  const policyProject = controlledStudent ? null : project;
  const chosen = ['', 'auto', 'smart'].includes(String(requestedExecutor))
    ? String(task.requestedExecutor || project.agentTool || '') : String(requestedExecutor);
  if (!commitRecovery && !providerSupportsProfile(chosen, DIGEST_PROFILE, aiExecutorRegistry())) return { ok: false, code: 'controlled_adapter_required',
    message: '此项目需要已连接且通过资料消化合同验证的结构化执行器，请在 AI 接入与调度中心确认连接状态。' };
  const adapter = commitRecovery ? { id: chosen } : await classificationAdapter(chosen);
  const capability = { ...adapterCapabilities()[chosen], ...(chosen === 'codex' ? { exePath: adapter?.executable } : {}) };
  if (!commitRecovery && (!adapter || adapter.unavailable || (chosen === 'codex' && !capability.exePath))) {
    return { ok: false, code: 'agent_unavailable', message: '所选受控执行器尚未就绪，资料已保留。' };
  }
  const circuit = circuitDecision(readTaskStore().runtime?.circuits?.[chosen]);
  // Authorization is rechecked with synthetic content at this explicit task
  // boundary. Resource/network cooldowns still block execution.
  if (!commitRecovery && !circuit.allowed && circuit.category !== 'authorization') {
    return { ok: false, code: 'EXECUTOR_CIRCUIT_OPEN', message: circuit.reason };
  }
  if (!commitRecovery && chosen === 'codex') {
    const runtimeHash = await require('./smart-inbox-agent.cjs').routingRuntimeHash(adapter);
    const authScope = JSON.stringify([adapter.authScope || '', adapter.authVersion || 0]);
    const saved = readTaskStore().runtime?.agentQualifications?.codex?.[DIGEST_PROFILE];
    if (!saved?.ready || saved.runtimeHash !== runtimeHash || saved.authScope !== authScope || Date.parse(saved.expiresAt) <= Date.now()) {
      const release = !taskChildProcesses.size && captureHeavyWorkGate.tryAcquire({ kind: 'agent_probe', studentId: '', sessionId: `qualification-${task.id}`, snapshot: captureTimelineResourceSnapshot() });
      if (!release) return deferTaskForAdapter(task, chosen, '后台资源忙，稍后验证并继续。');
      try {
        const probe = await require('./task-circuit-probe.cjs').probeControlledCodex(adapter.executable);
        const latest = readTaskStore(); latest.runtime ||= {}; latest.runtime.agentQualifications ||= {}; latest.runtime.agentQualifications.codex ||= {};
        latest.runtime.agentQualifications.codex[DIGEST_PROFILE] = { ...createAgentQualification({ providerId: chosen, profile: DIGEST_PROFILE,
          runtimeHash, ready: probe.passed, message: probe.message }), authScope };
        await writeTaskStoreDurably(latest);
        if (!probe.passed) return { ok: false, code: probe.code === 'execution_unknown' ? 'EXECUTION_UNRESOLVED' : 'AGENT_UNAVAILABLE', message: probe.message };
      } finally { release(); }
    }
  }
  let workBuddyRuntime, qualification;
  if (!commitRecovery && chosen === 'workbuddy') {
    workBuddyRuntime = (await classificationAdapter('workbuddy'))?.runtime;
    if (!workBuddyRuntime) return { ok: false, code: 'AGENT_UNAVAILABLE', message: 'WorkBuddy 后台连接未就绪' };
    if (workBuddyRuntime.cliPath) workBuddyRuntime.version = String(fs.statSync(workBuddyRuntime.cliPath).mtimeMs);
    qualification = workBuddyQualification.peek(workBuddyRuntime);
    if (!qualification) {
      const saved = readTaskStore().runtime?.agentQualifications?.workbuddy?.[DIGEST_PROFILE];
      if (saved?.ready && saved.authScope === JSON.stringify([workBuddyRuntime.configDir || '', workBuddyRuntime.authVersion || 0]) && Date.parse(saved.expiresAt) > Date.now()) qualification = await workBuddyQualification.adopt(workBuddyRuntime, { ...saved, cliHash: saved.runtimeHash });
    }
    if (!qualification) {
      // Recheck only the selected executor at an explicit task boundary. The
      // probe and qualification use synthetic content and run before any
      // student text is extracted or sent.
      const releaseProbe = !taskChildProcesses.size && captureHeavyWorkGate.tryAcquire({ kind: 'agent_probe',
        studentId: '', sessionId: `qualification-${task.id}`, snapshot: captureTimelineResourceSnapshot() });
      if (!releaseProbe) return deferTaskForAdapter(task, chosen, '后台资源忙，空闲后自动校验 WorkBuddy 并继续。');
      try {
        const auth = await workBuddyProbeCache.detect(workBuddyRuntime);
        qualification = auth.authorized ? await workBuddyQualification.check(workBuddyRuntime) : { ready: false,
          code: auth.executionUnknown ? 'execution_unknown' : 'AUTHENTICATION_REQUIRED', message: auth.message };
        await persistWorkBuddyControlledStatus(workBuddyRuntime, auth, qualification);
      } finally { releaseProbe(); }
    }
    if (!qualification?.ready) return {
      ok: false,
      code: qualification?.code === 'execution_unknown' ? 'EXECUTION_UNRESOLVED' : qualification?.code === 'SENSITIVE_REVIEW_REQUIRED' ? 'SENSITIVE_REVIEW_REQUIRED' : /登录|auth/i.test(String(qualification?.message || '')) ? 'AUTHENTICATION_REQUIRED' : 'WORKBUDDY_QUALIFICATION_REQUIRED',
      message: `${qualification?.message || 'WorkBuddy 自动安全校验暂未通过。'} 请在官方 WorkBuddy 中保持登录后重新开始任务；系统会自动复检，不需要单独检测。未发送学生或项目原文。`,
    };
  }
  if (!commitRecovery && chosen === 'llm-api') {
    const settings = await getLlmApiProvider().get();
    const runtime = adapter && !adapter.unavailable ? await getLlmApiProvider().runtime() : null;
    if (!runtime || !settings.lastCheck?.ok || settings.lastCheck.runtimeHash !== runtime.runtimeHash) {
      const releaseProbe = !taskChildProcesses.size && captureHeavyWorkGate.tryAcquire({ kind: 'agent_probe', studentId: '',
        sessionId: `qualification-${task.id}`, snapshot: captureTimelineResourceSnapshot() });
      if (!releaseProbe) return deferTaskForAdapter(task, chosen, '后台资源忙，空闲后自动验证 LLM API 并继续。');
      try { await getLlmApiProvider().verify(); }
      catch (error) { return { ok: false, code: error.code || 'LLM_API_CONFIGURATION_REQUIRED', stage: error.stage || 'not_sent', message: error.message }; }
      finally { releaseProbe(); }
    }
  }
  if (!commitRecovery && adapter?.structuredBuiltin) {
    const releaseProbe = !taskChildProcesses.size && captureHeavyWorkGate.tryAcquire({ kind: 'agent_probe', studentId: '',
      sessionId: `qualification-${task.id}-${chosen}`, snapshot: captureTimelineResourceSnapshot() });
    if (!releaseProbe) return deferTaskForAdapter(task, chosen, `后台资源忙，空闲后自动验证 ${capability.label || chosen} 的资料消化合同。`);
    try { await ensureBuiltinStructuredQualification(adapter, DIGEST_PROFILE); }
    catch (error) { return { ok: false, code: error.code || 'AGENT_CONTRACT_REQUIRED', stage: error.stage || 'not_sent', message: error.message }; }
    finally { releaseProbe(); }
  }
  if (activeAdapterTask(chosen, task.id)) {
    return deferTaskForAdapter(task, chosen, '已有执行器任务在运行；受控项目资料任务已排队等待。');
  }
  const access = controlledStudent ? { project } : mutableProject(project.id, '执行受控项目资料消化');
  if (access.error) return JSON.parse(access.error);
  const releaseHeavyPermit = captureHeavyWorkGate.tryAcquire({ kind: `agent_${chosen}`, studentId: `project:${project.id}`,
    sessionId: task.id, snapshot: captureTimelineResourceSnapshot() });
  if (!releaseHeavyPermit) return deferTaskForAdapter(task, chosen, '后台正在处理其他资料，本任务已排队，空闲后自动继续。');
  const executionId = `material-${crypto.randomUUID()}`;
  let store, transition;
  try {
    store = readTaskStore();
    transition = transitionTaskInStore(store, task.id, 'running', { executionId, adapterId: chosen, executor: chosen,
    executionMode: 'automatic', attempt: Number(task.attempt || 0) + 1, startedAt: taskNow(), lastHeartbeatAt: taskNow(),
    autoRetry: false, nextRetryAt: '', resourceDeferredAt: '', resourceRetryAt: '', resourceAdapterId: '', error: null, result: null,
    ...(projectScoped ? { input: { ...task.input, projectExecutionScope }, permissions: projectScopePermissions(projectExecutionScope) } : {}) }, 'controlled_material_started');
  } catch (error) { releaseHeavyPermit(); throw error; }
  if (!transition.ok) { releaseHeavyPermit(); return transition; }
  try { (await writeTaskStoreDurably(store)); } catch (error) { releaseHeavyPermit(); throw error; }
  const controller = new AbortController();
  const scope = (value) => JSON.stringify([value?.id, value?.status, value?.studentIds, value?.workspacePath,
    value?.rawPath, value?.managerPath, value?.knowledgeRootPath, value?.agentPath, value?.materialStorageMode]);
  const expectedScope = scope(project);
  let runtime;
  try { runtime = createProjectMaterialTask({ project, executionId, executable: capability.exePath,
    executionScope: projectScoped ? projectExecutionScope : null,
    ...(chosen === 'workbuddy' ? {
      verifySandbox: async () => {
        if (!workBuddyQualification.peek(workBuddyRuntime)?.ready) throw new Error('WorkBuddy 受控检测已过期，请重新检测');
        return qualification;
      },
      execute: options => executeMaterialWorkBuddy({ ...options, runtime: workBuddyRuntime, qualification }),
    } : {}),
    ...(typeof adapter.generate === 'function' ? {
      verifySandbox: async () => ({ passed: false, mode: 'host-mediated-no-tools', providerId: chosen }),
      execute: options => require('./project-material-agent.cjs').executeMaterialLlmApi({ ...options, provider: adapter }),
    } : {}),
    timeoutMs: Math.max(30, Number(task.timeoutSeconds || 900)) * 1000, signal: controller.signal,
    checkpoint: task.input?.materialExecution || {},
    authorize: async () => {
      const currentTask = readTaskStore().tasks.find((item) => item.id === task.id);
      const latestStudent = controlledStudent ? readStudentsIndex().map(toHostStudent).find(item => String(item.id) === String(controlledStudent.id)) : null;
      const currentAccess = controlledStudent ? { project: latestStudent ? studentControlledProject(latestStudent, project.managerPath) : null, error: latestStudent ? '' : 'missing' }
        : mutableProject(project.id, '继续受控项目消化');
      const scopeCurrent = projectScoped
        ? Boolean(currentGlobalProjectExecutionScope(projectExecutionScope, DIGEST_PROFILE))
        : scope(currentAccess.project) === expectedScope;
      return (!controlledScope?.policyCurrent || controlledScope.policyCurrent()) && !currentAccess.error && scopeCurrent
        && currentTask?.executionId === executionId && currentTask.status === 'running'
        && !licenseRequiredJson('继续受控项目消化') && validateTaskPermissionDeclaration(currentTask).ok
        && taskPathAllowed(project.knowledgeRootPath, currentTask.permissions?.write || [])
        && (projectScoped
          ? (currentTask.permissions?.read || []).every(item => pathWithinProjectScope(item, projectExecutionScope))
            && (currentTask.permissions?.write || []).every(item => pathWithinProjectScope(item, projectExecutionScope))
          : taskPathAllowed(project.managerPath, currentTask.permissions?.write || []));
    },
    onCheckpoint: async (checkpoint) => {
      const currentStore = readTaskStore();
      const current = currentStore.tasks.find((item) => item.id === task.id);
      if (!current || current.executionId !== executionId || current.status !== 'running') throw Object.assign(new Error('执行归属已失效。'), { code: 'cancelled' });
      current.input = { ...current.input, materialExecution: checkpoint, digestBatchId: checkpoint.batchId || '' };
      current.lastHeartbeatAt = taskNow();
      (await writeTaskStoreDurably(currentStore));
    },
  }); } catch (error) {
    releaseHeavyPermit();
    const failedStore = readTaskStore();
    transitionTaskInStore(failedStore, task.id, 'failed', { error: { code: error.code || 'MATERIAL_SETUP_FAILED', message: error.message } }, 'controlled_material_setup_failed');
    (await writeTaskStoreDurably(failedStore));
    return { ok: false, message: error.message };
  }
  const child = { killed: false, kill() {
    if (!runtime.canCancel) return false;
    this.killed = true; controller.abort(); return true;
  } };
  const heartbeatTimer = setInterval(() => heartbeatTask(task.id, executionId, '受控资料处理', false), 5000);
  heartbeatTimer.unref?.();
  const running = { child, executionId, adapterId: chosen, heartbeatTimer, releaseHeavyPermit,
    materialRuntime: runtime, lastHeartbeatWrite: Date.now() };
  taskChildProcesses.set(task.id, running);
  let safeApiFallback = null;
  running.completion = runtime.run().then(async (output) => {
    const currentStore = readTaskStore();
    const current = currentStore.tasks.find((item) => item.id === task.id);
    if (!current || current.executionId !== executionId || current.status !== 'running') return;
    if (projectScoped && (!currentGlobalProjectExecutionScope(projectExecutionScope, DIGEST_PROFILE)
      || (controlledScope?.policyCurrent && !controlledScope.policyCurrent()))) {
      transitionTaskInStore(currentStore, task.id, 'failed', {
        recoveryState: 'quarantined', autoRetry: false, nextRetryAt: '',
        resultDisposition: 'result_quarantined',
        error: { code: 'scope_changed_after_send', message: '项目成员、知识空间或授权在结果提交前发生变化；结果已隔离，未采纳且不会重复派发。' },
      }, 'project_scope_changed_after_send');
      await writeTaskStoreDurably(currentStore);
      return;
    }
    if (controlledStudent) await finalizeStudentControlledDigest({ student: controlledStudent, batch: controlledBatch,
      receiptPath: studentDigestReceiptPath(controlledStudent), summaryPath: controlledStudent.summaryPath || getSummaryDir(controlledStudent.name), output, now: taskNow });
    const studentValidation = controlledStudent ? validateTaskCompletion(current, current.startedAt, null) : null;
    const validation = studentValidation || { valid: output.fullyCommitted, checkedAt: taskNow(), artifacts: [],
      message: output.fullyCommitted ? `本次资料已全部校验提交；项目仍有 ${output.remainingCount} 份待处理。`
        : output.failures?.length ? `可处理资料已继续执行；${output.failures.length} 份资料提取异常，项目仍有 ${output.remainingCount} 份待处理。请查看逐项原因。`
          : '部分知识提交存在冲突，已保留成功产物及未完成项。' };
    const result = normalizeTaskResult(current, { status: 'reviewing', structuredOutput: output, summary: validation.message }, validation);
    commitValidatedTaskResult(currentStore, current, result, validation, { successful: output.fullyCommitted,
      event: 'controlled_material_finished', autoSummary: validation.message });
    currentStore.runtime ||= {}; currentStore.runtime.circuits ||= {};
    currentStore.runtime.circuits[chosen] = recordCircuitOutcome(currentStore.runtime.circuits[chosen], { success: true, executionId });
    (await writeTaskStoreDurably(currentStore));
  }).catch(async (error) => {
    const currentStore = readTaskStore();
    const current = currentStore.tasks.find((item) => item.id === task.id);
    if (!current || current.executionId !== executionId || current.status !== 'running') return;
    currentStore.runtime ||= {}; currentStore.runtime.circuits ||= {};
    currentStore.runtime.circuits[chosen] = recordCircuitOutcome(currentStore.runtime.circuits[chosen], { success: false,
      executionId, failure: { code: error.code, message: `${error.message} ${error.details?.diagnostic || ''}` } });
    const scopeChanged = projectScoped && error.code === 'project_scope_changed';
    const scopeChangedAfterSend = scopeChanged && ['running', 'output_ready', 'committing'].includes(runtime?.phase);
    const unknown = error.stage === 'unknown' || ['execution_unknown', 'EXECUTION_UNRESOLVED', 'LLM_API_TIMEOUT_UNKNOWN', 'LLM_API_TRANSPORT_UNKNOWN'].includes(error.code);
    transitionTaskInStore(currentStore, task.id, unknown ? current.status : ['cancelled', 'AGENT_CANCELLED'].includes(error.code) ? 'cancelled' : 'failed', {
      ...(unknown ? unknownExecutionPatch(current, 'controlled_stop_unconfirmed') : {}),
      ...(scopeChanged ? { recoveryState: scopeChangedAfterSend ? 'quarantined' : 'stopped',
        resultDisposition: scopeChangedAfterSend ? 'result_quarantined' : 'not_sent' } : {}),
      error: { code: scopeChanged ? (scopeChangedAfterSend ? 'scope_changed_after_send' : 'scope_changed_before_send') : error.code || 'MATERIAL_EXECUTION_FAILED',
        message: scopeChangedAfterSend
          ? '项目范围在正文发送后发生变化；返回结果已隔离，未写入项目知识空间，也不会自动重复派发。'
          : scopeChanged ? '项目范围在正文发送前发生变化；本批次已停止且未发送。' : error.message },
      nextRetryAt: '', autoRetry: false,
    }, 'controlled_material_failed');
    const latestPolicy = projectScoped ? globalProjectAgentPolicy(project, DIGEST_PROFILE)
      : policyStudent ? agentControlPolicy(policyStudent, DIGEST_PROFILE, policyProject) : null;
    const apiAllowed = latestPolicy?.enabled && !commitRecovery;
    const definite = require('./agent-control-plane.cjs').safeToRetry(error)
      && !['output_ready', 'committing', 'committed', 'conflict'].includes(current.input?.materialExecution?.phase);
    if (apiAllowed && definite && (!controlledScope?.policyCurrent || controlledScope.policyCurrent())) {
      const prepared = transitionTaskInStore(currentStore, task.id, 'approved', { executionId: '', adapterId: '', executor: '',
        error: null, message: '执行器明确失败；按全局顺序尝试下一通道，最后为手工交接。',
        routeAttempts: [...new Set([...(current.routeAttempts || []), ...(current.routeDecision?.attempts || []).filter(a => a.stage === 'not_sent').map(a => a.providerId), chosen])],
      }, 'controlled_material_api_fallback_prepared');
      if (prepared.ok) safeApiFallback = prepared.task;
    }
    (await writeTaskStoreDurably(currentStore));
  }).finally(() => {
    clearInterval(heartbeatTimer); releaseHeavyPermit();
    if (taskChildProcesses.get(task.id) === running) taskChildProcesses.delete(task.id);
    notify('onNativeTaskCenterChanged', JSON.stringify({ taskId: task.id }));
    notify('onNativeDigestWorkflowChanged', JSON.stringify({ scopeType: controlledStudent ? 'student' : 'project', scopeId: controlledStudent?.id || project.id, taskId: task.id }));
    if (safeApiFallback) setImmediate(() => { void submitProjectMaterialTask(safeApiFallback, project, 'auto', controlledScope)
      .catch(error => console.warn('LLM API fallback paused:', error.message)); });
  });
  void running.completion.catch(error => console.warn('Controlled result retained; settlement paused:', error.message));
  return { ok: true, task: transition.task, message: '已进入受控处理：验证隔离能力、固定来源版本，然后校验提交知识。' };
}

function submitCodexTask(task, command) {
  const capability = adapterCapabilities().codex;
  if (!capability.available || !capability.exePath) return { ok: false, unavailable: true, message: 'Codex CLI 不可用。' };
  const hostDraftMode = isHostValidatedDraftTask(task);
  const cwd = hostDraftMode
    ? taskCenterDirPath()
    : canonicalTaskPath(task.input?.knowledgeRoot || (task.sourceType === 'project' ? readProjects().map(normalizeProject).find((item) => String(item.id) === task.sourceId)?.knowledgeRootPath : '') || taskCenterDirPath());
  const writableRoots = hostDraftMode ? [] : [...new Set((task.permissions?.write || []).map(canonicalTaskPath).filter(Boolean))];
  const addDirArgs = writableRoots.filter((root) => !taskPathWithin(root, cwd)).flatMap((root) => ['--add-dir', root]);
  const sandboxMode = hostDraftMode || task.input?.remoteLocalExecution ? 'read-only' : 'workspace-write';
  const args = ['exec', '--sandbox', sandboxMode, '--skip-git-repo-check', '--ephemeral', '-C', cwd, ...addDirArgs, '-'];
  return launchCommandAdapter(task, 'codex', capability.exePath, args, cwd, hostDraftMode ? hostValidatedDraftPrompt(command) : command);
}

async function savePreparedTaskResult(task) {
  const store = readTaskStore();
  const current = store.tasks.find(item => item.id === task.id);
  if (!current || current.executionId !== task.executionId || !['running', 'waiting_result'].includes(current.status)) {
    throw Object.assign(new Error('交接批次已变化，旧结果未覆盖当前任务。'), { code: 'DISPATCH_STATE_CHANGED' });
  }
  current.result = task.result;
  await writeTaskStoreDurably(store);
  return current;
}

async function submitWorkBuddyTask(task, command) {
  const waiting = readTaskStore().tasks.find(item => item.id !== task.id && item.adapterId === 'workbuddy'
    && item.executionMode === 'desktop_handoff' && ['running', 'waiting_result'].includes(item.status));
  if (waiting) return deferTaskForAdapter(task, 'workbuddy', `已排队，等待 WorkBuddy 当前任务“${waiting.title}”结束后自动打开。`);
  const capability = adapterCapabilities().workbuddy;
  const runtime = discoverWorkBuddyRuntime(capability?.exePath || findAgentToolInstall('workbuddy').exePath || '', {
    findExecutable: findExecutableInPath,
    hostNodePath: process.execPath,
  });
  if (!runtime.exePath || !fs.existsSync(runtime.exePath)) return { ok: false, unavailable: true, message: 'WorkBuddy 桌面程序不可用。' };
  const cwd = canonicalTaskPath(task.input?.knowledgeRoot || taskCenterDirPath());
  const store = readTaskStore();
  const executionId = `workbuddy-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`;
  const transition = transitionTaskInStore(store, task.id, 'waiting_result', {
    executionId,
    adapterId: 'workbuddy',
    executor: 'workbuddy',
    executionMode: 'desktop_handoff',
    attempt: task.attempt + 1,
    startedAt: taskNow(),
    lastHeartbeatAt: taskNow(),
    resultTimeoutSeconds: 0,
    autoRetry: false,
    nextRetryAt: '',
    result: null,
  }, 'workbuddy_desktop_handoff_prepared');
  if (!transition.ok) return transition;
  Object.assign(transition.task, { resourceDeferredAt: '', resourceRetryAt: '', resourceAdapterId: '' });
  await writeTaskStoreDurably(store);
  assertTaskDispatchCurrent(task.id, executionId);
  let packet;
  try {
    packet = writeTaskPacket(transition.task, workbuddyTaskOutboxPath(), command);
    const desktopCommand = packet.command.length <= 7000
      ? packet.command
      : `请执行教育管家任务 ${task.id}。完整任务指令保存在：${packet.promptPath}\n请先读取该文件，严格遵守其中的资料范围、输出路径和结果回写要求。`;
    const deepLink = buildWorkBuddyTaskDeepLink(runtime, {
      command: desktopCommand,
      cwd,
      welcomeMode: 'work',
      permissionMode: 'default',
    });
    if (!deepLink) throw Error('WorkBuddy 桌面任务入口初始化失败。');
    await new Promise((resolve, reject) => {
      const child = spawn(runtime.exePath, [deepLink], { detached: true, stdio: 'ignore', windowsHide: false, shell: false });
      child.once('error', reject);
      child.once('spawn', () => { child.unref(); resolve(); });
    });
  } catch (error) {
    const failedStore = readTaskStore();
    const current = failedStore.tasks.find(item => item.id === task.id);
    if (current?.executionId === executionId && current.status === 'waiting_result') transitionTaskInStore(failedStore, task.id, 'failed', {
      error: { code: 'WORKBUDDY_DESKTOP_LAUNCH_FAILED', message: error.message },
      lastHeartbeatAt: taskNow(),
      result: { packet, handoffState: 'launch_failed', requiresUserAction: true, summary: packet ? '未能打开 WorkBuddy。指令已保留，可重新打开或复制。' : '未能生成 WorkBuddy 交接包，尚未发送任务，请重试。' },
    }, 'workbuddy_desktop_handoff_failed');
    (await writeTaskStoreDurably(failedStore));
    notify('onNativeTaskCenterChanged', JSON.stringify({ taskId: task.id }));
    return { ok: false, message: `WorkBuddy 桌面端启动失败：${error.message}` };
  }
  transition.task.result = normalizeTaskResult(transition.task, {
    executionId,
    status: 'waiting_result',
    artifacts: [],
  }, null, {
    summary: '已请求打开 WorkBuddy 并尝试预填，尚未确认发送或执行。请检查输入框后发送；未看到内容时可复制本次指令。',
    handoffState: 'awaiting_user_send',
    requiresUserAction: true,
  });
  transition.task.result.packet = packet;
  await savePreparedTaskResult(transition.task);
  appendTaskEvent(task.id, 'workbuddy_desktop_handoff_opened', {
    executionId,
    packet,
    desktopSessionAvailable: Boolean(runtime.desktopSessionAvailable),
  }, executionId);
  return {
    ok: true,
    task: transition.task,
    packet,
    message: '已请求打开 WorkBuddy。请检查输入框后发送；尚未确认领取，不代表已经执行。',
  };
}

async function submitModernAgentTask(task, command, agentId) {
  const capability = adapterCapabilities()[agentId];
  if (!capability?.available) return { ok: false, unavailable: true, message: `${capability?.label || agentId} 不可用。` };
  const cwd = canonicalTaskPath(task.input?.knowledgeRoot || (task.sourceType === 'project'
    ? readProjects().map(normalizeProject).find((item) => String(item.id) === String(task.sourceId))?.knowledgeRootPath : '') || taskCenterDirPath());
  const readOnly = isHostValidatedDraftTask(task) || task.input?.remoteLocalExecution
    || !Array.isArray(task.permissions?.write) || task.permissions.write.length === 0;
  const additionalRoots = [...new Set([...(task.permissions?.read || []), ...(task.permissions?.write || [])]
    .map(canonicalTaskPath).filter(Boolean))];
  const invocation = agentId === 'trae'
    ? buildTraeInvocation({ cliPath: capability.cliPath }, { cwd, command, readOnly })
    : buildQoderInvocation({ cliPath: capability.cliPath }, { cwd, command, readOnly, additionalRoots });
  if (invocation) {
    return (await launchCommandAdapter(task, agentId, invocation.executable, invocation.args, invocation.cwd, invocation.stdinText));
  }
  const handoff = (await submitAgentHandoffTask(task, command, agentId));
  if (handoff.ok) {
    openApp(agentId);
    return { ...handoff, message: `已打开 ${capability.label} 并复制任务指令。当前桌面版没有可验证的外部自动发送接口，请粘贴后发送；结果仍由教育管家自动校验。` };
  }
  return handoff;
}

async function submitQClawInboxTask(task, command) {
  const store = readTaskStore();
  const executionId = `qclaw-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`;
  const transition = transitionTaskInStore(store, task.id, 'waiting_result', {
    executionId,
    adapterId: 'qclaw',
    executor: 'qclaw',
    executionMode: 'inbox',
    attempt: task.attempt + 1,
    startedAt: taskNow(),
    lastHeartbeatAt: taskNow(),
    resultTimeoutSeconds: 24 * 60 * 60,
    autoRetry: false,
    nextRetryAt: '',
    result: null,
  }, 'qclaw_inbox_prepared');
  if (!transition.ok) return transition;
  await writeTaskStoreDurably(store);
  assertTaskDispatchCurrent(task.id, executionId);
  const packet = writeTaskPacket(transition.task, qclawTaskInboxPath(), command);
  transition.task.result = normalizeTaskResult(transition.task, { executionId, status: 'waiting_result', artifacts: [] }, null, { summary: '任务已写入 QClaw 收件箱。' });
  transition.task.result.packet = packet;
  await savePreparedTaskResult(transition.task);
  appendTaskEvent(task.id, 'qclaw_inbox_written', { executionId, packet }, executionId);
  return transition.ok ? { ok: true, task: transition.task, packet, message: '任务已写入 QClaw 任务收件箱，等待领取和结果回写。' } : transition;
}

async function submitQClawTask(task, command) {
  if (process.env.EDU_QCLAW_INBOX_BRIDGE === '1') return (await submitQClawInboxTask(task, command));
  const capability = adapterCapabilities().qclaw;
  const runtime = discoverQClawRuntime(capability.exePath || findAgentToolInstall('qclaw').exePath || '');
  if (runtime.available && capability.gatewayHealthy) {
    const agentId = selectQClawAgentId(runtime, task);
    const sessionKey = `agent:${agentId}:edu-task-${task.id.replace(/[^a-zA-Z0-9_-]/g, '').slice(-40)}`;
    const args = [
      runtime.cliPath,
      'agent',
      '--agent',
      agentId,
      '--message',
      command,
      '--json',
      '--timeout',
      String(task.timeoutSeconds),
      '--session-key',
      sessionKey,
    ];
    const launched = (await launchCommandAdapter(
      task,
      'qclaw',
      runtime.nodePath,
      args,
      task.input?.knowledgeRoot || taskCenterDirPath(),
      '',
      { env: qclawRuntimeEnv(runtime) },
    ));
    return launched.ok
      ? { ...launched, message: `已交给 QClaw 的「${agentId}」自动执行；完成回执将由系统自动校验。` }
      : launched;
  }
  const fallback = (await submitManualTask(task, command, 'QClaw 已安装，但自动执行 Gateway 尚未连接。'));
  if (fallback.ok) {
    openApp('qclaw');
    appendTaskEvent(task.id, 'qclaw_manual_fallback', { gatewayPort: runtime.port || 0, reason: capability.healthMessage || 'gateway_unavailable' }, fallback.task?.executionId || '');
  }
  return fallback.ok
    ? { ...fallback, message: '已打开 QClaw 并复制本批次指令。请粘贴执行；标准回执写回后会自动完成校验。' }
    : fallback;
}

async function submitManualTask(task, command, reason = '') {
  const store = readTaskStore();
  const executionId = `manual-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`;
  const transition = transitionTaskInStore(store, task.id, 'waiting_result', {
    executionId,
    adapterId: 'manual',
    executor: 'manual',
    executionMode: 'manual',
    attempt: task.attempt + 1,
    startedAt: taskNow(),
    lastHeartbeatAt: taskNow(),
    resultTimeoutSeconds: 0,
    autoRetry: false,
    nextRetryAt: '',
    result: null,
  }, 'manual_execution_prepared');
  if (transition.ok) {
    await writeTaskStoreDurably(store);
    assertTaskDispatchCurrent(task.id, executionId);
    const packet = writeTaskPacket(transition.task, taskManualOutboxPath(), command);
    clipboard.writeText(packet.command);
    transition.task.result = normalizeTaskResult(transition.task, { executionId, status: 'manual_required', artifacts: [] }, null, { summary: '任务已降级为人工执行。' });
    transition.task.result.packet = packet;
    await savePreparedTaskResult(transition.task);
    appendTaskEvent(task.id, 'manual_packet_exported', { executionId, packet }, executionId);
    return { ok: true, task: transition.task, packet, command: packet.command, fallback: true, message: `${reason || '任务已转为人工执行。'}任务指令已复制，并导出人工任务包。` };
  }
  return transition;
}

async function submitAgentHandoffTask(task, command, agentId) {
  const capability = aiExecutorRegistry().find(p => p.id === agentId && p.handoff);
  if (!capability) return { ok: false, message: '未找到该 Agent 的任务交接通道。' };
  const global = agentControlStore().read().global;
  if (global && (!global.enabled || global.disabledProviders.includes(agentId))) return { ok: false, code: 'AGENT_SCOPE_DENIED', message: '全局授权或所选执行器已停用。' };
  if (task.sourceType === 'student') {
    const sourceStudent = findStudentByKey(String(task.sourceId));
    if (!sourceStudent || sourceStudent.archived || sourceStudent.status === 'archived') return { ok: false, code: 'AGENT_SCOPE_DENIED', message: '学生范围已失效，未发送资料。' };
  }
  if (task.sourceType === 'project' && mutableProject(task.sourceId, '手工交接任务').error) return { ok: false, code: 'AGENT_SCOPE_DENIED', message: '项目范围已封存或不可访问。' };
  const store = readTaskStore();
  const executionId = `${agentId}-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`;
  const transition = transitionTaskInStore(store, task.id, 'waiting_result', {
    executionId, adapterId: agentId, executor: agentId, executionMode: 'agent_handoff',
    attempt: task.attempt + 1, startedAt: taskNow(), lastHeartbeatAt: taskNow(),
    resultTimeoutSeconds: 0, autoRetry: false, nextRetryAt: '', result: null,
  }, 'agent_handoff_prepared');
  if (!transition.ok) return transition;
  await writeTaskStoreDurably(store);
  assertTaskDispatchCurrent(task.id, executionId);
  const packet = writeTaskPacket(transition.task, agentTaskInboxPath(agentId), command);
  clipboard.writeText(packet.command);
  transition.task.result = normalizeTaskResult(transition.task, { executionId, status: 'waiting_result', artifacts: [] }, null,
    { summary: `已为 ${capability.label} 准备任务包，等待发送及结果回写。` });
  transition.task.result.packet = packet;
  await savePreparedTaskResult(transition.task);
  appendTaskEvent(task.id, 'agent_handoff_exported', { agentId, packet }, executionId);
  return { ok: true, task: transition.task, packet, command: packet.command,
    message: `已复制 ${capability.label} 任务指令，请粘贴到该 Agent 执行；结果回写后自动校验，也可导入返回的结果。` };
}

async function submitInternalTask(task) {
  const store = readTaskStore();
  const executionId = `internal-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`;
  const transition = transitionTaskInStore(store, task.id, 'running', { executionId, adapterId: 'internal', executor: 'internal', executionMode: 'internal', attempt: task.attempt + 1, startedAt: taskNow(), lastHeartbeatAt: taskNow(), error: null }, 'internal_operation_started');
  if (!transition.ok) return transition;
  (await writeTaskStoreDurably(store));
  const context = { taskId: task.id, executionId };
  assertTaskDispatchCurrent(task.id, executionId);
  let operation;
  if (task.input?.operation === 'execute_archive_plan') operation = performProjectPromotionPlan(task.sourceId, JSON.stringify(task.input?.plan || {}), context);
  else if (task.input?.operation === 'publish_growth_evidence') operation = performPublishProjectPromotion(task.sourceId, context);
  else if (task.input?.operation === 'rollback_promotion') operation = performRollbackProjectPromotionRun(task.sourceId, task.input?.runId, context);
  else if (task.input?.operation === 'topic_suggestion_refresh' && task.kind === 'topic_suggestion_refresh'
    && task.sourceType === 'student' && String(task.input?.studentId) === String(task.sourceId)) {
    // The internal adapter performs a local evidence-based refresh, not a hidden
    // model call that bypasses the shared Agent queue or user's executor choice.
    operation = JSON.stringify(planningGuidanceService().refreshTopicSuggestions(task.sourceId));
  }
  else operation = JSON.stringify({ ok: false, message: `未知内部操作：${task.input?.operation || '-'}` });
  const finish = async (serialized) => {
  const operationResult = JSON.parse(serialized);
  const nextStore = readTaskStore();
  const current = nextStore.tasks.find((item) => item.id === task.id);
  if (!current || current.executionId !== executionId || current.status !== 'running') return { ok: false, message: '任务执行上下文已变化，未覆盖新的任务状态。' };
  const changedPaths = [...new Set([
    ...(operationResult.results || []).map((item) => item.target),
    ...(operationResult.published || []).flatMap((item) => [item.growthDir, item.projectSummaryFile]),
    operationResult.executionLog,
    operationResult.path,
  ].filter(Boolean))];
  const artifacts = changedPaths.map((file) => ({ path: file, exists: fs.existsSync(file), size: fs.existsSync(file) && fs.statSync(file).isFile() ? fs.statSync(file).size : 0, modifiedAt: fs.existsSync(file) ? fs.statSync(file).mtime.toISOString() : '' }));
  const validation = { valid: Boolean(operationResult.ok), artifacts, checkedAt: taskNow(), message: operationResult.message || (operationResult.ok ? '内部操作校验通过。' : '内部操作失败。') };
  const nextStatus = operationResult.ok ? task.kind === 'topic_suggestion_refresh' ? 'succeeded' : 'reviewing' : 'failed';
  const result = normalizeTaskResult(current || transition.task, { status: nextStatus, structuredOutput: operationResult, artifacts, fileChanges: changedPaths.map((file) => ({ path: file, operation: 'created_or_updated' })) }, validation, { adapterId: 'internal', executionId, summary: operationResult.message });
  if (nextStatus === 'succeeded') {
    const checked = transitionTaskInStore(nextStore, task.id, 'reviewing', { result }, 'local_topic_validated');
    if (!checked.ok) return checked;
  }
  const completed = transitionTaskInStore(nextStore, task.id, nextStatus, { result, lastHeartbeatAt: taskNow(), error: operationResult.ok ? null : { code: 'INTERNAL_OPERATION_FAILED', message: operationResult.message || '内部操作失败。' } }, 'internal_operation_completed');
  (await writeTaskStoreDurably(nextStore));
  if (operationResult.ok && operationResult.transactionId) void projectArchiveStartupManager().complete(operationResult.transactionId).catch(() => {});
  notify('onNativeTaskCenterChanged', JSON.stringify({ taskId: task.id, status: nextStatus }));
  return { ...completed, message: nextStatus === 'succeeded' ? `${operationResult.message} 仅更新待选建议，未形成正式成长结论。` : operationResult.ok ? '内部操作已执行，等待结果审核。' : operationResult.message };
  };
  if (operation && typeof operation.then === 'function') {
    const heartbeatTimer = setInterval(() => heartbeatTask(task.id, executionId, '固定归档来源版本', false), 5000);
    heartbeatTimer.unref?.();
    // Reuse lifecycle protection: no shutdown, watchdog or cancellation may
    // interrupt this high-risk internal operation halfway through its writes.
    const running = { executionId, adapterId: 'internal', heartbeatTimer,
      child: { killed: false, kill: () => false }, materialRuntime: { canCancel: false } };
    taskChildProcesses.set(task.id, running);
    running.completion = operation.then(finish).catch((error) => finish(JSON.stringify({ ok: false,
      message: `内部归档失败：${error.message}` }))).finally(() => {
      clearInterval(heartbeatTimer);
      if (taskChildProcesses.get(task.id) === running) taskChildProcesses.delete(task.id);
      notify('onNativeTaskCenterChanged', JSON.stringify({ taskId: task.id }));
    });
    void running.completion.catch(error => console.warn('Internal result retained; settlement paused:', error.message));
    return { ok: true, task: transition.task, message: '正在校验并固定归档来源版本；完成后进入结果审核。' };
  }
  return finish(operation);
}

function getAgentExecutionAdapters() {
  const common = { status: adapterTaskStatus, readResult: adapterTaskResult };
  const adapters = {
    ...Object.fromEntries(Object.keys(handoffAgentCapabilities()).map((id) => [id, {
      ...common, id, capabilities: () => adapterCapabilities()[id],
      submit: (task, command) => submitAgentHandoffTask(task, command, id),
      cancel: () => ({ ok: true }), health: () => adapterCapabilities()[id],
    }])),
    internal: { ...common, id: 'internal', capabilities: () => adapterCapabilities().internal, submit: (task, command) => submitInternalTask(task, command), cancel: (task) => cancelInternalTask(task), health: () => adapterCapabilities().internal },
    openclaw: { ...common, id: 'openclaw', capabilities: () => adapterCapabilities().openclaw, submit: (task, command) => submitOpenClawTask(task, command), cancel: (task) => cancelRunningAdapterTask(task.id), health: () => adapterCapabilities(true).openclaw },
    codex: { ...common, id: 'codex', capabilities: () => adapterCapabilities().codex, submit: (task, command) => submitCodexTask(task, command), cancel: (task) => cancelRunningAdapterTask(task.id), health: () => adapterCapabilities(true).codex },
    workbuddy: { ...common, id: 'workbuddy', capabilities: () => adapterCapabilities().workbuddy, submit: (task, command) => submitWorkBuddyTask(task, command), cancel: (task) => cancelRunningAdapterTask(task.id), health: () => adapterCapabilities(true).workbuddy },
    trae: { ...common, id: 'trae', capabilities: () => adapterCapabilities().trae, submit: (task, command) => submitModernAgentTask(task, command, 'trae'), cancel: (task) => cancelRunningAdapterTask(task.id), health: () => adapterCapabilities(true).trae },
    'qoder-work': { ...common, id: 'qoder-work', capabilities: () => adapterCapabilities()['qoder-work'], submit: (task, command) => submitModernAgentTask(task, command, 'qoder-work'), cancel: (task) => cancelRunningAdapterTask(task.id), health: () => adapterCapabilities(true)['qoder-work'] },
    qclaw: { ...common, id: 'qclaw', capabilities: () => adapterCapabilities().qclaw, submit: (task, command) => submitQClawTask(task, command), cancel: () => ({ ok: false, message: 'QClaw 收件箱任务需要在 QClaw 侧停止。' }), health: () => adapterCapabilities(true).qclaw },
    manual: { ...common, id: 'manual', capabilities: () => adapterCapabilities().manual, submit: (task, command, context = {}) => submitManualTask(task, command, context.reason), cancel: () => ({ ok: true }), health: () => adapterCapabilities().manual },
  };
  for (const executor of aiExecutorRegistry()) {
    if (adapters[executor.id]) continue;
    adapters[executor.id] = { ...common, id: executor.id, capabilities: () => adapterCapabilities()[executor.id],
      submit: (task, command) => executor.handoff ? submitAgentHandoffTask(task, command, executor.id)
        : { ok: false, code: 'UNSUPPORTED_TASK_CONTRACT', message: '此通道仅支持中心列出的结构化任务，请使用对应任务入口。' },
      cancel: task => cancelRunningAdapterTask(task.id), health: () => adapterCapabilities()[executor.id] };
  }
  return adapters;
}

function cancelInternalTask(task) {
  const running = taskChildProcesses.get(String(task?.id || ''));
  if (!running) return { ok: true, stopConfirmed: true, message: '内置任务已不在运行。' };
  if (running.materialRuntime && !running.materialRuntime.canCancel) {
    return { ok: false, stopConfirmed: false, message: '知识正在校验提交，暂不能取消。' };
  }
  if (running.researchType === 'competition') {
    try { planningGuidanceService().cancelCompetitionResearch(running.studentId); } catch {}
  } else if (running.researchType === 'guidance') {
    try { planningGuidanceService().cancelGuidanceResearch(running.studentId); } catch {}
  }
  clearTaskProcessHeartbeat(task?.id);
  const stopped = running.child?.killed || running.child?.kill?.() !== false;
  return { ok: stopped, stopConfirmed: stopped, message: stopped ? '内置任务已停止；迟到结果不会被采用。' : '内置任务暂未停止。' };
}

function cancelRunningAdapterTask(taskId) {
  const running = taskChildProcesses.get(String(taskId));
  if (!running?.child || running.child.killed) return { ok: false, message: '没有正在运行的进程。' };
  clearTaskProcessHeartbeat(taskId);
  running.child.once?.('close', () => {
    try {
      const store = readTaskStore();
      const task = store.tasks.find(item => item.id === String(taskId));
      if (task?.executionId === running.executionId && task.recoveryState === 'unknown' && task.status === 'cancelled') {
        // A launcher exiting does not prove its children or remote job stopped.
        const source = executionProvenance(task).providerLabel;
        task.error = { code: 'CANCEL_STOP_UNCONFIRMED', message: `本机启动进程已退出，但 ${source} 的任务状态尚未确认。系统将先查询回执；已取消结果不会自动入库。` };
        writeTaskStore(store);
        notify('onNativeTaskCenterChanged', JSON.stringify({ taskId }));
      }
    } catch (error) { console.error('取消状态保存失败', error.message); }
    if (taskChildProcesses.get(String(taskId)) === running) taskChildProcesses.delete(String(taskId));
  });
  running.child.kill();
  return { ok: true, stopConfirmed: false, message: '已请求停止，等待进程退出确认。' };
}

function adapterTaskStatus(task) {
  const running = taskChildProcesses.get(String(task?.id || ''));
  return { ok: true, taskId: task?.id || '', status: running?.child && !running.child.killed ? 'running' : task?.status || 'unknown', executionId: task?.executionId || '', lastHeartbeatAt: task?.lastHeartbeatAt || '' };
}

function adapterTaskResult(task) {
  return { ok: Boolean(task?.result), taskId: task?.id || '', result: task?.result || null };
}

function attachDigestBatchToTask(taskId, batch, manifestPath, receiptPath) {
  const store = readTaskStore();
  const index = store.tasks.findIndex((item) => String(item.id) === String(taskId));
  if (index < 0) return null;
  const current = store.tasks[index];
  store.tasks[index] = normalizeTaskEnvelope({
    ...current,
    idempotencyKey: batch.idempotencyKey || current.idempotencyKey,
    completionPolicy: 'auto_after_validation',
    input: { ...(current.input || {}), digestBatchId: batch.batchId, manifestPath },
    expectedOutput: { ...(current.expectedOutput || {}), path: receiptPath, type: 'digest_receipt_v1' },
  }, current);
  writeTaskStore(store);
  return store.tasks[index];
}

function submitCompetitionResearchTask(task) { return submitResearchTask(task, 'competition'); }
function submitGuidanceResearchTask(task) { return submitResearchTask(task, 'guidance'); }

async function submitResearchTask(task, type) {
  const capability = planningGuidanceService().getResearchCapabilityStatus();
  if (!capability.available) {
    const blockedStore = readTaskStore();
    const blocked = transitionTaskInStore(blockedStore, task.id, 'blocked', {
      error: { code: 'RESEARCH_CAPABILITY_UNAVAILABLE', message: capability.message }, nextRetryAt: '',
    }, 'research_capability_blocked');
    if (blocked.ok) (await writeTaskStoreDurably(blockedStore));
    return { ...blocked, ok: false, blocked: true, message: capability.message };
  }
  const existing = [...taskChildProcesses.values()].find(run => run.researchType === type && run.studentId === task.sourceId);
  if (existing) return { ok: true, task: readTaskStore().tasks.find(t => t.id === existing.taskId), message: '已复用当前学生的研究任务。' };
  const controller = new AbortController();
  const executionId = `research-${crypto.randomUUID()}`;
  const store = readTaskStore();
  const tasks = type === 'guidance'
    ? store.tasks.filter(t => t.sourceId === task.sourceId && ['guidance_research_check', 'guidance_plan_refresh'].includes(t.kind)
      && (t.id === task.id || ['pending', 'queued', 'approved', 'blocked'].includes(t.status)
        || (t.status === 'failed' && t.executionId === task.executionId)))
    : [store.tasks.find(t => t.id === task.id)];
  const startedIds = [];
  for (const current of tasks) {
    if (!current || ['cancelled', 'running', 'waiting_result'].includes(current.status)) continue;
    if (!['approved', 'queued'].includes(current.status)) {
      const prepared = transitionTaskInStore(store, current.id, 'approved', {}, 'research_task_prepared');
      if (!prepared.ok) return prepared;
    }
    const started = transitionTaskInStore(store, current.id, 'running', {
      executionId, adapterId: 'internal', executor: 'internal', executionMode: 'internal',
      attempt: Number(current.attempt || 0) + 1, startedAt: taskNow(), lastHeartbeatAt: taskNow(),
      automaticExecution: task.automaticExecution, error: null, result: null, autoRetry: false, nextRetryAt: '',
    }, `${type}_research_started`);
    if (!started.ok) return started;
    startedIds.push(current.id);
  }
  if (!startedIds.includes(task.id)) return { ok: false, message: '当前研究任务不能启动。' };
  (await writeTaskStoreDurably(store));
  const heartbeatTimer = setInterval(() => startedIds.forEach(id => heartbeatTask(id, executionId, '官方来源研究', false)), 5000);
  heartbeatTimer.unref?.();
  const running = { executionId, adapterId: 'internal', heartbeatTimer, researchType: type, studentId: task.sourceId, taskId: task.id,
    child: { killed: false, kill() { this.killed = true; controller.abort(); return true; } }, completion: null };
  startedIds.forEach(id => taskChildProcesses.set(id, running));
  const context = { signal: controller.signal, trigger: task.trigger || 'schedule',
    executionContext: { taskId: task.id, executionId, researchRunId: executionId } };
  running.completion = Promise.resolve().then(() => type === 'competition'
    ? planningGuidanceService().refreshCompetitionRecommendations(task.sourceId, context)
    : planningGuidanceService().refreshGuidancePlan(task.sourceId, context)).then(async output => {
    if (controller.signal.aborted) throw Object.assign(new Error('研究已取消。'), { code: 'RESEARCH_CANCELLED' });
    const identityMatches = output.receipt?.taskId === task.id && output.receipt?.executionId === executionId;
    if (!identityMatches) output = { ...output, ok: false, message: '研究回执与当前执行批次不匹配。' };
    const currentStore = readTaskStore();
    for (const id of startedIds) {
      const current = currentStore.tasks.find(item => item.id === id);
      if (!current || current.executionId !== executionId || current.status !== 'running') continue;
      const receipt = output.receipt && { ...output.receipt, taskId: id };
      const validation = { ...researchResultValidation(current, { ...output, receipt }), checkedAt: taskNow() };
      const result = normalizeTaskResult(current, { structuredOutput: { receipt, versionId: output.current?.id }, artifacts: [], fileChanges: [] },
        validation, { adapterId: 'internal', executionId, summary: output.message });
      const committed = commitValidatedTaskResult(currentStore, current, result, validation, {
        successful: validation.valid, event: `${type}_research_completed`, autoSummary: output.message,
        error: { code: output.receipt?.code || 'RESEARCH_RESULT_INVALID', message: output.message },
      });
      if (!committed.ok) throw new Error(`研究任务收尾失败：${committed.message}`);
      Object.assign(committed.task, validation.valid ? { autoRetry: false, nextRetryAt: '' }
        : researchRetryPatch(current, output.receipt));
    }
    (await writeTaskStoreDurably(currentStore));
    return output;
  }).catch(async error => {
    const currentStore = readTaskStore();
    for (const id of startedIds) {
      const current = currentStore.tasks.find(item => item.id === id);
      if (current?.executionId !== executionId || !['running', 'reviewing'].includes(current.status)) continue;
      const failed = transitionTaskInStore(currentStore, id, controller.signal.aborted ? 'cancelled' : 'failed', {
        error: { code: error.code || 'RESEARCH_EXECUTION_FAILED', message: error.message },
        ...researchRetryPatch(current, error),
      }, `${type}_research_failed`);
      if (!failed.ok) appendTaskEvent(id, 'research_settlement_rejected', { message: failed.message }, executionId);
    }
    (await writeTaskStoreDurably(currentStore));
    return { ok: false, message: error.message };
  }).finally(() => {
    clearInterval(heartbeatTimer);
    for (const id of startedIds) if (taskChildProcesses.get(id) === running) taskChildProcesses.delete(id);
    notify('onNativeTaskCenterChanged', JSON.stringify({ taskId: task.id }));
  });
  void running.completion.catch(error => console.warn('Research result retained; settlement paused:', error.message));
  return { ok: true, task: store.tasks.find(t => t.id === task.id), message: '正在异步核验官方来源；结果通过校验后自动完成。' };
}

async function refreshGuidanceThroughTask(studentId, request = {}) {
  await refreshAdapterCapabilities(true);
  upsertTaskCandidates(buildTaskCenterCandidates(), { reconcileInactiveStudents: true });
  const taskId = taskStableId('guidance_research_check', 'student', studentId);
  const active = taskChildProcesses.get(taskId);
  if (active) return await active.completion;
  const student = findStudentByKey(studentId);
  if (!student) return { ok: false, message: '未找到学生。' };
  const store = readTaskStore();
  let task = store.tasks.find(t => t.id === taskId);
  if (!task) {
    task = normalizeTaskEnvelope({ id: taskId, kind: 'guidance_research_check', title: `${student.name}规划来源检查`,
      sourceType: 'student', sourceId: String(studentId), status: 'pending', executor: 'internal', trigger: 'manual',
      input: { studentId: String(studentId) }, permissions: { read: [studentAiManagerDir(student)],
        write: [path.join(studentAiManagerDir(student), 'planning-guidance')], operations: ['read_planning_evidence', 'write_planning_suggestions'] } });
    store.tasks.push(task);
  } else if (['succeeded', 'failed', 'cancelled', 'timed_out', 'blocked'].includes(task.status)) {
    const prepared = transitionTaskInStore(store, taskId, 'pending', { attempt: 0, error: null, autoRetry: false, nextRetryAt: '' }, 'research_manual_refresh');
    if (!prepared.ok) return prepared;
  }
  const manualTask = store.tasks.find(t => t.id === taskId);
  manualTask.trigger = 'manual';
  manualTask.automaticExecution = false;
  writeTaskStore(store);
  const submitted = JSON.parse(executeTaskByAdapter(taskId, 'internal'));
  if (!submitted.ok) return submitted;
  const running = taskChildProcesses.get(taskId);
  return running ? await running.completion : submitted;
}

const taskDispatchPending = new Map();
function executeTaskByAdapter(taskId, requestedExecutor = '', executionOptions = {}) {
  const id = String(taskId);
  if (taskDispatchPending.has(id)) return JSON.stringify({ ok: true, queued: true, taskId: id, message: '本次启动正在保存和检查，请稍候。' });
  const work = projectArchiveRuntime.track(() => Promise.resolve().then(() => executeTaskByAdapterCore(id, requestedExecutor, executionOptions)));
  taskDispatchPending.set(id, work);
  void work.then(result => {
    notify('onNativeTaskCenterChanged', JSON.stringify({ taskId: id, dispatchResult: JSON.parse(result) }));
  }).catch(error => console.warn('Task dispatch paused:', error.message)).finally(() => taskDispatchPending.delete(id));
  return JSON.stringify({ ok: true, queued: true, taskId: id, message: '已登记启动请求；执行批次保存成功后开始处理。' });
}

async function executeTaskByAdapterCore(taskId, requestedExecutor = '', executionOptions = {}) {
  try {
    if (!taskPowerRecovery.canDispatch()) return JSON.stringify({ ok: false, code: 'POWER_RECONCILING', message: '电脑恢复后正在核对结果，资料已保留，核对完成后继续。' });
    projectArchiveRuntime.assertAccess();
    const store = readTaskStore();
    const task = store.tasks.find((item) => String(item.id) === String(taskId));
    if (!task) return JSON.stringify({ ok: false, message: '未找到任务。' });
    const globalPolicy = agentControlStore().read().global;
    if (globalPolicy && !globalPolicy.enabled && task.kind !== 'project_archive') return JSON.stringify({ ok: false, code: 'AGENT_SCOPE_DENIED', message: 'AI 接入与调度中心已全局停用。' });
    if (executionOptions.automatic && automaticStudentTaskBlocked(task,findStudentByKey(task.sourceId))) return JSON.stringify({ok:true,skipped:true,reason:'student_automation_paused',message:'该学生已暂停周期自动任务；仍可手动执行。'});
    if (taskExecutionUnresolved(task)) return JSON.stringify({ ok: false, code: 'EXECUTION_UNRESOLVED', message: recoveryPlan(task).nextAction || '系统正在核对上次执行，不会重复派发同一批资料。' });
    const unresolved = store.tasks.find(item => item.id !== task.id && taskExecutionUnresolved(item)
      && item.sourceType === task.sourceType && item.sourceId === task.sourceId);
    if (unresolved) return JSON.stringify({ ok: false, code: 'SOURCE_EXECUTION_UNRESOLVED', message: `同一资料范围还有“${unresolved.title}”需要核对外部执行状态；其他学生任务不受影响。` });
    task.automaticExecution = executionOptions.automatic===true;
    const permissionCheck = validateTaskPermissionDeclaration(task);
    if (!permissionCheck.ok) return JSON.stringify({ ok: false, blocked: true, message: permissionCheck.message });
    if (['running', 'waiting_result'].includes(task.status)) return JSON.stringify({ ok: false, message: '任务已经在执行或等待结果。' });
    if (taskRequiresApproval(task) && task.approval?.status !== 'approved') return JSON.stringify({ ok: false, approvalRequired: true, message: '该任务属于高风险操作，必须先审批。' });
    if (['draft', 'pending', 'failed', 'blocked', 'timed_out', 'cancelled'].includes(task.status)) {
      const approvalStatus = taskRequiresApproval(task) ? task.approval?.status : 'not_required';
      const transition = transitionTaskInStore(store, task.id, 'approved', { routeAttempts: [], approval: { ...(task.approval || {}), required: taskRequiresApproval(task), status: approvalStatus } }, 'task_prepared');
      if (!transition.ok) return JSON.stringify(transition);
    }
    (await writeTaskStoreDurably(store));
    let refreshed = readTaskStore().tasks.find((item) => item.id === task.id);
    if (refreshed.kind === 'practice_attempt_review') return JSON.stringify(await getPracticeTaskHost().submit(refreshed));
    if (refreshed.kind === 'competition_research_check') return JSON.stringify((await submitCompetitionResearchTask(refreshed)));
    if (['guidance_research_check', 'guidance_plan_refresh'].includes(refreshed.kind)) return JSON.stringify((await submitGuidanceResearchTask(refreshed)));
    const explicitHandoff = aiExecutorRegistry().find(p => p.id === requestedExecutor && p.handoff && !p.automaticProfiles.length);
    if (explicitHandoff) {
      if (globalPolicy?.disabledProviders.includes(explicitHandoff.id)) return JSON.stringify({ ok: false, code: 'AGENT_SCOPE_DENIED', message: '执行器已停用' });
      return JSON.stringify(await submitAgentHandoffTask(refreshed, taskCommandFor(refreshed), explicitHandoff.id));
    }
    if (refreshed.kind === 'student_digest') {
      const student = readStudentsIndex().map(toHostStudent).find((item) => String(item.id) === refreshed.sourceId);
      if (!student) return JSON.stringify({ ok: false, message: '未找到学生档案。' });
      const currentState = readStudentDigestState(student);
      let batch = readDigestBatch(studentDigestBatchPath(student));
      if (!batch || String(batch.batchId || '') !== String(currentState.digestBatchId || '') || !['submitted', 'digesting'].includes(normalizeDigestStateStatus(currentState.status))) {
        const registered = registerStudentDigestBatch(student.id, { includeSubmitted: true });
        if (!registered.ok) {
          if (registered.needsPathRepair && !registered.retryable) {
            const blockedStore = readTaskStore();
            const blocked = transitionTaskInStore(blockedStore, refreshed.id, 'blocked', {
              error: { code: 'MATERIAL_PREFLIGHT_BLOCKED', message: registered.message },
              message: registered.message,
              result: null,
            }, 'digest_preflight_blocked');
            if (blocked.ok) {
              (await writeTaskStoreDurably(blockedStore));
              notify('onNativeTaskCenterChanged', JSON.stringify({ taskId: refreshed.id, status: 'blocked' }));
              return JSON.stringify({ ...registered, blocked: true, task: blocked.task });
            }
          }
          return JSON.stringify(registered);
        }
        batch = registered.batch;
      }
      refreshed = attachDigestBatchToTask(refreshed.id, batch, studentDigestBatchPath(student), studentDigestReceiptPath(student)) || refreshed;
      const selected = String(requestedExecutor || 'auto');
      if (providerSupportsProfile(String(student.agentTool || ''), DIGEST_PROFILE) || agentControlPolicy(student, DIGEST_PROFILE).version > 0) {
        const controlledProject = studentControlledProject(student, path.join(studentManagerDir(student), 'controlled-materials'));
        const host = createProjectMaterialHost(controlledProject);
        await registerStudentControlledBatch(host, batch, student.id);
        return JSON.stringify(await submitProjectMaterialTask(refreshed, controlledProject, selected, { student, batch }));
      }
    }
    if (refreshed.kind === 'project_digest') {
      const project = readProjects().map(normalizeProject).find((item) => String(item.id) === refreshed.sourceId);
      if (project) {
        if (isWorkspaceMaterialProject(project)) return JSON.stringify((await submitProjectMaterialTask(refreshed, project, requestedExecutor)));
        const ensured = ensureProjectWorkspace(project);
        const currentDigest = readProjectDigestState(ensured);
        if (currentDigest.pendingCount > 0 && !['submitted', 'digesting'].includes(currentDigest.status)) {
          const registered = registerProjectDigestBatch(ensured, { prefix: 'task-digest', message: '项目资料已进入自动处理，等待逐文件回执。' });
          if (!registered.ok) return JSON.stringify(registered);
          updateProjectRecord(project.id, (item) => ({ ...item, digestState: registered.digestState, updatedAt: taskNow() }));
          refreshed = attachDigestBatchToTask(refreshed.id, registered.request, projectDigestRequestPath(ensured), projectDigestReceiptPath(ensured)) || refreshed;
        } else {
          const request = safeReadJson(projectDigestRequestPath(ensured), null);
          if (request?.digestBatchId === currentDigest.digestBatchId) refreshed = attachDigestBatchToTask(refreshed.id, request, projectDigestRequestPath(ensured), projectDigestReceiptPath(ensured)) || refreshed;
        }
      }
    }
    const routeDecision = routeTask(refreshed, requestedExecutor);
    if (routeDecision.confirmationRequired) {
      const confirmStore = readTaskStore();
      const confirmTask = confirmStore.tasks.find((item) => item.id === refreshed.id);
      Object.assign(confirmTask, { routeDecision, routingMode: 'confirm', updatedAt: taskNow() });
      (await writeTaskStoreDurably(confirmStore));
      return JSON.stringify({ ok: true, confirmationRequired: true, task: confirmTask, routeDecision, message: `${routeDecision.reason}请在执行器下拉框中确认具体执行器。` });
    }
    const adapterId = routeDecision.selectedAdapter;
    const command = directReportExecutionCommand(refreshed, taskCommandFor(refreshed));
    const nextStore = readTaskStore();
    const taskIndex = nextStore.tasks.findIndex((item) => item.id === refreshed.id);
    nextStore.tasks[taskIndex] = normalizeTaskEnvelope({ ...refreshed, routeDecision, routingMode: routeDecision.mode, adapterId, executor: adapterId, executionMode: adapterId === 'internal' ? 'internal' : adapterId === 'manual' ? 'manual' : adapterId === 'qclaw' ? 'inbox' : 'automatic', routeAttempts: [...new Set([...(refreshed.routeAttempts || []), adapterId])] }, refreshed);
    (await writeTaskStoreDurably(nextStore));
    const routedTask = readTaskStore().tasks.find((item) => item.id === refreshed.id);
    const registered = aiExecutorRegistry().find(p => p.id === adapterId);
    if (registered?.handoff && !registered.automaticProfiles.length) return JSON.stringify(await submitAgentHandoffTask(routedTask, command, adapterId));
    const adapter = getAgentExecutionAdapters()[adapterId] || getAgentExecutionAdapters().manual;
    const capability = adapter.capabilities();
    const selectedAdapter = capability.available && capability.authorized ? adapter : getAgentExecutionAdapters().manual;
    const result = await selectedAdapter.submit(routedTask, command, { reason: selectedAdapter.id === adapterId ? routeDecision.reason : `${routeDecision.reason}所选适配器当前不可用，已降级。` });
    await taskStoreGuard.flush();
    return JSON.stringify(result);
  } catch (error) {
    return JSON.stringify({ ok: false, message: `执行任务失败：${error.message}` });
  }
}

let taskCircuitProbeRunning = false;
async function checkTaskExecutorCircuits() {
  if (taskCircuitProbeRunning || !taskPowerRecovery.canDispatch() || !taskAutomationEnabled()
    || !publicLicenseStatus().active || taskStoreGuard.status() || taskChildProcesses.size || taskDispatchPending.size
    || captureHeavyWorkGate.state().length) return;
  const circuits = readTaskStore().runtime?.circuits || {};
  // No capability discovery on page reads, and no probing all fallback tools.
  const entry = Object.entries(circuits).find(([id, state]) => ['codex', 'workbuddy'].includes(id)
    && (circuitDecision(state).probeDue || (state.phase === 'half_open' && Date.now() - Date.parse(state.updatedAt || '') > 30000))
    && adapterCapabilityCache.value?.[id]?.authorized);
  if (!entry) return;
  const [id] = entry;
  const release = captureHeavyWorkGate.tryAcquire({ kind: 'agent_probe', studentId: '', sessionId: `circuit-${id}`, snapshot: captureTimelineResourceSnapshot() });
  if (!release) return;
  taskCircuitProbeRunning = true;
  try {
    const store = readTaskStore(); store.runtime.circuits[id] = { ...store.runtime.circuits[id], phase: 'half_open', updatedAt: taskNow() };
    await writeTaskStoreDurably(store);
    let passed = false;
    if (id === 'codex') passed = (await require('./task-circuit-probe.cjs').probeControlledCodex(adapterCapabilityCache.value.codex.exePath)).passed;
    else {
      const runtime = discoverWorkBuddyRuntime(adapterCapabilityCache.value.workbuddy.exePath, { findExecutable: findExecutableInPath, hostNodePath: process.execPath });
      if (runtime.cliPath) runtime.version = String(fs.statSync(runtime.cliPath).mtimeMs);
      const authorized = await workBuddyProbeCache.detect(runtime, { force: true });
      const qualification = authorized.authorized
        ? await workBuddyQualification.check(runtime, { force: true })
        : { ready: false, message: authorized.message };
      passed = authorized.authorized && qualification.ready;
      await persistWorkBuddyControlledStatus(runtime, authorized, qualification);
      if (!authorized.authorized && authorized.authRequired) {
        return;
      }
    }
    const latest = readTaskStore(); latest.runtime.circuits[id] = completeCircuitProbe(latest.runtime.circuits[id], passed);
    await writeTaskStoreDurably(latest);
  } catch (error) { console.warn('Circuit health check paused:', error.message); }
  finally { taskCircuitProbeRunning = false; release(); }
}

async function executeTaskByAdapterWithFreshCapabilities(taskId, requestedExecutor = '') {
  const task = readTaskStore().tasks.find((item) => String(item.id) === String(taskId));
  const explicitExecutor = String(requestedExecutor || task?.requestedExecutor || task?.executor || '');
  await refreshCapabilitiesForExplicitExecution(explicitExecutor);
  appendTaskEvent(taskId, 'explicit_execution_capability_refreshed', {
    automationEnabled: taskAutomationEnabled(),
    requestedExecutor: explicitExecutor,
  });
  executeTaskByAdapter(taskId, requestedExecutor);
  return taskDispatchPending.get(String(taskId));
}

function approveTask(taskId, decision, note = '') {
  try {
    const store = readTaskStore();
    const task = store.tasks.find((item) => item.id === String(taskId));
    if (!task) return JSON.stringify({ ok: false, message: '未找到任务。' });
    const approved = String(decision) === 'approved';
    if (task.status === 'reviewing') {
      if (!approved) {
        const rejected = transitionTaskInStore(store, task.id, 'failed', { approval: { required: true, status: 'rejected', note, reviewedAt: taskNow(), reviewedBy: 'local-user' }, error: { code: 'REVIEW_REJECTED', message: note || '任务结果审核未通过。' } }, 'result_rejected');
        writeTaskStore(store);
        return JSON.stringify({ ...rejected, message: '任务结果已驳回，可修正后重试。' });
      }
      if (task.kind === 'weekly_action' || PERIODIC_REPORT_TASKS[task.kind]) {
        const approvalValidation = validateTaskCompletion(task, task.startedAt, task.result);
        if (!approvalValidation.valid) return JSON.stringify({ ok: false, message: `报告草稿校验失败，不能采用：${approvalValidation.message}` });
        const draftPath = task.expectedOutput?.draftPath;
        const publishPath = task.expectedOutput?.publishPath;
        if (!draftPath || !publishPath || !fs.existsSync(draftPath)) return JSON.stringify({ ok: false, message: '报告草稿不存在，不能采用。' });
        const today = String(task.input?.date || taskToday());
        const publishResult = publishValidatedReport({ stagingPath: draftPath, publishPath, updated: today, type: task.kind });
        if (!publishResult.ok) return JSON.stringify(publishResult);
      }
      const accepted = transitionTaskInStore(store, task.id, 'succeeded', { approval: { required: true, status: 'approved', note, reviewedAt: taskNow(), reviewedBy: 'local-user' }, result: { ...(task.result || {}), publishedAt: taskNow(), reviewNote: note } }, 'result_approved');
      writeTaskStore(store);
      return JSON.stringify({ ...accepted, message: task.action === 'learning_report' || task.kind === 'weekly_action' ? '报告已采用并发布。' : '任务结果已确认。' });
    }
    const nextApproval = { required: taskRequiresApproval(task), status: approved ? 'approved' : 'rejected', note: String(note || ''), reviewedAt: taskNow(), reviewedBy: 'local-user' };
    if (!approved) {
      const rejected = transitionTaskInStore(store, task.id, 'cancelled', { approval: nextApproval }, 'execution_rejected');
      writeTaskStore(store);
      return JSON.stringify({ ...rejected, message: '任务执行申请已拒绝。' });
    }
    const nextStatus = task.status === 'pending' ? 'approved' : task.status;
    const accepted = transitionTaskInStore(store, task.id, nextStatus, { approval: nextApproval }, 'execution_approved');
    writeTaskStore(store);
    return JSON.stringify({ ...accepted, message: '任务已批准，可以执行。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `审批任务失败：${error.message}` });
  }
}

function retryTask(taskId) {
  try {
    const store = readTaskStore();
    const task = store.tasks.find((item) => item.id === String(taskId));
    if (!task) return JSON.stringify({ ok: false, message: '未找到任务。' });
    if (!['failed', 'blocked', 'timed_out', 'cancelled'].includes(task.status)) return JSON.stringify({ ok: false, message: '只有失败、阻塞、超时或已取消任务可以重试。' });
    if (task.recoveryState === 'unknown') return JSON.stringify({ ok: false, code: 'EXECUTION_UNRESOLVED', message: recoveryPlan(task).nextAction || '系统正在核对上次执行；当前批次编号和结果保持不变。' });
    const transition = transitionTaskInStore(store, task.id, 'pending', { error: null, result: null, executionId: '', adapterId: '', routeAttempts: [], nextRetryAt: '', retryRecovery: null, completedAt: '', attempt: 0, autoRetry: false }, 'task_retried');
    writeTaskStore(store);
    return JSON.stringify({ ...transition, message: '任务已重置为待处理；本次只在用户点击后执行，不会后台连环重试。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `重试任务失败：${error.message}` });
  }
}

async function cancelTask(taskId, note = '') {
  try {
    const materialRun = taskChildProcesses.get(String(taskId));
    if (materialRun?.materialRuntime && !materialRun.materialRuntime.canCancel) {
      return JSON.stringify({ ok: false, code: 'commit_in_progress', message: '知识正在校验提交，暂不能取消；请等待提交完成后查看结果。' });
    }
    const store = readTaskStore();
    const task = store.tasks.find((item) => item.id === String(taskId));
    const adapter = task ? getAgentExecutionAdapters()[task.adapterId] : null;
    const uncertain = task?.executionId && !String(task.executionId).startsWith('handoff-select-') && ['running', 'waiting_result', 'reviewing'].includes(task.status);
    const transition = transitionTaskInStore(store, String(taskId), 'cancelled', {
      recoveryState: uncertain ? 'unknown' : task?.recoveryState || '',
      error: { code: uncertain ? 'CANCEL_STOP_UNCONFIRMED' : 'CANCELLED', message: uncertain ? '本机已停止接收此批次，系统正在确认执行来源是否已经停止。' : String(note || '用户取消任务。') } }, 'task_cancelled');
    let stop = null;
    if (transition.ok) {
      await writeTaskStoreDurably(store);
      // Persist the revoked batch before signalling an external process. A storage
      // fault must not leave an apparently running task whose process was killed.
      const current = readTaskStore().tasks.find(item => item.id === String(taskId));
      if (current?.status === 'cancelled' && current.executionId === task.executionId && adapter?.cancel) {
        stop = await Promise.resolve(adapter.cancel(task));
        if (stop?.stopConfirmed === true) {
          const confirmedStore = readTaskStore();
          const confirmed = confirmedStore.tasks.find(item => item.id === String(taskId));
          if (confirmed?.status === 'cancelled' && confirmed.executionId === task.executionId) {
            Object.assign(confirmed, internalStoppedPatch(confirmed, taskNow()));
            await writeTaskStoreDurably(confirmedStore);
            appendTaskEvent(confirmed.id, 'task_stop_confirmed', { source: taskExecutionClass(task), message: stop.message }, confirmed.executionId);
            transition.task = confirmed;
          }
        }
      }
    }
    return JSON.stringify({ ...transition, message: transition.ok
      ? stop?.stopConfirmed === true
        ? '任务已停止；未采用不完整结果，上一有效版本保持不变。'
        : uncertain ? '已停止本机接收，系统会先查询回执；不会自动重跑同一批资料。' : '任务已取消。'
      : transition.message });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `取消任务失败：${error.message}` });
  }
}

function deleteTaskHistory(taskId) {
  try {
    const store = readTaskStore();
    const removed = removeHistoricalTaskRecord(store, String(taskId), taskNow());
    if (!removed.ok) return JSON.stringify(removed);
    writeTaskStore(store);
    appendTaskEvent(removed.task.id, 'task_history_deleted', {
      title: removed.task.title,
      kind: removed.task.kind,
      sourceType: removed.task.sourceType,
      sourceId: removed.task.sourceId,
      previousStatus: removed.task.status,
      idempotencyKey: removed.task.idempotencyKey,
      removedHistoryCount: removed.removedHistoryCount,
      artifactsPreserved: true,
    }, removed.task.executionId);
    notify('onNativeTaskCenterChanged', JSON.stringify({ taskId: removed.task.id, deleted: true }));
    return JSON.stringify({ ok: true, taskId: removed.task.id, removedHistoryCount: removed.removedHistoryCount,
      message: '历史任务已从任务中心移除；学生资料、任务产物和审计事件均保留。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `删除历史任务失败：${error.message}` });
  }
}

function pruneTaskGovernancePreviews(nowValue = Date.now()) {
  for (const [token, preview] of taskGovernancePreviews) {
    if (nowValue - Number(preview.createdAt || 0) > 5 * 60 * 1000) taskGovernancePreviews.delete(token);
  }
}

function resolveTaskGovernanceSelection(store, request = {}) {
  if (request.selection !== 'filtered') {
    const ids = [...new Set((Array.isArray(request.ids) ? request.ids : []).map(String).filter(Boolean))];
    return { ids: ids.slice(0, 1000), matchedCount: ids.length, truncated: ids.length > 1000, selection: 'explicit' };
  }
  const query = request.query && typeof request.query === 'object' ? request.query : {};
  const status = ['all', 'actionable', 'running', 'scheduled', 'completed', 'archived', 'automatic', 'needs_help', 'history'].includes(String(query.status || ''))
    ? String(query.status) : 'all';
  const source = ['all', 'student', 'project'].includes(String(query.source || '')) ? String(query.source) : 'all';
  const executor = String(query.executor || 'all').slice(0, 200);
  const matched = (store.tasks || []).filter((task) => {
    const presentation = taskPresentation(task);
    return (status === 'all' || presentation.statusGroup === status || presentation.userGroup === status)
      && (source === 'all' || String(task.sourceType || '') === source)
      && (executor === 'all' || String(task.executor || '') === executor);
  }).map((task) => String(task.id)).filter(Boolean);
  return { ids: matched.slice(0, 1000), matchedCount: matched.length, truncated: matched.length > 1000,
    selection: 'filtered', query: { status, source, executor } };
}

function previewTaskGovernanceBatch(request = {}) {
  pruneTaskGovernancePreviews();
  const action = String(request.action || 'archive');
  if (!['cancel', 'archive', 'delete', 'restore'].includes(action)) return { ok: false, message: '不支持的批量操作。' };
  const store = readTaskStore();
  const selection = resolveTaskGovernanceSelection(store, request);
  const ids = selection.ids;
  if (!ids.length) return { ok: false, message: '请先选择任务。' };
  const preview = batchGovernancePreview(store.tasks, ids, action);
  const token = crypto.randomUUID();
  taskGovernancePreviews.set(token, { ...preview, ...selection, ids, action, sequence: taskStoreGuard.sequence(), createdAt: Date.now() });
  return { ok: true, token, expiresInSeconds: 300, ...selection, ...preview };
}

async function commitTaskGovernanceBatch(request = {}) {
  pruneTaskGovernancePreviews();
  const token = String(request.token || '');
  const saved = taskGovernancePreviews.get(token);
  if (!saved) return { ok: false, code: 'PREVIEW_EXPIRED', message: '批量预览已过期，请重新预览。' };
  taskGovernancePreviews.delete(token);
  if (saved.sequence !== taskStoreGuard.sequence()) return { ok: false, code: 'TASK_STORE_CHANGED', message: '任务队列已变化，请重新预览后提交。' };
  const store = readTaskStore();
  const current = batchGovernancePreview(store.tasks, saved.ids, saved.action);
  const eligibilitySignature = (preview) => JSON.stringify({
    eligible: preview.eligible.map((item) => item.id).sort(),
    skipped: preview.skipped.map((item) => `${item.id}:${item.reason}`).sort(),
  });
  if (eligibilitySignature(current) !== eligibilitySignature(saved)) {
    return { ok: false, code: 'ELIGIBILITY_CHANGED', message: '任务状态已变化，请重新预览。' };
  }
  const processed = [];
  const now = taskNow();
  for (const item of current.eligible) {
    const task = store.tasks.find((entry) => String(entry.id) === item.id);
    if (!task) continue;
    if (saved.action === 'cancel') {
      task.status = 'cancelled'; task.statusGroup = 'completed'; task.completedAt = now; task.updatedAt = now;
      task.autoRetry = false; task.nextRetryAt = ''; task.error = { code: 'BATCH_CANCELLED', message: '用户批量取消未启动任务。' };
    } else if (saved.action === 'archive') archiveTaskRecord(task, String(request.reason || '用户批量归档'), now);
    else if (saved.action === 'restore') restoreArchivedTask(task, now);
    else if (saved.action === 'delete') {
      const removed = removeHistoricalTaskRecord(store, item.id, now);
      if (!removed.ok) continue;
    }
    processed.push(item.id);
  }
  await writeTaskStoreDurably(store);
  for (const taskId of processed) appendTaskEvent(taskId, `task_batch_${saved.action}`, { batchSize: processed.length, skippedCount: current.skipped.length });
  notify('onNativeTaskCenterChanged', JSON.stringify({ batchAction: saved.action, taskIds: processed }));
  return { ok: true, action: saved.action, processedCount: processed.length, skipped: current.skipped,
    message: `已${{ cancel: '取消', archive: '归档', delete: '删除', restore: '恢复' }[saved.action]} ${processed.length} 个任务。` };
}

async function migrateTaskQueueGovernance() {
  const store = readTaskStore();
  const runtime = store.runtime && typeof store.runtime === 'object' ? store.runtime : (store.runtime = {});
  if (Number(runtime.taskGovernanceMigration?.version || 0) >= 2) return runtime.taskGovernanceMigration;
  const now = taskNow();
  const inboxDir = path.join(app.getPath('userData'), 'smart-inbox', 'items');
  // Fail closed if metadata cannot be read; never equate a parse/permission
  // failure with an empty inbox. No model calls or task dispatch in migration.
  const inboxItems = fs.existsSync(inboxDir) ? fs.readdirSync(inboxDir).filter(name => name.endsWith('.json'))
    .map(name => JSON.parse(fs.readFileSync(path.join(inboxDir, name), 'utf8'))) : null;
  const projects = readProjects().map(normalizeProject).map(project => ({ ...project, digestState: readProjectDigestState(project) }));
  const { candidates, skipped } = queueGovernanceCandidates(store, { inboxItems, projects,
    hasExecutionArtifacts: task => fs.existsSync(path.join(taskExecutionDirPath(), task.id))
      || Boolean(task.input?.manifestPath && fs.existsSync(task.input.manifestPath))
      || Boolean(task.expectedOutput?.path && fs.existsSync(task.expectedOutput.path)) });
  const backupDir = path.join(taskCenterDirPath(), 'migration-backups', `task-governance-p0-v2-${timestampForFilename()}`);
  fs.mkdirSync(backupDir, { recursive: true });
  if (fs.existsSync(taskStorePath())) fs.copyFileSync(taskStorePath(), path.join(backupDir, 'tasks.before.json'));
  if (fs.existsSync(taskEventLogPath())) fs.copyFileSync(taskEventLogPath(), path.join(backupDir, 'events.before.jsonl'));
  for (const { task, reason } of candidates) archiveTaskRecord(task, reason, now);
  runtime.taskGovernanceMigration = { version: 2, migratedAt: now, archivedCount: candidates.length,
    legacyInboxArchivedCount: candidates.filter(item => item.task.kind === 'smart_material_intake').length,
    idleProjectArchivedCount: candidates.filter(item => item.task.kind === 'project_digest').length, skipped, backupDir };
  await writeTaskStoreDurably(store);
  const report = { ...runtime.taskGovernanceMigration, taskIds: candidates.map(({ task }) => task.id),
    protectedStatuses: ['running', 'waiting_result', 'reviewing'], unknownResultsProtected: true };
  fs.writeFileSync(path.join(backupDir, 'migration-report.json'), `${JSON.stringify(report, null, 2)}\n`, 'utf8');
  return report;
}

async function acceptImportedTaskResult(taskId, payload, source = {}) {
  const store = readTaskStore();
  const task = store.tasks.find((item) => item.id === String(taskId));
  const identity = validateExternalTaskResultIdentity(task, payload);
  if (!identity.ok) {
    appendTaskEvent(taskId, 'external_result_rejected', { source: source.kind || 'manual_import', file: source.path || '', code: identity.code, message: identity.message }, task?.executionId || '');
    return resultIdentityFeedback(task, payload, identity);
  }
  const validation = validateTaskCompletion(task, task.startedAt, payload);
  const successful = payload.status !== 'failed' && validation.valid;
  const failureMessage = !validation.valid ? validation.message || '宿主校验未通过。' : 'Agent 已报告执行失败，不能仅凭文件存在认定任务完成。';
  const importedFrom = source.path || source.kind || 'manual_import';
  const result = normalizeTaskResult(task, { ...payload, importedFrom, status: successful ? 'reviewing' : 'failed' }, validation, { importedFrom });
  const transition = commitValidatedTaskResult(store, task, result, validation, {
    successful,
    error: successful ? null : { code: 'RESULT_INVALID', message: failureMessage },
    event: source.event || 'task_result_imported',
    autoSummary: '资料处理结果已导入并通过自动校验。',
  });
  if (!transition.ok) return { ...transition, ok: false, accepted: false, message: `结果未提交：${transition.message || '任务状态不允许提交'}。输入已保留。` };
  await writeTaskStoreDurably(store);
  if (successful) publishCompletedRemoteCollaborationTask(taskId);
  const nextStatus = transition.task?.status || (successful ? 'reviewing' : 'failed');
  if (isDigestTask(task)) notify('onNativeDigestWorkflowChanged', JSON.stringify({ scopeType: task.sourceType, scopeId: task.sourceId, status: nextStatus, taskId: task.id }));
  return { ...transition, ok: Boolean(transition.ok && successful), accepted: true, validationPassed: Boolean(successful),
    message: !successful ? `结果已保存为未通过校验，尚未完成任务：${failureMessage} 粘贴内容已保留。`
      : nextStatus === 'succeeded' ? '资料结果已导入并自动完成。' : '结果已导入，等待审核。' };
}

function confirmTaskExternalStopped(taskId, executionId) {
  try {
    const store = readTaskStore();
    const task = store.tasks.find(item => item.id === String(taskId));
    if (!task || task.executionId !== String(executionId) || task.status !== 'cancelled' || task.recoveryState !== 'unknown') return JSON.stringify({ ok: false, message: '任务批次或状态已变化，请刷新后核对。' });
    if (typeof taskExecutionClass === 'function' && taskExecutionClass(task) === 'internal') return JSON.stringify({ ok: false, message: '这是内置任务，停止状态应由系统确认，不需要人工核对。请刷新任务状态。' });
    if (taskChildProcesses.has(task.id)) return JSON.stringify({ ok: false, message: '本机仍在等待该进程退出，不能用人工确认替代进程退出。' });
    task.recoveryState = 'user_confirmed_stopped';
    task.error = { code: 'CANCELLED', message: '用户已在外部工具核对未发送或已停止；未自动重跑。' };
    appendTaskEvent(task.id, 'external_stop_user_confirmed', { source: 'explicit_user_confirmation', automaticRetry: false }, task.executionId);
    writeTaskStore(store);
    return JSON.stringify({ ok: true, message: '已记录您的核对确认，保留原批次历史。如需继续，请手动重新执行。' });
  } catch (error) { return JSON.stringify({ ok: false, message: `核对记录保存失败：${error.message}` }); }
}

async function importTaskResult(taskId) {
  try {
    const selected = dialog.showOpenDialogSync(mainWindow, { title: '导入 Agent 任务结果', properties: ['openFile'], filters: [{ name: 'TaskResult JSON', extensions: ['json'] }] });
    if (!selected?.[0]) return JSON.stringify({ ok: false, message: '未选择结果文件。' });
    const payload = safeReadJson(selected[0], null);
    return JSON.stringify(await acceptImportedTaskResult(taskId, payload, { kind: 'manual_file', path: selected[0], event: 'task_result_file_imported' }));
  } catch (error) {
    return JSON.stringify({ ok: false, message: `导入任务结果失败：${error.message}` });
  }
}

async function importTaskResultFileAsync(taskId) {
  try {
    const selected = await dialog.showOpenDialog(mainWindow, { title: '导入 Agent 任务结果', properties: ['openFile'], filters: [{ name: 'TaskResult JSON', extensions: ['json'] }] });
    if (selected.canceled || !selected.filePaths?.[0]) return JSON.stringify({ ok: false, cancelled: true, message: '未选择结果文件。' });
    const file = selected.filePaths[0];
    const handle = await fs.promises.open(file, 'r');
    let text;
    try {
      const stat = await handle.stat();
      if (!stat.isFile() || stat.size > 1024 * 1024) throw new Error('结果 JSON 必须小于 1 MB；原始资料请通过资料入口上传。');
      const bytes = Buffer.alloc(1024 * 1024 + 1);
      const { bytesRead } = await handle.read(bytes, 0, bytes.length, 0);
      if (bytesRead > 1024 * 1024) throw new Error('结果文件读取期间超过 1 MB。');
      text = bytes.subarray(0, bytesRead).toString('utf8').replace(/^\uFEFF/, '');
    } finally { await handle.close(); }
    return JSON.stringify(await acceptImportedTaskResult(taskId, JSON.parse(text), { kind: 'manual_file', path: file, event: 'task_result_file_imported' }));
  } catch (error) { return JSON.stringify({ ok: false, message: `导入失败：${error.message} 未清空粘贴内容。` }); }
}

async function importTaskResultText(taskId, content) {
  try {
    const text = String(content || '').trim();
    if (!text) return JSON.stringify({ ok: false, message: '请先粘贴 Agent 返回的执行结果。' });
    if (Buffer.byteLength(text, 'utf8') > 1024 * 1024) return JSON.stringify({ ok: false, message: '粘贴结果超过 1 MB，请改用文件导入。' });
    const store = readTaskStore();
    const task = store.tasks.find((item) => item.id === String(taskId));
    if (!task) return JSON.stringify({ ok: false, message: '未找到任务。' });
    if (!['running', 'waiting_result'].includes(task.status) || !task.executionId) return JSON.stringify({ ok: false, message: '当前任务没有可接收结果的有效执行批次。' });

    let parsed = null;
    try {
      parsed = parseJsonText(text);
    } catch {
      parsed = null;
    }
    const hasProtocolIdentity = parsed && typeof parsed === 'object' && ['protocolVersion', 'taskId', 'executionId'].some((key) => Object.prototype.hasOwnProperty.call(parsed, key));
    const payload = hasProtocolIdentity
      ? parsed
      : {
          protocolVersion: TASK_PROTOCOL_VERSION,
          taskId: task.id,
          executionId: task.executionId,
          status: 'completed',
          message: '用户粘贴 Agent 执行结果。',
          output: text,
          data: parsed && typeof parsed === 'object' ? parsed : undefined,
        };
    return JSON.stringify(await acceptImportedTaskResult(task.id, payload, { kind: 'manual_paste', event: 'task_result_text_imported' }));
  } catch (error) {
    return JSON.stringify({ ok: false, message: `导入粘贴结果失败：${error.message}` });
  }
}

function quarantineAgentPayload(file, reason) {
  const rejectedDir = path.join(path.dirname(file), 'rejected');
  fs.mkdirSync(rejectedDir, { recursive: true });
  const parsed = path.parse(file);
  const nonce = crypto.randomBytes(3).toString('hex');
  const target = path.join(rejectedDir, `${parsed.name}-${timestampForFilename()}-${nonce}${parsed.ext}`);
  fs.renameSync(file, target);
  writeJsonFile(`${target}.reason.json`, { rejectedAt: taskNow(), source: file, reason });
  return target;
}

async function archiveAgentPayload(file, kind) {
  const archiveDir = path.join(path.dirname(file), 'processed', kind === 'claim' ? 'claims' : 'results');
  await fs.promises.mkdir(archiveDir, { recursive: true });
  const parsed = path.parse(file);
  const target = path.join(archiveDir, `${parsed.name}-${timestampForFilename()}-${crypto.randomBytes(3).toString('hex')}${parsed.ext}`);
  // Keep the inbox original until the ledger durably points to the archive.
  await fs.promises.copyFile(file, target, fs.constants.COPYFILE_EXCL);
  return target;
}

async function consumeAgentTaskResults(agentId, discovered) {
  try {
    const channel = agentTaskChannel(taskCenterDirPath(), agentId);
    let imported = 0;
    let claimed = 0;
    let rejected = 0;
    for (const candidate of discovered.claims) {
      const store = readTaskStore();
      const { file, payload } = candidate;
      const task = store.tasks.find((item) => item.id === String(payload?.taskId || ''));
      const executionIdentity = validateExternalTaskResultIdentity(task, payload, { allowedStatuses: ['waiting_result'] });
      const identity = executionIdentity.ok ? validateTaskChannelIdentity(task, payload, candidate.channel) : executionIdentity;
      if (!identity.ok) {
        const rejectedPath = quarantineAgentPayload(file, identity);
        appendTaskEvent(payload?.taskId || '', 'agent_claim_rejected', { agentId: candidate.channel.agentId, code: identity.code, message: identity.message, rejectedPath }, task?.executionId || '');
        rejected += 1;
        continue;
      }
      const transition = transitionTaskInStore(store, task.id, 'running', { lastHeartbeatAt: taskNow(), result: { ...(task.result || {}), claimFile: file, claimedBy: payload.agentId || candidate.channel.agentId, claimedAt: payload.claimedAt || taskNow(), handoffState: 'claimed_running', requiresUserAction: false } }, 'agent_task_claimed');
      if (transition.ok) {
        await writeTaskStoreDurably(store);
        const archivedFile = await archiveAgentPayload(file, 'claim');
        const current = readTaskStore();
        const received = current.tasks.find(item => item.id === task.id && item.executionId === task.executionId);
        if (received?.result?.claimFile === file) {
          received.result.claimFile = archivedFile;
          await writeTaskStoreDurably(current);
          await fs.promises.unlink(file);
        }
        claimed += 1;
      }
    }
    for (const candidate of discovered.results) {
      const store = readTaskStore();
      const { file, payload } = candidate;
      const task = store.tasks.find((item) => item.id === String(payload?.taskId || ''));
      const receiptHash = crypto.createHash('sha256').update(JSON.stringify(payload ?? null)).digest('hex');
      if (task && payload && task.executionId === payload.executionId && task.result?.receiptHash === receiptHash
        && validateTaskChannelIdentity(task, payload, candidate.channel).ok) {
        // Crash after commit but before inbox cleanup: recover the saved receipt
        // without reapplying learning events or treating it as a failed attempt.
        const archivedFile = await archiveAgentPayload(file, 'result');
        const recovered = readTaskStore();
        const current = recovered.tasks.find(item => item.id === task.id);
        if (current?.executionId === task.executionId && current.result?.receiptHash === receiptHash) {
          current.result.resultFile = archivedFile; current.result.importedFrom = archivedFile;
          await writeTaskStoreDurably(recovered); await fs.promises.unlink(file);
        }
        continue;
      }
      const executionIdentity = validateExternalTaskResultIdentity(task, payload);
      const identity = executionIdentity.ok ? validateTaskChannelIdentity(task, payload, candidate.channel) : executionIdentity;
      if (!identity.ok) {
        const rejectedPath = quarantineAgentPayload(file, identity);
        appendTaskEvent(payload?.taskId || '', 'agent_result_rejected', { agentId: candidate.channel.agentId, code: identity.code, message: identity.message, rejectedPath }, task?.executionId || '');
        rejected += 1;
        continue;
      }
      const validation = validateTaskCompletion(task, task.startedAt, payload);
      const successful = payload.status !== 'failed' && validation.valid;
      const result = normalizeTaskResult(task, { ...payload, resultFile: file, status: successful ? 'reviewing' : 'failed' }, validation, { importedFrom: file });
      result.resultFile = file;
      result.receiptHash = receiptHash;
      const transition = commitValidatedTaskResult(store, task, result, validation, {
        successful,
        error: successful ? null : { code: 'AGENT_RESULT_INVALID', message: payload.message || validation.message },
        event: 'agent_result_synced',
        autoSummary: '资料处理完成并已通过自动校验。',
      });
      if (transition.ok) {
        await writeTaskStoreDurably(store);
        const archivedFile = await archiveAgentPayload(file, 'result');
        const current = readTaskStore();
        const received = current.tasks.find(item => item.id === task.id && item.executionId === task.executionId);
        if (received?.result?.resultFile === file) {
          received.result.resultFile = archivedFile;
          received.result.importedFrom = archivedFile;
          await writeTaskStoreDurably(current);
          await fs.promises.unlink(file);
        }
        imported += 1;
      }
      if (transition.ok && isDigestTask(task)) notify('onNativeDigestWorkflowChanged', JSON.stringify({ scopeType: task.sourceType, scopeId: task.sourceId, status: transition.task?.status || '', taskId: task.id }));
    }
    if (imported || claimed || rejected) await taskStoreGuard.flush();
    if (imported || claimed || rejected) notify('onNativeTaskCenterChanged', JSON.stringify({ agentId, imported, claimed, rejected }));
    return JSON.stringify({ ok: true, claimed, imported, rejected, ...channel, message: imported || claimed || rejected ? `Agent 同步完成：领取 ${claimed} 项，结果 ${imported} 项，拒绝过期或无效包 ${rejected} 项。` : '没有新的 Agent 任务领取或结果。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `同步 Agent 结果失败：${error.message}` });
  }
}

async function recordUnknownReceiptChecks(agentId = '') {
  const store = readTaskStore();
  const now = taskNow();
  let changed = false;
  for (const task of store.tasks) {
    if (task.recoveryState !== 'unknown' || taskExecutionClass(task) === 'internal') continue;
    const provenance = executionProvenance(task);
    if (!provenance.querySupport || (agentId && provenance.providerId !== String(agentId))) continue;
    const budget = recoveryBudget(task, now);
    if (budget.receiptQueries >= budget.limits.receiptQueries) continue;
    task.recoveryBudget = { ...budget, receiptQueries: budget.receiptQueries + 1 };
    task.recoveryCheckedAt = now;
    task.recoveryPlan = recoveryPlan(task, now);
    task.updatedAt = now;
    changed = true;
  }
  if (changed) await writeTaskStoreDurably(store);
  return changed;
}

function syncAgentTaskResults(agentId = '') {
  // A synchronous compatibility request only schedules work; it never reads result files.
  if (taskReadMaintenanceStopped) return JSON.stringify({ ok: false, message: '任务中心正在关闭。' });
  if (!taskInboxPromise && (agentId || Date.now() - taskInboxLastScan >= 60000)) {
    taskInboxDirty = false;
    taskInboxLastScan = Date.now();
    taskInboxPromise = taskIoClient.request(taskStorePath(), 'inbox', { agentId }).then(async discovered => {
      if (!Array.isArray(discovered.claims) || !Array.isArray(discovered.results)) throw new Error(discovered.message || '回执扫描失败');
      for (const kind of ['claims', 'results']) {
        for (const candidate of discovered[kind]) {
          await new Promise(resolve => setImmediate(resolve));
          if (taskReadMaintenanceStopped) return;
          if (!fs.existsSync(candidate.file)) continue;
          await consumeAgentTaskResults(candidate.channel.agentId, { claims: [], results: [], [kind]: [candidate] });
        }
      }
      await recordUnknownReceiptChecks(agentId);
      if (discovered.deferred && !taskInboxTimer) {
        taskInboxTimer = setTimeout(() => { taskInboxTimer = null; taskInboxLastScan = 0; syncAgentTaskResults(); }, 1000);
        taskInboxTimer.unref?.();
      }
    }).catch(error => console.warn('Task inbox scan:', error.message)).finally(() => {
      taskInboxPromise = null;
      if (taskInboxDirty && !taskReadMaintenanceStopped && !taskInboxTimer) {
        taskInboxTimer = setTimeout(() => { taskInboxTimer = null; taskInboxLastScan = 0; syncAgentTaskResults(); }, 1000);
        taskInboxTimer.unref?.();
      }
    });
  }
  return JSON.stringify({ ok: true, pending: true, message: '已请求后台检查回执；有效结果将自动更新。' });
}

// Retain the IPC alias for older clients and already exported QClaw bridges.
function syncQClawTaskResults() {
  return syncAgentTaskResults('qclaw');
}

function submitDailyActionFeedback(taskId, status, note = '') {
  try {
    const store = readTaskStore();
    const task = store.tasks.find((item) => item.id === String(taskId));
    if (!task || task.kind !== 'weekly_action') return JSON.stringify({ ok: false, message: '未找到每周行动建议任务。' });
    if (task.status !== 'succeeded') return JSON.stringify({ ok: false, message: '每周行动建议尚未审核发布，不能提交完成反馈。' });
    const normalizedStatus = String(status || 'completed');
    if (!['completed', 'partial', 'skipped'].includes(normalizedStatus)) return JSON.stringify({ ok: false, message: '反馈状态只能是 completed、partial 或 skipped。' });
    const student = readStudentsIndex().find((item) => String(item.id) === task.sourceId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const normalized = toHostStudent(student);
    const feedbackDate = String(task.input?.date || taskToday());
    const entries = readDailyActionFeedback(normalized).filter((entry) => !(String(entry.taskId || '') === task.id && String(entry.date || '') === feedbackDate));
    const feedback = { taskId: task.id, date: feedbackDate, status: normalizedStatus, note: String(note || ''), submittedAt: taskNow() };
    entries.unshift(feedback);
    writeJsonFile(dailyActionFeedbackPath(normalized), { version: 1, updatedAt: taskNow(), entries: entries.slice(0, 90) });
    const transition = transitionTaskInStore(store, task.id, task.status, {
      result: {
        ...(task.result || {}),
        summary: task.result?.summary || '每周行动建议已发布。',
        feedback,
      },
      message: '完成反馈已保存，将作为下一次每周行动建议的输入。',
    }, 'weekly_action_feedback');
    if (transition.ok) writeTaskStore(store);
    return JSON.stringify({ ok: true, task: transition.task || task, feedback, message: '完成反馈已保存，将作为下一次每周行动建议的输入。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `保存行动反馈失败：${error.message}` });
  }
}

function enforceTaskTimeouts(store) {
  if (!taskPowerRecovery.canDispatch()) return false;
  taskProgressBuffer.apply(store);
  const now = Date.now();
  let changed = false;
  for (const task of store.tasks) {
    const timeout = taskTimeoutDecision(task, now);
    if (!timeout.enabled || !timeout.due) continue;
    const running = taskChildProcesses.get(task.id);
    if (running?.materialRuntime && !running.materialRuntime.canCancel) continue;
    if (running) {
      clearTaskProcessHeartbeat(task.id);
      running.controller?.abort();
      if (running.child && !running.child.killed) {
        try { running.child.kill(); } catch { /* Timeout state still applies. */ }
      }
      // Keep ownership and the resource permit until the runner reports exit.
    }
    if (taskExecutionClass(task) === 'internal') {
      Object.assign(task, internalStoppedPatch(task, new Date(now).toISOString()));
      appendTaskEvent(task.id, 'internal_task_timed_out_stopped', { timeoutKind: timeout.kind, automaticRetry: false }, task.executionId);
      changed = true;
      businessTaskRetryQueue.delete(String(task.id));
      continue;
    }
    const eventType = timeout.kind === 'heartbeat' ? 'task_heartbeat_lost' : timeout.kind === 'result_wait' ? 'task_result_wait_timed_out' : 'task_timed_out';
    // Keep the same execution receivable while quarantined, so a matching late
    // result can still be validated. Cancelled/superseded executions stay closed.
    const transition = transitionTaskInStore(store, task.id, task.status, {
      ...unknownExecutionPatch(task, timeout.kind),
      error: { code: timeout.error.code, message: `${timeout.error.message} 已请求停止，系统将先查询 ${executionProvenance(task).providerLabel} 的回执；不会自动重跑。` },
    }, eventType);
    if (transition.ok) {
      changed = true;
      businessTaskRetryQueue.delete(String(task.id));
    }
  }
  return changed;
}

function getTaskCenterCapabilities() {
  const adapters = adapterCapabilities();
  const automationEnabled = taskAutomationEnabled();
  return JSON.stringify({ ok: true, protocolVersion: TASK_PROTOCOL_VERSION, adapters, automationEnabled, executionMode: automationEnabled ? 'automatic' : 'manual', agentInboxPath: agentTaskInboxPath(), agentResultPath: agentTaskResultPath(), qclawInboxPath: qclawTaskInboxPath(), qclawResultPath: qclawTaskResultPath(), taskStorePath: taskStorePath() });
}

function isManagedOpenClawCronJob(job) {
  const name = String(job?.name || '');
  const owner = String(job?.metadata?.owner || job?.payload?.metadata?.owner || '');
  return /^\[教育管家\]/.test(name) || owner === 'edu-manager';
}

function managedOpenClawCronDefinition(job) {
  const payload = job?.payload || {};
  const schedule = job?.schedule || payload.schedule || {};
  const command = String(payload.message || payload.command || job?.message || job?.command || '');
  const permissions = payload.permissions || job?.permissions || {};
  const expectedOutput = payload.expectedOutput || job.expectedOutput || {};
  const declaredTimezone = String(schedule?.tz || schedule?.timezone || '');
  const localTimezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
  const reads = Array.isArray(permissions.read) ? permissions.read.filter((item) => path.isAbsolute(String(item))) : [];
  const writes = Array.isArray(permissions.write) ? permissions.write.filter((item) => path.isAbsolute(String(item))) : [];
  if (!job?.id || !command || !cronOccurrence(schedule) || (declaredTimezone && declaredTimezone !== localTimezone) || (!reads.length && !writes.length) || !(expectedOutput.path || expectedOutput.draftPath)) return null;
  return {
    id: String(job.id),
    name: String(job.name || job.id),
    schedule,
    command,
    permissions: { read: reads, write: writes, operations: ['execute_scheduled_task'] },
    expectedOutput,
    adoptedAt: taskNow(),
    source: 'openclaw_cron',
  };
}

function readManagedOpenClawCronRegistry() {
  const parsed = safeReadJson(openClawCronRegistryPath(), {});
  return { version: 1, updatedAt: String(parsed.updatedAt || ''), jobs: Array.isArray(parsed.jobs) ? parsed.jobs : [] };
}

function writeManagedOpenClawCronRegistry(registry) {
  writeJsonFile(openClawCronRegistryPath(), { version: 1, updatedAt: taskNow(), jobs: registry.jobs || [] });
}

function managedOpenClawCronCandidates(registry, now = Date.now()) {
  return (registry.jobs || []).map((job) => {
    const occurrence = cronOccurrence(job.schedule, now);
    if (!occurrence) return null;
    return normalizeTaskEnvelope({
      id: taskStableId('openclaw_cron', 'system', job.id, occurrence.key),
      title: `OpenClaw 定时任务：${job.name}`,
      kind: 'openclaw_cron',
      sourceType: 'system',
      sourceId: job.id,
      sourceName: 'OpenClaw Cron（任务中心托管）',
      status: 'pending',
      trigger: 'schedule',
      executor: 'openclaw',
      requestedExecutor: 'auto',
      executionMode: 'adapter',
      scheduledAt: occurrence.scheduledAt,
      scheduleKey: occurrence.key,
      idempotencyKey: `openclaw_cron:${job.id}:${occurrence.key}`,
      input: { command: job.command, externalSchedule: job.schedule, importedFrom: 'openclaw_cron', adopted: true },
      expectedOutput: job.expectedOutput || { type: 'external_schedule_event' },
      permissions: job.permissions,
      detail: 'OpenClaw 原定时任务已停用，由统一任务中心按原计划生成执行批次并统一审核。',
      action: 'openclaw_cron',
    });
  }).filter(Boolean);
}

function syncOpenClawCronTasks(force = false) {
  if (!taskAutomationEnabled()) return Promise.resolve({ ok: true, skipped: true, message: '仅手动模式未执行 OpenClaw Cron 同步。' });
  if (openClawCronSyncState.promise) return openClawCronSyncState.promise;
  if (!force && openClawCronSyncState.result && Date.now() - openClawCronSyncState.at < 10 * 60 * 1000) return Promise.resolve({ ...openClawCronSyncState.result, throttled: true });
  const promise = (async () => {
    const capability = adapterCapabilities().openclaw;
    const registry = readManagedOpenClawCronRegistry();
    let adopted = 0;
    let observed = 0;
    let probeMessage = '';
    if (capability.healthPending) {
      await refreshAdapterCapabilities(true);
    }
    if (!taskAutomationEnabled()) {
      const result = { ok: true, skipped: true, message: '同步过程中切换为仅手动模式，未接管 OpenClaw Cron。' };
      openClawCronSyncState = { at: Date.now(), promise: null, result };
      return result;
    }
    const refreshedCapability = adapterCapabilities().openclaw;
    if (refreshedCapability.cron && refreshedCapability.gatewayHealthy && refreshedCapability.exePath) {
      const probe = await probeExecutableAsync(refreshedCapability.exePath, ['cron', 'list', '--all', '--json', '--timeout', '5000'], 7000);
      if (probe.ok) {
        try {
          const parsed = JSON.parse(probe.output);
          const jobs = Array.isArray(parsed) ? parsed : Array.isArray(parsed.jobs) ? parsed.jobs : [];
          const byId = new Map(registry.jobs.map((job) => [String(job.id), job]));
          for (const job of jobs) {
            if (!isManagedOpenClawCronJob(job)) { observed += 1; continue; }
            const definition = managedOpenClawCronDefinition(job);
            if (!definition) {
              appendTaskEvent('', 'openclaw_cron_adoption_rejected', { jobId: job.id, name: job.name, reason: '托管任务必须提供命令、受支持且与本机一致的时区、绝对读写权限和明确产物路径。' });
              continue;
            }
            byId.set(definition.id, { ...(byId.get(definition.id) || {}), ...definition });
            registry.jobs = [...byId.values()];
            writeManagedOpenClawCronRegistry(registry);
            if (job.enabled !== false) {
              const disabled = await probeExecutableAsync(refreshedCapability.exePath, ['cron', 'disable', definition.id, '--timeout', '5000'], 7000);
              if (!disabled.ok) {
                appendTaskEvent('', 'openclaw_cron_adoption_failed', { jobId: definition.id, message: disabled.output || disabled.error || '停用外部 Cron 失败。' });
                byId.delete(definition.id);
                registry.jobs = [...byId.values()];
                writeManagedOpenClawCronRegistry(registry);
                continue;
              }
            }
            adopted += 1;
          }
          registry.jobs = [...byId.values()];
          writeManagedOpenClawCronRegistry(registry);
        } catch {
          probeMessage = 'OpenClaw Cron 返回的不是有效 JSON。';
        }
      } else {
        probeMessage = probe.error || probe.output || '读取 OpenClaw Cron 失败。';
      }
    } else {
      probeMessage = 'OpenClaw Gateway/Cron 当前不可用，继续使用已接管的任务中心计划。';
    }
    const candidates = managedOpenClawCronCandidates(registry);
    if (candidates.length) upsertTaskCandidates(candidates);
    const result = { ok: true, adopted, observed, count: candidates.length, registryPath: openClawCronRegistryPath(), message: `任务中心托管 ${registry.jobs.length} 个 OpenClaw Cron，生成 ${candidates.length} 个当前执行批次。${probeMessage ? ` ${probeMessage}` : ''}` };
    openClawCronSyncState = { at: Date.now(), promise: null, result };
    return result;
  })().catch((error) => {
    const result = { ok: false, message: `OpenClaw Cron 同步失败：${error.message}` };
    openClawCronSyncState = { at: Date.now(), promise: null, result };
    return result;
  });
  openClawCronSyncState.promise = promise;
  return promise;
}

function openTaskCenterPath(kind = 'root', agentId = '') {
  try {
    const target = kind === 'agent-inbox' && agentId === 'qclaw' ? qclawTaskInboxPath()
      : kind === 'agent-inbox' && agentId === 'manual' ? taskManualOutboxPath()
      : kind === 'agent-inbox' ? agentTaskInboxPath(agentId)
      : kind === 'agent-results' ? agentTaskResultPath(agentId)
      : kind === 'qclaw-inbox' ? qclawTaskInboxPath()
      : kind === 'qclaw-results' ? qclawTaskResultPath()
        : kind === 'manual-outbox' ? taskManualOutboxPath()
          : kind === 'events' ? taskEventLogPath()
            : taskCenterDirPath();
    const folder = kind === 'events' ? path.dirname(target) : target;
    fs.mkdirSync(folder, { recursive: true });
    shell.openPath(folder);
    return JSON.stringify({ ok: true, path: folder, message: `已打开 ${folder}` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `打开任务目录失败：${error.message}` });
  }
}

function openTaskResultPath(taskId) {
  try {
    const task = readTaskStore().tasks.find((item) => String(item.id) === String(taskId));
    if (!task) return JSON.stringify({ ok: false, message: '未找到任务。' });
    if (!taskPresentation(task).hasResult) return JSON.stringify({ ok: false, message: '尚无已校验的结果文件。任务指令和诊断日志不是整理结果。' });
    const result = task.result && typeof task.result === 'object' ? task.result : {};
    const artifacts = Array.isArray(result.artifacts) ? result.artifacts : [];
    const fileChanges = Array.isArray(result.fileChanges) ? result.fileChanges : [];
    const candidates = [
      result.resultFile,
      result.importedFrom,
      ...artifacts.map((item) => item?.path),
      ...fileChanges.map((item) => item?.path),
      task.expectedOutput?.publishPath,
      task.expectedOutput?.draftPath,
      task.expectedOutput?.path,
    ].map((item) => canonicalTaskPath(item)).filter(Boolean);
    const allowedRoots = [
      taskCenterDirPath(),
      ...(task.permissions?.read || []),
      ...(task.permissions?.write || []),
      task.input?.knowledgeRoot,
      task.input?.rawPath,
      ...[task.expectedOutput?.publishPath, task.expectedOutput?.draftPath, task.expectedOutput?.path].filter(Boolean).map((item) => path.dirname(String(item))),
    ].map((item) => canonicalTaskPath(item)).filter(Boolean);
    const target = [...new Set(candidates)].find((item) => fs.existsSync(item) && taskPathAllowed(item, allowedRoots));
    if (!target) {
      return JSON.stringify({ ok: false, message: result.summary || result.message
        ? '当前任务已有反馈摘要，但没有可打开的结果文件；请在任务详情中查看反馈。'
        : '当前任务尚未生成可打开的反馈结果。' });
    }
    shell.openPath(target).catch(() => {});
    return JSON.stringify({ ok: true, path: target, message: `已打开任务结果：${target}` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `打开任务结果失败：${error.message}` });
  }
}

function scheduledTimeReached(value) {
  const match = String(value || '').match(/^(\d{1,2}):(\d{2})$/);
  if (!match) return true;
  const now = new Date();
  return now.getHours() * 60 + now.getMinutes() >= Number(match[1]) * 60 + Number(match[2]);
}

async function reopenTaskHandoff(taskId, executionId, action = 'open') {
  const task = readTaskStore().tasks.find(item => item.id === String(taskId));
  if (!task || task.executionId !== String(executionId) || !taskPresentation(task).awaitingSend) return JSON.stringify({ ok: false, message: '任务状态或执行批次已变化，请刷新后操作。' });
  if (!['open', 'copy'].includes(action)) return JSON.stringify({ ok: false, message: '不支持的交接操作。' });
  const file = canonicalTaskPath(task.result?.packet?.promptPath);
  if (!file || !taskPathWithin(file, taskCenterDirPath())) return JSON.stringify({ ok: false, message: '本次任务指令路径无效。' });
  const real = await fs.promises.realpath(file);
  if (!taskPathWithin(real, await fs.promises.realpath(taskCenterDirPath()))) return JSON.stringify({ ok: false, message: '任务指令超出允许目录。' });
  if ((await fs.promises.stat(real)).size > 1024 * 1024) return JSON.stringify({ ok: false, message: '任务指令文件过大。' });
  const command = await fs.promises.readFile(real, 'utf8');
  const current = readTaskStore().tasks.find(item => item.id === task.id);
  if (current?.executionId !== executionId || !taskPresentation(current).awaitingSend) return JSON.stringify({ ok: false, message: '任务已发生变化，未重复交接。' });
  if (action === 'copy') { clipboard.writeText(command); return JSON.stringify({ ok: true, message: '已复制本次执行指令，请检查后发送。' }); }
  if (task.adapterId !== 'workbuddy') return JSON.stringify({ ok: false, message: '当前工具请使用复制指令。' });
  const install = findAgentToolInstall('workbuddy');
  if (!install.exePath) return JSON.stringify({ ok: false, message: '未找到 WorkBuddy，请使用复制指令。' });
  const prompt = command.length <= 7000 ? command : `请执行教育管家任务 ${task.id}。完整任务指令保存在：${real}\n请读取该文件并遵守资料范围和结果回写要求。`;
  const deepLink = buildWorkBuddyTaskDeepLink(install, { command: prompt, cwd: task.input?.knowledgeRoot || taskCenterDirPath(), permissionMode: 'default' });
  await new Promise((resolve, reject) => {
    const child = spawn(install.exePath, [deepLink], { detached: true, stdio: 'ignore', windowsHide: false, shell: false });
    child.once('error', reject); child.once('spawn', () => { child.unref(); resolve(); });
  });
  return JSON.stringify({ ok: true, message: '已请求打开原批次，请检查输入框后发送；未创建重复任务。' });
}

async function runUnifiedTaskScheduler() {
  if (!projectArchiveRuntime.status().ready) return { ok: true, skipped: true, reason: 'archive_busy' };
  repairTaskCenterRuntimeState();
  if (taskSchedulerRunning) return { ok: true, skipped: true, message: '上一轮统一任务调度仍在运行。' };
  if (!taskAutomationEnabled()) return { ok: true, skipped: true, message: '当前为仅手动模式，未运行自动调度。' };
  if (captureTimelineScheduler?.state().running.length) return { ok: true, skipped: true, message: '学习时间线正在后台整理，本轮自动任务稍后重试。' };
  taskSchedulerRunning = true;
  try {
    if (!publicLicenseStatus().active) return { ok: false, skipped: true, message: '许可证未激活，自动任务未执行。' };
    syncAgentTaskResults();
    await syncOpenClawCronTasks();
    await refreshAdapterCapabilities(false);
    if (!taskAutomationEnabled()) return { ok: true, skipped: true, message: '调度过程中已切换为仅手动模式，未启动新任务。' };
    await runProjectAutomationSweep();
    restoreHeavyTaskRetries();
    restoreBusinessTaskRetries();
    const store = upsertTaskCandidates(buildTaskCenterCandidates(), { reconcileStudentDigests: true, reconcileWeeklyActions: true, reconcileInactiveStudents: true });
    const automationStudents = new Map(readStudentsIndex().map(s=>[String(s.id),s]));
    const automaticAllowed = task => !task.recovery?.manualOnly && !automaticStudentTaskBlocked(task,automationStudents.get(String(task.sourceId)));
    if (enforceTaskTimeouts(store)) writeTaskStore(store);
    const retryDue = readTaskStore().tasks.filter((task) => ['failed', 'timed_out', 'blocked'].includes(task.status)
      && automaticAllowed(task) && !RESEARCH_KINDS.has(task.kind)
      && taskRetryEligible(task));
    for (const task of retryDue) fallbackTaskAfterFailure(task.id, task.adapterId, task.error?.message || '计划重试');
    const scheduledReportKinds = new Set(['weekly_action', ...Object.keys(PERIODIC_REPORT_TASKS), 'openclaw_cron',
      'maintenance_lint', 'topic_suggestion_refresh', 'student_digest']);
    const due = readTaskStore().tasks.filter((task) => automaticAllowed(task) && scheduledReportKinds.has(task.kind)
      && ['pending', 'approved', 'queued'].includes(task.status)
      && Number(task.attempt || 0) === 0
      && (!isAutoPublishReportTask(task) || Boolean(task.input?.growthFingerprint))
      && (['student_digest', 'topic_suggestion_refresh'].includes(task.kind)
        || (task.kind === 'openclaw_cron' ? Date.parse(task.scheduledAt || '') <= Date.now() : scheduledTimeReached(task.scheduledAt))));
    const results = due.map((task) => {
      try { return JSON.parse(executeTaskByAdapter(task.id, 'auto', {automatic:true})); }
      catch (error) { return { ok: false, taskId: task.id, message: error.message }; }
    });
    // Reuse the existing licensed/manual-mode-aware scheduler. Research remains async and serial.
    void runCompetitionResearchSchedule();
    if (typeof getSmartInbox === 'function') void getSmartInbox().then(engine => engine.tick()).catch(error => console.warn('资料归集调度：', error.message));
    if (results.length) appendHostTimeline({ type: 'unified_task_scheduler', title: 'Unified task scheduler', detail: `due tasks ${results.length}`, count: results.length });
    notify('onNativeTaskCenterChanged', JSON.stringify({ scheduled: results.length, at: taskNow() }));
    return { ok: true, results, message: results.length ? `已调度 ${results.length} 个到期任务。` : '当前没有到期的统一任务。' };
  } catch (error) {
    return { ok: false, message: `统一任务调度失败：${error.message}` };
  } finally {
    taskSchedulerRunning = false;
  }
}

function startUnifiedTaskScheduler() {
  stopUnifiedTaskScheduler();
  if (process.env.EDU_DISABLE_TASK_SCHEDULER !== '1' && publicLicenseStatus().active) {
    setImmediate(async () => { for (const student of readStudentsIndex().map(toHostStudent)) {
      try { await getPracticeTaskHost().recover(String(student.id)); } catch (error) { console.warn('Practice recovery:', error.message); }
    } });
  }
  if (process.env.EDU_DISABLE_TASK_SCHEDULER === '1' || !taskAutomationEnabled()) return;
  try { restoreBusinessTaskRetries(); } catch (error) { console.warn('Task retry recovery paused:', error.message); }
  taskSchedulerStartupTimer = setTimeout(() => { void runUnifiedTaskScheduler(); }, 30 * 1000);
  taskSchedulerTimer = setInterval(() => { void runUnifiedTaskScheduler(); }, 15 * 60 * 1000);
}

let competitionScheduleRunning = false;
async function runCompetitionResearchSchedule() {
  if (competitionScheduleRunning || !taskAutomationEnabled() || !publicLicenseStatus().active) return;
  competitionScheduleRunning = true;
  try {
    await refreshAdapterCapabilities(false);
    const service = planningGuidanceService();
    if (!service.getResearchCapabilityStatus().available) return;
    upsertTaskCandidates(buildTaskCenterCandidates(), { reconcileInactiveStudents: true });
    const retryCandidates = readTaskStore().tasks.filter(task => ['failed', 'blocked'].includes(task.status) && researchTaskDue(task)
      && task.kind !== 'guidance_plan_refresh').map(task => ({ taskType: task.kind, studentId: task.sourceId, scheduledAt: task.scheduledAt }));
    const candidates = [...service.competitionTaskCandidates(), ...service.taskCandidates().filter(item => item.taskType === 'guidance_research_check'), ...retryCandidates];
    const seen = new Set();
    for (const candidate of candidates) {
      const key = `${candidate.taskType}:${candidate.studentId}`;
      if (seen.has(key)) continue;
      seen.add(key);
      if (!taskAutomationEnabled() || !publicLicenseStatus().active) break;
      if (studentAutomaticTasksPaused(findStudentByKey(candidate.studentId))) continue;
      if (candidate.taskType === 'competition_research_check' && service.getCompetitionRecommendations(candidate.studentId).preferences.automaticMonthlyCheck === false) continue;
      if (candidate.taskType === 'guidance_research_check' && service.getGuidancePlan(candidate.studentId).preferences.automaticMonthlyCheck === false) continue;
      if (!scheduledTimeReached(candidate.scheduledAt || findStudentByKey(candidate.studentId)?.digestTime || '21:30')) continue;
      const taskId = taskStableId(candidate.taskType, 'student', candidate.studentId);
      if (!researchTaskDue(readTaskStore().tasks.find(task => task.id === taskId))) continue;
      executeTaskByAdapter(taskId, 'internal', {automatic:true});
      await taskDispatchPending.get(String(taskId));
      await taskChildProcesses.get(taskId)?.completion;
      notify('onNativeTaskCenterChanged', JSON.stringify({ competitionResearch: true, at: taskNow() }));
    }
  } catch (error) {
    appendHostTimeline({ type: 'competition_research_check_failed', title: '比赛推荐研究未完成', detail: String(error.message || '研究失败').slice(0, 300) });
  } finally { competitionScheduleRunning = false; }
}

function stopUnifiedTaskScheduler() {
  if (taskSchedulerStartupTimer) clearTimeout(taskSchedulerStartupTimer);
  if (taskSchedulerTimer) clearInterval(taskSchedulerTimer);
  taskSchedulerStartupTimer = null;
  taskSchedulerTimer = null;
}

function readStudentScheduleLedger(student) {
  const file = studentScheduleLedgerPath(student);
  const parsed = safeReadJson(file, {});
  return {
    version: 1,
    updatedAt: parsed.updatedAt || '',
    entries: Array.isArray(parsed.entries) ? parsed.entries : [],
  };
}

function writeStudentScheduleLedger(student, ledger) {
  const file = studentScheduleLedgerPath(student);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, JSON.stringify({
    version: 1,
    updatedAt: new Date().toISOString(),
    entries: (ledger.entries || []).slice(0, 300),
  }, null, 2), 'utf8');
}

function recordScheduledTaskAction(studentId, kind, commandText) {
  try {
    const student = readStudentsIndex().find((item) => String(item.id) === String(studentId));
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const normalized = toHostStudent(student);
    ensureStudentWorkspaceConfig(normalized);
    const now = new Date().toISOString();
    const day = now.slice(0, 10);
    const taskKind = String(kind || 'digest');
    if (taskKind === 'digest') {
      const pendingCount = readStudentMaterials(normalized).filter((item) => normalizeUploadStatus(item.status) === 'pending_digest').length;
      if (pendingCount === 0) return JSON.stringify({ ok: false, skipped: true, reason: 'no_pending_materials', message: '当前没有待提交资料，未创建消化任务记录。' });
    }
    const commandHash = sha1Text(String(commandText || '')).slice(0, 16);
    const ledger = readStudentScheduleLedger(normalized);
    const duplicate = ledger.entries.find((entry) => entry.day === day && entry.kind === taskKind && entry.commandHash === commandHash);
    if (duplicate) {
      duplicate.lastCopiedAt = now;
      duplicate.copyCount = Number(duplicate.copyCount || 1) + 1;
      duplicate.status = 'copied';
      writeStudentScheduleLedger(normalized, ledger);
      return JSON.stringify({ ok: true, duplicate: true, ledger, message: '今日同类指令已记录，本次只更新复制次数。' });
    }
    ledger.entries.unshift({
      id: `task-${day}-${taskKind}-${commandHash}`,
      day,
      kind: taskKind,
      commandHash,
      status: 'copied',
      copiedAt: now,
      lastCopiedAt: now,
      copyCount: 1,
      studentId: normalized.id,
      studentName: normalized.name,
      digestTime: normalized.digestTime,
    });
    writeStudentScheduleLedger(normalized, ledger);
    appendHostTimeline({ type: 'scheduled_task_recorded', title: 'Scheduled task recorded', detail: `${normalized.name} ${taskKind}`, count: 1 });
    return JSON.stringify({ ok: true, duplicate: false, ledger, message: '已写入定时任务去重账本。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `写入定时任务账本失败：${error.message}` });
  }
}

function getStudentScheduleLedger(studentId) {
  try {
    const student = readStudentsIndex().find((item) => String(item.id) === String(studentId));
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const normalized = toHostStudent(student);
    const ledger = readStudentScheduleLedger(normalized);
    const reportPath = studentMaintenanceReportPath(normalized);
    return JSON.stringify({
      ok: true,
      ledger,
      reportPath,
      reportExists: fs.existsSync(reportPath),
      message: `已读取 ${ledger.entries.length} 条定时任务记录。`,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `读取定时任务账本失败：${error.message}` });
  }
}

function buildTaskCenterCandidates() {
  const iterator = taskCenterCandidateBatches();
  let step = iterator.next();
  while (!step.done) step = iterator.next();
  return step.value;
}

function* taskCenterCandidateBatches() {
  const students = readStudentsIndex().map(toHostStudent);
  const taskCardStudents = students.filter((student) => !studentTaskCardsSuppressed(student));
  const projects = readProjects().map(normalizeProject);
  const tasks = [];
  for (const student of taskCardStudents) {
    const materials = readStudentMaterials(student);
    const digestState = readStudentDigestState(student);
    const pendingCount = materials.filter((item) => normalizeUploadStatus(item.status) === 'pending_digest').length;
    const submittedCount = materials.filter((item) => ['submitted', 'digesting'].includes(normalizeUploadStatus(item.status))).length;
    const digestStatus = String(digestState.status || student.digestStatus || '').toLowerCase();
    const openDigestMaterials = materials.filter((item) => isOpenDigestStatus(item.status));
    const studentDigestKey = digestState.digestBatchId
      ? `student_digest:${student.id}:${digestState.digestBatchId}`
      : openDigestMaterials.length
        ? digestIdempotencyKey({ type: 'student', id: String(student.id) }, openDigestMaterials.map((item) => ({ materialId: item.id, relativePath: item.path || item.fileName, sha1: item.sha1 || '', size: item.size || 0 })))
        : `student_digest:${student.id}:idle`;
    if (pendingCount > 0 || submittedCount > 0 || ['digesting', 'submitted'].includes(digestStatus)) {
      tasks.push(normalizeTaskEnvelope({
        id: taskStableId('student_digest', 'student', student.id),
        title: `${student.name}每日资料消化`, kind: 'student_digest', sourceType: 'student', sourceId: String(student.id), sourceName: student.name,
        status: digestStatus === 'digesting' ? 'running' : digestStatus === 'submitted' || submittedCount > 0 ? 'waiting_result' : 'pending',
        trigger: 'event', executor: String(student.agentTool || 'workbuddy'), requestedExecutor: String(student.agentTool || 'workbuddy'), executionMode: 'adapter',
        scheduledAt: String(student.digestTime || '21:30'), count: pendingCount || submittedCount,
        idempotencyKey: studentDigestKey,
        completionPolicy: 'auto_after_validation',
        input: { studentId: String(student.id), knowledgeRoot: student.rootPath || getStudentRootDir(student.name), rawPath: student.rawPath || getRawDir(student.name), digestBatchId: digestState.digestBatchId || '', manifestPath: studentDigestBatchPath(student), controlledMaterial: providerSupportsProfile(String(student.agentTool || ''), DIGEST_PROFILE) },
        expectedOutput: { type: 'digest_receipt_v1', path: studentDigestReceiptPath(student), statePath: studentDigestStatePath(student) },
        permissions: { read: [student.rootPath || getStudentRootDir(student.name)], write: [student.rootPath || getStudentRootDir(student.name), student.summaryPath || getSummaryDir(student.name), studentManagerDir(student)], operations: ['read', 'write_knowledge'] },
        detail: pendingCount > 0 ? `有 ${pendingCount} 份资料等待消化。` : `有 ${submittedCount} 份资料等待 Agent 回执。`, action: 'student_digest',
      }));
    }
    const governance = digestState.knowledgeGovernance || {};
    if (Number(governance.attentionCount || 0) > 0) {
      tasks.push(normalizeTaskEnvelope({
        id: taskStableId('knowledge_quality', 'student', student.id),
        title: `${student.name}知识处理需要检查`,
        kind: 'knowledge_quality',
        sourceType: 'student',
        sourceId: String(student.id),
        sourceName: student.name,
        status: 'pending',
        trigger: 'event',
        executor: 'human-review',
        requestedExecutor: 'manual',
        executionMode: 'review',
        count: Number(governance.attentionCount || 0),
        idempotencyKey: String(governance.runId || `knowledge_quality:${student.id}`),
        expectedOutput: { type: 'knowledge_governance_report', path: governance.reportPath || '' },
        permissions: { read: [governance.reportPath].filter(Boolean), write: [], operations: ['review_knowledge'] },
        detail: `自动治理发现 ${governance.attentionCount} 个会影响资料闭环的异常；低风险项已自动收起。`,
        action: 'knowledge_quality',
        riskLevel: 'medium',
      }));
    }
    tasks.push(...currentLearningReportTaskCandidates(student));
    const maintenanceWeek = weekRange(new Date());
    tasks.push(normalizeTaskEnvelope({
      id: taskStableId('maintenance_lint', 'student', student.id),
      title: `${student.name}知识库维护检查`, kind: 'maintenance_lint', sourceType: 'student', sourceId: String(student.id), sourceName: student.name,
      status: 'queued', trigger: 'schedule', executor: String(student.agentTool || 'workbuddy'), requestedExecutor: String(student.agentTool || 'workbuddy'), executionMode: 'adapter', scheduledAt: String(student.digestTime || '21:30'),
      idempotencyKey: `maintenance_lint:${student.id}:${maintenanceWeek.key}`,
      input: { studentId: String(student.id), knowledgeRoot: student.rootPath || getStudentRootDir(student.name) },
      expectedOutput: { type: 'markdown', path: studentMaintenanceReportPath(student) },
      permissions: { read: [student.rootPath || getStudentRootDir(student.name)], write: [studentMaintenanceReportPath(student)], operations: ['read', 'create_report'] },
      detail: '检查路径、规则、索引、断链和成长模型健康度。', action: 'student_maintenance',
    }));
    yield;
  }
  for (const project of projects) {
    const digestState = project.digestState || {};
    const pendingDigest = Math.max(0, Number(digestState.pendingCount || 0));
    const digestStatus = String(digestState.status || 'idle');
    const projectDigestKey = digestState.digestBatchId
      ? `project_digest:${project.id}:${digestState.digestBatchId}`
      : (digestState.pendingFiles || []).length
        ? digestIdempotencyKey({ type: 'project', id: String(project.id) }, (digestState.pendingFiles || []).map((file) => ({ materialId: `project-${crypto.createHash('sha1').update(`${project.id}|${file.relativePath}`).digest('hex').slice(0, 20)}`, ...file })))
        : `project_digest:${project.id}:idle`;
    const configuredProjectAgent = String(project.agentTool || 'workbuddy');
    const projectDigestExecutor = providerSupportsProfile(configuredProjectAgent, DIGEST_PROFILE) ? configuredProjectAgent : 'codex';
    const globalProjectScopeEnabled = Boolean(isWorkspaceMaterialProject(project)
      && agentControlStore().read().global?.enabled
      && Number(agentControlStore().read().global?.version || 0) > 0);
    if (pendingDigest > 0 || ['digesting', 'submitted', 'failed'].includes(digestStatus)) tasks.push(normalizeTaskEnvelope({
      id: taskStableId('project_digest', 'project', project.id),
      title: `${project.name}项目资料消化`, kind: 'project_digest', sourceType: 'project', sourceId: String(project.id), sourceName: project.name,
      status: digestStatus === 'digesting' ? 'running' : digestStatus === 'submitted' ? 'waiting_result' : digestStatus === 'failed' ? 'blocked' : pendingDigest > 0 ? 'pending' : 'queued',
      trigger: project.automation?.enabled ? 'schedule' : 'manual', executor: projectDigestExecutor, requestedExecutor: projectDigestExecutor, executionMode: 'adapter',
      scheduledAt: project.automation?.enabled ? String(project.automation.nextRunAt || '等待调度') : '', count: pendingDigest,
      idempotencyKey: projectDigestKey,
      completionPolicy: 'auto_after_validation',
      input: { projectId: String(project.id), knowledgeRoot: project.knowledgeRootPath,
        ...(globalProjectScopeEnabled ? { projectScopeContract: PROJECT_SCOPE_CONTRACT_VERSION } : { rawPath: project.rawPath }),
        digestBatchId: digestState.digestBatchId || '', manifestPath: projectDigestRequestPath(project), controlledMaterial: isWorkspaceMaterialProject(project) },
      expectedOutput: globalProjectScopeEnabled
        ? { type: 'project_digest_host_receipt', hostManaged: true }
        : { type: 'project_digest_receipt', path: projectDigestReceiptPath(project) },
      permissions: globalProjectScopeEnabled
        ? { read: [project.knowledgeRootPath].filter(Boolean), write: [project.knowledgeRootPath].filter(Boolean), operations: ['read', 'write_project_knowledge'] }
        : isWorkspaceMaterialProject(project)
        ? { read: [project.workspacePath, project.rawPath, project.knowledgeRootPath, project.managerPath, project.agentPath].filter(Boolean),
          write: [project.knowledgeRootPath, project.managerPath], operations: ['read', 'write_project_knowledge'] }
        : { read: [project.rawPath, project.knowledgeRootPath, projectDigestRequestPath(project)].filter(Boolean), write: [project.knowledgeRootPath, projectDigestReceiptPath(project)].filter(Boolean), operations: ['read', 'write_project_knowledge'] },
      detail: pendingDigest > 0 ? `有 ${pendingDigest} 份正式资料等待 Agent 消化。` : '当前没有待消化的项目资料。', action: 'project_digest', riskLevel: 'medium',
    }));
    const pendingKnowledge = Math.max(0, Number(project.dashboard?.pendingKnowledgeCount || 0));
    if (pendingKnowledge > 0) tasks.push(normalizeTaskEnvelope({
      id: taskStableId('knowledge_review', 'project', project.id),
      title: `${project.name}知识资产审核`, kind: 'knowledge_review', sourceType: 'project', sourceId: String(project.id), sourceName: project.name,
      status: 'pending', trigger: 'event', executor: 'human-review', requestedExecutor: 'manual', executionMode: 'review', count: pendingKnowledge,
      detail: `有 ${pendingKnowledge} 条概念、实体、摘要或结论等待审核。`, action: 'project_knowledge', riskLevel: 'medium',
      permissions: { read: [project.knowledgeRootPath].filter(Boolean), write: [project.knowledgeRootPath].filter(Boolean), operations: ['review_knowledge'] },
    }));
    const projectGovernance = digestState.knowledgeGovernance || {};
    if (Number(projectGovernance.attentionCount || 0) > 0) {
      tasks.push(normalizeTaskEnvelope({
        id: taskStableId('knowledge_quality', 'project', project.id),
        title: `${project.name}知识处理需要检查`,
        kind: 'knowledge_quality',
        sourceType: 'project',
        sourceId: String(project.id),
        sourceName: project.name,
        status: 'pending',
        trigger: 'event',
        executor: 'human-review',
        requestedExecutor: 'manual',
        executionMode: 'review',
        count: Number(projectGovernance.attentionCount || 0),
        idempotencyKey: String(projectGovernance.runId || `knowledge_quality:${project.id}`),
        expectedOutput: { type: 'knowledge_governance_report', path: projectGovernance.reportPath || '' },
        permissions: { read: [projectGovernance.reportPath].filter(Boolean), write: [], operations: ['review_knowledge'] },
        detail: `自动治理发现 ${projectGovernance.attentionCount} 个会影响资料闭环的异常；低风险项已自动收起。`,
        action: 'knowledge_quality',
        riskLevel: 'medium',
      }));
    }
    const contributionStatus = String(project.dashboard?.contributionStatus || '');
    const promotionTargets = readStudentsIndex().filter((student) => (project.studentIds || []).map(String).includes(String(student.id))).map((student) => growthModelDirForStudent(toHostStudent(student)));
    if (project.dashboard?.contributionReady || contributionStatus || project.archivedAt) tasks.push(normalizeTaskEnvelope({
      id: taskStableId('project_promotion', 'project', project.id),
      title: `${project.name}知识贡献与归档`, kind: 'project_promotion', sourceType: 'project', sourceId: String(project.id), sourceName: project.name,
      status: project.publishedAt ? 'succeeded' : 'pending', trigger: 'event', executor: 'human-review', requestedExecutor: 'manual', executionMode: 'review', riskLevel: 'high',
      detail: project.publishedAt ? '项目贡献已发布到成长模型。' : '高风险发布任务，审批后才能进入学生档案或成长模型。', action: 'project_promotion',
      permissions: { read: [project.knowledgeRootPath].filter(Boolean), write: promotionTargets, operations: ['publish_growth_evidence', 'archive_project'] },
      approval: { required: true, status: project.publishedAt ? 'approved' : 'pending' },
    }));
    yield;
  }
  const researchCapability = planningGuidanceService().getResearchCapabilityStatus();
  for (const candidate of planningGuidanceService().taskCandidates()) {
    const sourceStudent = taskCardStudents.find((item) => String(item.id) === String(candidate.studentId));
    if (!sourceStudent) continue;
    const isTopic = candidate.taskType === 'topic_suggestion_refresh';
    const isResearch = candidate.taskType === 'guidance_research_check';
    const isCompetition = candidate.taskType === 'competition_research_check';
    const status = isTopic ? (candidate.due ? 'pending' : 'queued') : researchCapability.available ? 'pending' : 'blocked';
    tasks.push(normalizeTaskEnvelope({
      id: taskStableId(candidate.taskType, 'student', candidate.studentId),
      title: isCompetition ? `${candidate.sourceName}比赛推荐来源检查` : isTopic ? `${candidate.sourceName}选题建议更新` : isResearch ? `${candidate.sourceName}规划来源检查` : `${candidate.sourceName}规划建议版本更新`,
      kind: candidate.taskType,
      sourceType: 'student',
      sourceId: candidate.studentId,
      sourceName: candidate.sourceName,
      status,
      trigger: isTopic ? 'event' : 'schedule',
      executor: isTopic ? 'internal' : 'auto',
      requestedExecutor: isTopic ? 'internal' : 'auto',
      executionMode: isTopic ? 'internal' : 'adapter',
      scheduledAt: isTopic ? '学生资料实质变化后' : (candidate.scheduledAt || sourceStudent.digestTime || '21:30'),
      idempotencyKey: candidate.idempotencyKey,
      input: { studentId: candidate.studentId, operation: candidate.taskType },
      permissions: { read: [studentAiManagerDir(sourceStudent)],
        write: [path.join(studentAiManagerDir(sourceStudent), 'planning-guidance')],
        operations: ['read_planning_evidence', 'write_planning_suggestions'] },
      detail: isTopic
        ? '依据学生档案和已确认成长证据生成科创与社会实践候选；采用只准备项目草稿。'
        : researchCapability.available ? '检查官方来源，并仅在输入或来源实质变化时生成新规划版本。' : '未发现通过真实 URL 与结构化结果探测的联网研究执行器，上一有效版本将继续保留。',
      action: candidate.taskType,
      riskLevel: 'low',
      error: status === 'blocked' ? { code: 'RESEARCH_CAPABILITY_UNAVAILABLE', message: researchCapability.message } : null,
    }));
  }
  return tasks;
}

// Read-model maintenance is independent of page reads and never dispatches an Agent.
// Manual mode still needs a task catalogue and incoming receipt collection.
async function maintainTaskReadModel() {
  if (taskReadMaintenanceRunning || taskReadMaintenanceStopped || !projectArchiveRuntime.status().ready) return;
  taskReadMaintenanceRunning = true;
  try {
    await taskIoClient.request(taskStorePath(), 'watch');
    if (taskReadMaintenanceStopped) return;
    syncAgentTaskResults();
    void checkTaskExecutorCircuits();
    if (Date.now() - taskCatalogRefreshedAt < 60_000) return;
    const iterator = taskCenterCandidateBatches();
    let step = iterator.next();
    while (!step.done) {
      await new Promise(resolve => setImmediate(resolve));
      if (taskReadMaintenanceStopped) return;
      step = iterator.next();
    }
    const store = upsertTaskCandidates(step.value, { reconcileStudentDigests: true, reconcileWeeklyActions: true, reconcileInactiveStudents: true });
    if (!fs.existsSync(taskStorePath())) writeTaskStore(store);
    taskCatalogRefreshedAt = Date.now();
    notify('onNativeTaskCenterChanged', JSON.stringify({ snapshot: true, at: taskNow() }));
  } catch (error) { console.warn('Task catalogue maintenance:', error.message); }
  finally { taskReadMaintenanceRunning = false; }
}

function startTaskReadMaintenance() {
  if (process.env.EDU_DISABLE_TASK_SCHEDULER === '1' || taskReadMaintenanceTimer) return;
  taskReadMaintenanceStopped = false;
  const tick = async () => {
    await maintainTaskReadModel();
    if (typeof smartInboxHostRuntime !== 'undefined' && smartInboxHostRuntime?.engine.hasPendingWork()) void smartInboxHostRuntime.engine.tick().catch(error => console.warn('资料批次等待资源：', error.message));
    if (!taskReadMaintenanceStopped) {
      taskReadMaintenanceTimer = setTimeout(tick, 60_000);
      taskReadMaintenanceTimer.unref?.();
    }
  };
  taskReadMaintenanceTimer = setTimeout(tick, 5_000);
  taskReadMaintenanceTimer.unref?.();
}

async function getTaskPage(query = {}, op = 'list') {
  try {
    const result = await taskIoClient.request(taskStorePath(), op, query && typeof query === 'object' ? query : {});
    if (!['list', 'legacy'].includes(op)) return JSON.stringify(result);
    const snapshot = { ...result, automationEnabled: taskAutomationEnabled(),
      storageFault: taskStoreGuard.status(),
      capabilities: registeredAdapterCapabilities(),
      executionMode: taskAutomationEnabled() ? 'automatic' : 'manual',
      message: result.ok ? (result.ready ? '已显示任务快照；后台持续更新。' : '正在等待任务快照初始化…') : result.message };
    const raw = JSON.stringify(snapshot);
    if (op === 'legacy') taskLegacySnapshot = raw;
    return raw;
  } catch (error) { return JSON.stringify({ ok: false, ready: false, message: error.message }); }
}

function getTaskCenter(options = {}) {
  // Compatibility getter is read-only too. Never scan, probe, or settle jobs on a page read.
  if (!taskSnapshotRefresh) {
    taskSnapshotRefresh = getTaskPage({}, 'legacy').finally(() => { taskSnapshotRefresh = null; });
  }
  return taskLegacySnapshot || JSON.stringify({ ok: true, ready: false, tasks: [], history: [],
    summary: { total: 0, actionable: 0, running: 0, scheduled: 0, completed: 0, archived: 0 },
    message: '任务快照正在加载，请稍候。' });
}

function getTaskStatuses(taskIds = []) {
  try {
    const ids = new Set((Array.isArray(taskIds) ? taskIds : []).map(String).filter(Boolean).slice(0, 32));
    if (!ids.size) return JSON.stringify({ ok: true, tasks: [], generatedAt: taskNow() });
    const store = readTaskStore();
    const tasks = store.tasks
      .filter((task) => ids.has(String(task.id)))
      .map((task) => ({
        id: task.id,
        status: task.status,
        updatedAt: task.updatedAt,
        completedAt: task.completedAt,
        error: task.error || null,
        result: task.result ? { summary: task.result.summary || '', message: task.result.message || '' } : null,
        detail: task.detail || '',
      }));
    return JSON.stringify({ ok: true, tasks, generatedAt: taskNow() });
  } catch (error) {
    return JSON.stringify({ ok: false, tasks: [], message: `读取任务状态失败：${error.message}` });
  }
}

function digestTaskId(scopeType, scopeId) {
  const kind = String(scopeType) === 'project' ? 'project_digest' : 'student_digest';
  return taskStableId(kind, String(scopeType), String(scopeId));
}

function digestBusinessSnapshot(scopeType, scopeId) {
  if (String(scopeType) === 'project') {
    const project = readProjectsForDigestLookup().find((item) => String(item.id) === String(scopeId));
    if (!project) return { ok: false, message: '未找到学习项目。' };
    const state = readProjectDigestState(project);
    return { ok: true, scopeType: 'project', scopeId: String(project.id), scopeName: project.name, state, pendingCount: Number(state.pendingCount || 0), submittedCount: Number(state.submittedCount || 0), processedCount: isWorkspaceMaterialProject(project) ? state.digestedFiles.length : Number(Object.keys(state.digestManifest || {}).length), lastDigestAt: state.lastDigestAt || '', knowledgePath: project.knowledgeRootPath };
  }
  const student = readStudentsIndex().map(toHostStudent).find((item) => String(item.id) === String(scopeId));
  if (!student) return { ok: false, message: '未找到学生档案。' };
  try { reconcileCompletedStudentDigestLearningReceipts(student); }
  catch (error) { console.warn('Completed digest late receipt reconciliation:', error.message); }
  syncStudentMaterialsFromUploadRecords(student);
  const state = readStudentDigestState(student);
  const materials = readStudentMaterials(student);
  return { ok: true, scopeType: 'student', scopeId: String(student.id), scopeName: student.name, state, pendingCount: materials.filter((item) => normalizeUploadStatus(item.status) === 'pending_digest').length, submittedCount: materials.filter((item) => ['submitted', 'digesting'].includes(normalizeUploadStatus(item.status))).length, processedCount: materials.filter((item) => normalizeUploadStatus(item.status) === 'processed').length, lastDigestAt: state.lastDigestAt || '', knowledgePath: student.rootPath || getStudentRootDir(student.name) };
}

function getDigestWorkflowStatusObject(scopeType, scopeId) {
  const business = digestBusinessSnapshot(scopeType, scopeId);
  if (!business.ok) return business;
  const task = readTaskStore().tasks.find((item) => String(item.id) === digestTaskId(scopeType, scopeId)) || null;
  const deferred = Boolean(task?.resourceDeferredAt && ['pending', 'approved', 'queued'].includes(task.status));
  const awaitingUserSend = task?.status === 'waiting_result' && task?.result?.handoffState === 'awaiting_user_send';
  const userStatus = deferred ? 'processing' : digestUserStatus(task?.status, business.state?.status, business.pendingCount, business.submittedCount);
  const manualMessage = task?.status === 'waiting_result' && task?.adapterId === 'manual'
    ? task?.result?.summary || '任务指令已复制；Agent 完成后系统会自动扫描输出和知识更新，不需要粘贴结果。'
    : '';
  return {
    ok: true,
    ...business,
    taskId: task?.id || digestTaskId(scopeType, scopeId),
    taskStatus: task?.status || '',
    executionId: task?.executionId || '',
    adapterId: task?.adapterId || task?.executor || '',
    executionMode: task?.executionMode || '',
    manualRequired: task?.status === 'waiting_result' && task?.adapterId === 'manual',
    command: task?.result?.packet?.promptPath ? '' : '',
    userStatus,
    label: deferred ? '排队中' : awaitingUserSend ? '待发送' : userStatusLabel(userStatus),
    message: deferred ? '已排队，当前任务结束或后台资源空闲后会自动继续。'
      : awaitingUserSend ? '资料已在 WorkBuddy 中准备好，请点击一次发送；完成后系统会自动收取结果。'
      : task?.error?.code === 'EXIT_4294770688'
      ? 'Agent 启动失败：旧版参数桥接器无法从安装包内访问。请使用修订版后点击“重试未完成项”。'
      : task?.error?.message || manualMessage || business.state?.message || task?.result?.summary || '',
    canStart: userStatus === 'pending' && business.pendingCount > 0,
    canRetry: ['partial', 'needs_help'].includes(userStatus) && (business.pendingCount > 0 || Number(business.submittedCount || 0) > 0),
    canPaste: false,
  };
}

function prepareDigestWorkflow(scopeType, scopeId) {
  const business = digestBusinessSnapshot(scopeType, scopeId);
  if (!business.ok) return business;
  if (business.pendingCount <= 0 && !Number(business.submittedCount || 0)) return { ok: false, skipped: true, completed: true, taskId: digestTaskId(scopeType, scopeId), message: '当前没有待处理资料。' };
  upsertTaskCandidates(buildTaskCenterCandidates(), { reconcileStudentDigests: true, reconcileInactiveStudents: true });
  const store = readTaskStore();
  const taskId = digestTaskId(scopeType, scopeId);
  const task = store.tasks.find((item) => item.id === taskId);
  if (!task) return { ok: false, message: '未能建立资料处理任务。' };
  let recoveredStaleExecution = false;
  if (['running', 'waiting_result'].includes(task.status) && task.executionId) {
    if (!shouldRecoverDigestExecution(task, business)) {
      return { ok: true, alreadyRunning: true, taskId, task, message: '资料已经在处理中；系统会自动检查回执，无需重复提交。' };
    }
    const running = taskChildProcesses.get(task.id);
    if (running?.materialRuntime) return { ok: true, alreadyRunning: true, taskId, task, message: '受控资料任务仍在执行，请等待当前批次。' };
    if (running) {
      clearTaskProcessHeartbeat(task.id);
      try { if (running.child && !running.child.killed) running.child.kill(); } catch { /* Stale execution reset still applies. */ }
      taskChildProcesses.delete(task.id);
    }
    Object.assign(task, {
      status: 'pending',
      statusGroup: taskStatusGroup('pending'),
      executionId: '',
      adapterId: '',
      executionMode: 'adapter',
      attempt: 0,
      startedAt: '',
      completedAt: '',
      lastHeartbeatAt: '',
      nextRetryAt: '',
      result: null,
      error: null,
      routeDecision: null,
      routeAttempts: [],
      updatedAt: taskNow(),
    });
    writeTaskStore(store);
    appendTaskEvent(task.id, 'digest_stale_execution_recovered', {
      from: 'active_without_submitted_materials',
      to: 'pending',
      pendingCount: business.pendingCount,
      submittedCount: Number(business.submittedCount || 0),
    });
    recoveredStaleExecution = true;
  }
  if (['running', 'waiting_result'].includes(task.status) && !task.executionId) {
    task.status = 'pending';
    task.statusGroup = taskStatusGroup('pending');
    task.updatedAt = taskNow();
    task.error = null;
    writeTaskStore(store);
    appendTaskEvent(task.id, 'digest_orphan_state_recovered', { from: 'waiting_without_execution', to: 'pending' });
  }
  return {
    ok: true,
    taskId,
    task: readTaskStore().tasks.find((item) => item.id === taskId),
    message: recoveredStaleExecution ? '已解除旧批次占位，正在为当前待处理资料建立新批次。' : '资料处理任务已准备。',
  };
}

function resetDigestWorkflow(scopeType, scopeId) {
  const prepared = prepareDigestWorkflow(scopeType, scopeId);
  if (!prepared.ok) return prepared;
  let task = readTaskStore().tasks.find((item) => item.id === prepared.taskId);
  if (['failed', 'blocked', 'timed_out', 'cancelled'].includes(task?.status)) {
    const retried = JSON.parse(retryTask(task.id));
    if (!retried.ok) return retried;
    task = retried.task;
  }
  return { ok: true, taskId: prepared.taskId, task, message: '未完成资料已准备重新处理。' };
}

function executeDigestTask(taskId, requestedExecutor = 'auto', options) {
  const result = JSON.parse(executeTaskByAdapter(taskId, requestedExecutor, options));
  const task = result.task || readTaskStore().tasks.find((item) => item.id === String(taskId));
  if (result.ok && task && isDigestTask(task)) notify('onNativeDigestWorkflowChanged', JSON.stringify({ scopeType: task.sourceType, scopeId: task.sourceId, status: task.status, taskId: task.id }));
  return { ...result, workflow: task ? getDigestWorkflowStatusObject(task.sourceType, task.sourceId) : null };
}

function configuredDigestExecutor(scopeType, scopeId, requestedExecutor = 'auto') {
  if (!['', 'auto', 'smart'].includes(String(requestedExecutor || 'auto'))) return String(requestedExecutor);
  if (agentControlStore().read().global) return 'auto';
  if (String(scopeType) === 'project') {
    const project = readProjectsForDigestLookup().find((item) => String(item.id) === String(scopeId));
    return String(project?.agentTool || 'manual');
  }
  const student = readStudentsIndex().find((item) => String(item.id) === String(scopeId));
  return String(student?.agentTool || 'manual');
}

function getDigestWorkflowCommand(scopeType, scopeId) {
  try {
    const prepared = prepareDigestWorkflow(scopeType, scopeId);
    if (!prepared.ok) return JSON.stringify(prepared);
    let task = readTaskStore().tasks.find((item) => item.id === prepared.taskId);
    if (!task) return JSON.stringify({ ok: false, message: '未找到当前资料处理任务。' });
    if (task.kind === 'student_digest') {
      const registered = registerStudentDigestBatch(task.sourceId, { includeSubmitted: true });
      if (!registered.ok) return JSON.stringify(registered);
      task = attachDigestBatchToTask(task.id, registered.batch, studentDigestBatchPath(registered.student), studentDigestReceiptPath(registered.student)) || task;
    } else if (task.kind === 'project_digest') {
      const project = readProjectsForDigestLookup().find((item) => String(item.id) === String(task.sourceId));
      if (!project) return JSON.stringify({ ok: false, message: '未找到学习项目。' });
      const ensured = ensureProjectWorkspace(project);
      const current = readProjectDigestState(ensured);
      let request = safeReadJson(projectDigestRequestPath(ensured), null);
      if (!request?.digestBatchId || request.digestBatchId !== current.digestBatchId) {
        const registered = registerProjectDigestBatch(ensured, { prefix: 'manual-copy', message: '项目资料已登记，等待 Agent 处理。' });
        if (!registered.ok) return JSON.stringify(registered);
        request = registered.request;
      }
      task = attachDigestBatchToTask(task.id, request, projectDigestRequestPath(ensured), projectDigestReceiptPath(ensured)) || task;
    }
    const command = directReportExecutionCommand(task, taskCommandFor(task));
    if (!command || /批次无效/.test(command)) return JSON.stringify({ ok: false, message: command || '当前批次指令生成失败。' });
    return JSON.stringify({ ok: true, command, taskId: task.id, digestBatchId: task.input?.digestBatchId || '', executor: task.requestedExecutor || task.executor || '', message: '已生成当前冻结批次的完整 Agent 指令。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `生成当前批次指令失败：${error.message}` });
  }
}

function reconcileDigestWorkflows() {
  if (!projectArchiveRuntime.status().ready) return { ok: true, skipped: true, reason: 'archive_busy' };
  if (digestWorkflowRunning) return { ok: true, skipped: true };
  digestWorkflowRunning = true;
  try {
    const initialStore = readTaskStore();
    const activeBeforeScan = initialStore.tasks.filter((task) => (
      isDigestTask(task) && ['running', 'waiting_result', 'reviewing'].includes(String(task.status))
    ));
    if (!activeBeforeScan.length) return { ok: true, idle: true, results: [] };
    if (activeBeforeScan.some((task) => ['inbox', 'desktop_handoff', 'agent_handoff', 'manual'].includes(task.executionMode))) {
      syncAgentTaskResults();
    }
    const store = readTaskStore();
    let changed = compactDigestTaskStore(store);
    changed = enforceTaskTimeouts(store) || changed;
    const results = [];
    for (const task of store.tasks.filter((item) => isDigestTask(item))) {
      if (taskChildProcesses.get(task.id)?.materialRuntime) continue;
      if (task.completionPolicy !== 'auto_after_validation') {
        task.completionPolicy = 'auto_after_validation';
        task.updatedAt = taskNow();
        changed = true;
        appendTaskEvent(task.id, 'digest_completion_policy_migrated', { from: 'legacy_manual_review', to: 'auto_after_validation' }, task.executionId);
      }
      const taskMayNeedSettlement = ['running', 'waiting_result', 'reviewing'].includes(task.status);
      const business = taskMayNeedSettlement ? digestBusinessSnapshot(task.sourceType, task.sourceId) : null;
      const businessStatus = String(business?.state?.status || '');
      const businessAlreadySettled = business?.ok
        && ['completed', 'partial'].includes(businessStatus)
        && (businessStatus === 'partial' || Number(business.pendingCount || 0) === 0);
      if (task.status === 'reviewing' && shouldAutoAccept(task, task.result?.validation)) {
        const accepted = transitionTaskInStore(store, task.id, 'succeeded', { result: { ...(task.result || {}), status: 'succeeded', autoAcceptedAt: taskNow() }, approval: { required: false, status: 'not_required', reviewedAt: taskNow(), reviewedBy: 'system_validation' } }, 'digest_review_recovered');
        changed = changed || accepted.ok;
        if (accepted.ok) results.push({ taskId: task.id, status: 'succeeded' });
        continue;
      }
      if (task.status === 'reviewing' && businessAlreadySettled) {
        const acceptedAt = taskNow();
        const accepted = transitionTaskInStore(store, task.id, 'succeeded', {
          result: { ...(task.result || {}), status: 'succeeded', validation: { ...(task.result?.validation || {}), valid: true, message: business.state?.message || '资料业务状态已经完成。', checkedAt: acceptedAt }, autoAcceptedAt: acceptedAt, summary: business.state?.message || task.result?.summary || '资料处理已完成。' },
          approval: { required: false, status: 'not_required', reviewedAt: acceptedAt, reviewedBy: 'system_business_state' },
        }, 'digest_business_state_reconciled');
        changed = changed || accepted.ok;
        if (accepted.ok) results.push({ taskId: task.id, status: 'succeeded' });
        continue;
      }
      if (['running', 'waiting_result'].includes(task.status) && businessAlreadySettled) {
        const validation = { valid: true, artifacts: [], checkedAt: taskNow(), message: business.state?.message || '资料业务状态已经完成。', domainSync: business };
        const result = normalizeTaskResult(task, { status: 'reviewing', summary: validation.message, structuredOutput: business }, validation);
        const committed = commitValidatedTaskResult(store, task, result, validation, { successful: true, event: 'digest_business_state_recovered', autoSummary: validation.message });
        changed = changed || committed.ok;
        if (committed.ok) results.push({ taskId: task.id, status: committed.task?.status || 'succeeded' });
        continue;
      }
      if (!['running', 'waiting_result'].includes(task.status)) continue;
      const resultPath = task.expectedOutput?.path;
      if (resultPath && fs.existsSync(resultPath)) {
        const validation = validateTaskCompletion(task, task.startedAt, null);
        if (validation.valid) {
          const result = normalizeTaskResult(task, { status: 'reviewing', summary: '恢复时检测到完整资料结果。' }, validation);
          const committed = commitValidatedTaskResult(store, task, result, validation, { successful: true, event: 'digest_result_recovered', autoSummary: '资料处理完成并已通过自动校验。' });
          changed = changed || committed.ok;
          if (committed.ok) results.push({ taskId: task.id, status: committed.task?.status || 'reviewing' });
          continue;
        }
      }
      if (task.status === 'running'
        && task.executionMode === 'automatic'
        && ['codex', 'workbuddy', 'openclaw', 'qclaw'].includes(task.adapterId)
        && !taskChildProcesses.has(task.id)) {
        const failed = transitionTaskInStore(store, task.id, 'failed', { error: { code: 'EXECUTION_INTERRUPTED', message: '应用关闭后原执行已中断，请重试未完成项。' }, nextRetryAt: '' }, 'digest_execution_interrupted');
        changed = changed || failed.ok;
        if (failed.ok) results.push({ taskId: task.id, status: 'failed' });
      }
    }
    if (changed) writeTaskStore(store);
    for (const item of results) {
      const task = store.tasks.find((candidate) => candidate.id === item.taskId);
      if (task) notify('onNativeDigestWorkflowChanged', JSON.stringify({ scopeType: task.sourceType, scopeId: task.sourceId, status: item.status, taskId: task.id }));
    }
    return { ok: true, results };
  } catch (error) {
    return { ok: false, message: error.message };
  } finally {
    digestWorkflowRunning = false;
  }
}

const digestOrchestrator = createDigestOrchestrator({
  prepare: prepareDigestWorkflow,
  execute: executeDigestTask,
  status: getDigestWorkflowStatusObject,
  reset: resetDigestWorkflow,
  reconcile: reconcileDigestWorkflows,
});

function startDigestWorkflow(scopeType, scopeId, requestedExecutor = 'auto', options) {
  try {
    projectArchiveRuntime.assertAccess();
    const result = digestOrchestrator.start(scopeType, scopeId, configuredDigestExecutor(scopeType, scopeId, requestedExecutor), options);
    scheduleDigestWorkflowMonitor(5_000);
    return JSON.stringify(result);
  }
  catch (error) { return JSON.stringify({ ok: false, message: `开始资料处理失败：${error.message}` }); }
}

function scheduleStudentDigestContinuation(studentId) {
  const key = String(studentId || '');
  if (!key || !taskAutomationEnabled() || studentAutomaticTasksPaused(findStudentByKey(key)) || studentDigestContinuationTimers.has(key)) return;
  const timer = setTimeout(async () => {
    studentDigestContinuationTimers.delete(key);
    try {
      if (!taskAutomationEnabled() || studentAutomaticTasksPaused(findStudentByKey(key))) return;
      if (!projectArchiveRuntime.status().ready || activeCaptureRuntime || captureTimelineScheduler?.state().running.length) {
        scheduleStudentDigestContinuation(key);
        return;
      }
      const business = digestBusinessSnapshot('student', key);
      if (!business.ok || Number(business.pendingCount || 0) <= 0 || Number(business.submittedCount || 0) > 0) return;
      const executor = configuredDigestExecutor('student', key, 'auto');
      // A manual adapter still needs a user to copy/run the new frozen batch;
      // automatic adapters may safely continue with the next bounded batch.
      if (!executor || executor === 'manual') return;
      const task = readTaskStore().tasks.find((item) => String(item.id) === digestTaskId('student', key));
      if (task && !['succeeded', 'failed', 'cancelled', 'timed_out', 'pending', 'queued', 'approved'].includes(String(task.status || ''))) {
        scheduleStudentDigestContinuation(key);
        return;
      }
      await startDigestWorkflowWithFreshCapabilities('student', key, executor, {automatic:true});
    } catch {
      // Pending materials remain visible and can be retried from the UI.
    }
  }, 5_000);
  studentDigestContinuationTimers.set(key, timer);
}

async function startDigestWorkflowWithFreshCapabilities(scopeType, scopeId, requestedExecutor = 'auto', options = {}) {
  if (options.automatic && !taskAutomationEnabled()) return JSON.stringify({ ok: true, skipped: true, reason: 'automation_disabled' });
  if(options.automatic&&scopeType==='student'&&studentAutomaticTasksPaused(findStudentByKey(scopeId)))return JSON.stringify({ok:true,skipped:true,reason:'student_automation_paused'});
  const executor = configuredDigestExecutor(scopeType, scopeId, requestedExecutor);
  await refreshCapabilitiesForExplicitExecution(executor);
  if (options.automatic && !taskAutomationEnabled()) return JSON.stringify({ ok: true, skipped: true, reason: 'automation_disabled' });
  if(options.automatic&&scopeType==='student'&&studentAutomaticTasksPaused(findStudentByKey(scopeId)))return JSON.stringify({ok:true,skipped:true,reason:'student_automation_paused'});
  return startDigestWorkflow(scopeType, scopeId, executor, options);
}

function getDigestWorkflowStatus(scopeType, scopeId) {
  try { return JSON.stringify(digestOrchestrator.status(scopeType, scopeId)); }
  catch (error) { return JSON.stringify({ ok: false, message: `读取资料处理状态失败：${error.message}` }); }
}

function retryDigestWorkflow(scopeType, scopeId, requestedExecutor = 'auto') {
  try {
    const result = digestOrchestrator.retry(scopeType, scopeId, configuredDigestExecutor(scopeType, scopeId, requestedExecutor));
    scheduleDigestWorkflowMonitor(5_000);
    return JSON.stringify(result);
  }
  catch (error) { return JSON.stringify({ ok: false, message: `重试资料处理失败：${error.message}` }); }
}

async function retryDigestWorkflowWithFreshCapabilities(scopeType, scopeId, requestedExecutor = 'auto') {
  const executor = configuredDigestExecutor(scopeType, scopeId, requestedExecutor);
  await refreshCapabilitiesForExplicitExecution(executor);
  return retryDigestWorkflow(scopeType, scopeId, executor);
}

async function importDigestWorkflowResultText(scopeType, scopeId, content) {
  try {
    const taskId = digestTaskId(scopeType, scopeId);
    const result = JSON.parse(await importTaskResultText(taskId, content));
    return JSON.stringify({ ...result, workflow: getDigestWorkflowStatusObject(scopeType, scopeId) });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `导入资料处理结果失败：${error.message}` });
  }
}

function digestWorkflowMonitorHasActiveWork() {
  try {
    return readTaskStore().tasks.some((task) => (
      isDigestTask(task) && ['running', 'waiting_result', 'reviewing'].includes(String(task.status))
    ));
  } catch {
    return false;
  }
}

function scheduleDigestWorkflowMonitor(delayMs) {
  if (process.env.EDU_DISABLE_DIGEST_MONITOR === '1') return;
  if (digestWorkflowTimer) clearTimeout(digestWorkflowTimer);
  digestWorkflowTimer = setTimeout(() => {
    digestWorkflowTimer = null;
    if (projectArchiveRuntime.status().ready) reconcileDigestWorkflows();
    scheduleDigestWorkflowMonitor(digestWorkflowMonitorHasActiveWork() ? 10_000 : 60_000);
  }, Math.max(1_000, Number(delayMs || 60_000)));
}

function startDigestWorkflowMonitor() {
  stopDigestWorkflowMonitor();
  scheduleDigestWorkflowMonitor(2_500);
}

function stopDigestWorkflowMonitor() {
  if (digestWorkflowTimer) clearTimeout(digestWorkflowTimer);
  digestWorkflowTimer = null;
}

function generateStudentMaintenanceReport(studentId) {
  try {
    const student = readStudentsIndex().find((item) => String(item.id) === String(studentId));
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const normalized = toHostStudent(student);
    const health = JSON.parse(checkStudentPathHealth(studentId));
    const ledger = readStudentScheduleLedger(normalized);
    const assets = assetStore().queryDetails({ studentId: String(normalized.id) });
    const materials = readStudentMaterials(normalized);
    const openMaterials = materials.filter((item) => isOpenDigestStatus(item.status));
    const staleAssetRefs = assets.reduce((total, asset) => total + (Array.isArray(asset.references) ? asset.references.filter((ref) => ref.path && !fs.existsSync(ref.path)).length : 0), 0);
    const recentEntries = ledger.entries.slice(0, 12).map((entry) => `| ${mdCell(entry.day)} | ${mdCell(entry.kind)} | ${mdCell(entry.status)} | ${entry.copyCount || 1} | ${mdCell(entry.lastCopiedAt || entry.copiedAt || '-')} |`).join('\n') || '| 暂无 | - | - | - | - |';
    const report = `# ${normalized.name} 定时维护报告\n\n生成时间：${new Date().toISOString()}\n\n## 总览\n\n| 项目 | 状态 |\n| --- | --- |\n| 路径健康 | ${mdCell(health.status || 'unknown')} |\n| 路径提醒 | ${mdCell(health.message || '-')} |\n| 待消化资料 | ${openMaterials.length} |\n| 资产记录 | ${assets.length} |\n| 失效资产引用 | ${staleAssetRefs} |\n| 账本记录 | ${ledger.entries.length} |\n\n## 最近定时任务账本\n\n| 日期 | 类型 | 状态 | 复制次数 | 最近复制 |\n| --- | --- | --- | ---: | --- |\n${recentEntries}\n\n## 维护建议\n\n- 若“待消化资料”大于 0，请先执行定时消化，再同步结果。\n- 若“路径健康”为 warning/error，请在知识库路径核对中查看并修复旧主机路径。\n- 若存在失效资产引用，请进入文件资产中心执行治理建议和清理失效引用。\n- 若成长证据草稿长期未确认，请进入 Growth Layer 完成审核。\n`;
    fs.mkdirSync(path.dirname(studentMaintenanceReportPath(normalized)), { recursive: true });
    fs.writeFileSync(studentMaintenanceReportPath(normalized), report, 'utf8');
    appendHostTimeline({ type: 'student_maintenance_report', title: 'Student maintenance report generated', detail: normalized.name, count: openMaterials.length });
    return JSON.stringify({ ok: true, path: studentMaintenanceReportPath(normalized), content: report, message: `已生成「${normalized.name}」定时维护报告。` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `生成定时维护报告失败：${error.message}` });
  }
}

function checkAllStudentsPathHealth() {
  try {
    const students = readStudentsIndex().map(toHostStudent);
    const reports = [];
    for (const student of students) {
      try {
        const report = JSON.parse(checkStudentPathHealth(student.id));
        reports.push({
          studentId: student.id,
          studentName: student.name,
          status: report.status || 'unknown',
          message: report.message || '',
          rootPath: report.rootPath || student.rootPath || getStudentRootDir(student.name),
          reportPath: report.reportPath || '',
          metadataPath: report.metadataPath || '',
          pathmapPath: report.pathmapPath || '',
          summary: report.summary || {},
        });
      } catch (error) {
        reports.push({
          studentId: student.id,
          studentName: student.name,
          status: 'error',
          message: error.message,
          rootPath: student.rootPath || getStudentRootDir(student.name),
          reportPath: '',
          metadataPath: '',
          pathmapPath: '',
          summary: {},
        });
      }
    }
    const statusRank = { error: 3, warning: 2, ok: 1 };
    const overallStatus = reports.some((item) => item.status === 'error')
      ? 'error'
      : reports.some((item) => item.status === 'warning')
        ? 'warning'
        : 'ok';
    const rows = reports
      .sort((a, b) => (statusRank[b.status] || 0) - (statusRank[a.status] || 0) || a.studentName.localeCompare(b.studentName, 'zh-CN'))
      .map((item) => `| ${mdCell(item.studentName)} | ${mdCell(item.status)} | ${Number(item.summary?.missingCount || 0)} | ${Number(item.summary?.warningCount || 0)} | ${Number(item.summary?.stalePathCount || 0)} | ${mdCell(item.message || '-')} | ${mdCell(item.rootPath)} | ${mdCell(item.reportPath || '-')} |`)
      .join('\n') || '| 暂无学生 | - | 0 | 0 | 0 | - | - | - |';
    const content = `# 所有学生知识库路径核对总报告\n\n生成时间：${new Date().toISOString()}\n\n## 总览\n\n| 指标 | 数量 |\n| --- | ---: |\n| 学生数 | ${reports.length} |\n| 正常 | ${reports.filter((item) => item.status === 'ok').length} |\n| 警告 | ${reports.filter((item) => item.status === 'warning').length} |\n| 错误 | ${reports.filter((item) => item.status === 'error').length} |\n\n## 明细\n\n| 学生 | 状态 | 缺失项 | 警告项 | 旧路径 | 说明 | 根目录 | 学生报告 |\n| --- | --- | ---: | ---: | ---: | --- | --- | --- |\n${rows}\n\n## 建议\n\n- 若“旧路径”大于 0，请进入对应学生执行“修复旧主机路径”。\n- 若“缺失项”大于 0，请先确认同步盘是否完成同步，再补建缺失目录或重新接管知识库。\n- 本报告只核对路径与配置，不会移动、删除、覆盖任何知识库文件。\n`;
    const file = allStudentsPathHealthReportPath();
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content, 'utf8');
    appendHostTimeline({ type: 'all_students_path_health', title: 'All students path health checked', detail: overallStatus, count: reports.length });
    return JSON.stringify({ ok: true, status: overallStatus, reports, path: file, content, message: `已完成 ${reports.length} 个学生的路径核对，总体状态：${overallStatus}。` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `批量核对学生路径失败：${error.message}` });
  }
}

function readGrowthEvidenceReview(student, fileIo = fs) {
  const file = growthEvidenceReviewPath(student);
  const parsed = fileIo === fs ? safeReadJson(file, {}) : fileIo.existsSync(file) ? JSON.parse(fileIo.readFileSync(file, 'utf8')) : {};
  if (fileIo !== fs && (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)
    || parsed.candidates !== undefined && !Array.isArray(parsed.candidates))) throw new Error('成长证据登记结构损坏，事务不能覆盖。');
  return {
    version: 1,
    updatedAt: parsed.updatedAt || '',
    candidates: Array.isArray(parsed.candidates) ? parsed.candidates : [],
  };
}

function writeGrowthEvidenceReview(student, review, options = {}) {
  const file = growthEvidenceReviewPath(student);
  const record = {
    version: 1,
    updatedAt: new Date().toISOString(),
    candidates: review.candidates || [],
  };
  if (options.fileIo && options.fileIo !== fs) options.fileIo.writeFileSync(file, JSON.stringify(record), 'utf8');
  else writeJsonAtomic(file, record);
  if ((!options.fileIo || options.fileIo === fs) && options.markDirty !== false) markGrowthStudentsDirty([student.id], 'growth_evidence_changed');
}

function linkGovernedStudentKnowledgeToGrowth(student, governanceRun) {
  const normalized = toHostStudent(student);
  const candidates = governedStudentGrowthCandidates({
    studentId: String(normalized.id),
    run: governanceRun,
    contentForArtifact: (artifact) => {
      const sourcePath = String(artifact?.path || '');
      return sourcePath && fs.existsSync(sourcePath) ? readSmallTextFile(sourcePath, 512 * 1024) : '';
    },
  });
  if (!candidates.length) return { added: 0, updated: 0, changed: false };
  const merged = mergeGrowthCandidates(readGrowthEvidenceReview(normalized), candidates);
  if (merged.changed) writeGrowthEvidenceReview(normalized, merged.review);
  return { added: merged.added, updated: merged.updated, changed: merged.changed, evidenceIds: candidates.map((item) => item.id) };
}

function readGrowthRefreshState() {
  return normalizeGrowthRefreshState(safeReadJson(growthRefreshStatePath(), {}));
}

function writeGrowthRefreshState(state) {
  writeJsonAtomic(growthRefreshStatePath(), normalizeGrowthRefreshState(state));
}

function nextGrowthRefreshDelay(state) {
  const now = Date.now();
  const dueTimes = Object.values(normalizeGrowthRefreshState(state).entries)
    .filter((entry) => entry.status === 'dirty')
    .map((entry) => Date.parse(entry.nextAttemptAt || entry.dirtyAt || ''))
    .filter(Number.isFinite);
  if (!dueTimes.length) return null;
  return Math.max(1000, Math.min(15 * 60 * 1000, Math.min(...dueTimes) - now));
}

function scheduleGrowthRefresh(delayMs = 1500) {
  if (process.env.EDU_DISABLE_GROWTH_REFRESH === '1') return;
  if (growthRefreshTimer) clearTimeout(growthRefreshTimer);
  growthRefreshTimer = setTimeout(() => {
    growthRefreshTimer = null;
    void runGrowthRefreshQueue();
  }, Math.max(250, Number(delayMs || 0)));
}

function markGrowthStudentsDirty(studentIds, reason = 'source_changed') {
  const ids = [...new Set((Array.isArray(studentIds) ? studentIds : [studentIds]).map(String).filter(Boolean))];
  if (!ids.length) return readGrowthRefreshState();
  const state = markGrowthDirty(readGrowthRefreshState(), ids, reason);
  writeGrowthRefreshState(state);
  scheduleGrowthRefresh();
  return state;
}

async function runGrowthRefreshQueue() {
  if (!projectArchiveRuntime.status().ready) return { ok: true, skipped: true, reason: 'archive_busy' };
  if (growthRefreshRunning || process.env.EDU_DISABLE_GROWTH_REFRESH === '1') return { ok: true, skipped: true };
  growthRefreshRunning = true;
  const results = [];
  try {
    const claimed = claimDueGrowthRefreshes(readGrowthRefreshState(), { limit: 2 });
    if (!claimed.claimed.length) return { ok: true, results };
    writeGrowthRefreshState(claimed.state);
    for (const claim of claimed.claimed) {
      let result;
      try {
        result = JSON.parse(rebuildGrowthIndex(claim.studentId, { queueManaged: true }));
      } catch (error) {
        result = { ok: false, message: error.message };
      }
      const current = readGrowthRefreshState();
      const completed = completeGrowthRefresh(current, claim, {
        ok: Boolean(result.ok),
        fingerprint: result.index?.sourceFingerprint || '',
        error: result.message || '成长模型更新失败。',
      });
      writeGrowthRefreshState(completed);
      results.push({ studentId: claim.studentId, ok: Boolean(result.ok), message: result.message || '' });
    }
    if (results.length) {
      appendHostTimeline({ type: 'growth_refresh_batch', title: 'Growth refresh batch', detail: `processed ${results.length}`, count: results.filter((item) => item.ok).length });
      notify('onNativeTaskCenterChanged', JSON.stringify({ kind: 'growth_refresh', results, at: taskNow() }));
    }
    return { ok: results.every((item) => item.ok), results };
  } finally {
    growthRefreshRunning = false;
    const delay = nextGrowthRefreshDelay(readGrowthRefreshState());
    if (delay !== null) scheduleGrowthRefresh(delay);
  }
}

function startGrowthRefreshMonitor() {
  stopGrowthRefreshMonitor();
  if (process.env.EDU_DISABLE_GROWTH_REFRESH === '1') return;
  const state = readGrowthRefreshState();
  if (dirtyStudentIds(state).length) scheduleGrowthRefresh(5000);
  growthRefreshFallbackTimer = setInterval(() => {
    if (!projectArchiveRuntime.status().ready) return;
    if (dirtyStudentIds(readGrowthRefreshState()).length) void runGrowthRefreshQueue();
  }, 15 * 60 * 1000);
}

function stopGrowthRefreshMonitor() {
  if (growthRefreshTimer) clearTimeout(growthRefreshTimer);
  if (growthRefreshFallbackTimer) clearInterval(growthRefreshFallbackTimer);
  growthRefreshTimer = null;
  growthRefreshFallbackTimer = null;
}

function growthTransactionSnapshot(student) {
  const normalized = toHostStudent(student);
  const files = [
    projectsPath(),
    growthEvidenceReviewPath(normalized),
    growthIndexPath(normalized),
    growthIndexMarkdownPath(normalized),
    path.join(growthModelDirForStudent(normalized), '成长证据.md'),
  ];
  return files.map((file) => ({ file, existed: fs.existsSync(file), content: fs.existsSync(file) ? fs.readFileSync(file) : null }));
}

function restoreGrowthTransaction(snapshot) {
  for (const item of Array.isArray(snapshot) ? snapshot : []) {
    if (item.existed) {
      fs.mkdirSync(path.dirname(item.file), { recursive: true });
      fs.writeFileSync(item.file, item.content);
    } else if (fs.existsSync(item.file)) {
      fs.unlinkSync(item.file);
    }
  }
  projectDigestLookupCache = { mtimeMs: -1, size: -1, projects: [] };
}

function createGrowthRecoverySnapshot(student, reason = 'repair') {
  const normalized = toHostStudent(student);
  const stamp = new Date().toISOString().replace(/[:.]/g, '-');
  const target = path.join(app.getPath('userData'), 'growth-recovery', `${stamp}-${sanitizeName(normalized.name)}-${normalized.id}`);
  const reportDir = learningReportDirForStudent(normalized);
  const files = [
    projectsPath(),
    growthEvidenceReviewPath(normalized),
    growthIndexPath(normalized),
    growthIndexMarkdownPath(normalized),
    path.join(growthModelDirForStudent(normalized), '成长证据.md'),
    ...LEARNING_REPORTS.map((report) => path.join(reportDir, report.fileName)),
  ];
  const copied = [];
  fs.mkdirSync(target, { recursive: true });
  for (const source of files) {
    if (!fs.existsSync(source) || !fs.statSync(source).isFile()) continue;
    const name = `${copied.length + 1}-${path.basename(source)}`;
    fs.copyFileSync(source, path.join(target, name));
    copied.push({ source, backup: name });
  }
  writeJsonAtomic(path.join(target, 'manifest.json'), { version: 1, createdAt: new Date().toISOString(), reason, studentId: normalized.id, studentName: normalized.name, files: copied });
  return target;
}

function appendGrowthEvidenceCandidate(student, candidate, fileIo = fs) {
  const normalized = toHostStudent(student);
  ensureGrowthModelForStudent(normalized, fileIo);
  const review = readGrowthEvidenceReview(normalized, fileIo);
  const content = String(candidate.content || candidate.title || '').trim();
  const seed = `${normalized.id}|${candidate.projectId || ''}|${candidate.title || ''}|${content}|${candidate.sourcePath || ''}`;
  const evidenceId = String(candidate.id || `evidence-${sha1Text(seed).slice(0, 14)}`);
  const existing = review.candidates.find((item) => item.id === evidenceId);
  if (existing) {
    Object.assign(existing, {
      projectId: String(candidate.projectId || existing.projectId || ''),
      projectName: String(candidate.projectName || existing.projectName || ''),
      title: String(candidate.title || existing.title || '未命名成长证据'),
      content,
      sourcePath: String(candidate.sourcePath || existing.sourcePath || ''),
      sourceBinding: candidate.sourceBinding || null,
      sourceMaterials: candidate.sourceMaterials || [],
      requiresProjectConfirmation: Boolean(candidate.requiresProjectConfirmation || existing.requiresProjectConfirmation),
      status: String(candidate.status || existing.status || 'pending'),
      confidence: String(candidate.confidence || existing.confidence || '待确认'),
      ability: String(candidate.ability || existing.ability || '待标注'),
      updatedAt: new Date().toISOString(),
    });
    writeGrowthEvidenceReview(normalized, review, { fileIo });
    return existing;
  }
  const item = {
    id: evidenceId,
    studentId: normalized.id,
    studentName: normalized.name,
    projectId: String(candidate.projectId || ''),
    projectName: String(candidate.projectName || ''),
    title: String(candidate.title || '未命名成长证据'),
    content,
    sourcePath: String(candidate.sourcePath || ''),
    sourceBinding: candidate.sourceBinding || null,
    sourceMaterials: candidate.sourceMaterials || [],
    requiresProjectConfirmation: Boolean(candidate.requiresProjectConfirmation),
    status: String(candidate.status || 'pending'),
    confidence: String(candidate.confidence || '待确认'),
    ability: String(candidate.ability || '待标注'),
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };
  review.candidates.unshift(item);
  writeGrowthEvidenceReview(normalized, review, { fileIo });
  return item;
}

function requiresFixedProjectEvidenceConfirmation(item) {
  if (item.requiresProjectConfirmation || item.sourceBinding) return true;
  return Boolean(item.projectId && readProjects().some((project) => String(project.id) === String(item.projectId)
    && isWorkspaceMaterialProject(project)));
}

function growthReadSources(student) {
  return createGrowthSourceReader({ student, projects: reportProjectsForStudent(student), readProjectIndex: readProjectMaterialIndexSync });
}

function queueGrowthRefreshOnRead(studentId, reason) {
  const state = readGrowthRefreshState();
  if (['dirty', 'running'].includes(state.entries?.[String(studentId)]?.status)) return state;
  return markGrowthStudentsDirty([studentId], reason);
}

function growthIndexReadResult(normalized, savedIndex, sourcePath, sources = growthReadSources(normalized)) {
  const index = currentGrowthReadView({ student: normalized, index: savedIndex, ...sources });
  const protocolCompatibility = mapGrowthIndexV2ToDomainSnapshot({ student: normalized, index, sourcePath, ...sources });
  return { index, protocolCompatibility, content: currentGrowthMarkdown(normalized, index) };
}

function applyAutomaticGrowthEvidencePlan(student, review) {
  const normalized = toHostStudent(student);
  let metadataChanged = 0;
  for (const item of review.candidates) {
    if (!['pending', 'confirmed'].includes(String(item.status || 'pending'))) continue;
    if (requiresFixedProjectEvidenceConfirmation(item)) continue;
    const sourceUnavailable = Boolean(String(item.sourceUri || item.sourcePath || '').trim())
      && !reportEvidenceSourceAccessible({ sourceId: normalized.id }, item);
    const nextReason = sourceUnavailable ? 'source_unavailable' : '';
    if (String(item.automationAttentionReason || '') !== nextReason) {
      item.automationAttentionReason = nextReason;
      item.updatedAt = new Date().toISOString();
      metadataChanged += 1;
    }
  }
  const compatibility = mapGrowthEvidenceReviewToEducationClaims({ student: normalized, review, sourcePath: growthEvidenceReviewPath(normalized) });
  const plan = buildGrowthEvidenceBatchPlan(review.candidates, { legacyReviewIds: compatibility.reviewQueue.map((item) => item.evidenceId) });
  if (!plan.summary.batchProcessable) return { changed: 0, metadataChanged, confirmed: 0, watching: 0, plan, batchId: '' };
  const processedAt = new Date().toISOString();
  const batchId = `growth-auto-${processedAt.replace(/[-:.TZ]/g, '').slice(0, 14)}-${crypto.randomBytes(3).toString('hex')}`;
  const confirmIds = new Set(plan.confirmIds);
  const watchIds = new Set(plan.watchIds);
  const reviewer = { reviewerRole: 'administrator', reviewerId: 'system-risk-policy', automated: true };
  let confirmed = 0;
  let watching = 0;
  for (const item of review.candidates) {
    // A generic risk score cannot replace the student's explicit observation
    // and project-scoped fixed-source confirmation.
    if (requiresFixedProjectEvidenceConfirmation(item)) continue;
    if (confirmIds.has(String(item.id))) {
      applyGrowthEvidenceReviewDecision(item, 'confirmed', '系统自动确认：来源完整、项目归属明确且未发现高风险因素。', processedAt, batchId, reviewer);
      appendConfirmedGrowthEvidence(normalized, item);
      confirmed += 1;
    } else if (watchIds.has(String(item.id))) {
      applyGrowthEvidenceReviewDecision(item, 'watching', '系统自动分流：信息不完整或可信度待观察，未发布为正式结论。', processedAt, batchId, reviewer);
      watching += 1;
    }
  }
  return { changed: confirmed + watching, metadataChanged, confirmed, watching, plan, batchId };
}

function getGrowthEvidenceReview(studentId) {
  try {
    const student = readStudentsIndex().find((item) => String(item.id) === String(studentId));
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const normalized = toHostStudent(student);
    ensureGrowthModelForStudent(normalized);
    let review = readGrowthEvidenceReview(normalized);
    const automatic = applyAutomaticGrowthEvidencePlan(normalized, review);
    if (automatic.changed || automatic.metadataChanged) {
      writeGrowthEvidenceReview(normalized, review, { markDirty: false });
      rebuildGrowthIndex(studentId, { skipAutomaticEvidence: true });
      review = readGrowthEvidenceReview(normalized);
    }
    if (automatic.changed) {
      appendHostTimeline({ type: 'growth_evidence_auto_processed', title: 'Growth evidence automatically processed', detail: `${normalized.name} confirmed ${automatic.confirmed}, watching ${automatic.watching}`, count: automatic.changed });
    }
    const sources = growthReadSources(normalized);
    review = currentGrowthReviewView({ student: normalized, review, ...sources });
    const protocolCompatibility = mapGrowthEvidenceReviewToEducationClaims({ student: normalized, review, sourcePath: growthEvidenceReviewPath(normalized), ...sources });
    const riskAssessment = buildGrowthEvidenceBatchPlan(review.candidates, { legacyReviewIds: protocolCompatibility.reviewQueue.map((item) => item.evidenceId) });
    const automaticMessage = automatic.changed ? `系统已自动确认 ${automatic.confirmed} 条低风险证据，并将 ${automatic.watching} 条转为继续观察；` : '';
    return JSON.stringify({ ok: true, automatic, review, protocolCompatibility, riskAssessment, path: growthEvidenceReviewPath(normalized), message: `${automaticMessage}当前仅有 ${riskAssessment.summary.high} 条高风险记录需要逐条确认。` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `读取成长证据审核失败：${error.message}` });
  }
}

function migrateLegacyGrowthEvidence(student, review, projects) {
  const growth = ensureGrowthModelForStudent(student);
  const evidenceFile = path.join(growth.dir, '成长证据.md');
  if (!fs.existsSync(evidenceFile)) return { imported: 0, source: evidenceFile };
  const legacy = parseLegacyGrowthEvidenceMarkdown(readSmallTextFile(evidenceFile, 1024 * 1024), evidenceFile);
  const existingKeys = new Set((review.candidates || []).map((item) => `${item.title || ''}|${item.sourcePath || ''}|${item.ability || ''}`));
  let imported = 0;
  for (const candidate of legacy) {
    const key = `${candidate.title || ''}|${candidate.sourcePath || ''}|${candidate.ability || ''}`;
    if (existingKeys.has(key)) continue;
    const matchedProject = projects.find((project) => String(project.name || '') === String(candidate.projectName || ''));
    review.candidates.push({
      ...candidate,
      studentId: student.id,
      studentName: student.name,
      projectId: matchedProject?.id || '',
      projectName: matchedProject?.name || candidate.projectName || '',
      createdAt: candidate.createdAt || fs.statSync(evidenceFile).mtime.toISOString(),
      updatedAt: candidate.updatedAt || fs.statSync(evidenceFile).mtime.toISOString(),
    });
    existingKeys.add(key);
    imported += 1;
  }
  if (imported) writeGrowthEvidenceReview(student, review);
  return { imported, source: evidenceFile };
}

function migrateLegacyLearningReports(student, review) {
  const reportDir = learningReportDirForStudent(student);
  const known = new Set((review.candidates || []).map((item) => String(item.migratedFrom || '')));
  let imported = 0;
  for (const report of LEARNING_REPORTS) {
    const sourcePath = path.join(reportDir, report.fileName);
    if (!fs.existsSync(sourcePath) || known.has(sourcePath)) continue;
    const candidate = legacyReportCandidate({
      studentId: student.id,
      reportId: report.id,
      title: report.title,
      sourcePath,
      content: readSmallTextFile(sourcePath, 1024 * 1024),
    });
    if (!candidate) continue;
    const timestamp = fs.statSync(sourcePath).mtime.toISOString();
    review.candidates.push({ ...candidate, studentId: student.id, studentName: student.name, createdAt: timestamp, updatedAt: timestamp });
    known.add(sourcePath);
    imported += 1;
  }
  if (imported) writeGrowthEvidenceReview(student, review);
  return { imported, source: reportDir };
}

function rebuildGrowthIndex(studentId, options = {}) {
  try {
    const student = readStudentsIndex().find((item) => String(item.id) === String(studentId));
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const normalized = toHostStudent(student);
    const growth = ensureGrowthModelForStudent(normalized);
    const projects = readProjects().map(normalizeProject).filter((project) => (project.studentIds || []).map(String).includes(String(normalized.id)));
    let review = readGrowthEvidenceReview(normalized);
    const projectEvidenceMerge = mergeGrowthCandidates(review, projectStudentGrowthCandidates({
      studentId: String(normalized.id),
      projects,
    }));
    if (projectEvidenceMerge.changed) {
      review = projectEvidenceMerge.review;
      writeGrowthEvidenceReview(normalized, review, { markDirty: false });
    }
    const migration = migrateLegacyGrowthEvidence(normalized, review, projects);
    const reportMigration = migrateLegacyLearningReports(normalized, review);
    const automatic = options.skipAutomaticEvidence
      ? { changed: 0, metadataChanged: 0, confirmed: 0, watching: 0, batchId: '' }
      : applyAutomaticGrowthEvidencePlan(normalized, review);
    if (automatic.changed || automatic.metadataChanged) writeGrowthEvidenceReview(normalized, review, { markDirty: false });
    const index = buildGrowthIndexV2({
      student: normalized,
      growthDir: growth.dir,
      review,
      projects,
      sourceFiles: {
        evidenceReview: growthEvidenceReviewPath(normalized),
        evidenceMd: path.join(growth.dir, '成长证据.md'),
        projectContributionMd: path.join(growth.dir, '项目贡献.md'),
      },
      migration: { legacyEvidenceImported: migration.imported, legacyEvidenceSource: migration.source, legacyReportCandidatesImported: reportMigration.imported, legacyReportSource: reportMigration.source },
    });
    index.sourceFingerprint = growthSourceFingerprint(review, projects);
    fs.mkdirSync(path.dirname(growthIndexPath(normalized)), { recursive: true });
    fs.writeFileSync(growthIndexPath(normalized), JSON.stringify(index, null, 2), 'utf8');
    const abilityRows = index.abilities.map((item) => `| ${mdCell(item.name)} | ${mdCell(item.maturity)} | ${mdCell(item.trend)} | ${item.evidenceCount} | ${item.confirmedCount} | ${mdCell(item.projectNames.join('、') || '-')} | ${mdCell(item.lastObservedAt || '-')} |`).join('\n') || '| 暂无 | - | - | 0 | 0 | - | - |';
    const projectRows = index.projects.map((item) => `| ${mdCell(item.projectName)} | ${mdCell(item.reviewStatus)} | ${item.evidenceCount} | ${item.confirmedEvidenceCount} | ${mdCell(item.abilityNames.join('、') || '-')} | ${mdCell(item.publishedAt || '-')} |`).join('\n') || '| 暂无 | - | 0 | 0 | - | - |';
    const markdown = `# ${normalized.name} 成长模型结构化索引\n\nSchema：edu-manager.growth-model.v2\n\n生成时间：${index.updatedAt}\n\n## 总览\n\n| 指标 | 数量 |\n| --- | ---: |\n| 成长证据 | ${index.summary.evidenceCount} |\n| 已确认 | ${index.summary.confirmedCount} |\n| 观察中 | ${index.summary.watchingCount} |\n| 待审核 | ${index.summary.pendingCount} |\n| 已驳回/回滚 | ${index.summary.rejectedCount} |\n| 能力维度 | ${index.summary.abilityCount} |\n| 关联项目 | ${index.summary.projectCount} |\n| 已发布项目贡献 | ${index.summary.publishedProjectCount} |\n\n## 能力画像\n\n| 能力 | 成熟度 | 趋势 | 证据 | 已确认 | 来源项目 | 最近观察 |\n| --- | --- | --- | ---: | ---: | --- | --- |\n${abilityRows}\n\n## 项目贡献\n\n| 项目 | 贡献状态 | 证据 | 已确认 | 能力 | 发布时间 |\n| --- | --- | ---: | ---: | --- | --- |\n${projectRows}\n\n> 该索引由教育管家控制台生成，用于统一能力画像、项目贡献和成长证据。它不会覆盖原始 Markdown；旧版成长证据会以兼容方式导入审核索引。\n`;
    fs.writeFileSync(growthIndexMarkdownPath(normalized), markdown, 'utf8');
    const readResult = growthIndexReadResult(normalized, index, growthIndexPath(normalized));
    appendHostTimeline({ type: 'growth_index_rebuilt', title: 'Growth index rebuilt', detail: normalized.name, count: review.candidates.length });
    scheduleEducationArchiveVersion(normalized.id);
    if (!options.queueManaged) {
      const refreshState = readGrowthRefreshState();
      const entry = refreshState.entries[String(normalized.id)];
      if (entry && entry.status !== 'clean') {
        writeGrowthRefreshState(completeGrowthRefresh(refreshState, {
          studentId: String(normalized.id),
          claimedDirtyAt: entry.dirtyAt,
          generation: entry.generation,
        }, { ok: true, fingerprint: index.sourceFingerprint }));
      }
    }
    return JSON.stringify({ ok: true, ...readResult, automatic, path: growthIndexPath(normalized), markdownPath: growthIndexMarkdownPath(normalized), message: `已重建「${normalized.name}」成长模型结构化索引。${automatic.changed ? ` 系统自动处理 ${automatic.changed} 条普通候选。` : ''}` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `重建成长模型结构化索引失败：${error.message}` });
  }
}

function getGrowthIndex(studentId) {
  try {
    const student = readStudentsIndex().find((item) => String(item.id) === String(studentId));
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const normalized = toHostStudent(student);
    const file = growthIndexPath(normalized);
    if (!fs.existsSync(file)) {
      queueGrowthRefreshOnRead(studentId, 'missing_index_on_read');
      return JSON.stringify({ ok: true, index: null, content: '', refreshPending: true, message: '成长索引正在后台建立，页面可继续操作。' });
    }
    const savedIndex = safeReadJson(file, {});
    const projects = reportProjectsForStudent(normalized);
    const review = readGrowthEvidenceReview(normalized);
    const fingerprint = growthSourceFingerprint(review, projects);
    const refreshPending = growthIndexNeedsRebuild(savedIndex, fingerprint);
    if (refreshPending) queueGrowthRefreshOnRead(studentId, 'stale_index_on_read');
    const { index, content, protocolCompatibility } = growthIndexReadResult(normalized, savedIndex, file);
    return JSON.stringify({ ok: true, index, protocolCompatibility, path: file, markdownPath: growthIndexMarkdownPath(normalized), content, refreshPending,
      message: refreshPending ? '已按当前来源核对展示，索引更新已排入后台。' : '已读取成长模型结构化索引。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `读取成长模型结构化索引失败：${error.message}` });
  }
}

function getGrowthModelSnapshot(studentId) {
  try {
    const student = readStudentsIndex().find((item) => String(item.id) === String(studentId));
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const normalized = toHostStudent(student);
    const sources = growthReadSources(normalized);
    const review = currentGrowthReviewView({ student: normalized, review: readGrowthEvidenceReview(normalized), ...sources });
    const file = growthIndexPath(normalized);
    const savedIndex = fs.existsSync(file) ? safeReadJson(file, null) : null;
    const { index, content } = savedIndex ? growthIndexReadResult(normalized, savedIndex, file, sources) : { index: null, content: '' };
    if (!index) queueGrowthRefreshOnRead(studentId, 'missing_index_on_open');
    return JSON.stringify({ ok: true, review, index, content, message: index
      ? '已读取成长模型快照；后续变动在后台更新。' : '成长模型正在后台建立，页面可继续操作。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `读取成长模型快照失败：${error.message}` });
  }
}

function repairStaleGrowthIndexes(studentIds = []) {
  const repaired = [];
  const failed = [];
  const requestedIds = new Set((Array.isArray(studentIds) ? studentIds : [studentIds]).map(String).filter(Boolean));
  for (const student of readStudentsIndex().filter((item) => requestedIds.has(String(item.id)))) {
    try {
      const normalized = toHostStudent(student);
      const file = growthIndexPath(normalized);
      const index = fs.existsSync(file) ? safeReadJson(file, {}) : {};
      const projects = readProjects().map(normalizeProject).filter((project) => (project.studentIds || []).map(String).includes(String(normalized.id)));
      const review = readGrowthEvidenceReview(normalized);
      const fingerprint = growthSourceFingerprint(review, projects);
      if (!fs.existsSync(file) || growthIndexNeedsRebuild(index, fingerprint)) {
        const backupPath = createGrowthRecoverySnapshot(normalized, 'targeted-consistency-repair');
        const result = JSON.parse(rebuildGrowthIndex(normalized.id));
        if (!result.ok) throw new Error(result.message || '索引重建失败。');
        repaired.push({ studentId: normalized.id, studentName: normalized.name, backupPath });
      }
    } catch (error) {
      failed.push({ studentId: student.id, studentName: student.name, message: error.message });
    }
  }
  if (repaired.length || failed.length) appendHostTimeline({ type: 'growth_consistency_repaired', title: 'Growth consistency repaired', detail: `repaired ${repaired.length}, failed ${failed.length}`, count: repaired.length });
  return { repaired, failed };
}

function applyGrowthEvidenceReviewDecision(item, nextStatus, note, reviewedAt, batchId = '', reviewer = {}) {
  const previousStatus = String(item.status || 'pending');
  const reviewDecision = nextStatus === 'confirmed' ? 'approved' : nextStatus === 'rejected' ? 'rejected' : 'pending';
  const reviewerRole = String(reviewer.reviewerRole || 'administrator');
  const reviewerId = String(reviewer.reviewerId || 'local-user');
  const automated = Boolean(reviewer.automated);
  item.status = nextStatus;
  item.note = String(note || item.note || '');
  item.updatedAt = reviewedAt;
  item.review = {
    status: reviewDecision,
    reviewerRole,
    reviewerId,
    reviewedAt,
    automated,
    ...(batchId ? { batchId } : {}),
  };
  item.reviewerRole = item.review.reviewerRole;
  item.reviewerId = item.review.reviewerId;
  item.reviewedAt = reviewedAt;
  item.reviewHistory = [
    ...(Array.isArray(item.reviewHistory) ? item.reviewHistory : []),
    {
      from: previousStatus,
      to: nextStatus,
      note: String(note || ''),
      reviewerRole: item.review.reviewerRole,
      reviewerId: item.review.reviewerId,
      reviewedAt,
      automated,
      ...(batchId ? { batchId } : {}),
    },
  ];
}

function appendConfirmedGrowthEvidence(student, item, fileIo = fs) {
  const growth = ensureGrowthModelForStudent(student, fileIo);
  const evidenceFile = path.join(growth.dir, '成长证据.md');
  const marker = `<!-- evidence:${item.id}${item.sourceBinding?.bindingId ? `:${item.sourceBinding.bindingId}` : ''} -->`;
  const current = fileIo.existsSync(evidenceFile) ? fileIo.readFileSync(evidenceFile, 'utf8') : '';
  if (!current.includes(marker)) {
    fileIo.appendFileSync(evidenceFile, `${marker}\n| ${new Date().toISOString().slice(0, 10)} | ${mdCell(item.title)} | ${mdCell(item.sourcePath || item.projectName || '-')} | ${mdCell(item.ability || '待标注')} | ${mdCell(item.confidence || '人工确认')} |\n`, 'utf8');
  }
}

function updateGrowthEvidenceStatus(studentId, evidenceId, status, note = '') {
  try {
    const student = readStudentsIndex().find((item) => String(item.id) === String(studentId));
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const normalized = toHostStudent(student);
    ensureGrowthModelForStudent(normalized);
    const review = readGrowthEvidenceReview(normalized);
    const nextStatus = ['pending', 'confirmed', 'watching', 'rejected'].includes(String(status)) ? String(status) : 'pending';
    const item = review.candidates.find((candidate) => String(candidate.id) === String(evidenceId));
    if (!item) return JSON.stringify({ ok: false, message: '未找到成长证据候选。' });
    if (requiresFixedProjectEvidenceConfirmation(item)) {
      return JSON.stringify({ ok: false, code: 'project_confirmation_required', projectId: item.projectId,
        message: '请在项目的学生独立成长证据中确认、驳回或修改状态；通用审核不能单独修改副本而保留项目中的已确认状态。' });
    }
    const reviewedAt = new Date().toISOString();
    applyGrowthEvidenceReviewDecision(item, nextStatus, note, reviewedAt);
    writeGrowthEvidenceReview(normalized, review);
    if (nextStatus === 'confirmed') {
      appendConfirmedGrowthEvidence(normalized, item);
    }
    rebuildGrowthIndex(studentId);
    appendHostTimeline({ type: 'growth_evidence_reviewed', title: 'Growth evidence reviewed', detail: `${normalized.name} ${nextStatus}`, count: 1 });
    const protocolCompatibility = mapGrowthEvidenceReviewToEducationClaims({ student: normalized, review, sourcePath: growthEvidenceReviewPath(normalized), ...growthReadSources(normalized) });
    const riskAssessment = buildGrowthEvidenceBatchPlan(review.candidates, { legacyReviewIds: protocolCompatibility.reviewQueue.map((entry) => entry.evidenceId) });
    return JSON.stringify({ ok: true, review, protocolCompatibility, riskAssessment, message: `已将成长证据标记为：${nextStatus}，并记录本机人工审核。` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `更新成长证据状态失败：${error.message}` });
  }
}

function batchReviewGrowthEvidence(studentId) {
  try {
    const student = readStudentsIndex().find((item) => String(item.id) === String(studentId));
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const normalized = toHostStudent(student);
    ensureGrowthModelForStudent(normalized);
    const review = readGrowthEvidenceReview(normalized);
    const automatic = applyAutomaticGrowthEvidencePlan(normalized, review);
    const { changed, metadataChanged, confirmed, watching, batchId } = automatic;
    if (!changed) {
      if (metadataChanged) {
        writeGrowthEvidenceReview(normalized, review);
        rebuildGrowthIndex(studentId, { skipAutomaticEvidence: true });
      }
      const compatibilityBefore = mapGrowthEvidenceReviewToEducationClaims({ student: normalized, review, sourcePath: growthEvidenceReviewPath(normalized) });
      return JSON.stringify({ ok: true, automatic: true, changed: 0, review, protocolCompatibility: compatibilityBefore, riskAssessment: automatic.plan, message: automatic.plan.summary.high ? `当前只有 ${automatic.plan.summary.high} 条高风险记录需要逐条确认。` : '当前没有需要系统处理的普通候选。' });
    }
    writeGrowthEvidenceReview(normalized, review);
    rebuildGrowthIndex(studentId);
    const protocolCompatibility = mapGrowthEvidenceReviewToEducationClaims({ student: normalized, review, sourcePath: growthEvidenceReviewPath(normalized), ...growthReadSources(normalized) });
    const riskAssessment = buildGrowthEvidenceBatchPlan(review.candidates, { legacyReviewIds: protocolCompatibility.reviewQueue.map((item) => item.evidenceId) });
    appendHostTimeline({ type: 'growth_evidence_auto_processed', title: 'Growth evidence automatically processed', detail: `${normalized.name} confirmed ${confirmed}, watching ${watching}`, count: changed });
    return JSON.stringify({ ok: true, automatic: true, changed, confirmed, watching, batchId, review, protocolCompatibility, riskAssessment, message: `系统自动处理完成：确认 ${confirmed} 条低风险证据，${watching} 条转为继续观察；${riskAssessment.summary.high} 条高风险记录保留逐条确认。` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `自动处理成长证据失败：${error.message}` });
  }
}

function learningReportPathForStudent(student, report) {
  return path.join(learningReportDirForStudent(student), report.fileName);
}

function learningReportTemplate(student, report) {
  const today = new Date().toISOString().slice(0, 10);
  const body = report.sections.map((section) => {
    if (section === report.summaryHeading) return `## ${section}\n\n待生成。`;
    return `## ${section}\n\n- 待补充。`;
  }).join('\n\n');
  const growthDir = growthModelDirForStudent(student);
  return `---\ntype: ${report.type}\ntarget: ${report.target}\nupdated: ${today}\nstatus: draft\nsource_layer: growth_model\npresentation_only: true\ngrowth_model: ${growthDir}\n---\n\n# ${report.title}\n\n> 本报告是成长模型的呈现输出，不是能力、项目贡献或成长证据的事实来源。生成和更新时，只引用成长模型中的已确认结论。\n\n## 成长证据来源\n\n- 成长模型：${growthDir}\n- 能力画像：${path.join(growthDir, '能力画像.md')}\n- 成长证据：${path.join(growthDir, '成长证据.md')}\n- 项目贡献：${path.join(growthDir, '项目贡献.md')}\n\n## 项目贡献来源\n\n- 待补充已确认的项目知识贡献申请。\n\n${body}\n`;
}

function ensureLearningReportsForStudent(student) {
  const reportDir = learningReportDirForStudent(student);
  fs.mkdirSync(reportDir, { recursive: true });
  ensureGrowthModelForStudent(student);
  const created = [];
  for (const report of LEARNING_REPORTS) {
    const file = learningReportPathForStudent(student, report);
    if (!fs.existsSync(file)) {
      fs.writeFileSync(file, learningReportTemplate(student, report), 'utf8');
      created.push(report.fileName);
    }
  }
  return { reportDir, created };
}

function recoverLearningReportsForStudent(student) {
  const normalized = toHostStudent(student);
  const metadataRepair = repairMigratedStudentMetadata(normalized);
  const recovered = recoverPlaceholderReportsFromArchive({
    rootDir: educationArchiveVersionRoot(normalized),
    studentId: normalized.id,
    reportPaths: Object.fromEntries(LEARNING_REPORTS.map((report) => [report.id, learningReportPathForStudent(normalized, report)])),
  });
  return { studentId: normalized.id, studentName: normalized.name, metadataRepair, ...recovered };
}

function remapAllAbsolutePathStrings(value, mappings) {
  if (typeof value === 'string') {
    return mappings.reduce((current, mapping) => rebaseStoragePath(current, mapping.sourceRoot, mapping.targetRoot, { platform: process.platform }), value);
  }
  if (Array.isArray(value)) return value.map((item) => remapAllAbsolutePathStrings(item, mappings));
  if (!value || typeof value !== 'object') return value;
  return Object.fromEntries(Object.entries(value).map(([key, child]) => [key, remapAllAbsolutePathStrings(child, mappings)]));
}

function collectMigratedStudentMetadataJson(student) {
  const roots = [studentAiManagerDir(student), studentManagerDir(student), growthModelDirForStudent(student)];
  const files = [];
  const visit = (current, depth = 0) => {
    if (depth > 8 || !fs.existsSync(current)) return;
    for (const entry of fs.readdirSync(current, { withFileTypes: true })) {
      if (entry.isDirectory() && entry.name === 'education-archive-versions') continue;
      const target = path.join(current, entry.name);
      if (entry.isDirectory()) visit(target, depth + 1);
      else if (entry.isFile() && entry.name.toLowerCase().endsWith('.json')) files.push(target);
    }
  };
  for (const root of roots) visit(root);
  return [...new Set(files)];
}

function repairMigratedStudentMetadata(student) {
  try {
    const report = safeReadJson(path.join(defaultStudentBaseDir(), '.edu-manager', 'migration-report.json'), {});
    const mappings = [
      ...(report.sourceManagedRoot && report.targetRoot ? [{ sourceRoot: report.sourceManagedRoot, targetRoot: report.targetRoot }] : []),
      ...(Array.isArray(report.externalMappings) ? report.externalMappings : []),
    ]
      .filter((item) => item?.sourceRoot && item?.targetRoot);
    if (!mappings.length) return { changedFiles: 0, scannedFiles: 0 };
    let changedFiles = 0;
    const files = collectMigratedStudentMetadataJson(student);
    for (const file of files) {
      const current = safeReadJson(file, null);
      if (!current) continue;
      const next = remapAllAbsolutePathStrings(current, mappings);
      if (JSON.stringify(next) === JSON.stringify(current)) continue;
      writeJsonAtomic(file, next);
      changedFiles += 1;
    }
    if (changedFiles) appendHostTimeline({ type: 'migration_metadata_paths_repaired', title: 'Migration metadata paths repaired', detail: `${student.name}: ${changedFiles}`, studentId: String(student.id), count: changedFiles });
    return { changedFiles, scannedFiles: files.length };
  } catch (error) {
    return { changedFiles: 0, scannedFiles: 0, message: error.message };
  }
}

function frontmatterValue(content, key) {
  const match = new RegExp(`^${key}:\\s*(.+)$`, 'im').exec(String(content || ''));
  return match ? match[1].trim() : '';
}

function extractSectionSummary(content, heading) {
  const text = String(content || '');
  const escaped = String(heading || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = new RegExp(`##\\s+${escaped}\\s*\\n([\\s\\S]*?)(?=\\n##\\s+|$)`, 'i').exec(text);
  const raw = (match?.[1] || text.replace(/^---[\s\S]*?---/, '')).trim();
  const line = raw
    .split(/\r?\n/)
    .map((item) => item.replace(/^[-*]\s*/, '').trim())
    .find((item) => item && !/^待(生成|补充)/.test(item));
  return (line || '待生成').slice(0, 120);
}

function reportHasEvidence(content) {
  const evidence = extractSectionSummary(content, '依据来源');
  return Boolean(evidence && evidence !== '待生成' && !/^待(生成|补充)/.test(evidence));
}

function learningReportRecord(student, report) {
  const file = learningReportPathForStudent(student, report);
  const exists = fs.existsSync(file);
  const content = exists ? fs.readFileSync(file, 'utf8') : learningReportTemplate(student, report);
  const stat = exists ? fs.statSync(file) : null;
  const status = frontmatterValue(content, 'status') || (/(待生成|待补充)/.test(content) ? 'draft' : 'active');
  const updatedMs = stat ? stat.mtimeMs : 0;
  const staleDays = updatedMs ? Math.floor((Date.now() - updatedMs) / (24 * 60 * 60 * 1000)) : null;
  const evidenceOk = reportHasEvidence(content);
  const substantive = reportHasSubstantiveContent(content);
  const stale = Boolean(staleDays !== null && staleDays >= 14);
  const warnings = [];
  if (!exists) warnings.push('报告文件缺失');
  if (status === 'draft') warnings.push('仍是草稿状态');
  if (stale) warnings.push(`已 ${staleDays} 天未更新`);
  if (!evidenceOk) warnings.push('缺少有效依据来源');
  if (!substantive) warnings.push('当前为占位模板，尚未生成正式正文');
  return {
    id: report.id,
    title: report.title,
    fileName: report.fileName,
    path: `学情报告/${report.fileName}`,
    absolutePath: file,
    exists,
    updatedAt: stat ? stat.mtime.toISOString() : '',
    status,
    stale,
    staleDays,
    evidenceOk,
    substantive,
    health: warnings.length ? 'warning' : 'ok',
    warnings,
    summary: extractSectionSummary(content, report.summaryHeading),
  };
}

function learningReportHealthSummary(reports) {
  const missingCount = reports.filter((report) => !report.exists).length;
  const draftCount = reports.filter((report) => report.status === 'draft').length;
  const staleCount = reports.filter((report) => report.stale).length;
  const evidenceMissingCount = reports.filter((report) => !report.evidenceOk).length;
  const warnings = [];
  if (missingCount) warnings.push(`${missingCount} 份报告缺失`);
  if (draftCount) warnings.push(`${draftCount} 份报告仍是草稿`);
  if (staleCount) warnings.push(`${staleCount} 份报告超过 14 天未更新`);
  if (evidenceMissingCount) warnings.push(`${evidenceMissingCount} 份报告缺少依据来源`);
  return {
    ok: warnings.length === 0,
    missingCount,
    draftCount,
    staleCount,
    evidenceMissingCount,
    warnings,
    message: warnings.length ? `学情报告需要检查：${warnings.join('；')}。` : '学情报告状态正常。',
  };
}

function templateLibraryDir() {
  return path.join(defaultStudentBaseDir(), '模板库');
}

function templateSystemDir() {
  return path.join(templateLibraryDir(), 'system');
}

function templateCustomDir() {
  return path.join(templateLibraryDir(), 'custom', 'current');
}

function templateMetaPath() {
  return path.join(templateCustomDir(), 'template-meta.json');
}

function templateFileKeys() {
  return ['AGENT.md', 'Soul.md', 'Memory.md', 'init-step-1.md', 'init-step-2.md', 'digest-prompt.md', 'consult-prompt.md'];
}

function parseJsonObject(value) {
  try {
    const parsed = JSON.parse(value || '{}');
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function writeTemplateFiles(dir, templates, overwrite) {
  fs.mkdirSync(dir, { recursive: true });
  for (const key of templateFileKeys()) {
    const file = path.join(dir, key);
    const content = String(templates[key] || '');
    if (fs.existsSync(file)) {
      if (!overwrite || fs.readFileSync(file, 'utf8') === content) continue;
    }
    fs.writeFileSync(file, content, 'utf8');
  }
}

function readTemplateFiles(dir) {
  const templates = {};
  for (const key of templateFileKeys()) {
    const file = path.join(dir, key);
    templates[key] = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : '';
  }
  return templates;
}

function ensureTemplateLibrary(systemTemplates) {
  fs.mkdirSync(templateLibraryDir(), { recursive: true });
  writeTemplateFiles(templateSystemDir(), systemTemplates || {}, true);
  fs.mkdirSync(templateCustomDir(), { recursive: true });
}

function getTemplateCenter(systemTemplatesJson) {
  try {
    const systemTemplates = parseJsonObject(systemTemplatesJson);
    ensureTemplateLibrary(systemTemplates);
    const settings = readSettings();
    const activeTemplate = settings.activeTemplate === 'custom' ? 'custom' : 'system';
    return JSON.stringify({
      ok: true,
      activeTemplate,
      templateRoot: templateLibraryDir(),
      systemPath: templateSystemDir(),
      customPath: templateCustomDir(),
      system: readTemplateFiles(templateSystemDir()),
      custom: readTemplateFiles(templateCustomDir()),
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `读取模板库失败：${error.message}` });
  }
}

function saveCustomTemplates(templatesJson) {
  try {
    const templates = parseJsonObject(templatesJson);
    ensureTemplateLibrary(templates);
    writeTemplateFiles(templateCustomDir(), templates, true);
    fs.writeFileSync(templateMetaPath(), JSON.stringify({
      version: 1,
      updatedAt: new Date().toISOString(),
      keys: templateFileKeys(),
    }, null, 2), 'utf8');
    const settings = readSettings();
    settings.activeTemplate = 'custom';
    writeSettings(settings);
    return JSON.stringify({ ok: true, activeTemplate: 'custom', customPath: templateCustomDir(), message: '已保存为当前自定义模板。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `保存模板失败：${error.message}` });
  }
}

function restoreSystemTemplates(systemTemplatesJson) {
  try {
    const systemTemplates = parseJsonObject(systemTemplatesJson);
    ensureTemplateLibrary(systemTemplates);
    const settings = readSettings();
    settings.activeTemplate = 'system';
    writeSettings(settings);
    return JSON.stringify({ ok: true, activeTemplate: 'system', systemPath: templateSystemDir(), message: '已恢复系统默认模板。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `恢复默认模板失败：${error.message}` });
  }
}

