      assetType: 'memory',
      tool: safeTool,
      sourceType: mode === 'file' ? 'fileImport' : 'manualPaste',
      targetPath: file,
      hash: sha1Text(content || ''),
      confidence: mode === 'file' ? 80 : 70,
      notes: '保存来源 Memory',
