function saveAgentRuleFile(studentId, fileName, content) {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const safeName = normalizeRuleFileName(fileName);
    if (!safeName) return JSON.stringify({ ok: false, message: '规则文件名无效，只能保存当前知识库根目录下的 .md 文件。' });
    const root = student.rootPath || getStudentRootDir(student.name);
    fs.mkdirSync(root, { recursive: true });
    fs.mkdirSync(path.join(agentRulesDir(student), 'snapshots'), { recursive: true });
    const file = path.join(root, safeName);
    const snapshot = snapshotCurrentFile(file, path.join(agentRulesDir(student), 'snapshots'));
    fs.writeFileSync(file, String(content || ''), 'utf8');
    appendAgentSourceRecord(student, {
      assetType: 'rule',
      tool: student.agentTool || 'workbuddy',
      sourceType: snapshot ? 'manualPaste' : 'manualPaste',
      targetPath: file,
      hash: sha1Text(content || ''),
      confidence: 100,
      notes: `保存规则文件 ${safeName}`,
    });
    return JSON.stringify({
      ok: true,
      fileName: safeName,
      path: file,
      snapshot,
      files: listAgentRuleFiles(student),
      message: `已保存规则文件 ${safeName}。`,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `保存规则文件失败：${error.message}` });
  }
}

function ruleFileTemplateIntro(student, fileName) {
  const cleanName = sanitizeName(student.name);
  const p = studentLogicalRulePaths();
  const lower = String(fileName || '').toLowerCase();
  if (lower === 'agents.md') {
    return `# ${cleanName} 教育管家项目说明（AGENTS.md）\n\n本目录是学生「${cleanName}」的 AI 教育管家知识库，供 Codex 或其他本地项目型 Agent 使用。\n\n## 工作规则\n\n- 该 Agent 的工作协议使用：${p.agent}\n- 后续所有学习资料消化都围绕该学生知识库执行。\n- 原始资料库是输入层：${p.raw}\n- 学情分析汇总是知识层：${p.summary}\n- 输出结果是临时交付层：${p.output}\n- 所有新增、修改和总结必须遵守 AGENT.md 中的证据追溯、索引更新和 log 记录规则。\n\n${learningReportProtocolText(p.summary)}\n`;
  }
  if (lower === 'claude.md' || lower === 'claud.md') {
    return `# ${cleanName} 教育管家 Claude Code 规则\n\n本文件用于 Claude Code 在该学生知识库目录中工作。\n\n## 工作规则\n\n该 Agent 的工作协议使用：${p.agent}\n后续所有学习资料消化都围绕该学生知识库执行。\n\n请优先读取 AGENT.md，再处理原始资料库与学情分析汇总。不要移动、删除用户原始资料。\n\n${learningReportProtocolText(p.summary)}\n`;
  }
  if (lower === 'ima.md' || lower === 'ima.copilot.md') {
    return `# ${cleanName} 教育管家 ima.copilot 规则\n\n本文件用于 ima.copilot 围绕该学生知识库进行搜、读、写和资料消化协作。\n\n## 工作规则\n\n该 Agent 的工作协议使用：${p.agent}\n后续所有学习资料消化都围绕该学生知识库执行。\n\n请优先读取 AGENT.md，再处理原始资料库与学情分析汇总。不要移动、删除用户原始资料。\n\n${learningReportProtocolText(p.summary)}\n`;
  }
  if (lower === 'workbuddy.md') {
    return `# ${cleanName} 教育管家 WorkBuddy 规则\n\n本文件用于 WorkBuddy 在该学生知识库目录中执行资料整理、报告生成和后续跟进。\n\n## 工作规则\n\n该 Agent 的工作协议使用：${p.agent}\n后续所有学习资料消化都围绕该学生知识库执行。\n\n请优先读取 AGENT.md，再处理原始资料库与学情分析汇总。不要移动、删除用户原始资料。教育管家任务中心只负责本任务执行，不会把任务上下文写入自动会话记忆；只有用户已授权的外部 Agent 当前聊天才由生命周期 Hook 自动采集，不需要 Agent 主动调用。\n\n${learningReportProtocolText(p.summary)}\n`;
  }
  return defaultRuleFileContent(student, fileName);
}

function generateAgentRuleFile(studentId, fileName) {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const safeName = normalizeRuleFileName(fileName);
    if (!safeName) return JSON.stringify({ ok: false, message: '规则文件名无效。' });
    const root = student.rootPath || getStudentRootDir(student.name);
    const agentPath = student.agentPath || path.join(root, 'AGENT.md');
    const agentContent = fs.existsSync(agentPath) ? fs.readFileSync(agentPath, 'utf8') : defaultRuleFileContent(student, 'AGENT.md');
    const generated = `${ruleFileTemplateIntro(student, safeName).trim()}\n\n## AGENT.md 基础协议摘录\n\n\`\`\`markdown\n${agentContent.slice(0, 12000)}\n\`\`\`\n`;
    return saveAgentRuleFile(studentId, safeName, generated);
  } catch (error) {
    return JSON.stringify({ ok: false, message: `生成规则模板失败：${error.message}` });
  }
}

function compareAgentRuleFiles(studentId, baseName, targetName) {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const root = student.rootPath || getStudentRootDir(student.name);
    const baseFile = path.join(root, normalizeRuleFileName(baseName) || 'AGENT.md');
    const targetFile = path.join(root, normalizeRuleFileName(targetName) || '');
    const base = fs.existsSync(baseFile) ? fs.readFileSync(baseFile, 'utf8') : '';
    const target = fs.existsSync(targetFile) ? fs.readFileSync(targetFile, 'utf8') : '';
    const baseLines = new Set(base.split(/\r?\n/).map((line) => line.trim()).filter(Boolean));
    const targetLines = new Set(target.split(/\r?\n/).map((line) => line.trim()).filter(Boolean));
    const onlyBase = Array.from(baseLines).filter((line) => !targetLines.has(line)).slice(0, 120);
    const onlyTarget = Array.from(targetLines).filter((line) => !baseLines.has(line)).slice(0, 120);
    return JSON.stringify({ ok: true, onlyBase, onlyTarget, message: onlyBase.length || onlyTarget.length ? '检测到规则差异。' : '未检测到明显差异。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `对比规则文件失败：${error.message}` });
  }
}

const AGENT_KNOWLEDGE_SCAN = {
  maxDepth: 6,
  maxFiles: 1200,
  maxEntries: 12000,
  maxCandidates: 80,
  maxReadBytes: 256 * 1024,
  maxImportBytes: 5 * 1024 * 1024,
};

function agentKnowledgeScanRoots() {
  const home = os.homedir();
  const roaming = process.env.APPDATA || path.join(home, 'AppData', 'Roaming');
  const local = process.env.LOCALAPPDATA || path.join(home, 'AppData', 'Local');
  const toolNames = ['QClaw', 'OpenClaw', 'Hohu', 'Marvis', 'IMA', 'ima.copilot', 'WorkBuddy', 'Codex', 'Claude'];
  const roots = [
    path.join(home, '.qclaw'),
    path.join(home, '.openclaw'),
    path.join(home, '.hohu'),
    path.join(home, '.marvis'),
    path.join(home, '.ima'),
    path.join(home, '.ima.copilot'),
    path.join(home, '.workbuddy'),
    path.join(home, '.codex'),
    path.join(home, '.claude'),
  ];
  for (const base of [roaming, local]) {
    for (const toolName of toolNames) roots.push(path.join(base, toolName));
  }
  return Array.from(new Set(roots)).filter((root) => fs.existsSync(root));
}

function shouldSkipAgentScanDir(name) {
  return [
    '.git',
    'node_modules',
    'cache',
    'code cache',
    'gpucache',
    'shadercache',
    'logs',
    'log',
    'tmp',
    'temp',
    'crashpad',
    'blob_storage',
    'session storage',
    'service worker',
  ].includes(String(name || '').toLowerCase());
}

function inferAgentToolFromPath(filePath, fallback = 'workbuddy') {
  const lower = String(filePath || '').toLowerCase();
  if (lower.includes('claude-code') || lower.includes('.claude')) return 'claude-code';
  if (lower.includes('ima.copilot') || lower.includes('\\ima\\') || lower.includes('/ima/') || lower.includes('.ima')) return 'ima.copilot';
  if (lower.includes('workbuddy') || lower.includes('work-buddy')) return 'workbuddy';
  if (lower.includes('hermes')) return 'hermes';
  if (lower.includes('chatgpt') || lower.includes('openai')) return 'chatgpt';
  if (lower.includes('doubao') || lower.includes('豆包')) return 'doubao';
  if (lower.includes('fastgpt')) return 'fastgpt';
  if (lower.includes('coze')) return 'coze';
  if (lower.includes('claude')) return 'claude';
  if (lower.includes('codex')) return 'codex';
  if (lower.includes('openclaw')) return 'openclaw';
  if (lower.includes('marvis')) return 'marvis';
  if (lower.includes('hohu')) return 'hohu';
  if (lower.includes('qclaw')) return 'qclaw';
  return isKnownAgentSource(fallback) ? fallback : 'workbuddy';
}

function inferAgentKnowledgeKind(fileName) {
  const lower = String(fileName || '').toLowerCase();
  if (/^(agents|agent|claude|claud|qclaw|openclaw|marvis|hohu|ima|ima\.copilot|workbuddy|hermes|rules?)\.(md|txt)$/i.test(lower)) return 'rule';
  if (/(conversation|chat|history|transcript|对话|聊天|会话)/i.test(lower)) return 'conversation';
  if (/^(memory|long[-_ ]?term[-_ ]?memory|memories)\.(md|txt|json)$/.test(lower) || lower.includes('memory')) return 'memory';
  if (/^(soul|persona|role|system|prompt|profile)\.(md|txt|json)$/.test(lower) || /(soul|persona|role|system|人设|角色)/i.test(lower)) return 'soul';
  return '';
}

function readTextPreview(filePath, maxBytes = AGENT_KNOWLEDGE_SCAN.maxReadBytes) {
  const stat = fs.statSync(filePath);
  const bytes = Math.min(stat.size, maxBytes);
  const fd = fs.openSync(filePath, 'r');
  try {
    const buffer = Buffer.alloc(bytes);
    fs.readSync(fd, buffer, 0, bytes, 0);
    return buffer.toString('utf8').replace(/\u0000/g, '').trim();
  } finally {
    fs.closeSync(fd);
  }
}

function scoreAgentKnowledgeCandidate(student, filePath, fileName, kind, content) {
  const lowerPath = String(filePath || '').toLowerCase();
  const lowerName = String(fileName || '').toLowerCase();
  const text = String(content || '');
  const lowerText = text.toLowerCase();
  const reasons = [];
  let score = 0;
  const add = (points, reason) => {
    score += points;
    reasons.push(reason);
  };
  if (student.name && text.includes(student.name)) add(60, `内容包含学生姓名「${student.name}」`);
  if (student.agentName && text.includes(student.agentName)) add(50, '内容包含 Agent 名称');
  if (student.rootPath && text.includes(student.rootPath)) add(45, '内容包含知识库根目录');
  if (student.agentPath && text.includes(student.agentPath)) add(35, '内容包含 AGENT.md 完整路径');
  if (lowerText.includes('agent.md')) add(22, '内容提到 AGENT.md');
  if (/原始资料库|学情分析汇总|学习资料消化|知识库/.test(text)) add(20, '内容包含教育管家知识库关键词');
  if (KNOWN_AGENT_SOURCE_IDS.some((tool) => lowerPath.includes(tool))) add(14, '路径命中 Agent 工具目录');
  if ((kind === 'memory' && lowerName === 'memory.md') || (kind === 'soul' && lowerName === 'soul.md') || (kind === 'rule' && /^(agent|agents|claude)\.md$/.test(lowerName))) add(12, '文件名为标准名称');
  if (lowerPath.includes(String(student.name || '').toLowerCase())) add(10, '路径包含学生姓名');
  return { score, reasons };
}

function walkAgentKnowledgeFiles(root, results, stats, depth = 0) {
  if (
    depth > AGENT_KNOWLEDGE_SCAN.maxDepth ||
    stats.files >= AGENT_KNOWLEDGE_SCAN.maxFiles ||
    stats.entries >= AGENT_KNOWLEDGE_SCAN.maxEntries
  ) return;
  let entries = [];
  try {
    entries = fs.readdirSync(root, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    stats.entries += 1;
    if (stats.files >= AGENT_KNOWLEDGE_SCAN.maxFiles || stats.entries >= AGENT_KNOWLEDGE_SCAN.maxEntries) return;
    const fullPath = path.join(root, entry.name);
    if (entry.isDirectory()) {
      if (!shouldSkipAgentScanDir(entry.name)) walkAgentKnowledgeFiles(fullPath, results, stats, depth + 1);
      continue;
    }
    if (!entry.isFile()) continue;
    const kind = inferAgentKnowledgeKind(entry.name);
    if (!kind) continue;
    stats.files += 1;
    results.push({ path: fullPath, name: entry.name, kind });
  }
}

function scanAgentKnowledgeFiles(studentId) {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const roots = agentKnowledgeScanRoots();
    const rawCandidates = [];
    const stats = { files: 0, entries: 0 };
    for (const root of roots) walkAgentKnowledgeFiles(root, rawCandidates, stats);
    const candidates = [];
    for (const item of rawCandidates) {
      try {
        const stat = fs.statSync(item.path);
        if (stat.size > AGENT_KNOWLEDGE_SCAN.maxImportBytes) continue;
        const preview = readTextPreview(item.path);
        const scored = scoreAgentKnowledgeCandidate(student, item.path, item.name, item.kind, preview);
        candidates.push({
          ...item,
          tool: inferAgentToolFromPath(item.path, student.agentTool),
          score: scored.score,
          reasons: scored.reasons,
          mtime: stat.mtime.toISOString(),
          size: stat.size,
          preview: preview.slice(0, 900),
        });
      } catch {
        // Ignore files that disappear or cannot be decoded during scanning.
      }
    }
    candidates.sort((a, b) => b.score - a.score || String(b.mtime).localeCompare(String(a.mtime)));
    return JSON.stringify({
      ok: true,
      scannedRoots: roots,
      candidates: candidates.slice(0, AGENT_KNOWLEDGE_SCAN.maxCandidates),
      message: roots.length
        ? `已扫描 ${roots.length} 个工具目录，找到 ${candidates.length} 个候选记忆/人设文件。`
        : '未找到常见 Agent 工具目录，可手动粘贴导入。',
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `扫描 Agent 记忆文件失败：${error.message}` });
  }
}

function importAgentKnowledgeFile(studentId, filePath, tool, kind) {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const safeTool = isKnownAgentSource(tool) ? tool : inferAgentToolFromPath(filePath, student.agentTool);
    const safeKind = ['soul', 'rule', 'conversation'].includes(kind) ? kind : 'memory';
    if (!filePath || !fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
      return JSON.stringify({ ok: false, message: '候选文件不存在或不可读取。' });
    }
    const stat = fs.statSync(filePath);
    if (stat.size > AGENT_KNOWLEDGE_SCAN.maxImportBytes) {
      return JSON.stringify({ ok: false, message: '候选文件过大，请手动打开确认后粘贴导入。' });
    }
    const content = fs.readFileSync(filePath, 'utf8');
    if (safeKind === 'soul') return saveAgentSoulSource(student.id, safeTool, content);
    if (safeKind === 'rule') return saveAgentRuleFile(student.id, path.basename(filePath), content);
    if (safeKind === 'conversation') return saveAgentConversationImport(student.id, content, safeTool, filePath);
    return saveAgentMemorySource(student.id, safeTool, content, 'file');
  } catch (error) {
    return JSON.stringify({ ok: false, message: `导入 Agent 文件失败：${error.message}` });
  }
}

function conversationIndexPath(student) {
  return path.join(agentConversationDir(student), 'conversation-index.json');
}

function conversationDeliveriesPath(student) {
  return path.join(conversationGovernanceDir(student), 'material-deliveries.json');
}

function conversationImportLocation(student, sourceScopeType, sourceScopeId) {
  if (sourceScopeType !== 'project') {
    if (String(sourceScopeId || student.id) !== String(student.id)) return null;
    return {
      scopeType: 'student',
      scopeId: String(student.id),
      scopeName: student.name,
      indexPath: conversationIndexPath(student),
      indexFallback: { version: 2, imports: [], extracts: [] },
      assetsDir: conversationAssetsDir(student),
      interactionsDir: conversationInteractionsDir(student),
      candidatesPath: conversationCandidatesPath(student),
      allowedContentRoot: agentConversationImportsDir(student),
    };
  }
  const project = readProjects().map(normalizeProject).find((item) => (
    String(item.id) === String(sourceScopeId || '')
    && (item.studentIds || []).map(String).includes(String(student.id))
  ));
  if (!project) return null;
  const governanceDir = projectConversationGovernanceDir(project);
  return {
    scopeType: 'project',
    scopeId: String(project.id),
    scopeName: project.name,
    project,
    indexPath: projectConversationIndexPath(project),
    indexFallback: { schema: 'edu-manager.project-conversation-index.v1', version: 1, projectId: String(project.id), imports: [] },
    assetsDir: path.join(governanceDir, 'assets'),
    interactionsDir: path.join(governanceDir, 'interactions'),
    candidatesPath: projectConversationCandidatesPath(project),
    allowedContentRoot: path.join(project.rawPath, 'Agent对话资料'),
  };
}

function conversationImportDependencySummary(student, location, item, deliveries = []) {
  const matchingDeliveries = deliveries.filter((delivery) => (
    String(delivery.assetId) === String(item.assetId)
    && String(delivery.sourceScopeType || 'student') === location.scopeType
    && String(delivery.sourceScopeId || student.id) === location.scopeId
  ));
  const candidateRegistry = readJsonFile(location.candidatesPath, { candidates: [] });
  const candidates = (candidateRegistry.candidates || []).filter((candidate) => (
    String(candidate?.source?.assetId || '') === String(item.assetId)
  ));
  const promoted = candidates.filter((candidate) => candidate.status === 'promoted' || candidate.promotionTransactionId).length;
  const registeredProjectOriginal = location.scopeType === 'project'
    && isWorkspaceMaterialProject(location.project) && Boolean(item.materialId);
  return {
    deliveryCount: matchingDeliveries.length,
    candidateCount: candidates.length,
    promotedCount: promoted,
    canPermanentlyDelete: !registeredProjectOriginal && matchingDeliveries.length === 0 && promoted === 0,
  };
}

function conversationAnalysisFor(student, content) {
  const projects = readProjects().map(normalizeProject).filter((project) => (
    (project.studentIds || []).map(String).includes(String(student.id))
    && !['sealed', 'archived'].includes(String(project.status || ''))
  ));
  return analyzeConversationAsset(content, projects);
}

function refreshConversationIndex(student, entry) {
  fs.mkdirSync(agentConversationDir(student), { recursive: true });
  const indexFile = conversationIndexPath(student);
  const current = readJsonFile(indexFile, { version: 1, imports: [], extracts: [] });
  if (entry?.type === 'import') current.imports = [entry, ...(Array.isArray(current.imports) ? current.imports : []).filter((item) => item.assetId !== entry.assetId && item.hash !== entry.hash)].slice(0, 200);
  if (entry?.type === 'extract') current.extracts = [entry, ...(Array.isArray(current.extracts) ? current.extracts : []).filter((item) => item.id !== entry.id)].slice(0, 200);
  current.version = 2;
  current.updatedAt = new Date().toISOString();
  writeJsonFile(indexFile, current);
  return current;
}

function readConversationDeliveries(student) {
  return readJsonFile(conversationDeliveriesPath(student), {
    schema: 'edu-manager.conversation-material-delivery-store.v1',
    deliveries: [],
    updatedAt: '',
  });
}

function writeConversationDeliveries(student, value) {
  const next = {
    schema: 'edu-manager.conversation-material-delivery-store.v1',
    deliveries: Array.isArray(value?.deliveries) ? value.deliveries.slice(0, 5000) : [],
    updatedAt: new Date().toISOString(),
  };
  writeJsonFile(conversationDeliveriesPath(student), next);
  return next;
}

function projectConversationIndexPath(project) {
  return path.join(projectConversationGovernanceDir(project), 'index.json');
}

function conversationInboxImports(student) {
  const refreshAnalysis = (indexPath, fallback) => {
    const index = readJsonFile(indexPath, fallback);
    let changed = false;
    let refreshed = 0;
    index.imports = (index.imports || []).map((item) => {
      if (
        refreshed >= 30
        || item.analysis?.schema === 'edu-manager.conversation-topic-analysis.v2'
        || !item.path
        || !fs.existsSync(item.path)
      ) return item;
      try {
        changed = true;
        refreshed += 1;
        return { ...item, analysis: conversationAnalysisFor(student, readSmallTextFile(item.path, 5 * 1024 * 1024)) };
      } catch {
        return item;
      }
    });
    if (changed) writeJsonFile(indexPath, { ...index, updatedAt: new Date().toISOString() });
    return index;
  };
  const studentIndex = refreshAnalysis(conversationIndexPath(student), { imports: [] });
  const studentImports = (studentIndex.imports || []).map((item) => ({
    ...item,
    sourceScopeType: 'student',
    sourceScopeId: String(student.id),
    sourceScopeName: student.name,
  }));
  const projectImports = readProjects().map(normalizeProject)
    .filter((project) => (project.studentIds || []).map(String).includes(String(student.id)))
    .flatMap((project) => {
      const index = refreshAnalysis(projectConversationIndexPath(project), { imports: [] });
      return (index.imports || []).map((item) => ({
        ...item,
        sourceScopeType: 'project',
        sourceScopeId: String(project.id),
        sourceScopeName: project.name,
        projectId: String(project.id),
        projectName: project.name,
      }));
    });
  const deliveries = readConversationDeliveries(student).deliveries || [];
  return [...studentImports, ...projectImports]
    .map((item) => ({
      ...item,
      deliveries: deliveries.filter((delivery) => (
        delivery.assetId === item.assetId
        && delivery.sourceScopeType === item.sourceScopeType
        && delivery.sourceScopeId === item.sourceScopeId
      )),
      dependencies: conversationImportDependencySummary(
        student,
        conversationImportLocation(student, item.sourceScopeType, item.sourceScopeId),
        item,
        deliveries,
      ),
    }))
    .sort((left, right) => String(right.importedAt || '').localeCompare(String(left.importedAt || '')));
}

function markAgentConversationSubmissionDeleted(assetId, deletedAt) {
  const store = readAgentConversationSubmissionStore();
  let changed = false;
  for (const record of Object.values(store.submissions || {})) {
    if (String(record?.receipt?.assetId || '') !== String(assetId || '')) continue;
    record.status = 'deleted';
    record.deletedAt = deletedAt;
    record.receipt = {
      ...(record.receipt || {}),
      status: 'deleted',
      message: '原始对话已按用户确认彻底删除；再次提交相同内容时允许重新导入。',
    };
    changed = true;
  }
  if (changed) writeAgentConversationSubmissionStore(store);
}

function removeDeletedConversationSourceRecord(student, contentPath) {
  const registryPath = agentSourceRegistryPath(student);
  const registry = readJsonFile(registryPath, { version: 1, records: [] });
  const records = Array.isArray(registry.records) ? registry.records : [];
  const target = path.resolve(String(contentPath || ''));
  const retained = records.filter((record) => (
    record.assetType !== 'conversation'
    || path.resolve(String(record.targetPath || '')) !== target
  ));
  if (retained.length !== records.length) {
    writeJsonFile(registryPath, { ...registry, records: retained, updatedAt: new Date().toISOString() });
  }
}

function manageConversationImports(studentId, requestJson) {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const request = parseJsonObject(requestJson);
    const action = ['trash', 'restore', 'delete'].includes(request.action) ? request.action : '';
    const sources = Array.isArray(request.sources) ? request.sources.slice(0, 100) : [];
    if (!action || !sources.length) return JSON.stringify({ ok: false, message: '请选择对话并指定有效操作。' });
    const deliveries = readConversationDeliveries(student).deliveries || [];
    const now = new Date().toISOString();
    const results = [];
    for (const source of sources) {
      const location = conversationImportLocation(student, source.sourceScopeType, source.sourceScopeId);
      if (!location) {
        results.push({ assetId: String(source.assetId || ''), ok: false, message: '对话来源不属于当前学生。' });
        continue;
      }
      const index = readJsonFile(location.indexPath, location.indexFallback);
      const imports = Array.isArray(index.imports) ? index.imports : [];
      const itemIndex = imports.findIndex((item) => String(item.assetId || '') === String(source.assetId || ''));
      if (itemIndex < 0) {
        results.push({ assetId: String(source.assetId || ''), ok: false, message: '未找到对话导入记录。' });
        continue;
      }
      const item = imports[itemIndex];
      const dependencies = conversationImportDependencySummary(student, location, item, deliveries);
      const syncCapturedSession = () => location.scopeType === 'student'
        ? agentMemoryStore().updateArchivedAssetLifecycle({ studentId: String(student.id), assetId: item.assetId, action })
        : { matched: 0, changed: 0 };
      if (action === 'trash') {
        if (item.lifecycleStatus === 'trashed') {
          syncCapturedSession();
          results.push({ assetId: item.assetId, ok: true, deduplicated: true, action, dependencies });
          continue;
        }
        syncCapturedSession();
        imports[itemIndex] = { ...item, lifecycleStatus: 'trashed', trashedAt: now };
      } else if (action === 'restore') {
        if (item.lifecycleStatus !== 'trashed') {
          syncCapturedSession();
          results.push({ assetId: item.assetId, ok: true, deduplicated: true, action, dependencies });
          continue;
        }
        const restored = { ...item, lifecycleStatus: 'active', restoredAt: now };
        delete restored.trashedAt;
        imports[itemIndex] = restored;
      } else {
        if (item.lifecycleStatus !== 'trashed') {
          results.push({ assetId: item.assetId, ok: false, action, dependencies, message: '请先将对话移入回收站，再执行彻底删除。' });
          continue;
        }
        if (!request.confirmPermanentDelete) {
          results.push({ assetId: item.assetId, ok: false, action, dependencies, message: '彻底删除需要二次确认。' });
          continue;
        }
        if (!dependencies.canPermanentlyDelete) {
          results.push({ assetId: item.assetId, ok: false, action, dependencies, message: `存在 ${dependencies.deliveryCount} 条资料投递和 ${dependencies.promotedCount} 条已晋升知识，不能彻底删除原始证据。` });
          continue;
        }
        const capturedSessions = syncCapturedSession();
        if (location.scopeType === 'student') {
          purgeQueuedAgentLifecycleSession(student.id, capturedSessions.sessionIds);
        }
        const candidateRegistry = readJsonFile(location.candidatesPath, { candidates: [] });
        const retainedCandidates = (candidateRegistry.candidates || []).filter((candidate) => (
          String(candidate?.source?.assetId || '') !== String(item.assetId)
        ));
        if (retainedCandidates.length !== (candidateRegistry.candidates || []).length) {
          writeJsonFile(location.candidatesPath, { ...candidateRegistry, candidates: retainedCandidates, updatedAt: now });
        }
        const asset = readJsonFile(path.join(location.assetsDir, `${item.assetId}.json`), null);
        const contentPath = path.resolve(asset?.storedPath || item.path || '');
        if (contentPath && fs.existsSync(contentPath) && canonicalIsPathInside(location.allowedContentRoot, contentPath)) fs.unlinkSync(contentPath);
        const assetPath = path.join(location.assetsDir, `${item.assetId}.json`);
        const interactionPath = path.join(location.interactionsDir, `${item.interactionId}.json`);
        if (fs.existsSync(assetPath)) fs.unlinkSync(assetPath);
        if (fs.existsSync(interactionPath)) fs.unlinkSync(interactionPath);
        if (location.scopeType === 'student') removeDeletedConversationSourceRecord(student, contentPath);
        imports.splice(itemIndex, 1);
        markAgentConversationSubmissionDeleted(item.assetId, now);
      }
      writeJsonFile(location.indexPath, { ...index, imports, updatedAt: now });
      if (action === 'restore') syncCapturedSession();
      results.push({ assetId: item.assetId, ok: true, action, dependencies });
    }
    const succeeded = results.filter((item) => item.ok).length;
    const failed = results.length - succeeded;
    if (succeeded) {
      appendHostTimeline({
        type: `conversation_import_${action}`,
        title: action === 'trash' ? 'Conversation moved to trash' : action === 'restore' ? 'Conversation restored' : 'Conversation permanently deleted',
        detail: `${student.name}: ${succeeded} succeeded, ${failed} failed`,
        studentId: String(student.id),
        studentName: student.name,
        count: succeeded,
      });
    }
    return JSON.stringify({
      ok: succeeded > 0 && failed === 0,
      partial: succeeded > 0 && failed > 0,
      succeeded,
      failed,
      results,
      message: action === 'trash'
        ? `已将 ${succeeded} 份对话移入回收站${failed ? `，${failed} 份未处理` : ''}。已投递资料和已晋升知识不受影响。`
        : action === 'restore'
          ? `已恢复 ${succeeded} 份对话${failed ? `，${failed} 份未处理` : ''}。`
          : `已彻底删除 ${succeeded} 份无下游资料或已晋升知识依赖的对话及未晋升候选${failed ? `，${failed} 份因依赖或校验未删除` : ''}。`,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `管理对话资料失败：${error.message}` });
  }
}

function resolveConversationInboxAsset(student, request) {
  const sourceScopeType = request?.sourceScopeType === 'project' ? 'project' : 'student';
  const sourceScopeId = String(request?.sourceScopeId || (sourceScopeType === 'student' ? student.id : ''));
  const assetId = String(request?.assetId || '');
  if (!assetId) return null;
  const location = conversationImportLocation(student, sourceScopeType, sourceScopeId);
  if (!location) return null;
  const indexed = (readJsonFile(location.indexPath, location.indexFallback).imports || [])
    .find((item) => String(item.assetId || '') === assetId);
  if (!indexed || indexed.lifecycleStatus === 'trashed') return null;
  if (sourceScopeType === 'student') {
    if (sourceScopeId !== String(student.id)) return null;
    const asset = readJsonFile(path.join(conversationAssetsDir(student), `${assetId}.json`), null);
    return asset?.storedPath && fs.existsSync(asset.storedPath)
      ? { asset, sourceScopeType, sourceScopeId, sourceScopeName: student.name }
      : null;
  }
  const project = readProjects().map(normalizeProject).find((item) => (
    String(item.id) === sourceScopeId
    && (item.studentIds || []).map(String).includes(String(student.id))
  ));
  if (!project) return null;
  const asset = readJsonFile(path.join(projectConversationGovernanceDir(project), 'assets', `${assetId}.json`), null);
  return asset?.storedPath && fs.existsSync(asset.storedPath)
    ? { asset, project, sourceScopeType, sourceScopeId, sourceScopeName: project.name }
    : null;
}

async function registerWorkspaceConversationDelivery(student, project, resolved, deliveryId, contentHash, intakeAssociation = null) {
  const sourcePath = path.resolve(resolved.asset.storedPath);
  if ((await sha256FileDirect(sourcePath)) !== contentHash) {
    throw Object.assign(new Error('对话资产原文已变化，不能沿用旧投递身份。'), { code: 'source_changed' });
  }
  const host = createProjectMaterialHost(project);
  const prior = (await host.store.read()).materials.filter((record) =>
    (record.sources || []).some((source) => source.type === 'conversation_delivery'
      && source.conversationDeliveryId === deliveryId));
  if (prior.length > 1) throw Object.assign(new Error('同一对话投递对应多份资料，需人工核对。'),
    { code: 'duplicate_event' });
  if (prior.length && prior[0].adoption.state !== 'accepted') {
    throw Object.assign(new Error('既有对话资料已被取消采用，不能自动恢复。'),
      { code: 'source_not_adopted' });
  }
  if (prior.length && (prior[0].links.assets || []).length) {
    const source = await host.store.resolve(prior[0].materialId);
    if (source.sha256 === contentHash) {
      // A crash after asset binding but before journal removal must not leave a
      // permanent "pending upload" beside an already accepted original.
      const intake = createProjectUploadIntake(project);
      for (const entry of (await intake.pending()).filter((item) =>
        item.sourceType === 'conversation_delivery'
        && item.conversationDeliveryId === deliveryId
        && item.conversationAssetId === String(resolved.asset.id)
        && item.studentId === String(student.id))) {
        await intake.verifyExisting(entry, { sha256: source.sha256, size: source.size });
        await intake.complete(entry);
      }
      return { path: source.path,
        materialId: prior[0].materialId,
        assetId: prior[0].links.assets.find((link) => link.version === source.version)?.assetId,
        deduplicated: true };
    }
  }
  const inbox = path.join(project.workspacePath, project.inboxRelativePath || '收件箱');
  let file;
  let materialId;
  let staged;
  if (canonicalIsPathInside(project.workspacePath, sourcePath)) {
    const relativePath = path.relative(project.workspacePath, sourcePath).replace(/\\/g, '/');
    const { result: [record] } = await host.store.registerFiles([{ location: {
      kind: 'workspace', rootId: 'workspace', relativePath,
    }, source: { eventId: deliveryId, type: 'conversation_delivery', studentId: String(student.id),
      deviceId: 'local-host', conversationDeliveryId: deliveryId,
      conversationAssetId: String(resolved.asset.id), ...(intakeAssociation ? { intakeAssociation: { ...intakeAssociation, studentId: String(student.id) } } : {}) } }], { intent: 'active' });
    file = sourcePath;
    materialId = record.materialId;
  } else {
    fs.mkdirSync(inbox, { recursive: true });
    staged = await stageProjectDirectImport(project, sourcePath,
      uniqueTargetFile(inbox, `${resolved.asset.id}.md`), {
        sourceType: 'conversation_delivery', intent: 'active', studentId: String(student.id),
        conversationDeliveryId: deliveryId, conversationAssetId: String(resolved.asset.id),
        findExisting: async (uploadId, fingerprint) => {
          if (await createProjectUploadIntake(project).find({ uploadId,
            studentId: String(student.id), deviceId: 'local-host' })) return null;
          const matches = (await host.store.read()).materials.filter((record) =>
            (record.sources || []).some((source) => source.eventId === uploadId));
          if (matches.length > 1) throw Object.assign(new Error('同一对话上传事件对应多份资料。'),
            { code: 'duplicate_event' });
          if (!matches.length) return null;
          const source = await host.store.resolve(matches[0].materialId);
          if (source.sha256 !== fingerprint.sha256 || !(matches[0].links.assets || []).length) {
            throw Object.assign(new Error('对话投递登记尚未完整恢复。'), { code: 'conversation_delivery_incomplete' });
          }
          return { material: matches[0], path: source.path };
        },
      });
    if (staged.alreadyImported) return { path: staged.existing.path,
      materialId: staged.existing.material.materialId,
      assetId: staged.existing.material.links.assets.find((link) =>
        link.version === staged.existing.material.version)?.assetId,
      deduplicated: true };
    file = staged.target;
    const registered = await host.registerTerminalUpload(file, {
      eventId: staged.uploadId, studentId: String(student.id), deviceId: 'local-host',
      sourceType: 'conversation_delivery', intent: 'active',
      conversationDeliveryId: deliveryId, conversationAssetId: String(resolved.asset.id), intakeAssociation,
    });
    materialId = registered.material.materialId;
  }
  const asset = upsertAssetFromFile(file, {
    spaceType: 'project', projectId: project.id, projectName: project.name,
    studentId: student.id, studentName: student.name,
    role: 'project_raw_conversation', sourceName: `对话资料箱：${resolved.sourceScopeName}`,
    sourceType: 'conversation_delivery', sourcePath, referenceId: deliveryId,
  });
  await host.bindUploadedAsset(materialId, asset);
  if (staged?.entry) {
    await staged.intake.complete(staged.entry);
    projectUploadRecoveryIssues = projectUploadRecoveryIssues.filter((issue) =>
      issue.projectId !== project.id || issue.key !== staged.entry.key);
  }
  return { path: file, materialId, assetId: asset.assetId, deduplicated: false };
}

async function deliverConversationMaterials(studentId, requestJson, intakeSnapshot = null) {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const request = parseJsonObject(requestJson);
    const sources = Array.isArray(request.sources) ? request.sources.slice(0, 100) : [];
    if (!sources.length) return JSON.stringify({ ok: false, message: '请先选择要投递的对话历史。' });
    const targetType = request.targetType === 'project' ? 'project' : 'student';
    const targetId = String(request.targetId || (targetType === 'student' ? student.id : ''));
    let targetProject = null;
    let targetRoot = student.rawPath || getRawDir(student.name);
    let targetName = student.name;
    if (targetType === 'student' && targetId !== String(student.id)) {
      return JSON.stringify({ ok: false, message: '投递目标与当前学生不一致，未写入任何资料。' });
    }
    if (targetType === 'project') {
      targetProject = readProjects().map(normalizeProject).find((project) => (
        String(project.id) === targetId
        && (project.studentIds || []).map(String).includes(String(student.id))
        && !['sealed', 'archived'].includes(String(project.status || ''))
      ));
      if (!targetProject) return JSON.stringify({ ok: false, message: '所选项目未与当前学生关联或当前不可写。' });
      targetProject = ensureProjectWorkspace(targetProject);
      targetRoot = isWorkspaceMaterialProject(targetProject) ? targetProject.workspacePath : targetProject.rawPath;
      targetName = targetProject.name;
    }
    const destinationDir = path.join(targetRoot, 'Agent对话资料');
    const store = readConversationDeliveries(student);
    const deliveries = [...(store.deliveries || [])];
    let delivered = 0;
    let deduplicated = 0;
    const results = [];
    for (const source of sources) {
      let resolved = resolveConversationInboxAsset(student, source);
      if (!resolved) continue;
      // Only the internal intake adapter supplies this third argument; IPC keeps
      // its existing two-argument contract. Import the analyzed immutable bytes.
      if (intakeSnapshot) {
        if (sources.length !== 1 || String(resolved.asset.id) !== String(intakeSnapshot.assetId)) throw Error('会话快照与授权资料不一致');
        const frozen = await hashStableFile(intakeSnapshot.path);
        if (frozen.sha256 !== intakeSnapshot.sha256) throw Error('会话固定快照校验失败');
        resolved = { ...resolved, asset: { ...resolved.asset, storedPath: intakeSnapshot.path, contentHash: frozen.sha256 } };
      }
      const contentHash = String(resolved.asset.contentHash || sha256Text(fs.readFileSync(resolved.asset.storedPath)));
      const deliveryId = stableGovernanceId(
        'conversation-delivery',
        student.id,
        resolved.sourceScopeType,
        resolved.sourceScopeId,
        resolved.asset.id,
        targetType,
        targetId,
        contentHash,
      );
      const existing = deliveries.find((item) => item.id === deliveryId);
      const workspaceDelivery = targetProject && isWorkspaceMaterialProject(targetProject);
      if (!workspaceDelivery && existing?.path && fs.existsSync(existing.path)) {
        deduplicated += 1;
        results.push(existing);
        continue;
      }
      const sourcePath = path.resolve(resolved.asset.storedPath);
      if (workspaceDelivery) {
        const accepted = await registerWorkspaceConversationDelivery(student, targetProject,
          resolved, deliveryId, contentHash, intakeSnapshot?.intakeAssociation || null);
        const delivery = {
          id: deliveryId, studentId: String(student.id), assetId: String(resolved.asset.id),
          interactionId: String(resolved.asset.interactionId || ''),
          sourceScopeType: resolved.sourceScopeType, sourceScopeId: resolved.sourceScopeId,
          sourceScopeName: resolved.sourceScopeName, targetType, targetId, targetName,
          path: accepted.path, materialId: accepted.materialId,
          registeredAssetId: accepted.assetId, contentHash,
          deliveredAt: existing?.deliveredAt || new Date().toISOString(),
        };
        const previousIndex = deliveries.findIndex((item) => item.id === deliveryId);
        if (previousIndex >= 0) deliveries.splice(previousIndex, 1);
        deliveries.unshift(delivery);
        writeConversationDeliveries(student, { deliveries });
        const now = new Date().toISOString();
        updateProjectRecord(targetProject.id, (item) => projectWithNewInputs({
          ...item, assetIds: mergeUnique([...(item.assetIds || []), accepted.assetId].filter(Boolean)),
          digestState: readProjectDigestState(targetProject), updatedAt: now,
        }, 'conversation_delivery', now));
        results.push(delivery);
        if (accepted.deduplicated) deduplicated += 1;
        else delivered += 1;
        continue;
      }
      const sourceAlreadyInTarget = canonicalIsPathInside(targetRoot, sourcePath);
      const finalPath = sourceAlreadyInTarget
        ? sourcePath
        : path.join(destinationDir, `${resolved.asset.id}.md`);
      if (!sourceAlreadyInTarget && !fs.existsSync(finalPath)) {
        fs.mkdirSync(destinationDir, { recursive: true });
        fs.copyFileSync(resolved.asset.storedPath, finalPath);
      }
      const delivery = {
        id: deliveryId,
        studentId: String(student.id),
        assetId: String(resolved.asset.id),
        interactionId: String(resolved.asset.interactionId || ''),
        sourceScopeType: resolved.sourceScopeType,
        sourceScopeId: resolved.sourceScopeId,
        sourceScopeName: resolved.sourceScopeName,
        targetType,
        targetId,
        targetName,
        path: finalPath,
        contentHash,
        deliveredAt: new Date().toISOString(),
      };
      deliveries.unshift(delivery);
      results.push(delivery);
      if (sourceAlreadyInTarget) deduplicated += 1;
      else delivered += 1;
      upsertAssetFromFile(finalPath, targetType === 'project'
        ? {
          spaceType: 'project',
          projectId: targetProject.id,
          projectName: targetProject.name,
          studentId: student.id,
          role: 'raw',
          sourceName: `对话资料箱：${resolved.sourceScopeName}`,
        }
        : {
          spaceType: 'student',
          studentId: student.id,
          studentName: student.name,
          role: 'raw',
          sourceName: `对话资料箱：${resolved.sourceScopeName}`,
        });
      writeConversationDeliveries(student, { deliveries });
    }
    return JSON.stringify({
      ok: delivered > 0 || deduplicated > 0,
      delivered,
      deduplicated,
      results,
      targetType,
      targetId,
      targetName,
      message: delivered
        ? `已向${targetType === 'project' ? '项目' : '学生'}“${targetName}”${targetProject && isWorkspaceMaterialProject(targetProject) ? '工作空间收件箱' : '原始资料库'}投递 ${delivered} 份对话资料${deduplicated ? `，另有 ${deduplicated} 份已存在` : ''}。`
        : deduplicated
          ? `所选 ${deduplicated} 份对话资料已经存在于目标${targetProject && isWorkspaceMaterialProject(targetProject) ? '工作空间' : '原始资料库'}，本次未生成重复文件。`
          : '没有找到可投递的对话资产。',
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `投递对话资料失败：${error.message}` });
  }
}

function readConversationCandidateRegistry(student) {
  return readJsonFile(conversationCandidatesPath(student), {
    schema: CANDIDATE_REGISTRY_SCHEMA,
    version: 1,
    updatedAt: '',
    candidates: [],
  });
}

function writeConversationCandidateRegistry(student, registry) {
  writeJsonFile(conversationCandidatesPath(student), {
    ...registry,
    schema: CANDIDATE_REGISTRY_SCHEMA,
    version: 1,
    updatedAt: new Date().toISOString(),
    candidates: Array.isArray(registry.candidates) ? registry.candidates : [],
  });
}

function listConversationTransactions(student) {
  fs.mkdirSync(conversationTransactionsDir(student), { recursive: true });
  return fs.readdirSync(conversationTransactionsDir(student), { withFileTypes: true })
    .filter((entry) => entry.isFile() && entry.name.endsWith('.json'))
    .map((entry) => readJsonFile(path.join(conversationTransactionsDir(student), entry.name), null))
    .filter(Boolean)
    .sort((a, b) => String(b.promotedAt || b.reversedAt || '').localeCompare(String(a.promotedAt || a.reversedAt || '')))
    .slice(0, 100);
}

function recoverInterruptedConversationTransactions(student) {
  fs.mkdirSync(conversationTransactionsDir(student), { recursive: true });
  for (const entry of fs.readdirSync(conversationTransactionsDir(student), { withFileTypes: true })) {
    if (!entry.isFile() || !entry.name.endsWith('.json')) continue;
    const file = path.join(conversationTransactionsDir(student), entry.name);
    const transaction = readJsonFile(file, null);
    if (!transaction || !['preparing', 'applying'].includes(transaction.status)) continue;
    try {
      writeJsonFile(file, rollbackInterruptedPromotionTransaction(transaction));
    } catch (error) {
      writeJsonFile(file, { ...transaction, status: 'recovery_required', recoveryError: error.message, recoveryCheckedAt: new Date().toISOString() });
    }
  }
}

function conversationGovernanceState(student) {
  const registry = readConversationCandidateRegistry(student);
  const candidates = Array.isArray(registry.candidates) ? registry.candidates : [];
  return {
    schema: 'edu-manager.conversation-governance-center.v1',
    candidates,
    transactions: listConversationTransactions(student),
    summary: {
      total: candidates.length,
      pending: candidates.filter((item) => item.status === 'pending').length,
      blocked: candidates.filter((item) => item.status === 'pending' && item.risk?.blocked).length,
      promoted: candidates.filter((item) => item.status === 'promoted').length,
      rejected: candidates.filter((item) => item.status === 'rejected').length,
    },
  };
}

function candidateSourceContent(student, candidate) {
  const assetId = String(candidate?.source?.assetId || '');
  if (!assetId) return '';
  const asset = readJsonFile(path.join(conversationAssetsDir(student), `${assetId}.json`), null);
  if (!asset?.storedPath || !fs.existsSync(asset.storedPath)) return '';
  return readSmallTextFile(asset.storedPath, 5 * 1024 * 1024);
}

function reassessConversationCandidate(student, candidate) {
  const next = candidate;
  const interactionId = String(next?.source?.interactionId || '');
  const messageId = String(next?.source?.messageId || '');
  if (interactionId && messageId) {
    const interaction = readJsonFile(path.join(conversationInteractionsDir(student), `${interactionId}.json`), null);
    next.source.messageIdValid = Boolean(interaction?.messages?.some((item) => String(item.id) === messageId));
  }
  next.risk = assessCandidateRisk(next, candidateSourceContent(student, next));
  return next;
}

function getAgentConversationCenter(studentId) {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    fs.mkdirSync(agentConversationImportsDir(student), { recursive: true });
    fs.mkdirSync(agentConversationExtractsDir(student), { recursive: true });
    fs.mkdirSync(conversationInteractionsDir(student), { recursive: true });
    fs.mkdirSync(conversationAssetsDir(student), { recursive: true });
    fs.mkdirSync(conversationTransactionsDir(student), { recursive: true });
    recoverInterruptedConversationTransactions(student);
    const index = readJsonFile(conversationIndexPath(student), { version: 1, imports: [], extracts: [] });
    const inboxImports = conversationInboxImports(student);
    const latestImport = inboxImports[0] || null;
    let latestInteraction = null;
    if (latestImport?.interactionId) {
      if (latestImport.sourceScopeType === 'project') {
        const sourceProject = readProjects().map(normalizeProject).find((project) => (
          String(project.id) === String(latestImport.sourceScopeId)
          && (project.studentIds || []).map(String).includes(String(student.id))
        ));
        if (sourceProject) {
          latestInteraction = readJsonFile(path.join(projectConversationGovernanceDir(sourceProject), 'interactions', `${latestImport.interactionId}.json`), null);
        }
      } else {
        latestInteraction = readJsonFile(path.join(conversationInteractionsDir(student), `${latestImport.interactionId}.json`), null);
      }
    }
    return JSON.stringify({
      ok: true,
      conversationDir: agentConversationDir(student),
      importsDir: agentConversationImportsDir(student),
      extractsDir: agentConversationExtractsDir(student),
      index: { ...index, imports: inboxImports },
      latestInteraction,
      governance: conversationGovernanceState(student),
      message: '已读取对话历史中心。',
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `读取对话历史失败：${error.message}` });
  }
}

function saveAgentConversationImport(studentId, content, tool = 'workbuddy', sourcePath = '', options = {}) {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const safeTool = isKnownAgentSource(tool) ? tool : 'workbuddy';
    if (!String(content || '').trim()) return JSON.stringify({ ok: false, message: '对话历史不能为空。' });
    fs.mkdirSync(agentConversationImportsDir(student), { recursive: true });
    fs.mkdirSync(conversationInteractionsDir(student), { recursive: true });
    fs.mkdirSync(conversationAssetsDir(student), { recursive: true });
    const normalized = normalizeConversationImport({ studentId: student.id, tool: safeTool, content, sourcePath });
    const routing = capturedConversationRoutingPolicy(agentControlStore().read().global);
    const sessionStartedAt = String(options.sessionStartedAt || '');
    const routingDisposition = options.lifecycleCapture === true && routing.authorizedAt && sessionStartedAt
      && Date.parse(sessionStartedAt) < Date.parse(routing.authorizedAt) ? 'before_authorization' : '';
    const analysis = conversationAnalysisFor(student, normalized.content);
    const currentIndex = readJsonFile(conversationIndexPath(student), { version: 2, imports: [], extracts: [] });
    const duplicate = (currentIndex.imports || []).find((item) => item.assetId === normalized.asset.id || item.hash === normalized.asset.contentHash);
    if (duplicate) {
      if (!duplicate.analysis) {
        refreshConversationIndex(student, { ...duplicate, type: 'import', analysis });
      }
      return JSON.stringify({ ok: true, deduplicated: true, path: duplicate.path, interaction: normalized.interaction, asset: normalized.asset, analysis, governance: conversationGovernanceState(student), message: '相同对话已经导入，本次未生成重复记录。' });
    }
    const file = path.join(agentConversationImportsDir(student), `${normalized.asset.id}.md`);
    if (!fs.existsSync(file)) fs.writeFileSync(file, normalized.content, 'utf8');
    normalized.asset.storedPath = file;
    normalized.interaction.assetId = normalized.asset.id;
    writeJsonFile(path.join(conversationInteractionsDir(student), `${normalized.interaction.id}.json`), normalized.interaction);
    writeJsonFile(path.join(conversationAssetsDir(student), `${normalized.asset.id}.json`), normalized.asset);
    refreshConversationIndex(student, {
      type: 'import',
      id: normalized.interaction.id,
      interactionId: normalized.interaction.id,
      assetId: normalized.asset.id,
      path: file,
      sourcePath,
      tool: safeTool,
      importedAt: normalized.asset.importedAt,
      hash: normalized.asset.contentHash,
      size: normalized.asset.size,
      messageCount: normalized.interaction.messageCount,
      sourceType: options.lifecycleCapture === true ? 'authorized_lifecycle' : /^https?:\/\//i.test(String(sourcePath || '')) ? 'share_link' : sourcePath ? 'file' : 'paste',
      sourceSessionId: options.lifecycleCapture === true ? String(options.sessionId || '') : '',
      capturedSessionStartedAt: sessionStartedAt,
      routingDisposition,
      sourceUrl: /^https?:\/\//i.test(String(sourcePath || '')) ? sourcePath : '',
      analysis,
    });
    appendAgentSourceRecord(student, {
      assetType: 'conversation',
      tool: safeTool,
      sourceType: options.lifecycleCapture === true ? 'authorizedLifecycle' : /^https?:\/\//i.test(String(sourcePath || '')) ? 'shareLink' : sourcePath ? 'fileImport' : 'manualPaste',
      sourcePath,
      targetPath: file,
      hash: normalized.asset.contentHash,
      confidence: 70,
      notes: `导入对话历史；Interaction ${normalized.interaction.id}；ConversationAsset ${normalized.asset.id}`,
    });
    void getSmartInbox().then(engine => engine.notifySource(options.lifecycleCapture === true ? 'session' : 'history', student.id)).catch(error => console.warn('会话分类等待后续扫描：', error.message));
    return JSON.stringify({ ok: true, path: file, interaction: normalized.interaction, asset: normalized.asset, analysis, governance: conversationGovernanceState(student), message: `已保存不可变对话资产，共定位 ${normalized.interaction.messageCount} 条消息，并完成主题整理。` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `保存对话历史失败：${error.message}` });
  }
}

async function readBoundedResponseText(response, maxBytes = 5 * 1024 * 1024) {
  const declaredSize = Number(response.headers.get('content-length') || 0);
  if (declaredSize > maxBytes) throw new Error('分享页面超过 5 MB，请改用文件导入。');
  if (!response.body?.getReader) {
    const text = await response.text();
    if (Buffer.byteLength(text, 'utf8') > maxBytes) throw new Error('分享页面超过 5 MB，请改用文件导入。');
    return text;
  }
  const reader = response.body.getReader();
  const chunks = [];
  let total = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > maxBytes) {
      await reader.cancel();
      throw new Error('分享页面超过 5 MB，请改用文件导入。');
    }
    chunks.push(Buffer.from(value));
  }
  return Buffer.concat(chunks).toString('utf8');
}

async function importConversationShareUrl(studentId, rawUrl, tool = 'workbuddy') {
  const student = findStudentByKey(studentId);
  if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
  const initial = validateConversationShareUrl(rawUrl);
  if (!initial.ok) return JSON.stringify({ ok: false, fallbackRequired: true, message: initial.message });
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 15000);
  try {
    let currentUrl = initial.url;
    let response = null;
    for (let redirectCount = 0; redirectCount < 4; redirectCount += 1) {
      response = await fetch(currentUrl, {
        signal: controller.signal,
        redirect: 'manual',
        headers: {
          Accept: 'text/html,text/plain,application/json;q=0.9,*/*;q=0.5',
          'User-Agent': 'Robogala-AI-Education-Manager/1.0',
        },
      });
      if (![301, 302, 303, 307, 308].includes(response.status)) break;
      const location = response.headers.get('location');
      if (!location) throw new Error('分享链接重定向地址缺失。');
      const next = validateConversationShareUrl(new URL(location, currentUrl).toString());
      if (!next.ok) throw new Error(next.message);
      currentUrl = next.url;
      response = null;
    }
    if (!response) throw new Error('分享链接重定向次数过多。');
    if (!response.ok) throw new Error(`分享页面返回 HTTP ${response.status}。`);
    const raw = await readBoundedResponseText(response);
    const contentType = String(response.headers.get('content-type') || '').toLowerCase();
    const parsed = contentType.includes('html') || /<html[\s>]/i.test(raw)
      ? htmlToConversationText(raw)
      : { title: '', content: raw.trim() };
    if (parsed.content.length < 20) throw new Error('分享页面没有提取到足够的对话正文。');
    const saved = JSON.parse(saveAgentConversationImport(student.id, parsed.content, tool, currentUrl));
    return JSON.stringify({
      ...saved,
      sourceUrl: currentUrl,
      title: parsed.title,
      extraction: parsed.extraction || '',
      fallbackRequired: false,
      message: saved.ok
        ? `${saved.message || '分享对话已导入。'}${parsed.title ? ` 标题：${parsed.title}` : ''}`
        : saved.message,
    });
  } catch (error) {
    const timeout = error?.name === 'AbortError';
    return JSON.stringify({
      ok: false,
      fallbackRequired: true,
      message: `${timeout ? '分享链接读取超时' : `分享链接自动导入失败：${error.message}`}。请直接粘贴对话内容，或导入 .md/.txt/.json 文件。`,
    });
  } finally {
    clearTimeout(timer);
  }
}

function projectConversationGovernanceDir(project) {
  return path.join(project.managerPath, 'agent-conversations');
}

function projectConversationCandidatesPath(project) {
  return path.join(projectConversationGovernanceDir(project), 'knowledge-candidates.json');
}

async function saveWorkspaceAgentProjectConversationImport(student, project, normalized, analysis, safeTool, sourcePath) {
  return withProjectMaterialLock(`conversation-submission:${project.id}`,
    () => saveWorkspaceAgentProjectConversationImportUnlocked(student, project,
      normalized, analysis, safeTool, sourcePath));
}

async function saveWorkspaceAgentProjectConversationImportUnlocked(student, project, normalized, analysis, safeTool, sourcePath) {
  try {
    const governanceDir = projectConversationGovernanceDir(project);
    const stagingDir = path.join(governanceDir, 'import-staging');
    const stagingPath = path.join(stagingDir, `${normalized.interaction.id}.md`);
    fs.mkdirSync(stagingDir, { recursive: true });
    if (fs.lstatSync(stagingDir).isSymbolicLink()) {
      throw Object.assign(new Error('对话提交准备目录不能是链接。'), { code: 'linked_path' });
    }
    if (fs.existsSync(stagingPath)) {
      if (!fs.lstatSync(stagingPath).isFile() || fs.lstatSync(stagingPath).isSymbolicLink()) {
        throw Object.assign(new Error('对话提交准备文件不是普通文件。'), { code: 'linked_path' });
      }
      if ((await sha256FileDirect(stagingPath)) !== normalized.asset.contentHash) {
        throw Object.assign(new Error('同一对话提交的准备文件内容冲突。'), { code: 'source_changed' });
      }
    } else fs.writeFileSync(stagingPath, normalized.content, { encoding: 'utf8', flag: 'wx' });
    const host = createProjectMaterialHost(project);
    const scopeStillValid = () => {
      const current = readProjects().map(normalizeProject).find((item) => String(item.id) === String(project.id));
      if (!current || !isWorkspaceMaterialProject(current) || current.workspacePath !== project.workspacePath
        || current.managerPath !== project.managerPath
        || !(current.studentIds || []).map(String).includes(String(student.id))
        || ['sealed', 'archived'].includes(String(current.status || ''))) {
        throw Object.assign(new Error('项目或学生范围已变化，未完成对话提交。'), { code: 'scope_changed' });
      }
    };
    scopeStillValid();
    const inbox = path.join(project.workspacePath, project.inboxRelativePath || '收件箱');
    fs.mkdirSync(inbox, { recursive: true });
    const staged = await stageProjectDirectImport(project, stagingPath,
      uniqueTargetFile(inbox, `${normalized.asset.id}.md`), {
        sourceType: 'conversation_submission', intent: 'active', studentId: String(student.id),
        conversationAssetId: normalized.asset.id, conversationInteractionId: normalized.interaction.id,
        findExisting: async (uploadId, fingerprint) => {
          if (await createProjectUploadIntake(project).find({ uploadId,
            studentId: String(student.id), deviceId: 'local-host' })) return null;
          const matches = (await host.store.read()).materials.filter((record) =>
            (record.sources || []).some((source) => source.eventId === uploadId));
          if (matches.length > 1) throw Object.assign(new Error('同一对话提交对应多份资料。'),
            { code: 'duplicate_event' });
          if (!matches.length) return null;
          const source = await host.store.resolve(matches[0].materialId);
          if (source.sha256 !== fingerprint.sha256 || !(matches[0].links.assets || []).length
            || matches[0].adoption.state !== 'accepted') {
            throw Object.assign(new Error('对话提交登记或资产引用尚未完整恢复。'),
              { code: 'conversation_submission_incomplete' });
          }
          return { material: matches[0], path: source.path };
        },
      });
    const file = staged.alreadyImported ? staged.existing.path : staged.target;
    let materialId = staged.alreadyImported ? staged.existing.material.materialId : '';
    let assetId = staged.alreadyImported
      ? staged.existing.material.links.assets.find((link) =>
        link.version === staged.existing.material.version)?.assetId : '';
    if (!staged.alreadyImported) {
      scopeStillValid();
      const registered = await host.registerTerminalUpload(file, {
        eventId: staged.uploadId, studentId: String(student.id), deviceId: 'local-host',
        sourceType: 'conversation_submission', intent: 'active',
        conversationAssetId: normalized.asset.id, conversationInteractionId: normalized.interaction.id,
      });
      materialId = registered.material.materialId;
      const asset = upsertAssetFromFile(file, {
        spaceType: 'project', projectId: project.id, projectName: project.name,
        studentId: student.id, studentName: student.name,
        role: 'project_raw_conversation', sourceName: `Agent 对话：${safeTool}`,
        sourceType: 'conversation_submission', sourcePath,
        conversationAssetId: normalized.asset.id,
        conversationInteractionId: normalized.interaction.id,
        referenceId: staged.uploadId,
      });
      await host.bindUploadedAsset(materialId, asset);
      assetId = asset.assetId;
      await staged.intake.complete(staged.entry);
      projectUploadRecoveryIssues = projectUploadRecoveryIssues.filter((issue) =>
        issue.projectId !== project.id || issue.key !== staged.entry.key);
    }
    normalized.asset.storedPath = file;
    normalized.interaction.assetId = normalized.asset.id;
    const interactionsDir = path.join(governanceDir, 'interactions');
    const assetsDir = path.join(governanceDir, 'assets');
    fs.mkdirSync(interactionsDir, { recursive: true });
    fs.mkdirSync(assetsDir, { recursive: true });
    const indexPath = path.join(governanceDir, 'index.json');
    const currentIndex = readJsonFile(indexPath, { imports: [] });
    writeJsonFile(path.join(interactionsDir, `${normalized.interaction.id}.json`), normalized.interaction);
    writeJsonFile(path.join(assetsDir, `${normalized.asset.id}.json`), normalized.asset);
    writeJsonFile(indexPath, {
      ...currentIndex, schema: 'edu-manager.project-conversation-index.v1',
      version: 1, projectId: String(project.id), updatedAt: new Date().toISOString(),
      imports: [{ interactionId: normalized.interaction.id, assetId: normalized.asset.id,
        path: file, materialId, sourcePath, tool: safeTool,
        importedAt: normalized.asset.importedAt, hash: normalized.asset.contentHash,
        size: normalized.asset.size, messageCount: normalized.interaction.messageCount,
        sourceType: /^https?:\/\//i.test(String(sourcePath || '')) ? 'share_link' : sourcePath ? 'file' : 'agent_submission',
        routingDisposition: 'already_scoped',
        sourceUrl: /^https?:\/\//i.test(String(sourcePath || '')) ? sourcePath : '', analysis,
      }, ...(Array.isArray(currentIndex.imports) ? currentIndex.imports : []).filter((item) =>
        item.assetId !== normalized.asset.id && item.hash !== normalized.asset.contentHash)].slice(0, 200),
    });
    const now = new Date().toISOString();
    updateProjectRecord(project.id, (item) => projectWithNewInputs({
      ...item, assetIds: mergeUnique([...(item.assetIds || []), assetId].filter(Boolean)),
      digestState: readProjectDigestState(project), updatedAt: now,
    }, 'agent_conversation_submission', now));
    if (fs.existsSync(stagingPath)) fs.unlinkSync(stagingPath);
    return { ok: true, deduplicated: staged.alreadyImported === true, path: file,
      materialId, interaction: normalized.interaction, asset: normalized.asset, analysis,
      message: staged.alreadyImported
        ? `相同对话已经保存在项目“${project.name}”工作空间，本次未生成重复原文。`
        : `已保存到项目“${project.name}”工作空间，共定位 ${normalized.interaction.messageCount} 条消息。` };
  } catch (error) {
    return { ok: false, message: `保存项目对话失败：${error.message}` };
  }
}

function saveAgentProjectConversationImport(student, project, content, tool = 'workbuddy', sourcePath = '') {
  try {
    const ensuredProject = ensureProjectWorkspace(project);
    const safeTool = isKnownAgentSource(tool) ? tool : 'workbuddy';
    if (!String(content || '').trim()) return { ok: false, message: '对话历史不能为空。' };
    const governanceDir = projectConversationGovernanceDir(ensuredProject);
    const interactionsDir = path.join(governanceDir, 'interactions');
    const assetsDir = path.join(governanceDir, 'assets');
    // “Agent对话资料”是唯一的对话原始资料目录。旧版本的
    // “Agent对话历史”继续只读兼容，但不再生成第二份副本。
    const importsDir = path.join(ensuredProject.rawPath, 'Agent对话资料');
    const indexPath = path.join(governanceDir, 'index.json');
    fs.mkdirSync(interactionsDir, { recursive: true });
    fs.mkdirSync(assetsDir, { recursive: true });
    const normalized = normalizeConversationImport({
      studentId: student.id,
      tool: safeTool,
      content,
      sourcePath,
    });
    const analysis = conversationAnalysisFor(student, normalized.content);
    normalized.interaction.scopeType = 'project';
    normalized.interaction.scopeId = String(ensuredProject.id);
    normalized.interaction.projectId = String(ensuredProject.id);
    normalized.asset.scopeType = 'project';
    normalized.asset.scopeId = String(ensuredProject.id);
    normalized.asset.projectId = String(ensuredProject.id);
    if (isWorkspaceMaterialProject(ensuredProject)) {
      return saveWorkspaceAgentProjectConversationImport(student, ensuredProject,
        normalized, analysis, safeTool, sourcePath);
    }
    fs.mkdirSync(importsDir, { recursive: true });
    const currentIndex = readJsonFile(indexPath, {
      schema: 'edu-manager.project-conversation-index.v1',
      version: 1,
      projectId: String(ensuredProject.id),
      imports: [],
    });
    const duplicate = (currentIndex.imports || []).find((item) => (
      item.assetId === normalized.asset.id || item.hash === normalized.asset.contentHash
    ));
    if (duplicate?.path && fs.existsSync(duplicate.path)) {
      normalized.asset.storedPath = duplicate.path;
      normalized.interaction.assetId = normalized.asset.id;
      if (!duplicate.analysis) {
        writeJsonFile(indexPath, {
          ...currentIndex,
          updatedAt: new Date().toISOString(),
          imports: (currentIndex.imports || []).map((item) => (
            item.assetId === duplicate.assetId ? { ...item, analysis } : item
          )),
        });
      }
      return {
        ok: true,
        deduplicated: true,
        path: duplicate.path,
        interaction: normalized.interaction,
        asset: normalized.asset,
        analysis,
        message: `相同对话已经保存在项目“${ensuredProject.name}”，本次未生成重复记录。`,
      };
    }
    const file = path.join(importsDir, `${normalized.asset.id}.md`);
    if (!fs.existsSync(file)) fs.writeFileSync(file, normalized.content, 'utf8');
    normalized.asset.storedPath = file;
    normalized.interaction.assetId = normalized.asset.id;
    writeJsonFile(path.join(interactionsDir, `${normalized.interaction.id}.json`), normalized.interaction);
    writeJsonFile(path.join(assetsDir, `${normalized.asset.id}.json`), normalized.asset);
    writeJsonFile(indexPath, {
      ...currentIndex,
      schema: 'edu-manager.project-conversation-index.v1',
      version: 1,
      projectId: String(ensuredProject.id),
      updatedAt: new Date().toISOString(),
      imports: [{
        interactionId: normalized.interaction.id,
        assetId: normalized.asset.id,
        path: file,
        sourcePath,
        tool: safeTool,
        importedAt: normalized.asset.importedAt,
        hash: normalized.asset.contentHash,
        size: normalized.asset.size,
        messageCount: normalized.interaction.messageCount,
        sourceType: /^https?:\/\//i.test(String(sourcePath || '')) ? 'share_link' : sourcePath ? 'file' : 'agent_submission',
        routingDisposition: 'already_scoped',
        sourceUrl: /^https?:\/\//i.test(String(sourcePath || '')) ? sourcePath : '',
        analysis,
      }, ...(Array.isArray(currentIndex.imports) ? currentIndex.imports : []).filter((item) => (
        item.assetId !== normalized.asset.id && item.hash !== normalized.asset.contentHash
      ))].slice(0, 200),
    });
    upsertAssetFromFile(file, {
      spaceType: 'project',
      projectId: ensuredProject.id,
      projectName: ensuredProject.name,
      studentId: student.id,
      role: 'raw',
      sourceName: `Agent 对话：${safeTool}`,
    });
    return {
      ok: true,
      path: file,
      interaction: normalized.interaction,
      asset: normalized.asset,
      analysis,
      message: `已保存到项目“${ensuredProject.name}”原始资料库，共定位 ${normalized.interaction.messageCount} 条消息。`,
    };
  } catch (error) {
    return { ok: false, message: `保存项目对话失败：${error.message}` };
  }
}

function agentConversationSubmissionStorePath() {
  return path.join(collaborationRootPath(), 'state', 'agent-conversation-submissions.json');
}

function agentConversationPendingDir() {
  return path.join(collaborationRootPath(), 'conversation-inbox', 'pending');
}

function readAgentConversationSubmissionStore() {
  const value = safeReadJson(agentConversationSubmissionStorePath(), {});
  return {
    schema: 'edu-manager.agent-conversation-submission-store.v1',
    submissions: value?.submissions && typeof value.submissions === 'object' ? value.submissions : {},
    importedObjectVersions: value?.importedObjectVersions && typeof value.importedObjectVersions === 'object'
      ? value.importedObjectVersions
      : {},
    updatedAt: String(value?.updatedAt || ''),
  };
}

function writeAgentConversationSubmissionStore(store) {
  const next = {
    schema: 'edu-manager.agent-conversation-submission-store.v1',
    submissions: store?.submissions || {},
    importedObjectVersions: store?.importedObjectVersions || {},
    updatedAt: new Date().toISOString(),
  };
  writeJsonAtomic(agentConversationSubmissionStorePath(), next);
  return next;
}

function resolveAgentConversationTarget(submission) {
  const projects = readProjects().map(normalizeProject);
  if (submission.targetProject) {
    const studentKey = submission.studentHint || (submission.scopeType === 'student' ? submission.scopeId : '');
    const student = findStudentByKey(studentKey);
    if (!student) {
      return {
        status: 'awaiting_attribution',
        message: '未找到当前对话对应的学生，未写入任何档案。',
      };
    }
    const resolvedProject = resolveLinkedConversationProject(projects, student.id, submission.targetProject);
    if (resolvedProject.status !== 'resolved') {
      return {
        status: 'awaiting_attribution',
        message: resolvedProject.status === 'ambiguous'
          ? `项目“${submission.targetProject}”在学生“${student.name}”的关联项目中不唯一，未写入任何档案。`
          : `项目“${submission.targetProject}”未与学生“${student.name}”关联，未写入任何档案。`,
      };
    }
    return { status: 'resolved', student, project: resolvedProject.project };
  }
  if (submission.scopeType === 'student' && submission.scopeId) {
    const student = findStudentByKey(submission.scopeId);
    if (student && submission.studentHint) {
      const hinted = findStudentByKey(submission.studentHint);
      if (!hinted || String(hinted.id) !== String(student.id)) return { status: 'awaiting_attribution' };
    }
    return student ? { status: 'resolved', student, project: null } : { status: 'awaiting_attribution' };
  }
  if (submission.scopeType === 'project') {
    const project = projects.find((item) => (
      (submission.projectLineageId && projectLineageForRemoteArchive(item, readCollaborationState().node.nodeId) === submission.projectLineageId)
      || String(item.id) === String(submission.scopeId || '')
    ));
    if (!project) return { status: 'awaiting_attribution' };
    const students = (project.studentIds || []).map(findStudentByKey).filter(Boolean);
    const hinted = submission.studentHint ? students.find((item) => (
      String(item.id) === submission.studentHint
      || String(item.loginId || '') === submission.studentHint
      || String(item.name || '') === submission.studentHint
    )) : null;
    if (hinted) return { status: 'resolved', student: hinted, project };
    if (submission.studentHint) return { status: 'awaiting_attribution', project };
    if (students.length === 1) return { status: 'resolved', student: students[0], project };
    return { status: 'awaiting_attribution', project };
  }
  if (submission.studentHint) {
    const student = findStudentByKey(submission.studentHint);
    if (student) return { status: 'resolved', student, project: null };
  }
  return { status: 'awaiting_attribution' };
}

function conversationSubmissionContent(submission) {
  return JSON.stringify({
    schema: AGENT_CONVERSATION_SUBMISSION_SCHEMA,
    title: submission.title,
    sourceAgent: submission.sourceAgent,
    sessionId: submission.sessionId,
    submittedAt: submission.submittedAt,
    messages: submission.messages.map((message) => ({
      role: message.role,
      content: message.content,
      occurredAt: message.occurredAt,
    })),
  }, null, 2);
}

function candidateDraftsForImportedInteraction(submission, interaction) {
  const drafts = deterministicCandidateDrafts(submission);
  return drafts.map((draft) => {
    const sourceIndex = (submission.messages || []).findIndex((message) => message.messageId === draft.messageId);
    const importedMessage = interaction?.messages?.[sourceIndex];
    if (!importedMessage || !String(importedMessage.content || '').includes(String(draft.sourceQuote || ''))) return null;
    return {
      ...draft,
      messageId: importedMessage.id,
      sourceLocation: importedMessage.locator,
      sourceQuote: draft.sourceQuote,
    };
  }).filter(Boolean);
}

function organizeConversationSubmissionCandidates(student, project, submission, imported) {
  const drafts = candidateDraftsForImportedInteraction(submission, imported.interaction);
  if (!drafts.length) return { organized: 0, watching: 0, attention: 0, duplicate: 0 };
  const sourceContent = fs.existsSync(imported.asset?.storedPath || '')
    ? readSmallTextFile(imported.asset.storedPath, 5 * 1024 * 1024)
    : conversationSubmissionContent(submission);
  const built = buildKnowledgeCandidates({ candidates: drafts }, {
    studentId: student.id,
    tool: submission.sourceAgent,
    source: {
      ...imported.asset,
      assetId: imported.asset.id,
      interactionId: imported.interaction.id,
      validMessageIds: (imported.interaction.messages || []).map((item) => item.id),
    },
    sourceContent,
  });
  const statusCounts = { organized: 0, watching: 0, attention: 0, duplicate: 0 };
  for (const candidate of built.candidates) {
    candidate.projectId = project?.id || '';
    candidate.submissionId = submission.submissionId;
    if (candidate.risk?.level === 'low') {
      candidate.status = 'organized';
      statusCounts.organized += 1;
    } else if (candidate.risk?.level === 'medium') {
      candidate.status = 'watching';
      statusCounts.watching += 1;
    } else {
      candidate.status = 'pending';
      statusCounts.attention += 1;
    }
    candidate.history = [
      ...(candidate.history || []),
      {
        action: candidate.status === 'pending' ? 'attention_required' : 'automatically_organized',
        at: new Date().toISOString(),
        actorRole: 'system',
        actorId: 'agent-conversation-submission',
      },
    ];
  }
  const candidateRegistry = project
    ? readJsonFile(projectConversationCandidatesPath(project), {
      schema: CANDIDATE_REGISTRY_SCHEMA,
      version: 1,
      updatedAt: '',
      candidates: [],
    })
    : readConversationCandidateRegistry(student);
  const merged = mergeCandidateRegistry(candidateRegistry, built.candidates);
  if (project) {
    writeJsonFile(projectConversationCandidatesPath(project), {
      ...merged.registry,
      schema: CANDIDATE_REGISTRY_SCHEMA,
      version: 1,
      projectId: String(project.id),
      updatedAt: new Date().toISOString(),
      candidates: Array.isArray(merged.registry.candidates) ? merged.registry.candidates : [],
    });
  } else {
    writeConversationCandidateRegistry(student, merged.registry);
  }
  statusCounts.duplicate = merged.duplicates.length;
  for (const duplicate of merged.duplicates) {
    const incoming = built.candidates.find((candidate) => candidate.id === duplicate.candidateId);
    if (incoming?.status === 'organized') statusCounts.organized = Math.max(0, statusCounts.organized - 1);
    else if (incoming?.status === 'watching') statusCounts.watching = Math.max(0, statusCounts.watching - 1);
    else if (incoming) statusCounts.attention = Math.max(0, statusCounts.attention - 1);
  }
  return statusCounts;
}

function persistAgentConversationSubmission(input, options = {}) {
  const submission = normalizeAgentConversationSubmission(input);
  const store = readAgentConversationSubmissionStore();
  const existing = store.submissions[submission.idempotencyKey];
  const target = resolveAgentConversationTarget(submission);
  if (existing && !['awaiting_attribution', 'deleted'].includes(existing.status)
    && target.status === 'resolved') {
    if (String(existing.receipt?.studentId || '') !== String(target.student.id)
      || String(existing.receipt?.projectId || '') !== String(target.project?.id || '')) {
      throw Object.assign(new Error('对话幂等键的学生或项目归属与既有回执不符。'),
        { code: 'idempotency_scope_conflict' });
    }
    const requiredVersion = target.project ? (isWorkspaceMaterialProject(target.project) ? 3 : 2) : 1;
    if (Number(existing.materializationVersion || 0) >= requiredVersion) {
      return { ok: true, deduplicated: true, submission, receipt: existing.receipt,
        message: '相同对话片段已经保存，本次未生成重复记录。' };
    }
  }
  if (target.status !== 'resolved') {
    fs.mkdirSync(agentConversationPendingDir(), { recursive: true });
    const pendingPath = path.join(agentConversationPendingDir(), `${submission.submissionId}.json`);
    if (!fs.existsSync(pendingPath)) writeJsonAtomic(pendingPath, submission);
    const receipt = conversationSubmissionReceipt(submission, {
      status: 'awaiting_attribution',
      message: target.message || '暂时无法唯一确定学生或项目，已进入待归属入口，未写入任何学生档案。',
    });
    store.submissions[submission.idempotencyKey] = {
      submissionId: submission.submissionId,
      idempotencyKey: submission.idempotencyKey,
      status: 'awaiting_attribution',
      pendingPath,
      receipt,
      receivedAt: new Date().toISOString(),
    };
    writeAgentConversationSubmissionStore(store);
    return { ok: true, awaitingAttribution: true, submission, receipt, message: receipt.message };
  }
  const imported = target.project
    ? saveAgentProjectConversationImport(
      target.student,
      target.project,
      conversationSubmissionContent(submission),
      isKnownAgentSource(submission.sourceAgent) ? submission.sourceAgent : (target.student.agentTool || 'workbuddy'),
      options.sourcePath || '',
    )
    : parseJsonObject(saveAgentConversationImport(
      target.student.id,
      conversationSubmissionContent(submission),
      isKnownAgentSource(submission.sourceAgent) ? submission.sourceAgent : (target.student.agentTool || 'workbuddy'),
      options.sourcePath || '',
      { lifecycleCapture: options.lifecycleCapture === true, sessionId: submission.sessionId },
    ));
  const finishImported = (saved) => {
  if (!saved.ok) throw new Error(saved.message || '保存不可变对话资产失败。');
  const counts = organizeConversationSubmissionCandidates(target.student, target.project, submission, saved);
  const receipt = conversationSubmissionReceipt(submission, {
    status: saved.deduplicated ? 'deduplicated' : 'stored',
    scopeType: target.project ? 'project' : 'student',
    scopeId: target.project?.id || target.student.id,
    studentId: target.student.id,
    projectId: target.project?.id || '',
    interactionId: saved.interaction?.id,
    assetId: saved.asset?.id,
    materialId: saved.materialId || '',
    ...counts,
    message: target.project
      ? (counts.attention
        ? `对话已保存到项目“${target.project.name}”${isWorkspaceMaterialProject(target.project) ? '工作空间' : '原始资料库'}；自动整理 ${counts.organized + counts.watching} 条，${counts.attention} 条异常候选需要处理。`
        : `对话已保存到项目“${target.project.name}”${isWorkspaceMaterialProject(target.project) ? '工作空间' : '原始资料库'}，并自动整理 ${counts.organized + counts.watching} 条候选。`)
      : (counts.attention
        ? `对话已保存到学生对话历史；自动整理 ${counts.organized + counts.watching} 条，${counts.attention} 条异常候选需要处理。`
        : `对话已保存到学生对话历史，并自动整理 ${counts.organized + counts.watching} 条候选。`),
  });
  if (existing?.pendingPath && fs.existsSync(existing.pendingPath)) {
    try { fs.unlinkSync(existing.pendingPath); } catch { /* Pending cleanup must not block the import. */ }
  }
  const latestStore = readAgentConversationSubmissionStore();
  latestStore.submissions[submission.idempotencyKey] = {
    submissionId: submission.submissionId,
    idempotencyKey: submission.idempotencyKey,
    status: receipt.status,
    materializationVersion: target.project ? (isWorkspaceMaterialProject(target.project) ? 3 : 2) : 1,
    receipt,
    receivedAt: existing?.receivedAt || new Date().toISOString(),
    storedAt: receipt.storedAt,
  };
  writeAgentConversationSubmissionStore(latestStore);
  return { ok: true, submission, receipt, imported: saved, message: receipt.message };
  };
  return imported && typeof imported.then === 'function' ? imported.then(finishImported) : finishImported(imported);
}

function agentConversationSubmissionState() {
  try {
    const store = readAgentConversationSubmissionStore();
    const records = Object.values(store.submissions || {});
    return JSON.stringify({
      ok: true,
      schema: store.schema,
      summary: {
        total: records.length,
        awaitingAttribution: records.filter((item) => item.status === 'awaiting_attribution').length,
        stored: records.filter((item) => ['stored', 'deduplicated'].includes(item.status)).length,
      },
      pending: records.filter((item) => item.status === 'awaiting_attribution').map((item) => {
        const submission = item.pendingPath && fs.existsSync(item.pendingPath)
          ? safeReadJson(item.pendingPath, {})
          : {};
        return {
          submissionId: item.submissionId,
          title: String(submission.title || 'Agent 对话片段').slice(0, 240),
          sourceAgent: String(submission.sourceAgent || 'Agent').slice(0, 120),
          messageCount: Array.isArray(submission.messages) ? submission.messages.length : 0,
          receivedAt: item.receivedAt,
          receipt: item.receipt,
        };
      }),
    });
  } catch (error) {
    return JSON.stringify({ ok: false, pending: [], message: `读取对话收件箱失败：${error.message}` });
  }
}

async function assignAgentConversationSubmission(submissionId, scopeType, scopeId) {
  try {
    const store = readAgentConversationSubmissionStore();
    const record = Object.values(store.submissions || {}).find((item) => (
      item.status === 'awaiting_attribution' && item.submissionId === String(submissionId || '')
    ));
    if (!record?.pendingPath || !fs.existsSync(record.pendingPath)) return JSON.stringify({ ok: false, message: '未找到待归属对话。' });
    const submission = safeReadJson(record.pendingPath, null);
    if (!submission) return JSON.stringify({ ok: false, message: '待归属对话文件不可读取。' });
    const attributed = applyManualConversationAttribution(submission, scopeType, scopeId);
    const result = await persistAgentConversationSubmission(attributed);
    return JSON.stringify(result);
  } catch (error) {
    return JSON.stringify({ ok: false, message: `归属对话失败：${error.message}` });
  }
}

function selectAgentConversationFiles(studentId, tool = 'workbuddy') {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const safeTool = isKnownAgentSource(tool) ? tool : 'workbuddy';
    const result = dialog.showOpenDialogSync(mainWindow, {
      title: '选择对话历史文件',
      properties: ['openFile', 'multiSelections'],
      filters: [
        { name: '对话历史文件', extensions: ['md', 'txt', 'json'] },
        { name: '所有文件', extensions: ['*'] },
      ],
    });
    if (!result || result.length === 0) {
      return JSON.stringify({ ok: false, cancelled: true, message: '未选择对话历史文件。' });
    }
    const imports = [];
    const combinedParts = [];
    for (const filePath of result) {
      try {
        const stat = fs.statSync(filePath);
        if (!stat.isFile()) continue;
        if (stat.size > 5 * 1024 * 1024) {
          imports.push({ ok: false, sourcePath: filePath, message: '文件超过 5MB，已跳过。' });
          continue;
        }
        const content = fs.readFileSync(filePath, 'utf8');
        const imported = JSON.parse(saveAgentConversationImport(student.id, content, safeTool, filePath));
        imports.push({ ...imported, sourcePath: filePath, size: stat.size });
        if (imported.ok) {
          combinedParts.push(`\n\n# 来源文件：${path.basename(filePath)}\n\n${content}`);
        }
      } catch (error) {
        imports.push({ ok: false, sourcePath: filePath, message: error.message });
      }
    }
    const successCount = imports.filter((item) => item.ok).length;
    return JSON.stringify({
      ok: successCount > 0,
      imports,
      combinedContent: combinedParts.join('\n\n---\n'),
      message: successCount > 0
        ? `已导入 ${successCount} 个对话历史文件。`
        : '没有可导入的对话历史文件。',
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `选择对话历史文件失败：${error.message}` });
  }
}

function appendTextSection(file, title, content, fileIo = fs) {
  fileIo.mkdirSync(path.dirname(file), { recursive: true });
  const section = `\n\n## ${title}\n\n${String(content || '').trim()}\n`;
  fileIo.appendFileSync(file, section, 'utf8');
}

function saveConversationExtract(studentId, extractJson, tool = 'workbuddy') {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const safeTool = isKnownAgentSource(tool) ? tool : 'workbuddy';
    let parsed = {};
    try {
      parsed = JSON.parse(extractJsonLikeText(extractJson || '{}'));
    } catch {
      return JSON.stringify({ ok: false, message: '提取结果不是有效 JSON。请确认只粘贴 JSON，或包含 JSON 的代码块。' });
    }
    const index = readJsonFile(conversationIndexPath(student), { version: 2, imports: [], extracts: [] });
    const latestImport = Array.isArray(index.imports) ? index.imports[0] : null;
    if (!latestImport?.assetId) return JSON.stringify({ ok: false, message: '请先保存对话导入记录，再提交 AI 提取候选。' });
    const asset = readJsonFile(path.join(conversationAssetsDir(student), `${latestImport.assetId}.json`), null);
    const interaction = readJsonFile(path.join(conversationInteractionsDir(student), `${latestImport.interactionId}.json`), null);
    if (!asset || !interaction || !asset.storedPath || !fs.existsSync(asset.storedPath)) {
      return JSON.stringify({ ok: false, message: '原始对话资产不完整，无法建立可追溯候选。' });
    }
    const sourceContent = readSmallTextFile(asset.storedPath, 5 * 1024 * 1024);
    const built = buildKnowledgeCandidates(parsed, {
      studentId: student.id,
      tool: safeTool,
      source: { ...asset, assetId: asset.id, interactionId: interaction.id, validMessageIds: (interaction.messages || []).map((item) => item.id) },
      sourceContent,
    });
    if (!built.candidates.length) return JSON.stringify({ ok: false, message: '提取结果中没有有效的逐条知识候选。' });
    const currentRegistry = readConversationCandidateRegistry(student);
    const merged = mergeCandidateRegistry(currentRegistry, built.candidates);
    writeConversationCandidateRegistry(student, merged.registry);
    fs.mkdirSync(agentConversationExtractsDir(student), { recursive: true });
    const extractId = stableGovernanceId('conversation-extract', student.id, asset.id, sha256Text(JSON.stringify(parsed)));
    const extractFile = path.join(agentConversationExtractsDir(student), `${extractId}.json`);
    if (!fs.existsSync(extractFile)) writeJsonFile(extractFile, { schema: 'edu-manager.conversation-extract.v2', id: extractId, studentId: String(student.id), interactionId: interaction.id, assetId: asset.id, tool: safeTool, parsed, candidateIds: built.candidates.map((item) => item.id), createdAt: new Date().toISOString() });
    refreshConversationIndex(student, {
      type: 'extract',
      id: extractId,
      path: extractFile,
      tool: safeTool,
      importedAt: new Date().toISOString(),
      hash: sha256Text(JSON.stringify(parsed)),
      interactionId: interaction.id,
      assetId: asset.id,
      memoryCount: built.candidates.filter((item) => item.target === 'memory').length,
      soulCount: built.candidates.filter((item) => item.target === 'soul').length,
      qaCount: built.candidates.filter((item) => item.target === 'qa').length,
      todoCount: built.candidates.filter((item) => item.target === 'todo').length,
      candidateCount: built.candidates.length,
    });
    appendAgentSourceRecord(student, {
      assetType: 'extract',
      tool: safeTool,
      sourceType: 'conversationExtract',
      sourcePath: asset.storedPath,
      targetPath: extractFile,
      hash: sha256Text(JSON.stringify(parsed)),
      confidence: 80,
      confirmed: false,
      notes: `对话提取仅生成候选：新增 ${merged.added.length} 条，重复 ${merged.duplicates.length} 条`,
    });
    return JSON.stringify({ ok: true, path: extractFile, added: merged.added.length, duplicates: merged.duplicates.length, candidates: merged.added, governance: conversationGovernanceState(student), message: `已生成 ${merged.added.length} 条逐条候选，跳过 ${merged.duplicates.length} 条重复内容；未写入正式长期知识。` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `保存对话提取失败：${error.message}` });
  }
}

function updateConversationKnowledgeCandidate(studentId, candidateId, action, payloadJson = '{}') {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const payload = parseJsonObject(payloadJson || '{}');
    const registry = readConversationCandidateRegistry(student);
    const candidates = Array.isArray(registry.candidates) ? registry.candidates : [];
    const index = candidates.findIndex((item) => String(item.id) === String(candidateId));
    if (index < 0) return JSON.stringify({ ok: false, message: '未找到知识候选。' });
    if (action === 'merge') {
      const targetIndex = candidates.findIndex((item) => String(item.id) === String(payload.targetId));
      if (targetIndex < 0 || targetIndex === index) return JSON.stringify({ ok: false, message: '请选择另一条有效候选作为合并目标。' });
      const sourceCandidate = candidates[index];
      const targetCandidate = candidates[targetIndex];
      if (sourceCandidate.target !== targetCandidate.target) return JSON.stringify({ ok: false, message: '只有相同知识类型的候选可以合并。' });
      const mergedContent = String(payload.content || `${targetCandidate.content}\n${sourceCandidate.content}`).trim();
      const editedTarget = reassessConversationCandidate(student, updateCandidate(targetCandidate, 'edit', { content: mergedContent, note: `合并候选 ${sourceCandidate.id}` }, new Date().toISOString(), candidateSourceContent(student, targetCandidate)));
      editedTarget.mergedFrom = Array.from(new Set([...(targetCandidate.mergedFrom || []), sourceCandidate.id]));
      candidates[targetIndex] = editedTarget;
      candidates[index] = reassessConversationCandidate(student, updateCandidate(sourceCandidate, 'merge', { targetId: targetCandidate.id, note: String(payload.note || '') }, new Date().toISOString(), candidateSourceContent(student, sourceCandidate)));
    } else {
      candidates[index] = reassessConversationCandidate(student, updateCandidate(candidates[index], action, payload, new Date().toISOString(), candidateSourceContent(student, candidates[index])));
    }
    writeConversationCandidateRegistry(student, { ...registry, candidates });
    return JSON.stringify({ ok: true, candidate: candidates[index], governance: conversationGovernanceState(student), message: '候选状态已更新并保留历史。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `更新知识候选失败：${error.message}` });
  }
}

function conversationPromotionTarget(student, candidate) {
  ensureAgentCenter(student);
  if (candidate.target === 'memory') return agentMemoryUnifiedPath(student);
  if (candidate.target === 'soul') return agentSoulUnifiedPath(student);
  if (candidate.target === 'qa') return path.join(student.summaryPath || getSummaryDir(student.name), '咨询精华库', '对话候选晋升.md');
  return path.join(student.outputPath || path.join(student.rootPath || getStudentRootDir(student.name), '输出结果'), '待办.md');
}

function promoteConversationKnowledgeCandidates(studentId, requestJson = '{}') {
  let appliedTransaction = null;
  let student = null;
  let originalRegistry = null;
  let transactionPath = '';
  try {
    student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const request = parseJsonObject(requestJson || '{}');
    const ids = Array.isArray(request.candidateIds) ? request.candidateIds.map(String) : [];
    if (!ids.length) return JSON.stringify({ ok: false, message: '请至少选择一条待晋升候选。' });
    if (ids.length > MAX_PROMOTION_BATCH) return JSON.stringify({ ok: false, message: `单次最多晋升 ${MAX_PROMOTION_BATCH} 条候选。` });
    const selectedIds = new Set(ids);
    originalRegistry = readConversationCandidateRegistry(student);
    const candidates = (originalRegistry.candidates || []).filter((item) => selectedIds.has(String(item.id)));
    if (candidates.length !== selectedIds.size) return JSON.stringify({ ok: false, message: '部分候选不存在，请刷新后重试。' });
    const blocked = candidates.map((candidate) => ({ candidate, check: canPromoteCandidate(candidate) })).filter((item) => !item.check.ok);
    if (blocked.length) return JSON.stringify({ ok: false, blocked: blocked.map((item) => ({ id: item.candidate.id, reason: item.check.reason })), message: `有 ${blocked.length} 条候选缺少证据、存在冲突或尚未确认风险，本次未写入任何正式知识。` });
    const promotedAt = new Date().toISOString();
    const transactionId = `knowledge-promotion-${promotedAt.replace(/[-:.TZ]/g, '').slice(0, 14)}-${crypto.randomBytes(4).toString('hex')}`;
    transactionPath = path.join(conversationTransactionsDir(student), `${transactionId}.json`);
    fs.mkdirSync(conversationTransactionsDir(student), { recursive: true });
    writeJsonFile(transactionPath, { schema: 'edu-manager.knowledge-promotion-transaction.v1', id: transactionId, studentId: String(student.id), status: 'preparing', promotedAt, candidateIds: candidates.map((item) => item.id), operations: [] });
    appliedTransaction = applyPromotionTransaction({
      transactionId,
      studentId: student.id,
      candidates,
      resolveTarget: (candidate) => conversationPromotionTarget(student, candidate),
      promotedAt,
      onProgress: (transaction) => writeJsonFile(transactionPath, transaction),
    });
    const nextCandidates = (originalRegistry.candidates || []).map((candidate) => {
      if (!selectedIds.has(String(candidate.id))) return candidate;
      return {
        ...candidate,
        status: 'promoted',
        promotionTransactionId: transactionId,
        promotedAt,
        updatedAt: promotedAt,
        history: [...(candidate.history || []), { action: 'promote', from: candidate.status, to: 'promoted', at: promotedAt, actorRole: 'administrator', actorId: 'local-user', transactionId }],
      };
    });
    writeConversationCandidateRegistry(student, { ...originalRegistry, candidates: nextCandidates });
    writeJsonFile(transactionPath, appliedTransaction);
    appendHostTimeline({ type: 'conversation_knowledge_promoted', title: 'Conversation knowledge promoted', detail: `${student.name} ${transactionId}`, studentId: String(student.id), studentName: student.name, count: candidates.length });
    scheduleStudentArchiveSync(student.id);
    return JSON.stringify({ ok: true, transaction: appliedTransaction, governance: conversationGovernanceState(student), message: `已通过一个可撤销事务晋升 ${candidates.length} 条知识候选。` });
  } catch (error) {
    if (appliedTransaction) {
      try { rollbackPromotionTransaction(appliedTransaction); } catch { /* transaction file remains for recovery */ }
    }
    if (student && originalRegistry) {
      try { writeConversationCandidateRegistry(student, originalRegistry); } catch { /* recovery metadata remains */ }
    }
    if (transactionPath) {
      try {
        const current = readJsonFile(transactionPath, {});
        writeJsonFile(transactionPath, { ...current, status: 'failed_rolled_back', failedAt: new Date().toISOString(), error: error.message });
      } catch { /* preserve the last recoverable journal */ }
    }
    return JSON.stringify({ ok: false, message: `知识候选晋升失败，已尝试回滚：${error.message}` });
  }
}

function rollbackConversationPromotion(studentId, transactionId) {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const transactionPath = path.join(conversationTransactionsDir(student), `${path.basename(String(transactionId || ''))}.json`);
    const transaction = readJsonFile(transactionPath, null);
    if (!transaction) return JSON.stringify({ ok: false, message: '未找到晋升事务。' });
    const registry = readConversationCandidateRegistry(student);
    const originalRegistry = JSON.parse(JSON.stringify(registry));
    const reversed = rollbackPromotionTransaction(transaction);
    const reversedAt = reversed.reversedAt;
    registry.candidates = (registry.candidates || []).map((candidate) => candidate.promotionTransactionId === transaction.id
      ? { ...candidate, status: 'revoked', revokedAt: reversedAt, updatedAt: reversedAt, history: [...(candidate.history || []), { action: 'revoke', from: 'promoted', to: 'revoked', at: reversedAt, actorRole: 'administrator', actorId: 'local-user', transactionId: transaction.id }] }
      : candidate);
    try {
      writeConversationCandidateRegistry(student, registry);
      writeJsonFile(transactionPath, reversed);
    } catch (error) {
      reapplyPromotionTransaction(transaction);
      writeConversationCandidateRegistry(student, originalRegistry);
      throw error;
    }
    appendHostTimeline({ type: 'conversation_knowledge_reversed', title: 'Conversation knowledge reversed', detail: `${student.name} ${transaction.id}`, studentId: String(student.id), studentName: student.name, count: transaction.candidateIds?.length || 0 });
    scheduleStudentArchiveSync(student.id);
    return JSON.stringify({ ok: true, transaction: reversed, governance: conversationGovernanceState(student), message: `已撤销事务，正式文件和候选索引同步恢复；原始对话保持不变。` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `撤销知识晋升失败：${error.message}` });
  }
}

function ingestKnowledgeCandidateEnvelope(studentId, envelopeJson = '{}') {
  try {
    const student = findStudentByKey(studentId);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const envelope = parseJsonObject(envelopeJson || '{}');
    const allowedSourceTypes = new Set(['conversation', 'screenshot', 'web', 'agent_result', 'manual']);
    const sourceType = String(envelope.source?.type || envelope.sourceType || 'agent_result');
    if (!allowedSourceTypes.has(sourceType)) return JSON.stringify({ ok: false, message: '不支持的候选来源类型。' });
    const sourceContent = String(envelope.sourceContent || '');
    const sourceUri = String(envelope.source?.sourceUri || envelope.sourceUri || '').trim();
    const contentHash = String(envelope.source?.contentHash || envelope.contentHash || (sourceContent ? sha256Text(sourceContent) : '')).trim();
    if (!sourceUri || !contentHash) return JSON.stringify({ ok: false, message: '多源候选必须提供稳定来源 URI 和内容哈希。' });
    const sourceId = String(envelope.source?.sourceId || stableGovernanceId(`${sourceType}-asset`, student.id, sourceUri, contentHash));
    const source = { ...(envelope.source || {}), type: sourceType, sourceType, sourceId, assetId: sourceId, sourceUri, contentHash };
    const built = buildKnowledgeCandidates(envelope, { studentId: student.id, tool: envelope.tool || 'workbuddy', source, sourceContent });
    if (!built.candidates.length) return JSON.stringify({ ok: false, message: '没有可登记的逐条候选。' });
    fs.mkdirSync(conversationAssetsDir(student), { recursive: true });
    const assetPath = path.join(conversationAssetsDir(student), `${sourceId}.json`);
    if (!fs.existsSync(assetPath)) writeJsonFile(assetPath, { schema: 'edu-manager.multi-source-asset.v1', id: sourceId, studentId: String(student.id), ...source, immutable: true, registeredAt: new Date().toISOString() });
    const merged = mergeCandidateRegistry(readConversationCandidateRegistry(student), built.candidates);
    writeConversationCandidateRegistry(student, merged.registry);
    return JSON.stringify({ ok: true, added: merged.added.length, duplicates: merged.duplicates.length, governance: conversationGovernanceState(student), message: `已将 ${sourceType} 来源登记为 ${merged.added.length} 条统一知识候选。` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `登记多源知识候选失败：${error.message}` });
  }
}

function readStudentsIndex() {
  try {
    const parsed = JSON.parse(fs.readFileSync(studentsPath(), 'utf8'));
    const input = Array.isArray(parsed) ? parsed : [];
    const ensured = ensureStudentLoginIds(input);
    if (ensured.changed) writeStudentsIndex(ensured.students);
    return ensured.students;
  } catch {
    return [];
  }
}

function getStudentsIndex() {
  return JSON.stringify({ ok: true, students: readStudentsIndex() });
}

function writeStudentsIndex(students) {
  const operation = writeJsonAtomic(studentsPath(), students);
  taskCenterSnapshotCache = { at: 0, value: '' };
  return operation;
}

function findStudentByKey(studentKey) {
  const key = String(studentKey || '');
  const cleanName = sanitizeName(key);
  return readStudentsIndex().find((student) => String(student.id) === key || student.name === cleanName) || null;
}

function toHostStudent(student) {
  const cleanName = sanitizeName(student.name);
  const createdAt = student.createdAt || new Date().toISOString();
  const channel = String(student.remoteChannel || 'none').toLowerCase();
  const remoteChannel = ['none', 'wecom', 'qq', 'both'].includes(channel) ? channel : 'none';
  const bindingStatus = String(student.remoteBindingStatus || 'unbound').toLowerCase();
  const remoteBindingStatus = ['unbound', 'pending', 'bound'].includes(bindingStatus) ? bindingStatus : 'unbound';
  const tool = String(student.agentTool || 'workbuddy').toLowerCase();
  const agentTool = isKnownAgentSource(tool) ? tool : 'workbuddy';
  const mode = String(student.knowledgeBaseMode || 'standard').toLowerCase() === 'adopted' ? 'adopted' : 'standard';
  const rootPath = student.rootPath || getStudentRootDir(cleanName);
  const rawPath = student.rawPath || getRawDir(cleanName);
  const summaryPath = student.summaryPath || getSummaryDir(cleanName);
  const agentPath = student.agentPath || path.join(rootPath, 'AGENT.md');
  const outputPath = student.outputPath || path.join(rootPath, '输出结果');
  const bindingMode = String(student.agentBindingMode || (agentTool === 'marvis' ? 'mainChat' : 'subAgent'));
  const memoryDir = path.join(rootPath, 'Agent记忆');
  const soulDir = path.join(rootPath, 'Agent设定');
  const memoryConfig = student.memoryConfig && typeof student.memoryConfig === 'object' ? student.memoryConfig : {};
  const soulConfig = student.soulConfig && typeof student.soulConfig === 'object' ? student.soulConfig : {};
  const templateProfile = student.templateProfile && typeof student.templateProfile === 'object' ? student.templateProfile : {};
  return {
    ...student,
    id: String(student.id || `${cleanName}-${Date.now()}`),
    loginId: String(student.loginId || ''),
    loginIdVersion: Number(student.loginIdVersion || 1),
    loginIdIssuedAt: String(student.loginIdIssuedAt || ''),
    name: cleanName,
    grade: String(student.grade || ''),
    school: String(student.school || ''),
    phone: String(student.phone || ''),
    email: String(student.email || ''),
    goal: String(student.goal || ''),
    ...(student.languageProfile == null ? {} : { languageProfile: checkedLanguageProfile(student.languageProfile) }),
    birthDate: /^\d{4}-\d{2}-\d{2}$/.test(String(student.birthDate || '')) ? String(student.birthDate) : '',
    manualAgeBand: String(student.manualAgeBand || ''),
    currentRegion: String(student.currentRegion || ''),
    targetRegions: Array.isArray(student.targetRegions) ? [...new Set(student.targetRegions.map((item) => String(item || '').trim()).filter(Boolean))].slice(0, 12) : [],
    planningRoutes: Array.isArray(student.planningRoutes) ? [...new Set(student.planningRoutes.map(String).filter((item) => ['domestic', 'hongkong_macau', 'international'].includes(item)))].slice(0, 3) : [],
    targetStage: String(student.targetStage || ''),
    planningPreferences: Array.isArray(student.planningPreferences) ? [...new Set(student.planningPreferences.map((item) => String(item || '').trim()).filter(Boolean))].slice(0, 20) : [],
    interests: Array.isArray(student.interests) ? [...new Set(student.interests.map((item) => String(item || '').trim()).filter(Boolean))].slice(0, 20) : [],
    subjectStrengths: Array.isArray(student.subjectStrengths) ? [...new Set(student.subjectStrengths.map((item) => String(item || '').trim()).filter(Boolean))].slice(0, 20) : [],
    careerDirections: Array.isArray(student.careerDirections) ? [...new Set(student.careerDirections.map((item) => String(item || '').trim()).filter(Boolean))].slice(0, 20) : [],
    digestTime: String(student.digestTime || '21:30'),
    activityStatus: studentActivity(student),
    pauseAutomaticTasksWhenInactive: student.pauseAutomaticTasksWhenInactive !== false,
    agentTool,
    agentToolLegacy: !isActiveAgentTool(agentTool),
    classificationFallback: student.classificationFallback || { enabled: false, version: 0 },
    agentBindingMode: ['subAgent', 'mainChat'].includes(bindingMode) ? bindingMode : 'subAgent',
    agentName: String(student.agentName || ''),
    agentNote: String(student.agentNote || ''),
    knowledgeBaseMode: mode,
    rootPath,
    rawPath,
    summaryPath,
    agentPath,
    outputPath,
    memoryConfig: {
      unifiedMemoryPath: memoryConfig.unifiedMemoryPath || path.join(memoryDir, 'UnifiedMemory.md'),
      lastMergedAt: memoryConfig.lastMergedAt || '',
      sources: Array.isArray(memoryConfig.sources) ? memoryConfig.sources : [],
    },
    soulConfig: {
      unifiedSoulPath: soulConfig.unifiedSoulPath || path.join(soulDir, 'UnifiedSoul.md'),
      lastDistributedAt: soulConfig.lastDistributedAt || '',
      sources: Array.isArray(soulConfig.sources) ? soulConfig.sources : [],
    },
    templateProfile: {
      activeTemplate: templateProfile.activeTemplate === 'custom' ? 'custom' : 'system',
      customTemplatePath: templateProfile.customTemplatePath || '',
    },
    materialSources: normalizeMaterialSources(student.materialSources),
    adoptedAt: String(student.adoptedAt || ''),
    remoteChannel,
    remoteContact: String(student.remoteContact || ''),
    remoteNote: String(student.remoteNote || ''),
    remoteBindingStatus,
    remoteBoundAt: String(student.remoteBoundAt || ''),
    createdAt,
  };
}

function ensureLocalStudentFromCloudProfile(envelope) {
  const students = readStudentsIndex();
  const plan = planCloudStudentBinding({ students, envelope, sanitizeName });
  const { cloudStudentId, profileRevisionId, profile, cleanName } = plan;
  if (plan.action === 'conflict') {
    if (plan.reason === 'same_name_different_identity') {
      throw new Error(`本机已有同名学生“${cleanName}”，但没有相同云端学生标识；为避免误合并，请在云端同步设置中选择现有档案或创建新档案`);
    }
    throw new Error('检测到多份本机档案绑定同一云端学生，请先在学生管理中处理');
  }
  const applyProfile = (student) => toHostStudent({
    ...student,
    name: cleanName,
    grade: profile.grade ?? student.grade,
    school: profile.school ?? student.school,
    goal: profile.learningGoal ?? student.goal,
    currentRegion: profile.currentRegion ?? student.currentRegion,
    phone: profile.phone ?? student.phone,
    email: profile.email ?? student.email,
    birthDate: profile.birthday ?? student.birthDate,
    address: profile.address ?? student.address,
    guardian: profile.guardian ?? student.guardian,
    cloudIdentity: {
      cloudStudentId, profileRevisionId, source: 'authorized_cloud_profile',
      authorizedFields: Array.isArray(envelope.fields) ? [...envelope.fields] : Object.keys(profile),
      syncedAt: new Date().toISOString(),
    },
  });
  if (plan.action === 'update') {
    const updated = applyProfile(plan.student);
    writeStudentsIndex(students.map(student => String(student.id) === String(updated.id) ? updated : student));
    return { localStudentId: String(updated.id), status: 'updated', profileRevisionId };
  }
  assertCanAddStudent('云端授权自动建档');
  const initialized = JSON.parse(initStudentWorkspace(cleanName,
    `# ${cleanName} AI教育管家\n\n本档案由已授权的云端学生基础信息自动建立。\n`,
    `# ${cleanName} 学情分析汇总\n`, `# ${cleanName} 知识更新日志\n`));
  if (!initialized.ok) throw new Error(initialized.message || '本机学生工作区创建失败');
  const localStudentId = plan.localStudentId;
  if (students.some(student => String(student.id) === localStudentId)) throw new Error('本机学生标识冲突，请人工核对');
  const created = applyProfile({
    id: localStudentId, name: cleanName, createdAt: new Date().toISOString(), status: 'ready',
    schemaVersion: 1, storageMode: 'app_private', knowledgeBaseMode: 'standard',
    rootPath: initialized.rootPath, rawPath: initialized.rawPath, summaryPath: initialized.summaryPath,
    agentPath: initialized.agentPath, outputPath: initialized.outputPath,
    agentTool: 'workbuddy', agentBindingMode: 'subAgent', agentName: `${cleanName} AI教育管家`,
  });
  assertStudentCapacity([created, ...students], students, '云端授权自动建档');
  writeStudentsIndex([created, ...students]);
  appendHostTimeline({ type: 'cloud_student_profile_created', title: '已按云端授权建立学生档案',
    detail: profileRevisionId, studentId: localStudentId, studentName: cleanName });
  return { localStudentId, status: 'created', profileRevisionId };
}

function syncStudentsIndex(studentsJson) {
  try {
    const parsed = JSON.parse(studentsJson || '[]');
    if (!Array.isArray(parsed)) throw new Error('学生数据格式不是数组');
    const currentStudents = readStudentsIndex();
    const existingById = new Map(currentStudents.map((student) => [String(student.id), student]));
    const merged = parsed.map((student) => {
      const existing = existingById.get(String(student.id));
      return toHostStudent({
        ...student,
        classificationFallback: existing?.classificationFallback || { enabled: false, version: 0 },
        languageProfile: Object.hasOwn(student, 'languageProfile') ? student.languageProfile : existing?.languageProfile,
        activityStatus: Object.hasOwn(student, 'activityStatus') ? student.activityStatus : studentActivity(existing || student),
        pauseAutomaticTasksWhenInactive: Object.hasOwn(student, 'pauseAutomaticTasksWhenInactive') ? student.pauseAutomaticTasksWhenInactive : existing?.pauseAutomaticTasksWhenInactive,
        createdAt: student.createdAt || existing?.createdAt || '',
        loginId: student.loginId || existing?.loginId || '',
        loginIdVersion: student.loginIdVersion || existing?.loginIdVersion || 1,
        loginIdIssuedAt: student.loginIdIssuedAt || existing?.loginIdIssuedAt || '',
      });
    });
    const ensured = ensureStudentLoginIds(merged);
    const students = ensured.students;
    assertStudentCapacity(students, currentStudents, '同步学生档案');
    const nextById = new Map(students.map((student) => [String(student.id), student]));
    const becomingBlocked = currentStudents.filter((student) => !studentConversationCaptureBlocked(student)
      && studentConversationCaptureBlocked(nextById.get(String(student.id))));
    const becomingActive = students.filter((student) => !studentConversationCaptureBlocked(student)
      && studentConversationCaptureBlocked(existingById.get(String(student.id))));
    const activeDescriptor = safeReadJson(activeAgentKnowledgeDescriptorPath(), {});
    const originalCaptureStudentId = String(activeDescriptor?.defaults?.scopeId || '');
    if (becomingBlocked.length) drainAgentLifecycleQueue();
    for (const student of becomingBlocked) {
      finalizeActiveLifecycleSessionsForStudent(student, 'student-inactive');
      setLifecycleDescriptorEnabled(student, false);
      notify('onNativeAgentMemoryChanged', JSON.stringify({ studentId: String(student.id), reason: 'student_inactive' }));
    }
    const writeOperation = !isDeepStrictEqual(students, currentStudents) ? writeStudentsIndex(students) : Promise.resolve();
    void Promise.resolve(writeOperation).then(async () => {
      const global = agentControlStore().read().global;
      for (const student of becomingActive) {
        if (!global?.enabled || originalCaptureStudentId !== String(student.id)) continue;
        const currentDescriptor = safeReadJson(activeAgentKnowledgeDescriptorPath(), {});
        if (String(currentDescriptor?.defaults?.scopeId || '') !== String(student.id)) continue;
        const prepared = parseJsonObject(prepareAgentKnowledgeAccess(student.id, { activateGlobal: true, captureEnabled: true }));
        if (prepared.ok) notify('onNativeAgentMemoryChanged', JSON.stringify({ studentId: String(student.id), reason: 'student_reactivated' }));
      }
      const engine = await getSmartInbox();
      await engine.syncConversationRouting(capturedConversationRoutingPolicy(global), students.filter(student => !studentConversationCaptureBlocked(student)));
      await engine.tick();
    }).catch(error => console.warn('学生状态变更后的会话路由恢复未完成：', error.message));
    const validIds = new Set(students.map((student) => String(student.id)));
    const migrated = migrateTerminalDevices(readDevices(), Array.from(validIds));
    if (migrated.changed) writeDevices(migrated.devices);
    return JSON.stringify({ ok: true, count: students.length });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `同步学生索引失败：${error.message}` });
  }
}

let planningGuidanceServiceInstance = null;

function planningEvidenceSummary(student) {
  const sourceIds = [];
  const confirmedGrowthSignals = [];
  try {
    const file = growthIndexPath(toHostStudent(student));
    const index = fs.existsSync(file) ? safeReadJson(file, {}) : {};
    const accessible = new Set(reportEligibleEvidence(student).items.filter(item => item.status === 'confirmed').map(item => item.id));
    for (const evidence of Array.isArray(index.evidence) ? index.evidence : []) {
      if (evidence.status !== 'confirmed' || !accessible.has(String(evidence.id))) continue;
      confirmedGrowthSignals.push(redactStudentGeneration(`${evidence.ability || ''}：${evidence.observation || evidence.content || evidence.title || ''}`.slice(0, 500), student));
      sourceIds.push(`growth:${student.id}:${evidence.id}`);
      if (confirmedGrowthSignals.length >= 20) break;
    }
  } catch {}
  const reportIds = [];
  const learningSignals = [];
  try {
    const reportDir = learningReportDirForStudent(student);
    if (fs.existsSync(reportDir)) {
      for (const definition of LEARNING_REPORTS) {
        const file = path.join(reportDir, definition.fileName);
        if (!fs.existsSync(file) || fs.statSync(file).size > 512 * 1024) continue;
        const content = fs.readFileSync(file, 'utf8');
        if (!['active', 'published', 'current', 'updated'].includes(frontmatterValue(content, 'status')) ||
            frontmatterValue(content, 'student_id') !== String(student.id)) continue;
        reportIds.push(definition.fileName);
        learningSignals.push(redactStudentGeneration(content.replace(/^---[\s\S]*?---\s*/, '').replace(/!\[[^\]]*\]\([^)]*\)/g, '').slice(0, 1200), student));
      }
    }
  } catch {}
  reportIds.forEach((reportId) => sourceIds.push(`report:${student.id}:${reportId}`));
  return {
    sourceIds,
    reportIds,
    confirmedGrowthSignals,
    learningSignals,
  };
}

function planningResearchProviders() {
  const capabilities = adapterCapabilities();
  const registry = aiExecutorRegistry(), global = agentControlStore().read().global || require('./agent-control-plane.cjs').globalDefaults('codex');
  const routed = require('./ai-executor-registry.cjs').routeProviders(global, 'research.v1', registry);
  const visible = [...new Set([...routed, 'codex', 'llm-api', 'workbuddy', 'openclaw'])];
  const workbuddyQualification = readTaskStore().runtime?.agentQualifications?.workbuddy?.[WORKBUDDY_RESEARCH_PROFILE];
  const workbuddyReady = Boolean(workbuddyQualification?.ready && workbuddyQualification.runtimeHash && Date.parse(workbuddyQualification.expiresAt || '') > Date.now());
  return visible.map((id) => {
    const ready = id === 'codex' ? Boolean(capabilities[id]?.exePath)
      : id === 'llm-api' ? Boolean(capabilities[id]?.researchReady) : id === 'workbuddy' ? workbuddyReady : false;
    return {
      id,
      label: capabilities[id]?.label || id,
      available: id === 'workbuddy' ? Boolean(capabilities[id]?.available && ready) : Boolean(capabilities[id]?.available),
      authorized: id === 'workbuddy' ? Boolean(ready) : Boolean(capabilities[id]?.authorized),
      structuredResult: ready,
      webResearch: ready,
      healthMessage: id === 'codex'
        ? (capabilities[id]?.authorized ? '已接通联网研究；每次结果检查网页来源。' : capabilities[id]?.healthMessage || '请先登录 Codex CLI。')
        : id === 'llm-api' ? capabilities[id]?.healthMessage || '请在 AI 接入与调度中心配置并验证联网研究合同。'
          : id === 'workbuddy' ? ready ? '联网研究合同已验证；仅允许 WebSearch/WebFetch，结果逐次核验实际抓取 URL。' : '请在 AI 接入与调度中心验证 WorkBuddy 联网研究合同。'
            : '当前版本尚未接入该工具的联网研究合同；保留手工交接。',
      ...(id === 'codex' && capabilities[id]?.exePath ? { search: createCodexResearchSearch({ executable: capabilities[id].exePath, spawnProcess: spawnAdapterProcess, terminateProcess: terminateCaptureVisionProcess }) } : {}),
      ...(id === 'llm-api' && capabilities[id]?.researchReady ? { search: input => getLlmApiProvider().search(input) } : {}),
      ...(id === 'workbuddy' && ready ? { search: async input => {
        const connected = await classificationAdapter('workbuddy');
        if (!connected || connected.unavailable) throw Object.assign(Error(connected?.message || 'WorkBuddy 后台通道尚未连接'), { code: connected?.code || 'AGENT_UNAVAILABLE' });
        const search = await createWorkBuddyResearchSearch({ runtime: connected.runtime, qualification: workbuddyQualification, spawnProcess: spawnAdapterProcess });
        return search(input);
      } } : {}),
    };
  });
}

function planningGuidanceService() {
  if (!planningGuidanceServiceInstance) {
    planningGuidanceServiceInstance = createPlanningGuidanceService({
      resolveStudent: (studentId) => {
        const student = readStudentsIndex().find((item) => String(item.id) === String(studentId));
        return student ? toHostStudent(student) : null;
      },
      listStudents: () => readStudentsIndex().map(toHostStudent),
      listProjects: () => readProjects().map((project) => normalizeProject(project, { metadataOnly: true })),
      resolveStudentDir: (student) => studentAiManagerDir(student),
      evidenceProvider: planningEvidenceSummary,
      researchProviders: planningResearchProviders,
      authorizeResearch: id => assertAgentProfileAllowed(id, 'research.v1'),
      topicGenerator: async input => {
        await refreshAdapterCapabilities(true);
        const capability = adapterCapabilities().codex;
        if (!capability?.available || !capability.authorized || !capability.exePath) throw new Error('Codex 结构化生成不可用，请完成 CLI 登录并重新检测；自定义工具入口不等于任务执行器');
        return createCodexStructuredGenerator({ executable: capability.exePath, spawnProcess: spawnAdapterProcess, terminateProcess: terminateCaptureVisionProcess })(input);
      },
    });
  }
  return planningGuidanceServiceInstance;
}

