async function executeProjectMaterialMigration(event, projectId, requestJson) {
  let project;
  try {
    const local = localProjectSourceAccess(projectId, event);
    project = local.project;
    if (project.status === 'sealed') throw Object.assign(new Error('项目已封存，不能执行迁移。'), { code: 'project_readonly' });
    if (project.materialMigrationState === 'running') throw Object.assign(new Error('项目迁移正在执行。'), { code: 'project_migration_busy' });
    const request = parseProjectMaterialPayload(requestJson, {});
    if (!await local.authorize()) throw Object.assign(new Error('项目范围已变化，请重新预览。'), { code: 'forbidden' });
    const service = projectMaterialMigrationService(project);
    updateProjectMaterialMigrationState(project.id, 'running');
    const result = await service.execute(request, { actorId: 'host-admin', canWrite: true });
    const attention = result.operation?.status === 'attention';
    const complete = !attention && result.operation?.status === 'succeeded'
      && result.remaining === 0 && !result.previewTruncated;
    const nextState = attention ? 'attention' : complete ? 'complete' : 'partial';
    const updated = updateProjectMaterialMigrationState(project.id, nextState,
      { enableWorkspaceMode: !attention });
    if (!attention) await projectClassificationService(normalizeProject(updated.project)).ensureWorkspaceCategories();
    return JSON.stringify({ ...result, migrationState: nextState, project: normalizeProjectMetadata(updated.project),
      message: attention
        ? '迁移中断现场需要主机管理员核对；项目仍保持原模式，原件和备份均未自动删除。'
        : complete ? '历史资料已全部归一并启用统一资料模式；迁移备份仍保留。'
          : `${result.message} 项目已启用统一资料模式，保留原位项标记为“部分统一”。` });
  } catch (error) {
    if (project) updateProjectMaterialMigrationState(project.id, 'attention');
    return JSON.stringify({ ok: false, code: error.code || 'migration_execute_failed',
      message: `执行历史资料迁移失败：${error.message}` });
  }
}

async function retryProjectMaterialMigration(event, projectId, operationId, requestJson) {
  try {
    const { project, authorize } = localProjectSourceAccess(projectId, event);
    if (project.status === 'sealed') throw Object.assign(new Error('项目已封存，不能重试迁移。'), { code: 'project_readonly' });
    if (!await authorize()) throw Object.assign(new Error('项目范围已变化，请刷新后重试。'), { code: 'forbidden' });
    updateProjectMaterialMigrationState(project.id, 'running');
    const result = await projectMaterialMigrationService(project).retry(String(operationId || ''),
      parseProjectMaterialPayload(requestJson, {}), { actorId: 'host-admin', canWrite: true });
    const attention = result.operation?.status === 'attention';
    const nextState = attention ? 'attention' : result.operation?.status === 'succeeded' ? 'partial' : 'partial';
    updateProjectMaterialMigrationState(project.id, nextState, { enableWorkspaceMode: !attention });
    return JSON.stringify({ ...result, migrationState: nextState,
      message: attention ? '重试后仍有现场需要核对，未覆盖任何文件。' : '已重试可恢复的迁移项；保留原位项仍按部分统一展示。' });
  } catch (error) {
    try { updateProjectMaterialMigrationState(projectId, 'attention'); } catch { /* preserve the original failure */ }
    return JSON.stringify({ ok: false, code: error.code || 'migration_retry_failed',
      message: `重试历史资料迁移失败：${error.message}` });
  }
}

async function rollbackProjectMaterialMigration(event, projectId, operationId, requestJson) {
  try {
    const { project, authorize } = localProjectSourceAccess(projectId, event);
    if (project.status === 'sealed') throw Object.assign(new Error('项目已封存，不能回滚迁移。'), { code: 'project_readonly' });
    if (!await authorize()) throw Object.assign(new Error('项目范围已变化，请刷新后重试。'), { code: 'forbidden' });
    const result = await projectMaterialMigrationService(project).rollback(String(operationId || ''),
      parseProjectMaterialPayload(requestJson, {}), { actorId: 'host-admin', canWrite: true });
    updateProjectMaterialMigrationState(project.id, 'partial', { enableWorkspaceMode: true });
    return JSON.stringify({ ...result, migrationState: 'partial',
      message: `已安全回滚 ${result.results.filter((item) => item.ok).length}/${result.results.length} 项；迁移后被编辑或位置冲突的文件保持现状。` });
  } catch (error) {
    return JSON.stringify({ ok: false, code: error.code || 'migration_rollback_failed',
      message: `回滚历史资料迁移失败：${error.message}` });
  }
}

async function inspectProjectMaterialMigrationBackups(event, projectId) {
  try {
    const { project, authorize } = localProjectSourceAccess(projectId, event);
    if (!await authorize()) throw Object.assign(new Error('项目范围已变化，请刷新后重试。'), { code: 'forbidden' });
    const result = await projectMaterialMigrationService(project).inspectBackupCleanup({ canRead: true });
    return JSON.stringify({ ok: true, ...result });
  } catch (error) {
    return JSON.stringify({ ok: false, code: error.code || 'migration_backup_inspection_failed',
      message: `检查迁移备份失败：${error.message}` });
  }
}

async function cleanupProjectMaterialMigrationBackups(event, projectId, requestJson) {
  try {
    const { project, authorize } = localProjectSourceAccess(projectId, event);
    if (project.status === 'sealed') throw Object.assign(new Error('项目已封存，不能清理迁移备份。'), { code: 'project_readonly' });
    if (project.materialMigrationState === 'running') throw Object.assign(new Error('项目迁移正在执行，不能同时清理备份。'), { code: 'project_migration_busy' });
    if (!await authorize()) throw Object.assign(new Error('项目范围已变化，请重新检查。'), { code: 'forbidden' });
    const result = await projectMaterialMigrationService(project).cleanupBackups(
      parseProjectMaterialPayload(requestJson, {}), { actorId: 'host-admin', canWrite: true });
    return JSON.stringify(result);
  } catch (error) {
    return JSON.stringify({ ok: false, code: error.code || 'migration_backup_cleanup_failed',
      message: `清理迁移备份失败：${error.message}` });
  }
}

async function recoverInterruptedProjectMaterialMigrations() {
  const projects = readProjects().map(normalizeProject)
    .filter((project) => project.materialMigrationState === 'running');
  for (const project of projects) {
    try {
      const result = await projectMaterialMigrationService(project).status({ limit: 10 });
      const latest = result.operations[0];
      const attention = !latest || latest.status === 'attention' || latest.status === 'running';
      updateProjectMaterialMigrationState(project.id, attention ? 'attention' : 'partial',
        { enableWorkspaceMode: !attention });
    } catch {
      updateProjectMaterialMigrationState(project.id, 'attention');
    }
  }
}

async function openProjectMaterialOriginal(event, projectId, materialId, version) {
  try {
    const { project, authorize } = localProjectSourceAccess(projectId, event);
    if (!isWorkspaceMaterialProject(project)) throw Object.assign(new Error('此项目仍使用旧资料模式。'), { code: 'unsupported_storage_mode' });
    if (!await authorize()) throw Object.assign(new Error('项目范围已变化，请刷新后重试。'), { code: 'forbidden' });
    const resolved = await createProjectMaterialHost(project).store.resolve(String(materialId || ''));
    if (resolved.version !== Number(version)) {
      throw Object.assign(new Error('资料版本已更新，请刷新后再定位原件。'), { code: 'version_conflict' });
    }
    if (!await authorize()) throw Object.assign(new Error('项目范围已变化，未打开资料位置。'), { code: 'forbidden' });
    shell.showItemInFolder(resolved.path);
    return JSON.stringify({ ok: true, materialId: resolved.materialId, version: resolved.version,
      message: '已在文件夹中定位原始资料；文件位置没有改变。' });
  } catch (error) {
    return JSON.stringify({ ok: false, code: error.code || 'material_open_failed',
      message: `定位项目原始资料失败：${error.message}` });
  }
}

function collectMarkdownFiles(root, current, files, depth) {
  if (depth < 0) return;
  let entries;
  try {
    entries = fs.readdirSync(current, { withFileTypes: true });
  } catch {
    return;
  }
  for (const entry of entries) {
    const full = path.join(current, entry.name);
    if (entry.isDirectory()) {
      collectMarkdownFiles(root, full, files, depth - 1);
    } else if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
      const stat = fs.statSync(full);
      files.push({
        id: full,
        name: entry.name,
        path: path.relative(root, full).replace(/\\/g, '/'),
        modified: stat.mtimeMs,
      });
    }
  }
}

function readMarkdownFile(studentKey, documentId) {
  try {
    const student = findStudentByKey(studentKey);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const summaryRoot = path.resolve(student.summaryPath || getSummaryDir(student.name));
    const target = path.resolve(String(documentId || ''));
    if (!target.toLowerCase().endsWith('.md') || !isPathInside(summaryRoot, target)) return JSON.stringify({ ok: false, message: '该文件不在当前学生教育档案范围内。' });
    if (!fs.existsSync(target) || !fs.statSync(target).isFile()) return JSON.stringify({ ok: false, message: '未找到文件' });
    const content = fs.readFileSync(target, 'utf8');
    return JSON.stringify({ ok: true, content, ...analyzeArchiveMarkdownContent(content) });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `读取 Markdown 失败：${error.message}` });
  }
}

function listLearningReports(studentKey) {
  try {
    const student = findStudentByKey(studentKey);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const recovery = recoverLearningReportsForStudent(student);
    const license = publicLicenseStatus();
    const ensured = license.active
      ? ensureLearningReportsForStudent(student)
      : { reportDir: learningReportDirForStudent(student), created: [] };
    const draftRecovery = license.active
      ? recoverValidatedLearningReportDrafts(student)
      : { recovered: [], rejected: [], taskIds: [] };
    const reports = LEARNING_REPORTS.map((report) => learningReportRecord(student, report));
    const health = learningReportHealthSummary(reports);
    return JSON.stringify({
      ok: true,
      studentId: String(student.id),
      folder: ensured.reportDir,
      reports,
      health,
      recovery,
      draftRecovery,
      created: ensured.created,
      message: draftRecovery.recovered.length
        ? `已恢复并发布 ${draftRecovery.recovered.length} 份通过校验的报告生成结果。${health.message}`
        : recovery.recovered.length
        ? `已从迁移的历史教育档案恢复 ${recovery.recovered.length} 份学情报告。${health.message}`
        : ensured.created.length ? `已补建 ${ensured.created.length} 个报告模板。${health.message}` : health.message,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `读取学情报告失败：${error.message}` });
  }
}

async function updateLearningReports(studentKey) {
  try {
    const license = publicLicenseStatus();
    if (!license.active) return JSON.stringify({ ok: false, message: '未激活状态仅支持浏览已有学情报告。' });
    const student = findStudentByKey(studentKey);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    ensureLearningReportsForStudent(student);
    const draftRecovery = recoverValidatedLearningReportDrafts(student);
    const prepared = prepareCurrentLearningReportTasks(student);
    await refreshAdapterCapabilities(true);
    const capabilities = adapterCapabilities();
    const started = [];
    const skipped = [];
    for (const taskId of prepared.candidates.map((task) => task.id)) {
      const task = readTaskStore().tasks.find((item) => String(item.id) === String(taskId));
      if (!task || ['succeeded', 'running', 'waiting_result', 'reviewing'].includes(task.status)) continue;
      if (!String(task.input?.growthFingerprint || '')) {
        skipped.push({ taskId, title: task.title, message: '成长模型尚无可验证指纹。' });
        continue;
      }
      const preferred = String(task.requestedExecutor || task.executor || '');
      const preferredCapability = capabilities[preferred];
      const executor = preferredCapability?.available && preferredCapability?.authorized !== false ? preferred : 'auto';
      const route = routeTask(task, executor);
      if (route.selectedAdapter === 'manual') {
        skipped.push({ taskId, title: task.title, message: '当前没有可自动执行的 Agent，请到任务中心选择执行器。' });
        continue;
      }
      let execution;
      try { execution = JSON.parse(executeTaskByAdapter(task.id, executor)); }
      catch { execution = { ok: false, message: '任务启动结果无法解析。' }; }
      if (execution.ok) started.push({ taskId, title: task.title, adapterId: execution.task?.adapterId || route.selectedAdapter });
      else skipped.push({ taskId, title: task.title, message: execution.message || '任务未能启动。' });
    }
    const reports = LEARNING_REPORTS.map((report) => learningReportRecord(student, report));
    const health = learningReportHealthSummary(reports);
    const recoveredCount = draftRecovery.recovered.length;
    const startedCount = started.length;
    const skippedCount = skipped.length;
    const message = [
      recoveredCount ? `已恢复并发布 ${recoveredCount} 份有效生成结果` : '',
      startedCount ? `已启动 ${startedCount} 项当前周期更新` : '',
      skippedCount ? `${skippedCount} 项暂未启动，可在任务中心查看原因` : '',
      !recoveredCount && !startedCount && !skippedCount ? '当前四份学情报告均已是最新版本。' : '',
    ].filter(Boolean).join('；');
    return JSON.stringify({ ok: true, studentId: String(student.id), recovered: draftRecovery.recovered, started, skipped, reports, health, message });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `更新学情报告失败：${error.message}` });
  }
}

function readLearningReport(studentKey, reportId) {
  try {
    const student = findStudentByKey(studentKey);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    recoverLearningReportsForStudent(student);
    const license = publicLicenseStatus();
    if (license.active) ensureLearningReportsForStudent(student);
    const report = LEARNING_REPORTS.find((item) => item.id === String(reportId));
    if (!report) return JSON.stringify({ ok: false, message: '未找到报告类型。' });
    const file = learningReportPathForStudent(student, report);
    if (!fs.existsSync(file)) {
      if (!license.active) return JSON.stringify({ ok: false, message: '未激活状态仅支持浏览已存在的学情报告。请激活后补建报告模板。' });
      fs.writeFileSync(file, learningReportTemplate(student, report), 'utf8');
    }
    return JSON.stringify({
      ok: true,
      ...learningReportRecord(student, report),
      content: fs.readFileSync(file, 'utf8'),
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `读取学情报告正文失败：${error.message}` });
  }
}

function fixedReportEvidenceSources(student, projects, evidence, verifyBytes = false, budget = { remaining: 256 * 1024 * 1024 }) {
  try {
    const project = projects.find((item) => String(item.id) === String(evidence.projectId));
    if (!project) return [];
    return resolveFixedEvidenceSources({ studentId: String(student.id), project, evidence,
      index: readProjectMaterialIndexSync(project), verifyBytes, budget });
  } catch { return []; }
}

function reportEvidenceSourceResolver(student, projects, source) {
  const access = currentArchiveAccess();
  const projectIds = new Set(projects.map((project) => String(project.id)));
  if (String(source).startsWith('edu://')) {
    const result = access.getResource({ uri: source, maxChars: 1 });
    const resource = result?.resource;
    const inScope = resource && (
      (resource.scopeType === 'student' && String(resource.scopeId) === String(student.id))
      || (resource.scopeType === 'project' && projectIds.has(String(resource.scopeId)))
    );
    return inScope
      ? { available: true, kind: 'archive', uri: source, location: resource.path, title: resource.title }
      : { available: false, kind: 'archive', uri: source, location: source, title: '档案来源' };
  }
  const target = canonicalTaskPath(source);
  const allowedRoots = [
    student.rootPath || getStudentRootDir(student.name),
    ...projects.flatMap((project) => [
      project.projectRootPath,
      project.workspacePath,
      project.knowledgeRootPath,
      project.contributionPath,
    ].filter(Boolean)),
  ].map(canonicalTaskPath).filter(Boolean);
  const available = Boolean(
    target
    && fs.existsSync(target)
    && allowedRoots.some((root) => canonicalIsPathInside(root, target))
  );
  return {
    available,
    kind: 'file',
    location: target || String(source || ''),
    title: path.basename(target || String(source || '来源资料')),
  };
}

function learningReportEvidence(studentKey, reportId) {
  try {
    const student = findStudentByKey(studentKey);
    if (!student) return { ok: false, message: '未找到学生。', cards: [] };
    const report = LEARNING_REPORTS.find((item) => item.id === String(reportId));
    if (!report) return { ok: false, message: '未找到报告类型。', cards: [] };
    const file = learningReportPathForStudent(student, report);
    if (!fs.existsSync(file)) return { ok: false, message: '报告尚未生成。', cards: [] };
    const projects = reportProjectsForStudent(student);
    const growthIndex = safeReadJson(growthIndexPath(student), {});
    const reportContent = fs.readFileSync(file, 'utf8');
    const citedIds = new Set(evidenceMarkers(reportContent).flatMap((marker) => marker.ids));
    const matchingGrowthVersion = Boolean(growthIndex.sourceFingerprint && frontmatterValue(reportContent, 'growth_fingerprint') === growthIndex.sourceFingerprint);
    const historical = matchingGrowthVersion || !citedIds.size ? null : readArchivedReportEvidence({ rootDir: educationArchiveVersionRoot(student),
      studentId: String(student.id), reportId: report.id, content: reportContent });
    const reportIndex = historical?.ok ? archivedReportIndex(historical.archive, student.id) : growthIndex;
    const fixedSources = new Map();
    const projectIndexes = new Map();
    const resolveFixed = (evidence) => {
      if (fixedSources.has(evidence.id)) return fixedSources.get(evidence.id);
      let sources = [];
      if (matchingGrowthVersion) sources = fixedReportEvidenceSources(student, projects, evidence);
      else if (historical?.ok) {
        try {
          const project = projects.find((item) => String(item.id) === String(evidence.projectId));
          if (project) {
            if (!projectIndexes.has(project.id)) projectIndexes.set(project.id, readProjectMaterialIndexSync(project));
            sources = resolveHistoricalEvidenceSources({ archive: historical.archive, studentId: String(student.id),
              project, evidence, index: projectIndexes.get(project.id) });
          }
        } catch { /* Unverifiable or withdrawn history has no current-path fallback. */ }
      }
      fixedSources.set(evidence.id, sources); return sources;
    };
    const evidenceWithFallbackSources = (Array.isArray(reportIndex.evidence) ? reportIndex.evidence : [])
      .filter((evidence) => citedIds.has(evidence.id))
      .filter((evidence) => matchingGrowthVersion || !requiresFixedReportEvidence(evidence, projects) || (historical?.ok && resolveFixed(evidence).length > 0)).map((evidence) => ({
      ...evidence,
      requiresProjectConfirmation: requiresFixedReportEvidence(evidence, projects),
      sourcePath: reportEvidenceSourceValues(student, projects, evidence).join('；'),
    }));
    const result = resolveReportEvidence({
      content: reportContent,
      growthIndex: { ...reportIndex, evidence: evidenceWithFallbackSources },
      resolveSource: (source) => reportEvidenceSourceResolver(student, projects, source),
      resolveFixedSources: resolveFixed,
    });
    const cards = (result.cards || []).map((card) => ({
      ...card,
      sources: (card.sources || []).map((source) => ({
        ...source,
        timelineRefs: source.location ? findCaptureTimelineKnowledgeLinks(captureCenterRootPath(), {
          studentId: String(student.id),
          targetPath: source.location,
        }) : [],
      })),
    }));
    const timelineReferenceCount = cards.reduce((sum, card) => sum + card.sources.reduce((sourceSum, source) => sourceSum + (source.timelineRefs || []).length, 0), 0);
    return {
      ...result,
      cards,
      timelineReferenceCount,
      studentId: String(student.id),
      reportId: report.id,
      historical: Boolean(historical?.ok),
      archiveVersionId: historical?.ok ? historical.archive.versionId : '',
      historyStatus: matchingGrowthVersion ? 'current' : historical?.ok ? 'matched' : historical?.reason || 'archive_unavailable',
      message: `${historical?.ok ? '正在查看报告引用的历史依据，未替换为当前证据。 ' : ''}${result.message}${timelineReferenceCount ? ` 其中 ${timelineReferenceCount} 项可回到学习时间线。` : ''}`,
    };
  } catch (error) {
    return { ok: false, message: `读取报告依据失败：${error.message}`, cards: [] };
  }
}

function getLearningReportEvidence(studentKey, reportId) {
  return JSON.stringify(learningReportEvidence(studentKey, reportId));
}

function openLearningReportEvidenceSource(studentKey, reportId, evidenceId, sourceIndex = 0) {
  try {
    const result = learningReportEvidence(studentKey, reportId);
    const card = (result.cards || []).find((item) => String(item.evidenceId) === String(evidenceId));
    const source = card?.sources?.[Math.max(0, Number(sourceIndex) || 0)];
    if (!source?.available || !source.location) {
      return JSON.stringify({ ok: false, message: '该依据来源已移动或暂时不可访问。' });
    }
    const target = canonicalTaskPath(source.location);
    if (!target || !fs.existsSync(target)) return JSON.stringify({ ok: false, message: '该依据来源已移动或暂时不可访问。' });
    const stat = fs.statSync(target);
    if (source.kind === 'project_evidence') verifyFixedEvidenceFile(source);
    if (stat.isDirectory()) shell.openPath(target).catch(() => {});
    else shell.showItemInFolder(target);
    return JSON.stringify({ ok: true, message: '已在本机定位依据来源。', path: target });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `打开报告依据失败：${error.message}` });
  }
}

function educationArchiveVersionRoot(student) {
  return path.join(studentManagerDir(toHostStudent(student)), 'education-archive-versions');
}

function educationArchiveReportSnapshots(student) {
  const normalized = toHostStudent(student);
  return LEARNING_REPORTS.map((report) => {
    const file = learningReportPathForStudent(normalized, report);
    return {
      id: report.id,
      title: report.title,
      fileName: report.fileName,
      path: file,
      content: fs.existsSync(file) && fs.statSync(file).isFile() ? fs.readFileSync(file, 'utf8') : '',
    };
  });
}

function createEducationArchiveVersion(studentKey) {
  const student = findStudentByKey(studentKey);
  if (!student) return { ok: false, message: '未找到学生。' };
  const normalized = toHostStudent(student);
  recoverLearningReportsForStudent(normalized);
  const indexFile = growthIndexPath(normalized);
  const growthIndex = safeReadJson(indexFile, {});
  if (!growthIndex.sourceFingerprint) return { ok: false, message: '成长模型尚未形成，暂不创建教育档案版本。' };
  try {
    const result = writeArchiveVersion({
      rootDir: educationArchiveVersionRoot(normalized),
      student: normalized,
      growthIndex,
      reports: educationArchiveReportSnapshots(normalized),
    });
    if (!result.unchanged) {
      appendHostTimeline({ type: 'education_archive_version_created', title: 'Education archive version created', detail: normalized.name });
    }
    scheduleStudentArchiveSync(normalized.id);
    return {
      ok: true,
      unchanged: result.unchanged,
      versionDir: result.versionDir,
      sourceFingerprint: result.snapshot?.sourceFingerprint || '',
      message: result.unchanged ? '教育档案无实质变化，保留当前版本。' : '教育档案已自动形成新版本。',
    };
  } catch (error) {
    return { ok: false, message: `教育档案版本创建失败：${error.message}` };
  }
}

function scheduleEducationArchiveVersion(studentKey, delayMs = 20_000) {
  const studentId = String(studentKey || '');
  if (!studentId) return;
  const current = educationArchiveVersionTimers.get(studentId);
  if (current) clearTimeout(current);
  educationArchiveVersionTimers.set(studentId, setTimeout(() => {
    educationArchiveVersionTimers.delete(studentId);
    if (!projectArchiveRuntime.status().ready) {
      scheduleEducationArchiveVersion(studentId, 30_000);
      return;
    }
    createEducationArchiveVersion(studentId);
  }, Math.max(1000, Number(delayMs || 0))));
}

function flushEducationArchiveVersions() {
  const studentIds = [...educationArchiveVersionTimers.keys()];
  for (const timer of educationArchiveVersionTimers.values()) clearTimeout(timer);
  educationArchiveVersionTimers.clear();
  for (const studentId of studentIds) createEducationArchiveVersion(studentId);
}

function exportEducationArchive(studentKey) {
  try {
    const student = findStudentByKey(studentKey);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const version = createEducationArchiveVersion(student.id);
    if (!version.ok || !version.versionDir) return JSON.stringify(version);
    const exported = exportDirectoryWithFallback(
      version.versionDir,
      educationExportBaseCandidates(),
      `AI-education-archive-${sanitizeName(student.name)}-${timestampForFilename()}`,
    );
    shell.openPath(exported.path).catch(() => {});
    return JSON.stringify({
      ok: true,
      path: exported.path,
      unchanged: version.unchanged,
      message: `完整教育档案已导出：${exported.path}`,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `导出教育档案失败：${error.message}` });
  }
}

async function exportLearningReport(studentKey, reportId, format) {
  let printWindow = null;
  let temporaryDir = '';
  try {
    const student = findStudentByKey(studentKey);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const report = LEARNING_REPORTS.find((item) => item.id === String(reportId));
    if (!report) return JSON.stringify({ ok: false, message: '未找到报告类型。' });
    const normalizedFormat = String(format || '').toLowerCase();
    if (!['markdown', 'pdf'].includes(normalizedFormat)) {
      return JSON.stringify({ ok: false, message: '学情报告仅支持 Markdown 或 PDF 格式。' });
    }
    const file = learningReportPathForStudent(student, report);
    if (!fs.existsSync(file) || !fs.statSync(file).isFile()) {
      return JSON.stringify({ ok: false, message: '当前学情报告尚未生成，请先刷新报告。' });
    }
    const content = fs.readFileSync(file, 'utf8');
    const stem = safeExportStem(
      `${sanitizeName(student.name)}-${report.title}-${timestampForFilename()}`,
      `learning-report-${timestampForFilename()}`,
    );
    if (normalizedFormat === 'markdown') {
      const exported = writeFileWithFallback(
        educationExportBaseCandidates(),
        stem,
        'md',
        Buffer.from(content, 'utf8'),
      );
      shell.showItemInFolder(exported.path);
      return JSON.stringify({
        ok: true,
        format: normalizedFormat,
        path: exported.path,
        message: `学情报告 Markdown 已导出：${exported.path}`,
      });
    }

    temporaryDir = fs.mkdtempSync(path.join(app.getPath('temp'), 'edu-learning-report-'));
    const htmlPath = path.join(temporaryDir, 'report.html');
    fs.writeFileSync(htmlPath, learningReportHtml({
      studentName: student.name,
      reportTitle: report.title,
      markdown: content,
      generatedAt: new Date().toLocaleString('zh-CN'),
    }), 'utf8');
    printWindow = new BrowserWindow({
      show: false,
      webPreferences: {
        contextIsolation: true,
        nodeIntegration: false,
        sandbox: true,
      },
    });
    await printWindow.loadFile(htmlPath);
    await printWindow.webContents.executeJavaScript('document.fonts.ready.then(() => true)');
    const pdf = await printWindow.webContents.printToPDF({
      pageSize: 'A4',
      printBackground: true,
      preferCSSPageSize: true,
      displayHeaderFooter: true,
      headerTemplate: '<span></span>',
      footerTemplate: '<div style="box-sizing:border-box;width:100%;padding:0 16mm;color:#8992a3;font-family:Microsoft YaHei,sans-serif;font-size:8px;text-align:center;">AI 教育管家 · Robogala　<span class="pageNumber"></span> / <span class="totalPages"></span></div>',
    });
    const exported = writeFileWithFallback(
      educationExportBaseCandidates(),
      stem,
      'pdf',
      pdf,
    );
    shell.showItemInFolder(exported.path);
    return JSON.stringify({
      ok: true,
      format: normalizedFormat,
      path: exported.path,
      message: `学情报告 PDF 已导出：${exported.path}`,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `导出学情报告失败：${error.message}` });
  } finally {
    if (printWindow && !printWindow.isDestroyed()) printWindow.destroy();
    if (temporaryDir && fs.existsSync(temporaryDir)) {
      try { fs.rmSync(temporaryDir, { recursive: true, force: true }); } catch {}
    }
  }
}

function educationPublicationIndexPath() {
  return path.join(app.getPath('userData'), 'education-publications.json');
}

function readEducationPublicationIndex() {
  try {
    const parsed = JSON.parse(fs.readFileSync(educationPublicationIndexPath(), 'utf8'));
    return Array.isArray(parsed?.records) ? parsed.records : [];
  } catch {
    return [];
  }
}

function writeEducationPublicationIndex(records) {
  writeJsonAtomic(educationPublicationIndexPath(), {
    schema: PUBLICATION_SCHEMA,
    updatedAt: new Date().toISOString(),
    records: records.slice(0, 200),
  });
}

function educationPublicationSource(student, sourceType, sourceId) {
  if (sourceType === 'learning_report') {
    const report = LEARNING_REPORTS.find((item) => item.id === String(sourceId));
    if (!report) return { ok: false, message: '未找到学情报告类型。' };
    const filePath = learningReportPathForStudent(student, report);
    if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) return { ok: false, message: '学情报告尚未生成。' };
    const content = fs.readFileSync(filePath, 'utf8');
    return { ok: true, title: report.title, path: filePath, content, eligibility: { eligible: true, reason: '' } };
  }
  if (sourceType === 'archive_file') {
    const filePath = path.resolve(String(sourceId || ''));
    const summaryRoot = path.resolve(student.summaryPath || getSummaryDir(student.name));
    if (!isPathInside(summaryRoot, filePath)) return { ok: false, message: '所选文件不属于当前学生的教育档案。' };
    const eligibility = publicationEligibility(filePath);
    if (!eligibility.eligible) return { ok: false, message: eligibility.reason, eligibility };
    if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) return { ok: false, message: '未找到所选档案文件。' };
    const content = fs.readFileSync(filePath, 'utf8');
    return { ok: true, title: path.basename(filePath, path.extname(filePath)), path: filePath, content, eligibility };
  }
  return { ok: false, message: '不支持的教育内容来源。' };
}

function sanitizeEducationPublicationDraft(candidate, automaticDraft, sourceContent) {
  if (!candidate || typeof candidate !== 'object') return automaticDraft;
  if (String(candidate.templateId || '') !== String(automaticDraft.templateId || '')) return automaticDraft;
  if (String(candidate.sourceHash || '') !== String(automaticDraft.sourceHash || '')) return automaticDraft;
  const title = String(candidate.title || automaticDraft.title || '').trim().slice(0, 160) || automaticDraft.title;
  const subtitle = String(candidate.subtitle || '').trim().slice(0, 240);
  if (automaticDraft.mode === 'document') {
    const markdown = String(candidate.markdown || '').trim();
    if (!markdown || Buffer.byteLength(markdown, 'utf8') > 512 * 1024) return automaticDraft;
    return {
      ...automaticDraft,
      title,
      subtitle,
      markdown,
      edited: markdown !== automaticDraft.markdown || title !== automaticDraft.title || subtitle !== automaticDraft.subtitle,
    };
  }
  const sections = Array.isArray(candidate.sections) ? candidate.sections.slice(0, 10).map((section, sectionIndex) => ({
    id: String(section?.id || `section-${sectionIndex + 1}`).slice(0, 80),
    label: String(section?.label || '内容要点').trim().slice(0, 80) || '内容要点',
    kind: String(section?.kind || '').slice(0, 32),
    items: (Array.isArray(section?.items) ? section.items : []).slice(0, 12).map((item, itemIndex) => ({
      id: String(item?.id || `item-${sectionIndex + 1}-${itemIndex + 1}`).slice(0, 120),
      text: String(item?.text || '').trim().slice(0, 1000),
      sourceHeading: String(item?.sourceHeading || '').slice(0, 160),
      sourceHash: String(item?.sourceHash || '').slice(0, 128),
      grounded: Boolean(item?.grounded),
      sourceQuote: String(item?.sourceQuote || '').trim().slice(0, 2000),
      sourceRefs: (Array.isArray(item?.sourceRefs) ? item.sourceRefs : []).slice(0, 8).map((value) => String(value).slice(0, 160)),
      emphasis: item?.emphasis === 'highlight' ? 'highlight' : 'normal',
    })).filter((item) => item.text),
  })).filter((section) => section.items.length) : [];
  if (!sections.length) return automaticDraft;
  if (candidate.generationMethod === 'agent') {
    const checked = validateEnhancementCandidate({
      schema: EDUCATION_PUBLICATION_ENHANCEMENT_SCHEMA,
      title, subtitle,
      layout: candidate.mode || automaticDraft.mode,
      sections,
    }, sourceContent, {
      templateId: automaticDraft.templateId,
      fallbackTitle: automaticDraft.title,
      fallbackSubtitle: automaticDraft.subtitle,
    });
    if (!checked.valid) return automaticDraft;
    return {
      ...automaticDraft,
      ...checked.draft,
      templateId: automaticDraft.templateId,
      sourceHash: automaticDraft.sourceHash,
      generationMethod: 'agent',
      promptTemplateId: String(candidate.promptTemplateId || ''),
      edited: Boolean(candidate.edited),
      validation: { total: checked.total, grounded: checked.grounded, coverage: checked.coverage, valid: checked.valid },
    };
  }
  const draft = {
    ...automaticDraft,
    title,
    subtitle,
    sections,
    edited: JSON.stringify(sections) !== JSON.stringify(automaticDraft.sections) || title !== automaticDraft.title || subtitle !== automaticDraft.subtitle,
  };
  return { ...draft, validation: validateDraftGrounding(draft, sourceContent) };
}

function getEducationPublishingState(studentKey, sourceType, sourceId) {
  try {
    const student = findStudentByKey(studentKey);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const source = educationPublicationSource(student, sourceType, sourceId);
    if (!source.ok) return JSON.stringify(source);
    const sourceHash = publicationFingerprint(source.content);
    const records = readEducationPublicationIndex()
      .filter((item) => String(item.studentId) === String(student.id))
      .map((item) => ({ ...item, sourceChanged: item.sourceId === String(sourceId) && item.sourceHash !== sourceHash }))
      .slice(0, 20);
    const templates = educationPublicationTemplateCatalog(publicLicenseStatus().plan || 'basic');
    const drafts = Object.fromEntries(templates.map((template) => [template.id, buildPublicationDraft(source.content, {
      templateId: template.id,
      title: source.title,
      sourceType,
      subtitle: sourceType === 'learning_report' ? (template.id === 'formal' || template.id === 'monochrome' ? '学情报告' : '学情报告要点') : (template.id === 'formal' || template.id === 'monochrome' ? '教育档案报告' : '教育档案要点'),
    })]));
    return JSON.stringify({
      ok: true,
      source: { type: sourceType, id: String(sourceId), title: source.title, path: source.path, hash: sourceHash },
      outline: extractPublicationOutline(source.content, { title: source.title, templateId: 'concise', sourceType }),
      drafts,
      templates,
      enhancementTemplates: Object.fromEntries(templates.map((template) => [template.id, educationPublicationPromptCatalog(template.id)])),
      records,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `读取教育内容出版状态失败：${error.message}` });
  }
}

function educationPublicationEnhancementTaskId(studentId, sourceHash, templateId, promptTemplateId) {
  return taskStableId('publication_enhancement', 'student', studentId, `${String(sourceHash).slice(0, 16)}:${templateId}:${promptTemplateId}:${EDUCATION_PUBLICATION_PROMPT_REVISION}`);
}

function educationPublicationEnhancementState(studentKey, optionsJson) {
  try {
    const student = findStudentByKey(studentKey);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const options = typeof optionsJson === 'string' ? JSON.parse(optionsJson || '{}') : (optionsJson || {});
    const source = educationPublicationSource(student, options.sourceType, options.sourceId);
    if (!source.ok) return JSON.stringify(source);
    const sourceHash = publicationFingerprint(source.content);
    const templateId = String(options.templateId || 'concise');
    const promptTemplateId = String(options.promptTemplateId || defaultEducationPublicationPrompt(templateId));
    const taskId = educationPublicationEnhancementTaskId(student.id, sourceHash, templateId, promptTemplateId);
    const task = readTaskStore().tasks.find((item) => item.id === taskId);
    const enhanced = task?.result?.structuredOutput?.draft || null;
    const fallbackDraft = buildPublicationDraft(source.content, {
      templateId,
      title: source.title,
      sourceType: options.sourceType,
      subtitle: options.sourceType === 'learning_report' ? '学情报告要点' : '教育档案要点',
    });
    return JSON.stringify({
      ok: true,
      taskId,
      status: task?.status || 'idle',
      message: enhanced ? (task?.result?.summary || 'Agent 草稿已通过证据优先校验。') : task?.result?.summary || task?.error?.message || '尚未生成 Agent 草稿。',
      draft: enhanced ? { ...fallbackDraft, ...enhanced, templateId, sourceHash, generationMethod: 'agent', promptTemplateId, edited: false } : fallbackDraft,
      fallback: !enhanced,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `读取 Agent 出版草稿失败：${error.message}` });
  }
}

async function startEducationPublicationEnhancement(studentKey, optionsJson) {
  try {
    const student = findStudentByKey(studentKey);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const options = typeof optionsJson === 'string' ? JSON.parse(optionsJson || '{}') : (optionsJson || {});
    const source = educationPublicationSource(student, options.sourceType, options.sourceId);
    if (!source.ok) return JSON.stringify(source);
    const sourceHash = publicationFingerprint(source.content);
    const templateId = String(options.templateId || 'concise');
    const promptTemplateId = String(options.promptTemplateId || defaultEducationPublicationPrompt(templateId));
    const taskId = educationPublicationEnhancementTaskId(student.id, sourceHash, templateId, promptTemplateId);
    const outputDir = path.join(taskCenterDirPath(), 'publication-enhancements', String(student.id));
    fs.mkdirSync(outputDir, { recursive: true });
    const resultPath = path.join(outputDir, `${taskId}.json`);
    const command = buildEnhancementPrompt({
      templateId, promptTemplateId, sourcePath: source.path, resultPath,
      studentId: student.id, studentName: student.name,
    });
    const store = readTaskStore();
    const existingIndex = store.tasks.findIndex((item) => item.id === taskId);
    const existing = existingIndex >= 0 ? store.tasks[existingIndex] : null;
    if (existing?.status === 'succeeded' && existing.result?.structuredOutput?.draft && options.force !== true) {
      return JSON.stringify({ ok: true, taskId, status: 'succeeded', message: '已使用通过校验的 Agent 草稿。' });
    }
    const task = normalizeTaskEnvelope({
      ...(existing || {}), id: taskId, title: `智能提炼：${source.title}`,
      kind: 'publication_enhancement', sourceType: 'student', sourceId: String(student.id), sourceName: student.name,
      status: 'pending', trigger: 'education_publishing', priority: 'normal', riskLevel: 'low',
      requestedExecutor: String(options.executor || 'auto'), executor: String(options.executor || 'auto'),
      completionPolicy: 'auto_after_validation', maxAttempts: 2, attempt: 0, autoRetry: true,
      input: { command, sourceType: options.sourceType, publicationSourceId: String(options.sourceId), sourceHash, templateId, promptTemplateId, promptRevision: EDUCATION_PUBLICATION_PROMPT_REVISION },
      expectedOutput: { type: EDUCATION_PUBLICATION_ENHANCEMENT_SCHEMA, path: resultPath },
      permissions: { read: [source.path], write: [outputDir], operations: ['read', 'create_draft'] },
      approval: { required: false, status: 'not_required' },
      detail: '根据原文生成结构化草稿；逐条依据校验失败时保留忠实原文草稿。',
      result: null, error: null, completedAt: '',
    }, existing || {});
    if (existingIndex >= 0) store.tasks[existingIndex] = task; else store.tasks.unshift(task);
    writeTaskStore(store);
    appendTaskEvent(taskId, 'publication_enhancement_created', { templateId, promptTemplateId, promptRevision: EDUCATION_PUBLICATION_PROMPT_REVISION, sourceHash });
    const execution = JSON.parse(await executeTaskByAdapterWithFreshCapabilities(taskId, String(options.executor || 'auto')));
    return JSON.stringify({ ...execution, taskId, status: execution.task?.status || 'running', fallbackDraftRetained: true });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `启动 Agent 智能提炼失败：${error.message}`, fallbackDraftRetained: true });
  }
}

async function exportEducationPublication(studentKey, optionsJson) {
  let renderWindow = null;
  let temporaryDir = '';
  try {
    const student = findStudentByKey(studentKey);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const options = typeof optionsJson === 'string' ? JSON.parse(optionsJson || '{}') : (optionsJson || {});
    const sourceType = String(options.sourceType || '');
    const sourceId = String(options.sourceId || '');
    const template = EDUCATION_PUBLICATION_TEMPLATES.find((item) => item.id === String(options.templateId || 'formal'));
    const outputFormat = String(options.format || '').toLowerCase();
    const colorMode = options.colorMode === 'monochrome' ? 'monochrome' : 'color';
    if (!template || !template.formats.includes(outputFormat)) return JSON.stringify({ ok: false, message: '当前模板不支持所选输出格式。' });
    const source = educationPublicationSource(student, sourceType, sourceId);
    if (!source.ok) return JSON.stringify(source);
    const sourceHash = publicationFingerprint(source.content);
    const automaticDraft = buildPublicationDraft(source.content, {
      templateId: template.id,
      title: source.title,
      sourceType,
      subtitle: sourceType === 'learning_report' ? (template.id === 'formal' || template.id === 'monochrome' ? '学情报告' : '学情报告要点') : (template.id === 'formal' || template.id === 'monochrome' ? '教育档案报告' : '教育档案要点'),
    });
    const draft = sanitizeEducationPublicationDraft(options.draft, automaticDraft, source.content);
    const generatedAt = new Date();
    const stem = safeExportStem(`${sanitizeName(student.name)}-${source.title}-${template.name}-${timestampForFilename()}`, `education-publication-${timestampForFilename()}`);
    let exported;
    if (outputFormat === 'markdown') {
      exported = writeFileWithFallback(educationExportBaseCandidates(), stem, 'md', Buffer.from(draftMarkdown(draft), 'utf8'));
    } else {
      temporaryDir = fs.mkdtempSync(path.join(app.getPath('temp'), 'edu-publication-'));
      const htmlPath = path.join(temporaryDir, 'publication.html');
      fs.writeFileSync(htmlPath, buildPublicationHtml({
        templateId: template.id,
        outputFormat,
        colorMode,
        studentName: student.name,
        title: source.title,
        subtitle: sourceType === 'learning_report' ? '学情报告要点' : '教育档案要点',
        markdown: source.content,
        draft,
        generatedAt: generatedAt.toLocaleString('zh-CN'),
      }), 'utf8');
      renderWindow = new BrowserWindow({
        show: false,
        width: outputFormat === 'png' ? 1080 : 900,
        height: outputFormat === 'png' ? 1920 : 1100,
        webPreferences: { contextIsolation: true, nodeIntegration: false, sandbox: true },
      });
      await renderWindow.loadFile(htmlPath);
      await renderWindow.webContents.executeJavaScript('document.fonts.ready.then(() => true)');
      if (outputFormat === 'pdf') {
        const pdf = await renderWindow.webContents.printToPDF({ pageSize: template.id === 'growth-card' ? { width: 285750, height: 508000 } : 'A4', printBackground: true, preferCSSPageSize: true });
        exported = writeFileWithFallback(educationExportBaseCandidates(), stem, 'pdf', pdf);
      } else {
        const contentHeight = await renderWindow.webContents.executeJavaScript(`(() => {
          const page = document.querySelector('.page');
          return Math.max(1440, Math.ceil(page?.scrollHeight || document.documentElement.scrollHeight || 1440));
        })()`);
        const captureHeight = Math.min(12000, Number(contentHeight) || 1440);
        if (Number(contentHeight) > 12000) throw new Error('卡片内容过长，请精简后重试，或改用 PDF 输出完整内容。');
        renderWindow.setContentSize(1080, captureHeight);
        await renderWindow.webContents.executeJavaScript('new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)))');
        const image = await renderWindow.webContents.capturePage({ x: 0, y: 0, width: 1080, height: captureHeight });
        exported = writeFileWithFallback(educationExportBaseCandidates(), stem, 'png', image.toPNG());
      }
    }
    const record = {
      id: `publication-${crypto.randomUUID()}`,
      studentId: String(student.id),
      studentName: student.name,
      sourceType,
      sourceId,
      sourcePath: source.path,
      sourceHash,
      sourceTitle: source.title,
      templateId: template.id,
      templateName: template.name,
      format: outputFormat,
      colorMode,
      outputPath: exported.path,
      generatedAt: generatedAt.toISOString(),
      edited: Boolean(draft.edited),
      generationMethod: draft.generationMethod || 'source',
      promptTemplateId: draft.promptTemplateId || '',
      validation: draft.validation,
      draft,
    };
    writeEducationPublicationIndex([record, ...readEducationPublicationIndex().filter((item) => item.id !== record.id)]);
    shell.showItemInFolder(exported.path);
    return JSON.stringify({ ok: true, record, message: `${template.name}已生成：${exported.path}` });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `生成教育内容失败：${error.message}` });
  } finally {
    if (renderWindow && !renderWindow.isDestroyed()) renderWindow.destroy();
    if (temporaryDir && fs.existsSync(temporaryDir)) {
      try { fs.rmSync(temporaryDir, { recursive: true, force: true }); } catch {}
    }
  }
}

function openEducationPublication(studentKey, publicationId) {
  const student = findStudentByKey(studentKey);
  const record = readEducationPublicationIndex().find((item) => item.id === String(publicationId) && String(item.studentId) === String(student?.id || ''));
  if (!record || !record.outputPath || !fs.existsSync(record.outputPath)) return JSON.stringify({ ok: false, message: '未找到生成文件。' });
  shell.showItemInFolder(record.outputPath);
  return JSON.stringify({ ok: true, message: '已定位生成文件。' });
}

function deleteEducationPublication(studentKey, publicationId) {
  try {
    const student = findStudentByKey(studentKey);
    const records = readEducationPublicationIndex();
    const record = records.find((item) => item.id === String(publicationId) && String(item.studentId) === String(student?.id || ''));
    if (!record) return JSON.stringify({ ok: false, message: '未找到生成记录。' });
    if (record.outputPath && fs.existsSync(record.outputPath)) fs.unlinkSync(record.outputPath);
    writeEducationPublicationIndex(records.filter((item) => item.id !== record.id));
    return JSON.stringify({ ok: true, message: '已删除生成文件和记录，原始档案未改动。' });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `删除生成文件失败：${error.message}` });
  }
}

async function regenerateEducationPublication(studentKey, publicationId) {
  const student = findStudentByKey(studentKey);
  const record = readEducationPublicationIndex().find((item) => item.id === String(publicationId) && String(item.studentId) === String(student?.id || ''));
  if (!record) return JSON.stringify({ ok: false, message: '未找到可重新生成的记录。' });
  return exportEducationPublication(studentKey, JSON.stringify({
    sourceType: record.sourceType,
    sourceId: record.sourceId,
    templateId: record.templateId,
    format: record.format,
    colorMode: record.colorMode,
    draft: record.draft,
  }));
}

function restoreEducationArchiveSnapshot(student, snapshot) {
  if (!snapshot || String(snapshot.student?.id || '') !== String(student.id)) return { ok: false, message: '教育档案备份与学生不匹配。' };
  const version = writeArchiveVersion({
    rootDir: educationArchiveVersionRoot(student),
    student,
    growthIndex: snapshot.growthIndex || {},
    reports: snapshot.reports || [],
    createdAt: snapshot.createdAt || new Date().toISOString(),
  });
  return restoreArchiveVersion({
    versionDir: version.versionDir,
    studentId: student.id,
    growthIndexPath: growthIndexPath(student),
    reportPaths: Object.fromEntries(LEARNING_REPORTS.map((report) => [report.id, learningReportPathForStudent(student, report)])),
  });
}

function ensureLearningReports(studentKey) {
  try {
    const student = findStudentByKey(studentKey);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const ensured = ensureLearningReportsForStudent(student);
    const reports = LEARNING_REPORTS.map((report) => learningReportRecord(student, report));
    const health = learningReportHealthSummary(reports);
    return JSON.stringify({
      ok: true,
      folder: ensured.reportDir,
      created: ensured.created,
      reports,
      health,
      message: ensured.created.length ? `已补建：${ensured.created.join('、')}。${health.message}` : health.message,
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `补建学情报告失败：${error.message}` });
  }
}

function ensureGrowthModel(studentKey) {
  try {
    const student = findStudentByKey(studentKey);
    if (!student) return JSON.stringify({ ok: false, message: '未找到学生。' });
    const result = ensureGrowthModelForStudent(student);
    const rebuilt = JSON.parse(rebuildGrowthIndex(student.id));
    return JSON.stringify({
      ok: true,
      folder: result.dir,
      created: result.created,
      index: rebuilt.index,
      content: rebuilt.content,
      message: result.created.length ? `已补建成长模型文件：${result.created.join('、')}，并升级结构化索引。` : '成长模型文件已存在，结构化索引已刷新。',
    });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `补建成长模型失败：${error.message}` });
  }
}

function resetUploadCounterIfNeeded() {
  const today = new Date().toISOString().slice(0, 10);
  if (today !== uploadCountDate) {
    uploadCountDate = today;
    todayUploadCount = 0;
  }
}

function sendJson(response, statusCode, body) {
  response.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Headers': 'Authorization, Content-Type, X-Upload-Id, X-Edu-Data-Generation, X-Edu-Binding-Id, X-Edu-Node-Id, X-Edu-Timestamp, X-Edu-Nonce, X-Edu-Content-Sha256, X-Edu-Signature',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
  });
  response.end(JSON.stringify(body));
}

function readRequestBuffer(request, maxBytes = MAX_UPLOAD_BYTES + 1024 * 1024) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let total = 0;
    request.on('data', (chunk) => {
      total += chunk.length;
      if (total > maxBytes) {
        reject(new Error('上传文件过大。'));
        request.destroy();
        return;
      }
      chunks.push(chunk);
    });
    request.on('end', () => resolve(Buffer.concat(chunks)));
    request.on('error', reject);
  });
}

function parseJsonBody(request) {
  return readRequestBuffer(request, 1024 * 1024).then((buffer) => {
    if (!buffer.length) return {};
    return JSON.parse(buffer.toString('utf8'));
  });
}

function parseMultipartFiles(buffer, contentType) {
  const boundaryMatch = /boundary=(?:"([^"]+)"|([^;]+))/i.exec(contentType || '');
  const boundary = boundaryMatch && (boundaryMatch[1] || boundaryMatch[2]);
  if (!boundary) throw new Error('缺少 multipart boundary。');
  const delimiter = Buffer.from(`--${boundary}`);
  const files = [];
  let cursor = 0;
  while (cursor < buffer.length) {
    const partStart = buffer.indexOf(delimiter, cursor);
    if (partStart < 0) break;
    let bodyStart = partStart + delimiter.length;
    if (buffer.slice(bodyStart, bodyStart + 2).toString() === '--') break;
    if (buffer.slice(bodyStart, bodyStart + 2).toString() === '\r\n') bodyStart += 2;
    const headerEnd = buffer.indexOf(Buffer.from('\r\n\r\n'), bodyStart);
    if (headerEnd < 0) break;
    const headersText = buffer.slice(bodyStart, headerEnd).toString('utf8');
    let partEnd = buffer.indexOf(delimiter, headerEnd + 4);
    if (partEnd < 0) partEnd = buffer.length;
    let content = buffer.slice(headerEnd + 4, partEnd);
    if (content.slice(-2).toString() === '\r\n') content = content.slice(0, -2);
    const disposition = headersText.split(/\r\n/).find((line) => /^content-disposition:/i.test(line)) || '';
    const filenameMatch = /filename\*?=(?:UTF-8''([^;\r\n]+)|"([^"]*)"|([^;\r\n]+))/i.exec(disposition);
    const filename = filenameMatch && decodeURIComponent(filenameMatch[1] || filenameMatch[2] || filenameMatch[3] || '').trim();
    if (filename) files.push({ filename, content });
    cursor = partEnd;
  }
  return files;
}

function authContext(request) {
  const header = String(request.headers.authorization || '');
  const match = /^Bearer\s+(.+)$/i.exec(header);
  const token = match ? match[1].trim() : '';
  if (!token) return null;
  const agentGrant = effectiveAgentGrant(token);
  if (agentGrant) return agentGrant;
  if (token === ensureApiToken()) {
    return { type: 'admin', allowedStudentIds: null };
  }
  const studentSession = studentSessionByBearerToken(token);
  if (studentSession) {
    touchDevice(studentSession.device.id, request);
    return {
      type: 'student_session',
      sessionId: studentSession.sessionId,
      sessionTokenHash: studentSession.tokenHash,
      deviceId: studentSession.device.id,
      deviceName: studentSession.device.name || '学生终端',
      terminalMode: studentSession.terminalMode,
      studentId: String(studentSession.student.id),
      allowedStudentIds: [String(studentSession.student.id)],
      allowedAllStudents: false,
    };
  }
  const device = deviceByBearerToken(token);
  if (!device) return null;
  touchDevice(device.id, request);
  const deviceRole = normalizeTerminalDeviceRole(device.deviceRole, device.capabilities);
  const teacherStudentIds = deviceRole === 'teacher' ? readStudentsIndex().map((student) => String(student.id)) : [];
  return {
    type: 'device',
    deviceId: device.id,
    deviceName: device.name || (deviceRole === 'teacher' ? '教师终端' : '学生终端'),
    deviceRole,
    terminalMode: normalizeTerminalMode(device.terminalMode, 'shared'),
    boundStudentId: String(device.boundStudentId || ''),
    allowedStudentIds: deviceRole === 'teacher'
      ? teacherStudentIds
      : (normalizeTerminalMode(device.terminalMode, 'shared') === 'personal' && device.boundStudentId ? [String(device.boundStudentId)] : []),
    allowedAllStudents: deviceRole === 'teacher',
  };
}

function requireAuth(request, response) {
  const auth = authContext(request);
  if (!auth) {
    sendJson(response, 401, { ok: false, message: 'Unauthorized' });
    return false;
  }
  const locked = licenseRequiredPayload('学生终端协作服务');
  if (locked) {
    sendJson(response, 402, locked);
    return false;
  }
  request.authContext = auth;
  return true;
}

function isStudentAllowed(request, studentId) {
  const auth = request.authContext;
  if (!auth || auth.type === 'admin') return true;
  if (auth.type === 'device' && auth.deviceRole === 'teacher') return true;
  if (auth.type === 'student_session') return String(auth.studentId) === String(studentId);
  if (auth.type === 'device' && auth.terminalMode === 'shared') return false;
  return auth.allowedStudentIds.includes(String(studentId));
}

function requireStudentAccess(request, response, studentId) {
  if (!requireAuth(request, response)) return false;
  if (!isStudentAllowed(request, studentId)) {
    sendJson(response, 403, { ok: false, message: '当前设备没有访问该学生档案的权限。' });
    return false;
  }
  return true;
}

function findStudent(studentId) {
  return readStudentsIndex().find((student) => String(student.id) === String(studentId));
}

let studentPortableMigrationManager;

function portableMigrationManager() {
  if (!studentPortableMigrationManager) {
    studentPortableMigrationManager = createStudentPortableMigrationManager({
      runBackground: (work) => projectArchiveRuntime.track(work),
      rootDir: path.join(app.getPath('userData'), 'student-portable-migrations'),
      resolveStudentRoot: (student) => student.rootPath || getStudentRootDir(student.name),
      resolveProjectRoot: (project) => project.projectRootPath || project.rootPath || '',
    });
  }
  return studentPortableMigrationManager;
}

function handlePortableMigrationCreate(request, response, studentId) {
  if (!requireStudentAccess(request, response, studentId)) return;
  const student = findStudent(studentId);
  if (!student) {
    sendJson(response, 404, { ok: false, message: '未找到指定学生档案。' });
    return;
  }
  const session = portableMigrationManager().create(student, readProjects().map(normalizeProject));
  sendJson(response, 202, {
    ...session,
    statusUrl: `/api/students/${encodeURIComponent(studentId)}/portable-migrations/${session.sessionId}`,
    downloadUrl: `/api/students/${encodeURIComponent(studentId)}/portable-migrations/${session.sessionId}/download`,
  });
}

function handlePortableMigrationStatus(request, response, studentId, sessionId) {
  if (!requireStudentAccess(request, response, studentId)) return;
  const session = portableMigrationManager().requireSession(sessionId, studentId);
  if (!session) {
    sendJson(response, 404, { ok: false, message: '迁移会话不存在或已经过期。' });
    return;
  }
  sendJson(response, 200, portableMigrationManager().publicSession(session));
}

function handlePortableMigrationDownload(request, response, studentId, sessionId) {
  if (!requireStudentAccess(request, response, studentId)) return;
  const session = portableMigrationManager().requireSession(sessionId, studentId);
  if (!session) {
    sendJson(response, 404, { ok: false, message: '迁移会话不存在或已经过期。' });
    return;
  }
  if (session.status !== 'ready' || !fs.existsSync(session.filePath)) {
    sendJson(response, 409, { ok: false, status: session.status, message: session.message });
    return;
  }
  response.writeHead(200, {
    'Content-Type': 'application/zip',
    'Content-Length': session.bytes,
    'Content-Disposition': `attachment; filename="student-${encodeURIComponent(studentId)}.edu-migration.zip"`,
    'X-Edu-Content-Sha256': session.sha256,
    'Access-Control-Allow-Origin': '*',
  });
  fs.createReadStream(session.filePath).pipe(response);
}

function handleHealth(_request, response) {
  const collaborationState = readCollaborationState();
  const identity = getHostIdentity();
  sendJson(response, 200, {
    ok: true,
    version: APP_VERSION,
    hostId: identity.hostId,
    dataGeneration: hostDataGenerationId(),
    projectMaterialProtocolVersion: 1,
    hostName: os.hostname(),
    projectUploadRecoveryIssueCount: projectUploadRecoveryIssues.length,
    port: getHostServicePort(),
    collaborationNodeId: collaborationState.node.nodeId,
    collaborationProtocolVersion: DIRECT_PROTOCOL_VERSION,
    license: publicLicenseStatus(),
  });
}

function studentTerminalProgress(records = [], state = {}) {
  return buildStudentTerminalProgress(records, state, { normalizeStatus: normalizeUploadStatus });
}

const terminalFileStatsCache = new Map();
const TERMINAL_FILE_STATS_TTL_MS = 30_000;

function immediateTick() {
  return new Promise((resolve) => setImmediate(resolve));
}

async function collectTerminalDirectoryStats(rootPath, markdownOnly = false) {
  const result = { fileCount: 0, totalBytes: 0 };
  if (!rootPath || !fs.existsSync(rootPath)) return result;
  const pending = [rootPath];
  let visited = 0;
  while (pending.length) {
    const current = pending.pop();
    let entries = [];
    try { entries = fs.readdirSync(current, { withFileTypes: true }); } catch { continue; }
    for (const entry of entries) {
      const full = path.join(current, entry.name);
      if (entry.isDirectory()) {
        pending.push(full);
      } else if (!markdownOnly || entry.name.toLowerCase().endsWith('.md')) {
        result.fileCount += 1;
        try { result.totalBytes += fs.statSync(full).size; } catch {}
      }
      visited += 1;
      if (visited % 100 === 0) await immediateTick();
    }
  }
  return result;
}

function terminalFileStats(student, records, progress) {
  const rawPath = student.rawPath || getRawDir(student.name);
  const summaryPath = student.summaryPath || getSummaryDir(student.name);
  const key = `${student.id}|${rawPath}|${summaryPath}`;
  const current = terminalFileStatsCache.get(key);
  const now = Date.now();
  if (!current || (!current.scanning && now - current.updatedAt > TERMINAL_FILE_STATS_TTL_MS)) {
    const next = current || { rawFileCount: 0, rawTotalBytes: 0, archiveFileCount: 0, archiveTotalBytes: 0, updatedAt: 0 };
    next.scanning = true;
    terminalFileStatsCache.set(key, next);
    Promise.all([
      collectTerminalDirectoryStats(rawPath, false),
      collectTerminalDirectoryStats(summaryPath, true),
    ]).then(([raw, archive]) => {
      terminalFileStatsCache.set(key, {
        rawFileCount: raw.fileCount,
        rawTotalBytes: raw.totalBytes,
        archiveFileCount: archive.fileCount,
        archiveTotalBytes: archive.totalBytes,
        updatedAt: Date.now(),
        scanning: false,
      });
    }).catch(() => {
      next.updatedAt = Date.now();
      next.scanning = false;
    });
  }
  const fallbackRawCount = new Set(records.map((record) => String(record.targetPath || record.sourcePath || record.id || '')).filter(Boolean)).size;
  const value = terminalFileStatsCache.get(key) || {};
  return {
    rawFileCount: Number(value.updatedAt ? value.rawFileCount : fallbackRawCount),
    rawTotalBytes: Number(value.updatedAt ? value.rawTotalBytes : 0),
    archiveFileCount: Number(value.updatedAt ? value.archiveFileCount : progress.knowledgeAssetCount || 0),
    archiveTotalBytes: Number(value.updatedAt ? value.archiveTotalBytes : 0),
    fileStatsReady: Boolean(value.updatedAt && !value.scanning),
  };
}

function terminalStudentRecord(student) {
  const records = readUploadRecords().filter((record) => String(record.studentId) === String(student.id));
  const materials = readStudentMaterials(student);
  const digestLedger = materials.length ? materials : records;
  const state = readStudentDigestState(student);
  const progress = studentTerminalProgress(records, state);
  const fileStats = terminalFileStats(student, records, progress);
  return {
    ...student,
    loginQrPayload: studentLoginQrPayload(student.loginId),
    ...fileStats,
    pendingDigestCount: digestLedger.filter((record) => normalizeUploadStatus(record.status) === 'pending_digest').length,
    submittedDigestCount: digestLedger.filter((record) => ['submitted', 'digesting'].includes(normalizeUploadStatus(record.status))).length,
    processedDigestCount: digestLedger.filter((record) => normalizeUploadStatus(record.status) === 'processed').length,
    lastDigestAt: state.lastDigestAt || '',
    digestStatus: state.status || 'idle',
    digestMessage: state.message || '',
    progress,
    submittedTodayCount: progress.submittedTodayCount,
    recentUploadCount7: progress.recentUploadCount7,
    previousUploadCount7: progress.previousUploadCount7,
    recentUploadTrend: progress.recentTrend,
    activeDays30: progress.activeDays30,
    knowledgeAssetCount: progress.knowledgeAssetCount,
    newSinceLastDigestCount: progress.newSinceLastDigestCount,
    lastUploadAt: progress.lastUploadAt,
  };
}

function teacherTerminalStudentRecord(student) {
  const record = terminalStudentRecord(student);
  return {
    id: String(record.id || ''),
    name: String(record.name || ''),
    grade: String(record.grade || ''),
    rawFileCount: Number(record.rawFileCount || 0),
    rawTotalBytes: Number(record.rawTotalBytes || 0),
    archiveFileCount: Number(record.archiveFileCount || 0),
    archiveTotalBytes: Number(record.archiveTotalBytes || 0),
    fileStatsReady: Boolean(record.fileStatsReady),
    pendingDigestCount: Number(record.pendingDigestCount || 0),
    submittedDigestCount: Number(record.submittedDigestCount || 0),
    processedDigestCount: Number(record.processedDigestCount || 0),
    lastDigestAt: String(record.lastDigestAt || ''),
    digestStatus: String(record.digestStatus || 'idle'),
    digestMessage: String(record.digestMessage || ''),
    progress: record.progress || {},
    submittedTodayCount: Number(record.submittedTodayCount || 0),
    recentUploadCount7: Number(record.recentUploadCount7 || 0),
    recentUploadTrend: Number(record.recentUploadTrend || 0),
    activeDays30: Number(record.activeDays30 || 0),
    knowledgeAssetCount: Number(record.knowledgeAssetCount || 0),
    newSinceLastDigestCount: Number(record.newSinceLastDigestCount || 0),
    lastUploadAt: String(record.lastUploadAt || ''),
  };
}

function studentSessionStatePayload(session, student) {
  const requestLike = { authContext: { type: 'student_session', studentId: String(student.id), allowedStudentIds: [String(student.id)] } };
  const projects = readProjects().map(normalizeProject).filter((project) => projectAllowed(requestLike, project));
  const record = terminalStudentRecord(student);
  return {
    session: publicStudentSession(session),
    student: record,
    students: [record],
    projects,
  };
}

function loginIdFromRequestValue(value) {
  const input = String(value || '').trim();
  if (input.startsWith('{')) {
    try {
      const payload = JSON.parse(input);
      if (payload?.type === 'AI_EDU_STUDENT_LOGIN') return normalizeStudentLoginId(payload.loginId);
    } catch {}
  }
  return normalizeStudentLoginId(input);
}

async function handleStudentSessionLogin(request, response) {
  if (!requireAuth(request, response)) return;
  if (request.authContext?.type !== 'device') {
    sendJson(response, 403, { ok: false, message: '请使用已配对学生终端进入学生档案。' });
    return;
  }
  try {
    const body = await parseJsonBody(request);
    const loginId = loginIdFromRequestValue(body.loginId || body.qrPayload);
    if (!isValidStudentLoginId(loginId)) {
      sendJson(response, 400, { ok: false, message: '学生 ID 格式或校验位不正确，请重新输入或扫码。' });
      return;
    }
    const students = readStudentsIndex();
    const student = students.find((item) => normalizeStudentLoginId(item.loginId) === loginId);
    if (!student) {
      sendJson(response, 404, { ok: false, message: '没有找到该学生 ID，请向教师或家长核对。' });
      return;
    }
    const devices = readDevices();
    const index = devices.findIndex((item) => String(item.id) === String(request.authContext.deviceId));
    if (index < 0) {
      sendJson(response, 404, { ok: false, message: '没有找到当前终端设备。' });
      return;
    }
    const terminalMode = normalizeTerminalMode(devices[index].terminalMode, 'shared');
    if (terminalMode === 'personal' && devices[index].boundStudentId && String(devices[index].boundStudentId) !== String(student.id)) {
      sendJson(response, 409, { ok: false, message: '该个人终端已经绑定其他学生，请先在系统设置中解除绑定。' });
      return;
    }
    if (terminalMode === 'personal' && !devices[index].boundStudentId) {
      devices[index] = {
        ...devices[index],
        boundStudentId: String(student.id),
        allowedStudentIds: [String(student.id)],
        allowedAllStudents: false,
        autoAuthorizeNewStudents: false,
        modeUpdatedAt: new Date().toISOString(),
      };
      writeDevices(devices);
    }
    const device = devices[index];
    const created = createStudentSession(device, student);
    appendHostTimeline({ type: 'student_session_started', title: 'Student session started', deviceId: device.id, studentId: student.id, studentName: student.name, detail: terminalMode });
    sendJson(response, 200, { ok: true, token: created.token, terminalMode, ...studentSessionStatePayload(created.session, student), message: `已进入 ${student.name} 的学习空间。` });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `进入学生档案失败：${error.message}` });
  }
}

function handleStudentSessionAuto(request, response) {
  if (!requireAuth(request, response)) return;
  if (request.authContext?.type !== 'device') {
    sendJson(response, 403, { ok: false, message: '请使用已配对学生终端。' });
    return;
  }
  const device = readDevices().find((item) => String(item.id) === String(request.authContext.deviceId));
  if (!device || normalizeTerminalMode(device.terminalMode, 'shared') !== 'personal' || !device.boundStudentId) {
    sendJson(response, 409, { ok: false, requiresLogin: true, message: '个人终端尚未绑定学生，请扫码或输入学生 ID。' });
    return;
  }
  const student = findStudent(device.boundStudentId);
  if (!student) {
    sendJson(response, 404, { ok: false, requiresLogin: true, message: '原绑定学生已经不存在，请重新绑定。' });
    return;
  }
  const created = createStudentSession(device, student);
  sendJson(response, 200, { ok: true, token: created.token, terminalMode: 'personal', ...studentSessionStatePayload(created.session, student), message: `已自动进入 ${student.name} 的学习空间。` });
}

function handleStudentSessionMe(request, response) {
  if (!requireAuth(request, response)) return;
  if (request.authContext?.type !== 'student_session') {
    sendJson(response, 401, { ok: false, requiresLogin: true, message: '请先扫码或输入学生 ID。' });
    return;
  }
  const student = findStudent(request.authContext.studentId);
  const session = [...studentSessions.values()].find((item) => item.sessionId === request.authContext.sessionId);
  if (!student || !session) {
    sendJson(response, 401, { ok: false, requiresLogin: true, message: '学生会话已结束，请重新进入。' });
    return;
  }
  sendJson(response, 200, { ok: true, ...studentSessionStatePayload(session, student) });
}

function handleStudentSessionLogout(request, response) {
  if (!requireAuth(request, response)) return;
  if (request.authContext?.type === 'student_session') {
    studentSessions.delete(request.authContext.sessionTokenHash);
    appendHostTimeline({ type: 'student_session_ended', title: 'Student session ended', deviceId: request.authContext.deviceId, studentId: request.authContext.studentId });
  }
  sendJson(response, 200, { ok: true, message: '已退出当前学生。' });
}

function studentTerminalAgentCapturePayload(device, studentId) {
  const settings = agentMemoryStore().getSettings(String(studentId));
  return {
    schema: 'edu-manager.student-terminal-agent-capture.v1',
    supported: true,
    personalModeRequired: true,
    enabled: Boolean(
      device?.agentCaptureEnabled
      && device?.agentCaptureEpoch
      && String(device?.agentCaptureStudentId || '') === String(studentId)
      && normalizeTerminalMode(device?.terminalMode, 'shared') === 'personal'
    ),
    studentId: String(studentId),
    deviceId: String(device?.id || ''),
    allowedAgents: [...AUTO_CAPTURE_AGENT_IDS],
    authorizedAt: String(device?.agentCaptureAuthorizedAt || ''),
    captureEpoch: String(device?.agentCaptureEpoch || ''),
    excludes: ['historical_sessions', 'system_prompts', 'tool_secrets', 'task_center_context'],
    hostArchiveEnabled: Boolean(settings.automationEnabled),
  };
}

async function handleStudentTerminalAgentCaptureAuthorization(request, response) {
  if (!requireAuth(request, response)) return;
  try {
    const device = studentTerminalCaptureDevice(request);
    if (request.method === 'GET') {
      sendJson(response, 200, { ok: true, capture: studentTerminalAgentCapturePayload(device, request.authContext.studentId) });
      return;
    }
    const body = await parseJsonBody(request);
    const enabled = Boolean(body.enabled);
    const devices = readDevices();
    const index = devices.findIndex((item) => String(item.id) === String(device.id));
    if (index < 0) throw new Error('没有找到当前个人终端设备。');
    const keepEpoch = Boolean(
      enabled
      && devices[index].agentCaptureEnabled
      && String(devices[index].agentCaptureStudentId || '') === String(request.authContext.studentId)
      && devices[index].agentCaptureEpoch
      && devices[index].agentCaptureAuthorizedAt
    );
    devices[index] = {
      ...devices[index],
      capabilities: Array.from(new Set([...(Array.isArray(devices[index].capabilities) ? devices[index].capabilities : []), 'agent-lifecycle-capture-v1'])),
      agentCaptureEnabled: enabled,
      agentCaptureStudentId: enabled ? String(request.authContext.studentId) : '',
      agentCaptureEpoch: enabled ? (keepEpoch ? String(devices[index].agentCaptureEpoch) : crypto.randomUUID()) : '',
      agentCaptureAuthorizedAt: enabled
        ? (keepEpoch ? String(devices[index].agentCaptureAuthorizedAt || '') : new Date().toISOString())
        : String(devices[index].agentCaptureAuthorizedAt || ''),
      agentCaptureDisabledAt: enabled ? '' : new Date().toISOString(),
    };
    writeDevices(devices);
    if (enabled) {
      agentMemoryStore().updateSettings(String(request.authContext.studentId), {
        automationEnabled: true,
        allowedAgents: AUTO_CAPTURE_AGENT_IDS,
      });
    }
    appendHostTimeline({
      type: 'student_terminal_agent_capture_changed',
      title: 'Student terminal Agent capture changed',
      detail: `${devices[index].id}: ${enabled ? 'enabled' : 'disabled'}`,
      deviceId: devices[index].id,
      studentId: String(request.authContext.studentId),
    });
    sendJson(response, 200, {
      ok: true,
      capture: studentTerminalAgentCapturePayload(devices[index], request.authContext.studentId),
      message: enabled
        ? '已授权此个人 Windows 学生终端采集后续轮次；已有会话从下一条提问开始，不扫描历史。'
        : '已停止此个人 Windows 学生终端的自动会话采集；已有归档不会删除。',
    });
  } catch (error) {
    sendJson(response, /个人|绑定|授权|范围/.test(error.message) ? 403 : 400, { ok: false, message: error.message });
  }
}

async function handleStudentTerminalLifecycleEvent(request, response) {
  if (!requireAuth(request, response)) return;
  try {
    const body = JSON.parse((await readRequestBuffer(request, 256 * 1024)).toString('utf8') || '{}');
    const result = processStudentTerminalLifecycleEnvelope(request, body);
    sendJson(response, 200, { ok: true, result });
  } catch (error) {
    sendJson(response, /个人|绑定|授权|范围|学生/.test(error.message) ? 403 : 400, { ok: false, message: error.message });
  }
}

async function handleDeviceMode(request, response) {
  if (!requireAuth(request, response)) return;
  if (request.authContext?.type !== 'device') {
    sendJson(response, 403, { ok: false, message: '只有学生终端可以切换终端模式。' });
    return;
  }
  const devices = readDevices();
  const index = devices.findIndex((item) => String(item.id) === String(request.authContext.deviceId));
  if (index < 0) {
    sendJson(response, 404, { ok: false, message: '没有找到当前终端设备。' });
    return;
  }
  if (request.method === 'GET') {
    sendJson(response, 200, { ok: true, device: publicDevice(devices[index]) });
    return;
  }
  try {
    const body = await parseJsonBody(request);
    const terminalMode = normalizeTerminalMode(body.terminalMode, 'shared');
    devices[index] = {
      ...devices[index],
      terminalMode,
      boundStudentId: terminalMode === 'personal' ? String(devices[index].boundStudentId || '') : '',
      allowedStudentIds: terminalMode === 'personal' && devices[index].boundStudentId ? [String(devices[index].boundStudentId)] : [],
      allowedAllStudents: terminalMode === 'shared',
      autoAuthorizeNewStudents: terminalMode === 'shared',
      agentCaptureEnabled: terminalMode === 'personal' ? Boolean(devices[index].agentCaptureEnabled) : false,
      agentCaptureStudentId: terminalMode === 'personal' ? String(devices[index].agentCaptureStudentId || '') : '',
      agentCaptureDisabledAt: terminalMode === 'personal' ? String(devices[index].agentCaptureDisabledAt || '') : new Date().toISOString(),
      modeUpdatedAt: new Date().toISOString(),
    };
    clearStudentSessionsForDevice(devices[index].id);
    writeDevices(devices);
    notify('onNativeHostServiceChanged', getHostServiceStatus());
    sendJson(response, 200, { ok: true, device: publicDevice(devices[index]), message: terminalMode === 'shared' ? '已切换为共享终端。' : (devices[index].boundStudentId ? '已切换为个人终端。' : '已切换为个人终端，请输入学生 ID 完成绑定。') });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `切换终端模式失败：${error.message}` });
  }
}

function handleStudents(request, response) {
  if (!requireAuth(request, response)) return;
  const auth = request.authContext;
  const isTeacherTerminal = auth.type === 'device' && auth.deviceRole === 'teacher';
  const students = readStudentsIndex()
    .filter((student) => isStudentAllowed(request, student.id))
    .map(isTeacherTerminal ? teacherTerminalStudentRecord : terminalStudentRecord);
  const requiresStudentLogin = auth.type === 'device' && auth.terminalMode === 'shared' && !isTeacherTerminal;
  const requiresBinding = auth.type === 'device' && auth.terminalMode === 'personal' && !auth.boundStudentId;
  sendJson(response, 200, {
    ok: true,
    students,
    authorization: {
      type: auth.type,
      deviceId: auth.deviceId || '',
      deviceName: auth.deviceName || '',
      deviceRole: auth.deviceRole || (auth.type === 'admin' ? 'admin' : 'student'),
      terminalMode: auth.terminalMode || '',
      requiresApproval: false,
      requiresStudentLogin,
      requiresBinding,
      allowedStudentCount: auth.type === 'admin' ? readStudentsIndex().length : students.length,
    },
  });
}

function handleStudentCourses(request, response, studentId) {
  if (!requireStudentAccess(request, response, studentId)) return;
  const student = findStudentByKey(studentId);
  if (!student) {
    sendJson(response, 404, { ok: false, message: '未找到当前学生。' });
    return;
  }
  const state = courseCatalogStore().state();
  const courses = courseCatalogStore().coursesForStudent(student)
    .filter(courseAllowedByCurrentPlan)
    .map((course) => ({
      ...course,
      coverUrl: `/api/course-assets/${encodeURIComponent(path.basename(course.coverAsset))}`,
    }));
  sendJson(response, 200, {
    ok: true,
    schemaVersion: 1,
    catalogVersion: state.catalog?.catalogVersion || '',
    studentId: String(student.id),
    courses,
    disclaimer: '打开第三方课程或采集屏幕资料不代表课程完成、正确率或学情结论。',
  });
}

function handleCourseAsset(response, assetName) {
  const filePath = courseCatalogStore().assetPathByFilename(assetName);
  if (!filePath) {
    sendJson(response, 404, { ok: false, message: '课程封面不存在。' });
    return;
  }
  const extension = path.extname(filePath).toLowerCase();
  const contentType = extension === '.png' ? 'image/png' : extension === '.webp' ? 'image/webp' : 'image/jpeg';
  response.writeHead(200, {
    'Content-Type': contentType,
    'Content-Length': fs.statSync(filePath).size,
    'Cache-Control': 'public, max-age=86400, immutable',
    'Content-Security-Policy': "default-src 'none'",
    'X-Content-Type-Options': 'nosniff',
  });
  fs.createReadStream(filePath).pipe(response);
}

function courseUploadAttribution(url, student) {
  const courseId = String(url?.searchParams?.get('courseId') || '').trim();
  if (!courseId) return {};
  const course = courseCatalogStore().findCourse(courseId, student);
  if (!course) throw new Error('课程已下架、未分配给当前学生或目录版本无效。');
  if (!courseAllowedByCurrentPlan(course)) throw new Error('当前授权不能使用机构自选课程。');
  const requestedUrl = String(url?.searchParams?.get('courseUrl') || course.url).trim();
  const navigation = safeCourseNavigation(requestedUrl, course.allowedHosts);
  if (!navigation.ok) throw new Error(navigation.message);
  return {
    courseId: course.courseId,
    courseProvider: course.provider,
    courseUrl: navigation.url,
    courseStartedAt: String(url?.searchParams?.get('courseStartedAt') || '').slice(0, 80),
    courseCompletedAt: String(url?.searchParams?.get('courseCompletedAt') || '').slice(0, 80),
  };
}

function upsertRemoteCaptureSession(remoteCapture, item, archiveStatus) {
  if (!remoteCapture?.session?.id || !remoteCapture.session.studentId || !item?.id) return null;
  const incoming = remoteCapture.session;
  const current = readCaptureSessionDetail(incoming.id);
  if (current && String(current.studentId || '') !== String(incoming.studentId)) throw new Error('远端采集会话学生归属不一致。');
  if (current && String(current.projectId || '') !== String(incoming.projectId || '')) throw new Error('远端采集会话项目归属不一致。');
  if (current && String(current.platform || '') && String(current.platform) !== String(incoming.platform || '')) throw new Error('远端采集会话设备来源不一致。');
  if (current?.deviceId && incoming.deviceId && String(current.deviceId) !== String(incoming.deviceId)) throw new Error('远端采集会话设备身份不一致。');
  const existingItems = Array.isArray(current?.items) ? current.items : [];
  if (existingItems.some((entry) => String(entry.id) === String(item.id))) return current;
  const normalizedItem = {
    ...item,
    hashAlgorithm: String(item.hashAlgorithm || (item.contentHash ? 'sha1' : '')),
    contentHash: String(item.contentHash || ''),
    archiveStatus,
  };
  const next = {
    ...incoming,
    ...current,
    id: String(incoming.id),
    platform: String(current?.platform || incoming.platform || 'windows-student-terminal'),
    deviceId: String(current?.deviceId || incoming.deviceId || ''),
    sourceType: String(current?.sourceType || incoming.sourceType || 'screen'),
    sourceName: String(current?.sourceName || incoming.sourceName || '学生端屏幕采集'),
    status: 'receiving',
    archiveStatus,
    startedAt: String(current?.startedAt || incoming.courseStartedAt || item.capturedAt || new Date().toISOString()),
    lastCapturedAt: String(item.capturedAt || current?.lastCapturedAt || ''),
    screenshotCount: existingItems.length + 1,
    inboxPath: String(current?.inboxPath || path.dirname(item.path || '')),
    items: [...existingItems, normalizedItem].sort((left, right) => String(left.capturedAt || '').localeCompare(String(right.capturedAt || ''))),
  };
  persistCaptureSession(next, normalizedItem);
  appendCaptureItem(captureCenterRootPath(), next, normalizedItem);
  captureTimelineMigratedStudents.delete(String(next.studentId));
  return next;
}

async function handleRemoteCaptureSessionComplete(request, response, studentId, sessionId) {
  if (!requireStudentAccess(request, response, studentId)) return;
  try {
    const body = await parseJsonBody(request);
    const student = findStudent(studentId);
    if (!student) return sendJson(response, 404, { ok: false, message: '未找到学生。' });
    const current = readCaptureSessionDetail(sessionId);
    if (!current || String(current.studentId || '') !== String(student.id)) {
      return sendJson(response, 404, { ok: false, message: '尚未收到该学生采集会话的截图。' });
    }
    const projectId = String(body.projectId || current.projectId || '');
    let project = null;
    if (projectId) {
      project = readProjects().map(normalizeProject).find((item) => String(item.id) === projectId);
      if (!project || !projectAllowed(request, project) || !(project.studentIds || []).map(String).includes(String(student.id)) || ['sealed', 'archived'].includes(String(project.status || ''))) {
        return sendJson(response, 403, { ok: false, message: '采集会话项目归属已变化，未进入自动整理。' });
      }
    }
    const expectedItemCount = Math.max(0, Number(body.expectedItemCount || 0));
    const receivedItemCount = Array.isArray(current.items) ? current.items.length : 0;
    if (expectedItemCount && receivedItemCount < expectedItemCount) {
      return sendJson(response, 409, {
        ok: false,
        code: 'CAPTURE_SESSION_INCOMPLETE',
        receivedItemCount,
        expectedItemCount,
        message: `采集会话仍在接收：已收到 ${receivedItemCount}/${expectedItemCount} 张，学生端将自动补送。`,
      });
    }
    const endedAtValue = Date.parse(String(body.endedAt || body.courseCompletedAt || ''));
    const completed = persistCaptureSession({
      ...current,
      status: 'completed',
      endedAt: Number.isFinite(endedAtValue) ? new Date(endedAtValue).toISOString() : new Date().toISOString(),
      courseCompletedAt: String(body.courseCompletedAt || current.courseCompletedAt || ''),
      sourceName: String(current.sourceName || '学生端屏幕采集'),
      archiveStatus: project ? 'project_raw' : 'student_raw',
      projectId: project ? String(project.id) : '',
      projectName: project?.name || '',
      expectedItemCount,
      remoteCompletionReceivedAt: new Date().toISOString(),
    });
    const scheduled = scheduleCaptureTimelineSemanticProcessing(completed, 2_000);
    notifyCaptureChanged(completed);
    return sendJson(response, 200, {
      ok: Boolean(scheduled?.ok),
      sessionId: completed.id,
      receivedItemCount,
      semanticProcessing: scheduled,
      message: scheduled?.ok ? '采集会话已完整送达，主机将在后台自动识别、归纳并进入资料消化。' : scheduled?.message,
    });
  } catch (error) {
    return sendJson(response, 400, { ok: false, message: `完成远端采集会话失败：${error.message}` });
  }
}

function projectAllowed(request, project) {
  if (!request.authContext || request.authContext.type === 'admin') return true;
  if (request.authContext.type === 'device' && request.authContext.deviceRole === 'teacher') return true;
  if (request.authContext.type === 'device' && request.authContext.terminalMode === 'shared') return false;
  if (request.authContext.type === 'agent_grant') {
    return (request.authContext.allowedProjectIds || []).includes(String(project.id));
  }
  const allowed = new Set(request.authContext.allowedStudentIds || []);
  return (project.studentIds || []).some((id) => allowed.has(String(id)));
}

function handleAssets(request, response) {
  if (!requireAuth(request, response)) return;
  const summary = assetIndexSummary();
  const allowedStudentIds = request.authContext.type === 'admin'
    ? null
    : new Set(request.authContext.allowedStudentIds || []);
  const assets = allowedStudentIds
    ? summary.assets.filter((asset) => (asset.linkedStudents || []).some((id) => allowedStudentIds.has(String(id))))
    : summary.assets;
  sendJson(response, 200, { ...summary, assets, total: assets.length });
}

function handleProjects(request, response) {
  if (!requireAuth(request, response)) return;
  const projects = readProjects().map(normalizeProjectMetadata).filter((project) => projectAllowed(request, project));
  sendJson(response, 200, { ok: true, hostId: getHostIdentity().hostId, dataGeneration: hostDataGenerationId(),
    projectMaterialProtocolVersion: 1,
    projects: projects.map((project) => publicRemoteProject(project, request.authContext, MAX_UPLOAD_BYTES)) });
}

function authorizedProjectMaterialRead(request, response, projectId) {
  if (!requireAuth(request, response)) return null;
  const project = readProjects().map(normalizeProjectMetadata)
    .find((item) => String(item.id) === String(projectId));
  if (!project) { sendJson(response, 404, { ok: false, code: 'project_missing' }); return null; }
  if (!canReadProjectMaterials(request.authContext) || !projectAllowed(request, project)) {
    sendJson(response, 403, { ok: false, code: 'project_forbidden' }); return null;
  }
  return project;
}

function handleProjectMaterialCapabilities(request, response, projectId) {
  const project = authorizedProjectMaterialRead(request, response, projectId);
  if (!project) return;
  sendJson(response, 200, { ok: true, hostId: getHostIdentity().hostId,
    dataGeneration: hostDataGenerationId(),
    capabilities: projectMaterialCapabilities(project, request.authContext, MAX_UPLOAD_BYTES) });
}

async function handleProjectKnowledgeDocument(request, response, projectId, url) {
  const project = authorizedProjectMaterialRead(request, response, projectId);
  if (!project) return;
  if (!isWorkspaceMaterialProject(project)) {
    sendJson(response, 409, { ok: false, code: 'unsupported_storage_mode' });
    return;
  }
  try {
    const documentId = String(url.searchParams.get('documentId') || '');
    const authorize = async (scope = {}) => {
      const current = readProjects().map(normalizeProjectMetadata)
        .find((item) => String(item.id) === String(project.id));
      if (!current || !isWorkspaceMaterialProject(current) || !projectAllowed(request, current)) return false;
      if (!scope.materialId) return true;
      const record = readProjectMaterialIndexSync(current).materials
        .find((item) => item.materialId === scope.materialId);
      return Boolean(record && materialVisibleToViewer(record, request.authContext));
    };
    const result = await createProjectMaterialAccess(project, { authorize }).readKnowledge(documentId);
    sendJson(response, 200, { ...result, hostId: getHostIdentity().hostId,
      dataGeneration: hostDataGenerationId() });
  } catch (error) {
    const forbidden = error.code === 'forbidden';
    sendJson(response, forbidden ? 403 : ['invalid_path', 'file_too_large'].includes(error.code) ? 400 : 409,
      { ok: false, code: error.code || 'knowledge_read_failed',
        message: `读取项目知识失败：${error.message}` });
  }
}

function handleProjectMaterialList(request, response, projectId, url) {
  const project = authorizedProjectMaterialRead(request, response, projectId);
  if (!project) return;
  if (!isWorkspaceMaterialProject(project)) {
    sendJson(response, 409, { ok: false, code: 'unsupported_storage_mode',
      message: '此项目仍使用旧资料模式，主机尚不能提供统一资料列表。' });
    return;
  }
  try {
    const index = readProjectMaterialIndexSync(project);
    const projectedIndex = { ...index, categories: projectMaterialCategoryDefinitions(project, index) };
    const result = listProjectMaterialsForViewer(projectedIndex, request.authContext, {
      offset: url.searchParams.get('offset') ?? 0, limit: url.searchParams.get('limit') ?? 50,
      search: url.searchParams.get('search') || '', categoryId: url.searchParams.get('categoryId') || '',
      adoption: url.searchParams.get('adoption') || '',
    });
    sendJson(response, 200, { ok: true, hostId: getHostIdentity().hostId,
      dataGeneration: hostDataGenerationId(), ...result });
  } catch (error) {
    const badQuery = ['invalid_pagination', 'invalid_search', 'invalid_adoption', 'invalid_category'].includes(error.code);
    sendJson(response, badQuery ? 400 : 409, { ok: false,
      code: badQuery ? error.code : 'material_registry_unavailable',
      message: badQuery ? error.message : '项目资料登记当前无法读取，请在主机核对。' });
  }
}

function handleProjectMaterialRemoteView(request, response, projectId, url) {
  const project = authorizedProjectMaterialRead(request, response, projectId);
  if (!project) return;
  if (!isWorkspaceMaterialProject(project)) {
    sendJson(response, 409, { ok: false, code: 'unsupported_storage_mode',
      message: '此项目仍使用旧资料模式，主机尚不能提供统一资料视图。' });
    return;
  }
  try {
    const index = readProjectMaterialIndexSync(project);
    const projectedIndex = { ...index, categories: projectMaterialCategoryDefinitions(project, index) };
    const result = projectMaterialRemoteView(project, projectedIndex, request.authContext, {
      view: url.searchParams.get('view') || 'materials', offset: url.searchParams.get('offset') ?? 0,
      limit: url.searchParams.get('limit') ?? 50, search: url.searchParams.get('search') || '',
      categoryId: url.searchParams.get('categoryId') || '',
    });
    sendJson(response, 200, { ok: true, hostId: getHostIdentity().hostId,
      dataGeneration: hostDataGenerationId(), ...result });
  } catch (error) {
    const badQuery = ['invalid_pagination', 'invalid_search', 'invalid_category', 'invalid_view'].includes(error.code);
    sendJson(response, badQuery ? 400 : 409, { ok: false,
      code: badQuery ? error.code : 'material_registry_unavailable',
      message: badQuery ? error.message : '项目资料视图当前无法读取，请稍后重试。' });
  }
}

function projectMaterialActorId(auth) {
  if (auth?.type === 'admin') return 'host-admin';
  if (auth?.type === 'device') return `device:${String(auth.deviceId || 'unknown')}`;
  if (auth?.type === 'student_session') return `student-session:${String(auth.studentId || 'unknown')}`;
  return 'unknown-principal';
}

function sendProjectClassificationError(response, error) {
  const badRequest = ['invalid_identity', 'invalid_version', 'invalid_revision', 'invalid_batch',
    'duplicate_material', 'invalid_tags', 'tag_missing', 'invalid_classification_request',
    'unsafe_classification_instruction', 'invalid_classification_decision',
    'invalid_suggestion_status', 'invalid_pagination'].includes(error.code);
  const forbidden = error.code === 'forbidden';
  sendJson(response, forbidden ? 403 : badRequest ? 400 : 409, { ok: false,
    code: error.code || 'classification_unavailable',
    message: badRequest || forbidden ? error.message : '项目分类状态已变化或暂不可用，请刷新后重试。' });
}

function sendProjectAdoptionError(response, error) {
  const badRequest = ['invalid_identity', 'invalid_version', 'invalid_revision', 'invalid_batch',
    'duplicate_material', 'invalid_adoption'].includes(error.code);
  const forbidden = error.code === 'forbidden';
  sendJson(response, forbidden ? 403 : badRequest ? 400 : 409, { ok: false,
    code: error.code || 'adoption_unavailable',
    message: badRequest || forbidden ? error.message : '项目采用审核状态已变化或暂不可用，请刷新后重试。' });
}

function projectClassificationService(project) {
  return createProjectMaterialClassification(project, createProjectMaterialHost(project).store);
}

async function handleProjectClassificationSuggestions(request, response, projectId) {
  const project = authorizedProjectMaterialRead(request, response, projectId);
  if (!project) return;
  if (!isWorkspaceMaterialProject(project)) {
    sendJson(response, 409, { ok: false, code: 'unsupported_storage_mode' });
    return;
  }
  const access = projectMaterialAccessPolicy(project, request.authContext);
  if (!access.suggestionContributor) {
    sendJson(response, 403, { ok: false, code: 'forbidden', message: '当前身份不能提交此项目的分类建议。' });
    return;
  }
  try {
    const body = await parseJsonBody(request);
    const requestedItems = Array.isArray(body.items) ? body.items : [];
    const visibleMaterialIds = new Set(readProjectMaterialIndexSync(project).materials
      .filter((record) => materialVisibleToViewer(record, request.authContext))
      .map((record) => String(record.materialId)));
    if (requestedItems.some((item) => item && typeof item.materialId === 'string'
      && !visibleMaterialIds.has(String(item.materialId)))) {
      sendJson(response, 404, { ok: false, code: 'material_missing',
        message: '未找到可提交分类建议的项目资料。' });
      return;
    }
    const service = projectClassificationService(project);
    await service.ensureWorkspaceCategories();
    const result = await service.recordSuggestions(requestedItems, {
      actorId: projectMaterialActorId(request.authContext),
      ruleVersion: 'member-suggestion-v1',
      requestId: String(body.idempotencyKey || body.requestId || ''),
      source: 'member', canSuggest: true,
    });
    sendJson(response, 200, { ok: true, hostId: getHostIdentity().hostId,
      dataGeneration: hostDataGenerationId(), ...result });
  } catch (error) { sendProjectClassificationError(response, error); }
}

async function handleProjectClassificationSuggestionList(request, response, projectId, url) {
  const project = authorizedProjectMaterialRead(request, response, projectId);
  if (!project) return;
  if (!isWorkspaceMaterialProject(project)) {
    sendJson(response, 409, { ok: false, code: 'unsupported_storage_mode' });
    return;
  }
  try {
    const index = readProjectMaterialIndexSync(project);
    const visibleMaterialIds = new Set(index.materials
      .filter((record) => materialVisibleToViewer(record, request.authContext))
      .map((record) => String(record.materialId)));
    const result = await projectClassificationService(project).listSuggestions({
      status: String(url.searchParams.get('status') || 'pending'),
      offset: Number(url.searchParams.get('offset') ?? 0), limit: Number(url.searchParams.get('limit') ?? 50),
      materialIds: visibleMaterialIds,
    });
    sendJson(response, 200, { ok: true, hostId: getHostIdentity().hostId,
      dataGeneration: hostDataGenerationId(), ...result });
  } catch (error) { sendProjectClassificationError(response, error); }
}

async function handleProjectMaterialVersionDownload(request, response, projectId, materialId, versionText) {
  const project = authorizedProjectMaterialRead(request, response, projectId);
  if (!project) return;
  if (!isWorkspaceMaterialProject(project)) {
    sendJson(response, 409, { ok: false, code: 'unsupported_storage_mode' });
    return;
  }
  try {
    const version = Number(versionText);
    if (!Number.isSafeInteger(version) || version < 1) throw Object.assign(new Error('资料版本无效。'), { code: 'invalid_version' });
    const index = readProjectMaterialIndexSync(project);
    const record = index.materials.find((item) => item.materialId === materialId);
    if (!record || !materialVisibleToViewer(record, request.authContext)) {
      sendJson(response, 404, { ok: false, code: 'material_missing' });
      return;
    }
    const resolved = await createProjectMaterialHost(project).store.resolve(materialId, version);
    const currentProject = readProjects().map(normalizeProjectMetadata)
      .find((item) => String(item.id) === String(project.id));
    const currentRecord = currentProject && isWorkspaceMaterialProject(currentProject)
      ? readProjectMaterialIndexSync(currentProject).materials.find((item) => item.materialId === materialId) : null;
    if (!currentProject || !projectAllowed(request, currentProject)
      || !currentRecord || !materialVisibleToViewer(currentRecord, request.authContext)) {
      sendJson(response, 403, { ok: false, code: 'project_forbidden' });
      return;
    }
    const originalName = path.posix.basename(record.location.relativePath).replace(/[\r\n"]/g, '_');
    const extension = path.extname(originalName).slice(0, 16);
    const fallbackName = `project-material-${materialId}-v${version}${extension}`.replace(/[^A-Za-z0-9._-]/g, '_');
    response.writeHead(200, {
      'Content-Type': 'application/octet-stream', 'Content-Length': resolved.size,
      'Content-Disposition': `attachment; filename="${fallbackName}"; filename*=UTF-8''${encodeURIComponent(originalName)}`,
      'Cache-Control': 'private, no-store', 'Content-Security-Policy': "default-src 'none'",
      'X-Content-Type-Options': 'nosniff', 'X-Edu-Material-Id': resolved.materialId,
      'X-Edu-Material-Version': String(resolved.version), 'X-Edu-Material-Sha256': resolved.sha256,
    });
    fs.createReadStream(resolved.path).pipe(response);
  } catch (error) {
    if (!response.headersSent) sendJson(response,
      ['invalid_version', 'invalid_identity'].includes(error.code) ? 400
        : ['material_missing', 'version_missing'].includes(error.code) ? 404 : 409,
      { ok: false, code: error.code || 'material_download_failed',
        message: `读取指定资料版本失败：${error.message}` });
    else response.destroy(error);
  }
}

async function handleProjectClassificationBatch(request, response, projectId) {
  const project = authorizedProjectMaterialRead(request, response, projectId);
  if (!project) return;
  if (!isWorkspaceMaterialProject(project)) {
    sendJson(response, 409, { ok: false, code: 'unsupported_storage_mode' });
    return;
  }
  const access = projectMaterialAccessPolicy(project, request.authContext);
  if (!access.formalManager) {
    sendJson(response, 403, { ok: false, code: 'forbidden', message: '当前身份没有此项目的正式分类权限。' });
    return;
  }
  try {
    const body = await parseJsonBody(request);
    const service = projectClassificationService(project);
    await service.ensureWorkspaceCategories();
    const result = await service.applyBatch(body.items, {
      actorId: projectMaterialActorId(request.authContext),
      idempotencyKey: String(body.idempotencyKey || ''), canWrite: true,
    });
    sendJson(response, 200, { ok: true, hostId: getHostIdentity().hostId,
      dataGeneration: hostDataGenerationId(), ...result });
  } catch (error) { sendProjectClassificationError(response, error); }
}

