function handleStudentGrowthSummary(request, response, studentId) {
  if (!requireStudentAccess(request, response, studentId)) return;
  const student = findStudent(studentId);
  if (!student) {
    sendJson(response, 404, { ok: false, message: '未找到学生' });
    return;
  }
  try {
    const indexFile = growthIndexPath(toHostStudent(student));
    const savedIndex = fs.existsSync(indexFile) ? safeReadJson(indexFile, {}) : {};
    const index = currentGrowthReadView({ student, index: savedIndex, ...growthReadSources(toHostStudent(student)), visibleOnly: true });
    sendJson(response, 200, buildStudentGrowthSummary(student, index));
  } catch (error) {
    sendJson(response, 400, { ok: false, message: error.message });
  }
}

function terminalLearningStudent(request, response, studentId = '') {
  if (!requireAuth(request, response)) return null;
  const auth = request.authContext;
  const isTeacher = auth.type === 'device' && auth.deviceRole === 'teacher';
  if (auth.type !== 'student_session' && !isTeacher) {
    sendJson(response, 403, { ok: false, code: 'STUDENT_SESSION_REQUIRED', message: '请先进入学生空间。' });
    return null;
  }
  const id = isTeacher ? String(studentId || '') : String(auth.studentId || '');
  if (!id || (studentId && String(studentId) !== id) || !isStudentAllowed(request, id)) {
    sendJson(response, 403, { ok: false, code: 'STUDENT_SCOPE_DENIED', message: '当前会话无权访问该学生。' });
    return null;
  }
  const student = findStudent(id);
  if (!student) sendJson(response, 404, { ok: false, code: 'STUDENT_NOT_FOUND' });
  return student || null;
}

async function handleTerminalPractice(request, response, action, cardId = '') {
  const student = terminalLearningStudent(request, response);
  if (!student) return;
  try {
    const id = String(student.id);
    if (request.method === 'GET') {
      const dashboard = await getPracticeCards().dashboard(id);
      sendJson(response, 200, { ok: true, studentId: id, dashboard });
      return;
    }
    const body = JSON.parse((await readRequestBuffer(request, 14 * 1024 * 1024)).toString('utf8') || '{}');
    if (action === 'start') {
      const card = await getPracticeCards().start(id, cardId);
      sendJson(response, 200, { ok: true, studentId: id, card });
    } else if (action === 'attempt') {
      const result = await getPracticeCards().submit(id, cardId, body);
      sendJson(response, 200, { ok: true, studentId: id, ...result });
    }
  } catch (error) {
    sendJson(response, 400, { ok: false, code: 'PRACTICE_INVALID', message: String(error.message || error).slice(0, 240) });
  }
}

function handleTerminalPlanning(request, response, kind, studentId = '') {
  const student = terminalLearningStudent(request, response, studentId);
  if (!student) return;
  try {
    const id = String(student.id), service = planningGuidanceService();
    const result = kind === 'guidance' ? service.getGuidancePlan(id)
      : kind === 'topics' ? service.getTopicSuggestions(id)
      : kind === 'competitions' ? service.getCompetitionRecommendations(id)
      : null;
    if (!result) return sendJson(response, 404, { ok: false, code: 'UNKNOWN_PLANNING_KIND' });
    const current = result.current ? Object.fromEntries([
      'id', 'version', 'createdAt', 'verifiedAt', 'findings', 'nearTermActions',
      'conditions', 'limitations', 'alternatives', 'notice',
    ].filter(key => Object.hasOwn(result.current, key)).map(key => [key, result.current[key]])) : null;
    if (current && Array.isArray(result.current.candidates)) {
      const keys = kind === 'topics'
        ? ['id', 'title', 'category', 'realWorldProblem', 'fitReason', 'path', 'expectedOutcomes', 'durationWeeks', 'difficulty', 'feasibility', 'verifyItems']
        : ['id', 'name', 'category', 'scope', 'organizer', 'officialUrl', 'eligibility', 'deadline', 'season', 'fees', 'status', 'matchReasons', 'preparation', 'risks', 'missing', 'sourceUrls'];
      current.candidates = result.current.candidates.map(candidate => Object.fromEntries(
        keys.filter(key => Object.hasOwn(candidate, key)).map(key => [key, candidate[key]])));
    }
    if (current && Array.isArray(result.current.sources)) current.sources = result.current.sources.map(source => ({
      url: source.url || '', title: source.title || '', fetchedAt: source.fetchedAt || '', official: Boolean(source.official),
    }));
    sendJson(response, 200, { ok: true, studentId: id, current,
      needsRefresh: Boolean(result.needsRefresh), configurationWarning: result.configurationWarning || '',
      latestCheck: result.latestCheck ? { checkedAt: result.latestCheck.checkedAt || '', status: result.latestCheck.status || '' } : null });
  } catch (error) {
    sendJson(response, 400, { ok: false, code: 'PLANNING_UNAVAILABLE', message: String(error.message || error).slice(0, 240) });
  }
}

async function handleTerminalPlanningFavorites(request, response, kind) {
  const student = terminalLearningStudent(request, response);
  if (!student) return;
  if (!['topics', 'competitions'].includes(kind)) return sendJson(response, 404, { ok: false, code: 'FAVORITE_KIND_INVALID' });
  try {
    const service = planningGuidanceService();
    let result;
    if (request.method === 'GET') result = service.getPlanningFavorites(String(student.id), kind);
    else {
      const body = JSON.parse((await readRequestBuffer(request, 32 * 1024)).toString('utf8') || '{}');
      result = service.setPlanningFavorite(String(student.id), kind, body.versionId, body.candidateId, body.saved);
    }
    sendJson(response, 200, { ok: true, studentId: String(student.id), favorites: result.favorites, unchanged: Boolean(result.unchanged) });
  } catch (error) {
    sendJson(response, 400, { ok: false, code: error.code || 'FAVORITE_INVALID', message: String(error.message || error).slice(0, 240) });
  }
}

async function handleTerminalInbox(request, response) {
  const student = terminalLearningStudent(request, response);
  if (!student) return;
  try {
    const id = String(student.id), inbox = getCaptureInbox();
    if (request.method === 'GET') return sendJson(response, 200, { ok: true, studentId: id, items: await inbox.listStored(id) });
    const body = JSON.parse((await readRequestBuffer(request, 32 * 1024)).toString('utf8') || '{}');
    const text = String(body.text || '').trim(), eventId = String(body.eventId || '');
    if (!text || text.length > 10000 || !/^[A-Za-z0-9_-]{8,100}$/.test(eventId)) throw Error('分享内容或提交编号无效');
    const title = String(body.title || '学生分享').replace(/[\x00-\x1f<>:"/\\|?*]/g, '_').slice(0, 80);
    const sourceDeviceId = String(request.authContext.deviceId || 'student-session');
    const previous = (await inbox.listStored(id)).find(item => item.sourceEventId === eventId && item.sourceDeviceId === sourceDeviceId);
    if (previous && (previous.sha256 !== crypto.createHash('sha256').update(text, 'utf8').digest('hex') || previous.originalName !== `${title || '学生分享'}.md`)) {
      return sendJson(response, 409, { ok: false, code: 'INBOX_EVENT_CONFLICT', message: '同一提交编号对应的内容已变化，请重新发送。' });
    }
    const received = await inbox.receive(id, { name: `${title || '学生分享'}.md`, sourceChannel: 'share',
      sourceEventId: eventId, sourceDeviceId, bytes: Buffer.from(text, 'utf8') });
    const { controlledObjectId: _controlledObjectId, ...item } = received.item;
    return sendJson(response, 200, { ok: true, studentId: id, duplicate: received.duplicate, item });
  } catch (error) {
    return sendJson(response, 400, { ok: false, code: 'INBOX_INVALID', message: String(error.message || error).slice(0, 240) });
  }
}

async function handleTeacherLearningOverview(request, response, url) {
  if (!requireAuth(request, response)) return;
  if (request.authContext?.type !== 'device' || request.authContext.deviceRole !== 'teacher') {
    return sendJson(response, 403, { ok: false, code: 'TEACHER_REQUIRED' });
  }
  const offset = Number(url.searchParams.get('offset') || 0);
  const limit = Number(url.searchParams.get('limit') || 50);
  if (!Number.isInteger(offset) || offset < 0 || !Number.isInteger(limit) || limit < 1 || limit > 50) {
    return sendJson(response, 400, { ok: false, code: 'PAGE_INVALID' });
  }
  const students = readStudentsIndex().filter(student => student.archived !== true && student.status !== 'archived');
  const items = [];
  for (const student of students.slice(offset, offset + limit)) {
    try {
      const dashboard = await getPracticeCards().dashboard(String(student.id));
      items.push({ studentId: String(student.id), studentName: String(student.name || ''),
        currentCardStatus: dashboard.current?.status || 'none',
        completedCount: dashboard.history.filter(card => card.status === 'completed').length });
    } catch (error) {
      items.push({ studentId: String(student.id), studentName: String(student.name || ''),
        currentCardStatus: 'unavailable', completedCount: 0, warning: String(error.message || error).slice(0, 120) });
    }
  }
  return sendJson(response, 200, { ok: true, total: students.length, offset, limit, items });
}

function handleDigestStatus(request, response, studentId) {
  if (!requireStudentAccess(request, response, studentId)) return;
  const student = findStudent(studentId);
  if (!student) {
    sendJson(response, 404, { ok: false, message: 'Student not found.' });
    return;
  }
  const records = readUploadRecords().filter((record) => String(record.studentId) === String(studentId));
  const state = readStudentDigestState(student);
  sendJson(response, 200, {
    ok: true,
    studentId: String(studentId),
    pendingCount: records.filter((record) => normalizeUploadStatus(record.status) === 'pending_digest').length,
    submittedCount: records.filter((record) => ['submitted', 'digesting'].includes(normalizeUploadStatus(record.status))).length,
    processedCount: records.filter((record) => normalizeUploadStatus(record.status) === 'processed').length,
    lastUploadAt: records.map((record) => record.uploadedAt || '').sort().pop() || '',
    lastDigestAt: state.lastDigestAt || '',
    digestStatus: state.status || 'idle',
    message: state.message || '',
  });
}

async function handleMaterialUpload(request, response, studentId, url) {
  if (!requireStudentAccess(request, response, studentId)) return;
  if (!requireMatchingUploadGeneration(request, response)) return;
  const student = findStudent(studentId);
  if (!student) {
    sendJson(response, 404, { ok: false, code: 'student_unavailable', message: '未找到学生' });
    return;
  }
  const rawPath = student.rawPath || getRawDir(student.name);
  try {
    fs.mkdirSync(rawPath, { recursive: true });
    const courseAttribution = courseUploadAttribution(url, student);
    const remoteCapture = remoteCaptureAttribution(url, student, null, request.authContext?.deviceId);
    const captureInbox = remoteCapture ? path.join(captureInboxRootPath(), String(remoteCapture.session.id).replace(/[^a-zA-Z0-9._-]/g, '_')) : rawPath;
    fs.mkdirSync(captureInbox, { recursive: true });
    const contentType = String(request.headers['content-type'] || '');
    const declaredSha256 = expectedContentSha256(request.headers['x-edu-content-sha256']);
    const uploadId = String(url.searchParams.get('uploadId') || request.headers['x-upload-id'] || '').trim().slice(0, 180);
    const existingUpload = uploadId ? readUploadRecords().find((record) => String(record.uploadId || '') === uploadId
      && String(record.studentId) === String(studentId)
      && String(record.deviceId || '') === String(request.authContext?.deviceId || 'admin')) : null;
    if (existingUpload) {
      if (!verifiedSource(existingUpload.path, existingUpload.size, existingUpload.sha1)) {
        const failure = studentUploadFailure({ code: 'receipt_source_unavailable' });
        sendJson(response, failure.status, failure.body);
        return;
      }
      const incoming = await fingerprintDuplicateRequest(request, contentType, Number(request.headers['content-length'] || 0));
      assertDeclaredUploadFingerprint(incoming, declaredSha256);
      if (incoming.size !== Number(existingUpload.size) || incoming.sha1 !== String(existingUpload.sha1)
        || incoming.sha256 !== await sha256FileDirect(existingUpload.path)) {
        const failure = studentUploadFailure({ code: 'upload_id_content_conflict' });
        sendJson(response, failure.status, failure.body);
        return;
      }
      const receiptFile = publicStudentUploadReceiptFile({
        ...existingUpload,
        sha256: incoming.sha256,
        assetId: studentUploadAssetId(existingUpload, [
          ...assetStore().queryDetails({ referenceId: existingUpload.id, studentId: String(studentId) }),
          ...assetStore().queryDetails({ referenceId: existingUpload.uploadId, studentId: String(studentId) }),
          assetStore().findByFingerprint({ sha1: existingUpload.sha1, sha256: existingUpload.contentSha256, path: existingUpload.path }),
        ].filter(Boolean)),
        duplicate: true,
      });
      sendJson(response, 200, {
        ok: true,
        duplicate: true,
        imported: 0,
        targetType: 'student',
        targetId: String(studentId),
        studentId: String(studentId),
        targetName: student.name,
        hostId: getHostIdentity().hostId,
        dataGeneration: hostDataGenerationId(),
        receiptStatus: 'received_verified',
        files: [receiptFile],
        filename: receiptFile.filename,
        size: receiptFile.size,
        sha1: receiptFile.sha1,
        sha256: receiptFile.sha256,
        assetId: receiptFile.assetId,
        uploadId: receiptFile.uploadId,
        clientRequestId: receiptFile.clientRequestId,
        receiptId: receiptFile.receiptId,
        rawFileCount: countFiles(rawPath),
        todayUploadCount,
      });
      return;
    }
    const saved = [];
    if (/multipart\/form-data/i.test(contentType)) {
      const buffer = await readRequestBuffer(request);
      const files = parseMultipartFiles(buffer, contentType);
      if (!files.length) throw new Error('multipart request has no file parts.');
      if (declaredSha256 && files.length !== 1) throw new Error('声明内容 SHA-256 的请求只能上传一个文件。');
      for (const file of files) {
        assertUploadFileAllowed(file.filename, file.content.length);
        const fingerprint = uploadBufferFingerprint(file.content);
        assertDeclaredUploadFingerprint(fingerprint, declaredSha256);
        const target = uniqueTargetFile(captureInbox, file.filename);
        fs.writeFileSync(target, file.content);
        saved.push({ filename: path.basename(target), path: target, ...fingerprint });
      }
    } else {
      const filename = url.searchParams.get('filename') || 'upload.bin';
      const expectedBytes = Number(request.headers['content-length'] || 0);
      assertUploadFileAllowed(filename, expectedBytes);
      const target = uniqueTargetFile(captureInbox, filename);
      const streamed = await streamRequestToFile(request, { targetPath: target, maxBytes: MAX_UPLOAD_BYTES,
        expectedBytes, expectedSha256: declaredSha256 });
      saved.push({ filename: path.basename(target), path: target, size: streamed.size, sha1: streamed.sha1, sha256: streamed.sha256 });
    }
    resetUploadCounterIfNeeded();
    todayUploadCount += saved.length;
    const uploadRecords = saved.map((item, index) => ({
      id: `${Date.now()}-${crypto.randomBytes(4).toString('hex')}`,
      studentId: String(studentId),
      studentName: student.name,
      filename: item.filename,
      size: item.size,
      path: item.path,
      rawPath,
      sha1: item.sha1 || sha1File(item.path),
      contentSha256: item.sha256,
      deviceId: request.authContext?.deviceId || 'admin',
      deviceName: request.authContext?.deviceName || '主机控制台',
      sourceType: url.searchParams.get('sourceType') || 'remote_upload',
      captureSessionId: url.searchParams.get('captureSessionId') || '',
      captureItemId: url.searchParams.get('captureItemId') || '',
      ...courseAttribution,
      uploadId,
      capturedAt: remoteCapture?.capturedAt || '',
      reportedCapturedAtRaw: remoteCapture?.reportedCapturedAtRaw || '',
      captureTimeStatus: remoteCapture?.captureTimeStatus || '',
      uploadedAt: new Date().toISOString(),
      status: remoteCapture ? 'ignored' : 'pending_digest',
      skipMaterialRegistration: Boolean(remoteCapture),
    }));
    addUploadRecords(uploadRecords);
    const receiptFiles = uploadRecords.map((record) => publicStudentUploadReceiptFile({
      ...record,
      sha256: record.contentSha256,
      assetId: studentUploadAssetId(record, [assetStore().findByFingerprint({ sha1: record.sha1,
        sha256: record.contentSha256, path: record.path })].filter(Boolean)),
      duplicate: false,
    }));
    if (remoteCapture) {
      uploadRecords.forEach((record, index) => upsertRemoteCaptureSession({ ...remoteCapture, session: { ...remoteCapture.session, ...courseAttribution } }, {
        id: remoteCapture.captureItemId || `${remoteCapture.session.id}-${index + 1}`,
        filename: record.filename,
        path: record.path,
        capturedAt: remoteCapture.capturedAt,
        reportedCapturedAtRaw: remoteCapture.reportedCapturedAtRaw,
        captureTimeStatus: remoteCapture.captureTimeStatus,
        uploadedAt: record.uploadedAt,
        receivedAtSource: 'host_received',
        reason: 'student_terminal_interval',
        sequence: remoteCapture.sequence || index + 1,
        isHighlighted: Boolean(remoteCapture.highlighted),
        hashAlgorithm: record.sha1 ? 'sha1' : '',
        contentHash: record.sha1 || '',
      }, 'student_raw'));
    }
    const rawFileCount = countFiles(rawPath);
    notify('onNativeHostServiceChanged', getHostServiceStatus());
    sendJson(response, 200, {
      ok: true,
      targetType: 'student',
      targetId: String(studentId),
      studentId: String(studentId),
      targetName: student.name,
      hostId: getHostIdentity().hostId,
      dataGeneration: hostDataGenerationId(),
      receiptStatus: 'received_verified',
      duplicate: false,
      imported: saved.length,
      files: receiptFiles,
      filename: receiptFiles[0]?.filename,
      size: receiptFiles.reduce((total, item) => total + item.size, 0),
      sha1: receiptFiles[0]?.sha1 || '',
      sha256: receiptFiles[0]?.sha256 || '',
      assetId: receiptFiles[0]?.assetId || '',
      uploadId: receiptFiles[0]?.uploadId || '',
      clientRequestId: receiptFiles[0]?.clientRequestId || '',
      receiptId: receiptFiles[0]?.receiptId || '',
      rawFileCount,
      todayUploadCount,
    });
  } catch (error) {
    console.error('[student-material-upload] failed', error);
    const failure = studentUploadFailure(error);
    sendJson(response, failure.status, failure.body);
  }
}
function enrollPairedTablet(input = {}, request = null) {
  const license = publicLicenseStatus();
  if (!license.active) return { ok: false, statusCode: 402, message: license.message || 'Windows 主机尚未激活。', license };
  const tabletId = String(input.tabletId || '').trim().slice(0, 120);
  const tabletCode = String(input.tabletMachineCode || '').trim().toUpperCase();
  if (!tabletId || tabletCode !== machineCode('tablet', tabletId)) {
    return { ok: false, statusCode: 400, message: '学生终端身份或固定机器码校验失败。' };
  }
  const students = readStudentsIndex();
  if (license.studentLimit && students.length > Number(license.studentLimit)) {
    return { ok: false, statusCode: 403, message: `当前学生数 ${students.length} 已超过授权上限（${license.studentLimit} 位）。`, license };
  }
  const devices = readDevices();
  const conflicting = machineCodeConflict(devices, 'tablet', tabletId, tabletCode);
  if (conflicting) return { ok: false, statusCode: 409, message: '固定机器码与另一设备身份冲突，已拒绝连接。' };
  const existing = devices.find((item) => String(item.id) === tabletId);
  if (existing?.revoked) {
    return { ok: false, statusCode: 403, message: '该设备已被撤销，不能自行恢复；请在主机端手动恢复后重试。' };
  }
  const activeDevices = devices.filter((item) => !item.revoked && String(item.id) !== tabletId);
  if (license.deviceLimit && activeDevices.length >= Number(license.deviceLimit)) {
    return { ok: false, statusCode: 403, message: `授权设备数已达上限（${license.deviceLimit} 台）。`, license };
  }
  const token = createDeviceToken();
  const now = new Date().toISOString();
  const requestedCapabilities = Array.isArray(input.tabletCapabilities) ? input.tabletCapabilities.map(String) : [];
  const deviceRole = normalizeTerminalDeviceRole(input.deviceRole, requestedCapabilities);
  const device = {
    ...(existing || {}),
    id: tabletId,
    name: String(input.tabletName || existing?.name || (deviceRole === 'teacher' ? 'Android 教师终端' : (input.tabletPlatform === 'windows' ? 'Windows 学生终端' : 'Android 平板'))).trim().slice(0, 80) || (deviceRole === 'teacher' ? '教师终端' : '学生终端'),
    machineCode: tabletCode,
    platform: String(input.tabletPlatform || existing?.platform || 'android').toLowerCase() === 'windows' ? 'windows' : 'android',
    deviceRole,
    tokenHash: hashDeviceToken(token),
    tokenPreview: `${token.slice(0, 7)}...${token.slice(-6)}`,
    terminalMode: normalizeTerminalMode(existing?.terminalMode, 'shared'),
    boundStudentId: String(existing?.boundStudentId || ''),
    capabilities: Array.from(new Set([
      ...(Array.isArray(existing?.capabilities) ? existing.capabilities : []),
      ...requestedCapabilities,
      ...(deviceRole === 'teacher' ? ['teacher-terminal-v1'] : ['student-session-v1']),
    ])),
    allowedStudentIds: normalizeTerminalMode(existing?.terminalMode, 'shared') === 'personal' && existing?.boundStudentId ? [String(existing.boundStudentId)] : [],
    allowedAllStudents: deviceRole === 'teacher' || normalizeTerminalMode(existing?.terminalMode, 'shared') === 'shared',
    autoAuthorizeNewStudents: deviceRole === 'teacher' || normalizeTerminalMode(existing?.terminalMode, 'shared') === 'shared',
    revoked: false,
    createdAt: existing?.createdAt || now,
    enrolledAt: now,
    lastSeenAt: now,
    lastIp: request ? requestClientIp(request) : String(input.tabletAddress || existing?.lastIp || ''),
    lastUserAgent: request ? requestUserAgent(request) : String(existing?.lastUserAgent || ''),
    pairedProtocolVersion: PAIR_PROTOCOL_VERSION,
  };
  writeDevices([...devices.filter((item) => String(item.id) !== tabletId), device]);
  appendHostTimeline({ type: 'device_pair_v2_accepted', title: 'Device connection accepted', detail: device.name, deviceId: tabletId });
  return { ok: true, statusCode: 200, token, device, requiresApproval: false, message: deviceRole === 'teacher' ? '教师终端已连接，可查看本主机学生并上传资料。' : '设备已连接。请选择个人终端或共享终端使用方式。' };
}

function savePairRequest(record) {
  const requests = refreshPairRequests();
  const index = requests.findIndex((item) => String(item.requestId) === String(record.requestId));
  const next = index >= 0
    ? requests.map((item, itemIndex) => itemIndex === index ? record : item)
    : [record, ...requests];
  writePairRequests(next);
  notify('onNativeHostServiceChanged', getHostServiceStatus());
  return record;
}

function acceptHostPairRequest(requestId) {
  const requests = refreshPairRequests();
  const current = requests.find((item) => String(item.requestId) === String(requestId));
  if (!current || current.status !== 'pending_host_accept') return JSON.stringify({ ok: false, message: '未找到待主机接受的连接请求。' });
  const transition = nextPairRequestStatus(current, 'accept');
  if (!transition.ok) return JSON.stringify({ ok: false, message: transition.message });
  const enrolled = enrollPairedTablet({
    tabletId: current.tabletId,
    tabletMachineCode: current.tabletMachineCode,
    tabletName: current.tabletName,
    tabletPlatform: current.tabletPlatform,
    tabletCapabilities: current.tabletCapabilities,
    tabletAddress: current.tabletAddress,
  });
  if (!enrolled.ok) return JSON.stringify(enrolled);
  savePairRequest({
    ...transition.request,
    issuedToken: enrolled.token,
    issuedTokenExpiresAt: new Date(Date.now() + 2 * 60 * 1000).toISOString(),
    deviceId: enrolled.device.id,
  });
  return JSON.stringify({ ok: true, message: enrolled.message, request: publicPairRequest(transition.request), device: publicDevice(enrolled.device), status: JSON.parse(getHostServiceStatus()) });
}

function rejectPairRequest(requestId) {
  const requests = refreshPairRequests();
  const current = requests.find((item) => String(item.requestId) === String(requestId));
  const transition = nextPairRequestStatus(current, 'reject');
  if (!transition.ok) return JSON.stringify({ ok: false, message: transition.message });
  savePairRequest(transition.request);
  appendHostTimeline({ type: 'device_pair_v2_rejected', title: 'Device connection rejected', detail: current?.tabletName || '', deviceId: current?.tabletId || '' });
  return JSON.stringify({ ok: true, message: '已拒绝连接请求。', request: publicPairRequest(transition.request), status: JSON.parse(getHostServiceStatus()) });
}

function inviteLanTablet(tabletId) {
  if (!hostDiscoverySocket) return JSON.stringify({ ok: false, message: '主机局域网发现服务未运行。' });
  const tablet = [...discoveredLanTablets.values()].find((item) => String(item.deviceId) === String(tabletId));
  if (!tablet) return JSON.stringify({ ok: false, message: '未找到该学生终端，请重新查找。' });
  const identity = getHostIdentity();
  const info = getConnectionInfo();
  const created = createPairRequest({
    initiator: 'host',
    hostId: identity.hostId,
    tabletId: tablet.deviceId,
    hostMachineCode: identity.machineCode,
    tabletMachineCode: tablet.machineCode,
    hostName: identity.displayName,
    tabletName: tablet.displayName,
    tabletPlatform: tablet.platform,
    tabletCapabilities: tablet.capabilities,
    hostAddress: info.serverUrl,
    tabletAddress: tablet.address,
  });
  savePairRequest(created.record);
  const payload = Buffer.from(JSON.stringify({
    type: 'AI_EDU_MANAGER_PAIR_INVITE',
    protocolVersion: PAIR_PROTOCOL_VERSION,
    requestId: created.record.requestId,
    requestToken: created.requestToken,
    targetTabletId: tablet.deviceId,
    targetTabletMachineCode: tablet.machineCode,
    hostId: identity.hostId,
    hostMachineCode: identity.machineCode,
    hostName: identity.displayName,
    appVersion: APP_VERSION,
    serverUrl: info.serverUrl,
    lanUrls: info.lanUrls,
    port: info.port,
    expiresAt: created.record.expiresAt,
  }), 'utf8');
  try {
    hostDiscoverySocket.send(payload, tablet.discoveryPort || HOST_DISCOVERY_PORT, tablet.address, (error) => {
      if (error) hostServiceLastError = `发送学生终端连接邀请失败：${error.message}`;
    });
    return JSON.stringify({ ok: true, message: '已发送连接邀请，请在学生终端点击接受。', request: publicPairRequest(created.record), status: JSON.parse(getHostServiceStatus()) });
  } catch (error) {
    return JSON.stringify({ ok: false, message: `发送学生终端连接邀请失败：${error.message}` });
  }
}

async function handlePairRequestV2(request, response) {
  try {
    const body = await parseJsonBody(request);
    const identity = getHostIdentity();
    const tabletId = String(body.tabletId || '').trim().slice(0, 120);
    const tabletCode = String(body.tabletMachineCode || '').trim().toUpperCase();
    if (String(body.hostId || identity.hostId) !== identity.hostId || String(body.hostMachineCode || identity.machineCode) !== identity.machineCode) {
      sendJson(response, 409, { ok: false, message: '目标主机身份不一致，请重新查找主机。' });
      return;
    }
    if (!tabletId || tabletCode !== machineCode('tablet', tabletId) || !body.requestToken || !body.requestId) {
      sendJson(response, 400, { ok: false, message: '连接请求身份信息不完整。' });
      return;
    }
    const existing = readDevices().find((item) => String(item.id) === tabletId);
    if (existing?.revoked) {
      sendJson(response, 403, { ok: false, message: '该设备已被撤销，不能自行恢复。' });
      return;
    }
    const pairRequests = refreshPairRequests();
    const duplicate = pairRequests.find((item) => String(item.requestId) === String(body.requestId));
    if (duplicate) {
      if (!verifyRequestToken(duplicate, body.requestToken)) {
        sendJson(response, 409, { ok: false, message: '请求编号冲突。' });
        return;
      }
      sendJson(response, 200, { ok: true, request: publicPairRequest(duplicate), message: '连接请求已存在。' });
      return;
    }
    const supersededAt = new Date().toISOString();
    const withoutSuperseded = pairRequests.map((item) => {
      if (item.status !== 'pending_host_accept' || String(item.tabletId) !== tabletId) return item;
      return { ...item, status: 'cancelled', updatedAt: supersededAt, cancelledAt: supersededAt, cancelReason: 'superseded' };
    });
    if (JSON.stringify(withoutSuperseded) !== JSON.stringify(pairRequests)) writePairRequests(withoutSuperseded);
    const created = createPairRequest({
      initiator: 'tablet',
      requestId: String(body.requestId),
      requestToken: String(body.requestToken),
      hostId: identity.hostId,
      tabletId,
      hostMachineCode: identity.machineCode,
      tabletMachineCode: tabletCode,
      hostName: identity.displayName,
      tabletName: String(body.tabletName || (body.platform === 'windows' ? 'Windows 学生终端' : 'Android 学生终端')),
      tabletPlatform: String(body.platform || 'android'),
      tabletCapabilities: Array.isArray(body.capabilities) ? body.capabilities : [],
      hostAddress: getConnectionInfo().serverUrl,
      tabletAddress: requestClientIp(request),
    });
    savePairRequest(created.record);
    appendHostTimeline({ type: 'device_pair_v2_requested', title: 'Device connection requested', detail: created.record.tabletName, deviceId: tabletId });
    sendJson(response, 202, { ok: true, request: publicPairRequest(created.record), message: '已发送连接请求，请等待主机端接受。' });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `连接请求失败：${error.message}` });
  }
}

async function handlePairCancelV2(request, response) {
  try {
    const body = await parseJsonBody(request);
    const current = refreshPairRequests().find((item) => String(item.requestId) === String(body.requestId));
    if (!current || !verifyRequestToken(current, body.requestToken)) {
      sendJson(response, 403, { ok: false, message: '连接请求不存在或令牌无效。' });
      return;
    }
    const transition = nextPairRequestStatus(current, 'cancel');
    if (!transition.ok) {
      sendJson(response, 409, { ok: false, message: transition.message, request: publicPairRequest(transition.request) });
      return;
    }
    savePairRequest(transition.request);
    appendHostTimeline({ type: 'device_pair_v2_cancelled', title: 'Device connection request cancelled', detail: current.tabletName || current.requestId, deviceId: current.tabletId || '' });
    sendJson(response, 200, { ok: true, request: publicPairRequest(transition.request), message: '连接请求已取消。' });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `取消连接失败：${error.message}` });
  }
}

function handlePairStatusV2(request, response, url) {
  const requestId = String(url.searchParams.get('requestId') || '');
  const token = String(url.searchParams.get('requestToken') || '');
  const current = refreshPairRequests().find((item) => String(item.requestId) === requestId);
  if (!current || !verifyRequestToken(current, token)) {
    sendJson(response, 404, { ok: false, message: '连接请求不存在或令牌无效。' });
    return;
  }
  sendJson(response, 200, {
    ok: true,
    request: publicPairRequest(current),
    token: current.status === 'accepted' && Date.parse(current.issuedTokenExpiresAt || 0) > Date.now() ? current.issuedToken || '' : '',
    requiresApproval: current.status === 'accepted',
  });
}

async function handleTabletPairAcceptV2(request, response) {
  try {
    const body = await parseJsonBody(request);
    const requests = refreshPairRequests();
    const current = requests.find((item) => String(item.requestId) === String(body.requestId));
    if (!current || current.status !== 'pending_tablet_accept' || !verifyRequestToken(current, body.requestToken)) {
      sendJson(response, 403, { ok: false, message: '连接邀请无效、已过期或已处理。' });
      return;
    }
    if (String(body.tabletId || '') !== current.tabletId || String(body.tabletMachineCode || '').toUpperCase() !== current.tabletMachineCode.toUpperCase()) {
      sendJson(response, 409, { ok: false, message: '接受邀请的平板身份与目标设备不一致。' });
      return;
    }
    const enrolled = enrollPairedTablet({
      tabletId: current.tabletId,
      tabletMachineCode: current.tabletMachineCode,
      tabletName: body.tabletName || current.tabletName,
      tabletPlatform: current.tabletPlatform || body.platform,
      tabletCapabilities: current.tabletCapabilities || body.capabilities,
      tabletAddress: requestClientIp(request),
    }, request);
    if (!enrolled.ok) {
      sendJson(response, enrolled.statusCode || 400, enrolled);
      return;
    }
    const transition = nextPairRequestStatus(current, 'accept');
    savePairRequest({
      ...transition.request,
      issuedToken: enrolled.token,
      issuedTokenExpiresAt: new Date(Date.now() + 2 * 60 * 1000).toISOString(),
      deviceId: enrolled.device.id,
    });
    sendJson(response, 200, { ok: true, token: enrolled.token, requiresApproval: true, message: enrolled.message, device: publicDevice(enrolled.device) });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `接受连接邀请失败：${error.message}` });
  }
}

async function handlePairRejectV2(request, response) {
  try {
    const body = await parseJsonBody(request);
    const current = refreshPairRequests().find((item) => String(item.requestId) === String(body.requestId));
    if (!current || !verifyRequestToken(current, body.requestToken)) {
      sendJson(response, 403, { ok: false, message: '连接请求不存在或令牌无效。' });
      return;
    }
    const transition = nextPairRequestStatus(current, 'reject');
    if (!transition.ok) {
      sendJson(response, 409, { ok: false, message: transition.message });
      return;
    }
    savePairRequest(transition.request);
    sendJson(response, 200, { ok: true, request: publicPairRequest(transition.request), message: '已拒绝连接邀请。' });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `拒绝连接失败：${error.message}` });
  }
}

async function handlePairConfirm(request, response) {
  try {
    const body = await parseJsonBody(request);
    const pairCode = String(body.pairCode || '').trim();
    const session = getPairSession();
    if (!pairCode || pairCode !== session.pairCode || session.expiresAtMs <= Date.now()) {
      sendJson(response, 403, { ok: false, message: '配对码无效或已过期。' });
      return;
    }
    const license = publicLicenseStatus();
    if (!license.active) {
      sendJson(response, 402, { ok: false, message: license.message || 'Windows 主机尚未激活，请先在主机端输入授权码。', license });
      return;
    }
    const existingStudents = readStudentsIndex();
    const deviceId = String(body.deviceId || `device-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`);
    const existingDevice = readDevices().find((item) => String(item.id) === deviceId);
    if (existingDevice?.revoked) {
      sendJson(response, 403, { ok: false, message: '该设备已被撤销，不能通过旧配对码自行恢复；请在主机端手动恢复。' });
      return;
    }
    const activeDevices = readDevices().filter((item) => !item.revoked && String(item.id) !== deviceId);
    if (license.deviceLimit && activeDevices.length >= Number(license.deviceLimit)) {
      sendJson(response, 403, { ok: false, message: `授权设备数已达上限（${license.deviceLimit} 台）。请在 Windows 主机端撤销旧设备或升级授权。`, license });
      return;
    }
    if (license.studentLimit && existingStudents.length > Number(license.studentLimit)) {
      sendJson(response, 403, { ok: false, message: `当前学生数 ${existingStudents.length} 已超过授权上限（${license.studentLimit} 位）。请升级授权或减少学生后再绑定。`, license });
      return;
    }
    const token = createDeviceToken();
    const requestedCapabilities = Array.isArray(body.capabilities) ? body.capabilities.map(String) : [];
    const deviceRole = normalizeTerminalDeviceRole(body.deviceRole, requestedCapabilities);
    const device = {
      id: deviceId,
      name: String(body.deviceName || body.name || (deviceRole === 'teacher' ? 'Android 教师终端' : '平板设备')).slice(0, 80),
      tokenHash: hashDeviceToken(token),
      tokenPreview: `${token.slice(0, 7)}...${token.slice(-6)}`,
      deviceRole,
      terminalMode: 'shared',
      boundStudentId: '',
      capabilities: Array.from(new Set([...requestedCapabilities, ...(deviceRole === 'teacher' ? ['teacher-terminal-v1'] : ['student-session-v1'])])),
      allowedStudentIds: [],
      allowedAllStudents: true,
      autoAuthorizeNewStudents: true,
      revoked: false,
      createdAt: new Date().toISOString(),
      lastSeenAt: new Date().toISOString(),
      lastIp: requestClientIp(request),
      lastUserAgent: requestUserAgent(request),
    };
    const devices = readDevices().filter((item) => item.id !== device.id);
    devices.push(device);
    writeDevices(devices);
    activePairSession = null;
    notify('onNativeHostServiceChanged', getHostServiceStatus());
    sendJson(response, 200, {
      ok: true,
      token,
      requiresApproval: false,
      message: deviceRole === 'teacher' ? '教师终端已登记，可直接读取本主机学生。' : '设备已登记，默认为共享终端；学生可扫码或输入个人 ID。',
      device: publicDevice(device),
      students: [],
    });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `Pair confirm failed: ${error.message}` });
  }
}

async function handleDeviceEnroll(request, response) {
  if (!requireAuth(request, response)) return;
  if (request.authContext?.type !== 'admin') {
    sendJson(response, 403, { ok: false, message: '只有主机连接信息可以登记新设备。' });
    return;
  }
  try {
    const body = await parseJsonBody(request);
    const license = publicLicenseStatus();
    const deviceId = String(body.deviceId || `device-${Date.now()}-${crypto.randomBytes(4).toString('hex')}`).slice(0, 120);
    const devices = readDevices();
    const activeDevices = devices.filter((item) => !item.revoked && String(item.id) !== deviceId);
    if (license.deviceLimit && activeDevices.length >= Number(license.deviceLimit)) {
      sendJson(response, 403, { ok: false, message: `授权设备数已达上限（${license.deviceLimit} 台）。请撤销旧设备或升级授权。` });
      return;
    }
    const token = createDeviceToken();
    const requestedCapabilities = Array.isArray(body.capabilities) ? body.capabilities.map(String) : [];
    const deviceRole = normalizeTerminalDeviceRole(body.deviceRole, requestedCapabilities);
    const device = {
      id: deviceId,
      name: String(body.deviceName || body.name || (deviceRole === 'teacher' ? 'Android 教师终端' : '平板设备')).trim().slice(0, 80) || (deviceRole === 'teacher' ? '教师终端' : '平板设备'),
      tokenHash: hashDeviceToken(token),
      tokenPreview: `${token.slice(0, 7)}...${token.slice(-6)}`,
      deviceRole,
      terminalMode: 'shared',
      boundStudentId: '',
      capabilities: Array.from(new Set([...requestedCapabilities, ...(deviceRole === 'teacher' ? ['teacher-terminal-v1'] : ['student-session-v1'])])),
      allowedStudentIds: [],
      allowedAllStudents: true,
      autoAuthorizeNewStudents: true,
      revoked: false,
      createdAt: devices.find((item) => String(item.id) === deviceId)?.createdAt || new Date().toISOString(),
      enrolledAt: new Date().toISOString(),
      lastSeenAt: new Date().toISOString(),
      lastIp: requestClientIp(request),
      lastUserAgent: requestUserAgent(request),
    };
    writeDevices([...devices.filter((item) => String(item.id) !== deviceId), device]);
    appendHostTimeline({ type: 'device_enrolled', title: 'Tablet awaiting authorization', detail: device.name, deviceId });
    notify('onNativeHostServiceChanged', getHostServiceStatus());
    sendJson(response, 200, {
      ok: true,
      token,
      requiresApproval: false,
      message: deviceRole === 'teacher' ? '教师终端已登记，可直接读取本主机学生。' : '设备已登记，默认为共享终端；学生可扫码或输入个人 ID。',
      device: publicDevice(device),
    });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `设备登记失败：${error.message}` });
  }
}

function handleDeviceHeartbeat(request, response) {
  if (!requireAuth(request, response)) return;
  const auth = request.authContext;
  const device = ['device', 'student_session'].includes(auth?.type)
    ? readDevices().find((item) => String(item.id) === String(auth.deviceId))
    : null;
  sendJson(response, 200, {
    ok: true,
    at: new Date().toISOString(),
    device: device ? publicDevice(device) : null,
    studentCount: readStudentsIndex().length,
  });
}

function directPackagePaths(manifestId) {
  const state = readCollaborationState();
  const safeId = String(manifestId || '');
  if (!/^[A-Za-z0-9._-]{1,160}$/.test(safeId)) throw new Error('协作包标识无效。');
  const root = path.join(collaborationRootPath(), '.direct-received', state.node.nodeId);
  return {
    state,
    writing: path.join(root, `.${safeId}.writing`),
    completed: path.join(root, safeId),
  };
}

function directPackageFilePath(locations, file) {
  const contentRoot = path.resolve(locations.writing, 'content');
  const targetPath = path.resolve(contentRoot, String(file?.relativePath || ''));
  if (!targetPath.startsWith(`${contentRoot}${path.sep}`)) throw new Error('协作文件路径越界。');
  return targetPath;
}

function directAvailableDiskBytes(targetPath) {
  try {
    if (typeof fs.statfsSync !== 'function') return Number.POSITIVE_INFINITY;
    let probe = path.resolve(targetPath);
    while (!fs.existsSync(probe) && path.dirname(probe) !== probe) probe = path.dirname(probe);
    const stats = fs.statfsSync(probe);
    return Number(stats.bavail || stats.bfree || 0) * Number(stats.bsize || 0);
  } catch {
    return Number.POSITIVE_INFINITY;
  }
}

function sha256FileDirect(filePath) {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash('sha256');
    const stream = fs.createReadStream(filePath);
    stream.on('error', reject);
    stream.on('data', (chunk) => hash.update(chunk));
    stream.on('end', () => resolve(hash.digest('hex')));
  });
}

function pruneDirectNonces(now = Date.now()) {
  for (const [key, expiresAt] of collaborationDirectNonces.entries()) {
    if (expiresAt <= now) collaborationDirectNonces.delete(key);
  }
}

function authenticateDirectRequest(request, pathname, actualContentSha256 = '') {
  const state = readCollaborationState();
  const bindingId = String(request.headers['x-edu-binding-id'] || '');
  const sourceNodeId = String(request.headers['x-edu-node-id'] || '');
  const binding = state.bindings.find((item) => item.bindingId === bindingId && item.status === 'active' && !item.revokedAt);
  const secret = binding ? collaborationDirectSecret(binding) : '';
  if (!binding || !secret || !binding.participantNodeIds?.includes(state.node.nodeId) || !binding.participantNodeIds?.includes(sourceNodeId)) {
    throw new Error('未找到有效的双主机协作认证。');
  }
  const verified = verifyDirectRequest({
    secret,
    method: request.method,
    pathname,
    headers: request.headers,
  });
  if (!verified.ok) throw new Error(verified.message);
  if (actualContentSha256 && verified.contentSha256 !== actualContentSha256) throw new Error('直传内容摘要不匹配。');
  pruneDirectNonces();
  const nonceKey = `${bindingId}:${verified.nonce}`;
  if (collaborationDirectNonces.has(nonceKey)) throw new Error('检测到重复的直传请求。');
  collaborationDirectNonces.set(nonceKey, Date.now() + 10 * 60 * 1000);
  return { state, binding, sourceNodeId, verified };
}

function directAuthorizedStudentIds(binding, nodeId) {
  return new Set((binding?.roleAssignments || [])
    .filter((assignment) => assignment.nodeId === nodeId && assignment.studentId && !assignment.revokedAt)
    .map((assignment) => String(assignment.studentId)));
}

function assertDirectStudentArchiveManifestScope(auth, files = []) {
  const archiveFiles = files.filter((file) => ['student_archive_publication', 'student_archive_asset_revision'].includes(file.objectType));
  if (!archiveFiles.length) return;
  const localStudentIds = directAuthorizedStudentIds(auth.binding, auth.state.node.nodeId);
  const declaredStudentIds = new Set(archiveFiles.map((file) => String(file.studentId || '')));
  if (localStudentIds.size < 1 || declaredStudentIds.size !== 1 || [...declaredStudentIds].some((studentId) => !studentId || !localStudentIds.has(studentId))) {
    throw new Error('学生档案包超出当前精确学生映射范围。');
  }
  if (!archiveFiles.some((file) => file.objectType === 'student_archive_publication')) {
    throw new Error('学生档案包缺少发布清单。');
  }
}

function assertDirectStudentArchiveContentScope(auth, manifest, packageRoot) {
  const files = Array.isArray(manifest?.files) ? manifest.files : [];
  assertDirectStudentArchiveManifestScope(auth, files);
  const publications = files.filter((file) => file.objectType === 'student_archive_publication');
  if (!publications.length) return;
  const remoteStudentIds = directAuthorizedStudentIds(auth.binding, auth.sourceNodeId);
  for (const descriptor of publications) {
    const relativePath = safeRelativePath(descriptor.relativePath);
    const publicationPath = path.resolve(packageRoot, 'content', relativePath);
    if (!relativePath || !pathInside(publicationPath, path.resolve(packageRoot, 'content')) || !fs.existsSync(publicationPath)) {
      throw new Error('学生档案发布清单路径无效。');
    }
    const publication = safeReadJson(publicationPath, null);
    const participants = [
      `${auth.state.node.nodeId}:${publication?.targetStudentId || ''}`,
      `${auth.sourceNodeId}:${publication?.sourceStudentId || ''}`,
    ].sort();
    const expectedLineage = `${auth.binding.bindingId}:student-archive:${participants.join('|')}`;
    if (
      publication?.schema !== 'edu-manager.student-archive-sync.v1'
      || publication.targetNodeId !== auth.state.node.nodeId
      || publication.sourceNodeId !== auth.sourceNodeId
      || String(publication.targetStudentId || '') !== String(descriptor.studentId || '')
      || !remoteStudentIds.has(String(publication.sourceStudentId || ''))
      || publication.lineageId !== expectedLineage
    ) {
      throw new Error('学生档案发布清单未通过精确学生与版本谱系校验。');
    }
  }
}

async function handleCollaborationDirectInit(request, response, pathname) {
  try {
    const bodyBuffer = await readRequestBuffer(request, 2 * 1024 * 1024);
    const auth = authenticateDirectRequest(request, pathname, sha256DirectContent(bodyBuffer));
    const payload = bodyBuffer.length ? JSON.parse(bodyBuffer.toString('utf8')) : {};
    const requestedProtocol = String(payload.protocolVersion || '1.0');
    if (Number(requestedProtocol.split('.')[0]) > Number(DIRECT_PROTOCOL_VERSION.split('.')[0])) {
      throw new Error(`直传协议版本不兼容：${requestedProtocol}。`);
    }
    const manifest = payload.manifest;
    if (manifest?.sourceNodeId !== auth.sourceNodeId || manifest?.targetNodeId !== auth.state.node.nodeId) {
      throw new Error('协作包发送方或目标主机不匹配。');
    }
    const files = Array.isArray(manifest?.files) ? manifest.files : [];
    if (!manifest?.manifestId || !files.length || files.length > 1000) throw new Error('协作包清单无效。');
    if (files.some((item) => !Number.isFinite(Number(item.size)) || Number(item.size) < 0 || Number(item.size) > MAX_UPLOAD_BYTES)) {
      throw new Error('协作包包含超出限制的文件。');
    }
    if (files.reduce((sum, item) => sum + Number(item.size || 0), 0) > 2 * 1024 * 1024 * 1024) {
      throw new Error('协作包总大小超出限制。');
    }
    assertDirectStudentArchiveManifestScope(auth, files);
    const locations = directPackagePaths(manifest.manifestId);
    if (fs.existsSync(locations.completed)) {
      sendJson(response, 200, { ok: true, duplicate: true, manifestId: manifest.manifestId });
      return;
    }
    fs.mkdirSync(path.join(locations.writing, 'content'), { recursive: true });
    const importLedger = safeReadJson(collaborationImportLedgerPath(), { objects: {} });
    for (const file of files) {
      const known = importLedger.objects?.[file.objectId];
      if (!known?.importedPath || String(known.sha256 || '') !== String(file.sha256 || '') || !fs.existsSync(known.importedPath)) continue;
      const candidate = directPackageFilePath(locations, file);
      fs.mkdirSync(path.dirname(candidate), { recursive: true });
      if (!fs.existsSync(candidate)) fs.copyFileSync(known.importedPath, candidate);
    }
    const remainingBytes = files.reduce((sum, file) => {
      try {
        const candidate = directPackageFilePath(locations, file);
        const received = fs.existsSync(candidate) ? Math.min(fs.statSync(candidate).size, Number(file.size || 0)) : 0;
        return sum + Math.max(0, Number(file.size || 0) - received);
      } catch {
        return sum + Number(file.size || 0);
      }
    }, 0);
    const freeBytes = directAvailableDiskBytes(locations.writing);
    if (Number.isFinite(freeBytes) && freeBytes < remainingBytes + 64 * 1024 * 1024) {
      throw new Error('接收端磁盘空间不足，未开始传输。');
    }
    const existing = safeReadJson(path.join(locations.writing, 'manifest.json'), null);
    if (existing && JSON.stringify(existing) !== JSON.stringify(manifest)) throw new Error('同名协作包清单发生冲突。');
    writeJsonAtomic(path.join(locations.writing, 'manifest.json'), manifest);
    const fileProgress = [];
    for (let index = 0; index < files.length; index += 1) {
      const file = files[index];
      const candidate = directPackageFilePath(locations, file);
      let receivedBytes = fs.existsSync(candidate) ? fs.statSync(candidate).size : 0;
      if (receivedBytes > Number(file.size || 0)) {
        fs.rmSync(candidate, { force: true });
        receivedBytes = 0;
      } else if (Number(file.size || 0) === 0 && !fs.existsSync(candidate)) {
        fs.mkdirSync(path.dirname(candidate), { recursive: true });
        fs.writeFileSync(candidate, Buffer.alloc(0));
      } else if (receivedBytes === Number(file.size || 0) && receivedBytes > 0) {
        const digest = await sha256FileDirect(candidate);
        if (digest !== file.sha256) {
          fs.rmSync(candidate, { force: true });
          receivedBytes = 0;
        }
      }
      fileProgress.push({ index, receivedBytes, size: Number(file.size || 0), complete: receivedBytes === Number(file.size || 0) });
    }
    sendJson(response, 200, {
      ok: true,
      manifestId: manifest.manifestId,
      fileCount: files.length,
      protocolVersion: DIRECT_PROTOCOL_VERSION,
      supportsResume: true,
      maxChunkBytes: 8 * 1024 * 1024,
      files: fileProgress,
    });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `初始化协作直传失败：${error.message}` });
  }
}

async function handleCollaborationDirectChunk(request, response, pathname, manifestId, fileIndex, offsetValue) {
  try {
    const locations = directPackagePaths(manifestId);
    const manifest = safeReadJson(path.join(locations.writing, 'manifest.json'), null);
    const file = manifest?.files?.[Number(fileIndex)];
    if (!file) throw new Error('协作包文件序号无效。');
    const expectedBytes = Number(request.headers['content-length'] || 0);
    if (!Number.isFinite(expectedBytes) || expectedBytes <= 0 || expectedBytes > 8 * 1024 * 1024) throw new Error('协作文件分块大小无效。');
    const bodyBuffer = await readRequestBuffer(request, 8 * 1024 * 1024);
    if (bodyBuffer.length !== expectedBytes) throw new Error('协作文件分块不完整。');
    const actualChunkSha256 = sha256DirectContent(bodyBuffer);
    const auth = authenticateDirectRequest(request, pathname, actualChunkSha256);
    if (manifest.sourceNodeId !== auth.sourceNodeId || manifest.targetNodeId !== auth.state.node.nodeId) {
      throw new Error('协作包与当前绑定不匹配。');
    }
    if (String(request.headers['x-edu-file-sha256'] || '') !== String(file.sha256 || '')) throw new Error('协作文件总摘要声明不匹配。');
    const offset = Number(offsetValue);
    if (!Number.isSafeInteger(offset) || offset < 0 || offset + bodyBuffer.length > Number(file.size)) throw new Error('协作文件分块位置无效。');
    const targetPath = directPackageFilePath(locations, file);
    fs.mkdirSync(path.dirname(targetPath), { recursive: true });
    const currentSize = fs.existsSync(targetPath) ? fs.statSync(targetPath).size : 0;
    if (offset < currentSize) {
      if (offset + bodyBuffer.length > currentSize) throw new Error('协作文件分块与现有断点重叠。');
      const handle = fs.openSync(targetPath, 'r');
      let existing;
      try {
        existing = Buffer.allocUnsafe(bodyBuffer.length);
        fs.readSync(handle, existing, 0, existing.length, offset);
      } finally {
        fs.closeSync(handle);
      }
      if (!existing.equals(bodyBuffer)) throw new Error('重复分块内容与已接收数据不一致。');
      sendJson(response, 200, { ok: true, duplicate: true, manifestId, fileIndex: Number(fileIndex), receivedBytes: currentSize });
      return;
    }
    if (offset !== currentSize) {
      sendJson(response, 409, { ok: false, message: '分块前仍有缺失数据。', expectedOffset: currentSize });
      return;
    }
    fs.appendFileSync(targetPath, bodyBuffer);
    const receivedBytes = currentSize + bodyBuffer.length;
    if (receivedBytes === Number(file.size)) {
      const digest = await sha256FileDirect(targetPath);
      if (digest !== file.sha256) {
        fs.rmSync(targetPath, { force: true });
        throw new Error('协作文件 SHA-256 校验失败，已清除错误断点。');
      }
    }
    sendJson(response, 200, { ok: true, manifestId, fileIndex: Number(fileIndex), receivedBytes, complete: receivedBytes === Number(file.size) });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `接收协作文件分块失败：${error.message}` });
  }
}

async function handleCollaborationDirectFile(request, response, pathname, manifestId, fileIndex) {
  try {
    const locations = directPackagePaths(manifestId);
    const manifest = safeReadJson(path.join(locations.writing, 'manifest.json'), null);
    const file = manifest?.files?.[Number(fileIndex)];
    if (!file) throw new Error('协作包文件序号无效。');
    const auth = authenticateDirectRequest(request, pathname);
    if (manifest.sourceNodeId !== auth.sourceNodeId || manifest.targetNodeId !== auth.state.node.nodeId) {
      throw new Error('协作包与当前绑定不匹配。');
    }
    if (auth.verified.contentSha256 !== file.sha256) throw new Error('协作文件声明摘要不匹配。');
    const targetPath = directPackageFilePath(locations, file);
    const streamed = await streamRequestToFile(request, {
      targetPath,
      maxBytes: MAX_UPLOAD_BYTES,
      expectedBytes: Number(file.size),
      hashAlgorithm: 'sha256',
    });
    if (streamed.sha256 !== file.sha256) {
      fs.rmSync(targetPath, { force: true });
      throw new Error('协作文件 SHA-256 校验失败。');
    }
    sendJson(response, 200, { ok: true, manifestId, fileIndex: Number(fileIndex), size: streamed.size });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `接收协作文件失败：${error.message}` });
  }
}

async function handleCollaborationDirectCommit(request, response, pathname, manifestId) {
  try {
    const bodyBuffer = await readRequestBuffer(request, 1024 * 1024);
    const auth = authenticateDirectRequest(request, pathname, sha256DirectContent(bodyBuffer));
    const payload = bodyBuffer.length ? JSON.parse(bodyBuffer.toString('utf8')) : {};
    if (payload.manifestId !== manifestId) throw new Error('协作包提交标识不匹配。');
    const locations = directPackagePaths(manifestId);
    let packageRoot = locations.completed;
    if (!fs.existsSync(packageRoot)) {
      const manifest = safeReadJson(path.join(locations.writing, 'manifest.json'), null);
      if (!manifest || manifest.sourceNodeId !== auth.sourceNodeId || manifest.targetNodeId !== auth.state.node.nodeId) {
        throw new Error('协作包清单不存在或目标不匹配。');
      }
      for (const file of manifest.files || []) {
        const candidate = path.resolve(locations.writing, 'content', String(file.relativePath || ''));
        if (!fs.existsSync(candidate) || fs.statSync(candidate).size !== Number(file.size)) throw new Error(`协作文件尚未完整接收：${file.relativePath}`);
        if (await sha256FileDirect(candidate) !== file.sha256) throw new Error(`协作文件摘要校验失败：${file.relativePath}`);
      }
      fs.writeFileSync(path.join(locations.writing, 'READY'), manifestId, 'utf8');
      fs.mkdirSync(path.dirname(locations.completed), { recursive: true });
      fs.renameSync(locations.writing, locations.completed);
      packageRoot = locations.completed;
    }
    const manifest = safeReadJson(path.join(packageRoot, 'manifest.json'), null);
    assertDirectStudentArchiveContentScope(auth, manifest, packageRoot);
    const receipt = importCollaborationPackage(collaborationRootPath(), { packageRoot, manifest }, {
      targetNodeId: auth.state.node.nodeId,
      ledgerPath: collaborationImportLedgerPath(),
    });
    const taskImport = ingestImportedCollaborationTasks();
    const projectImport = await ingestImportedProjectPublications();
    const studentArchiveImport = ingestImportedStudentArchives();
    const conversationImport = await ingestImportedAgentConversationSubmissions();
    appendHostTimeline({
      type: 'collaboration_direct_received',
      title: 'Collaboration package received',
      detail: `${manifestId}: ${receipt.status}; projects ${projectImport.importedPublications}, files ${projectImport.importedFiles}, student archive assets ${studentArchiveImport.imported}, known ${projectImport.duplicateFiles + studentArchiveImport.duplicates}`,
    });
    notify('onNativeHostServiceChanged', getHostServiceStatus());
    notify('onNativeCollaborationChanged', JSON.stringify({ manifestId, receipt, taskImport, projectImport, studentArchiveImport, conversationImport }));
    sendJson(response, 200, { ok: true, receipt, taskImport, projectImport, studentArchiveImport,
      conversationImport, materializationPending: conversationImport.failed > 0 });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `提交协作直传失败：${error.message}` });
  }
}

function androidPullStudentMapping(auth, studentMapId) {
  const mapping = (auth.state.studentMaps || []).find((item) => (
    item.studentMapId === String(studentMapId || '')
    && item.status === 'active'
    && !item.revokedAt
    && item.participantStudents?.some((part) => part.nodeId === auth.sourceNodeId)
    && item.participantStudents?.some((part) => part.nodeId === auth.state.node.nodeId)
    && item.transportBindingIds?.includes(auth.binding.bindingId)
  ));
  if (!mapping) throw new Error('没有找到当前协作设备可用的精确学生映射。');
  const device = (auth.state.deviceBindings || []).find((item) => (
    item.deviceBindingId === mapping.deviceBindingId
    && item.status === 'active'
    && !item.revokedAt
    && item.participantNodeIds?.includes(auth.sourceNodeId)
    && item.participantNodeIds?.includes(auth.state.node.nodeId)
  ));
  if (!device) throw new Error('学生映射对应的设备信任已暂停或失效。');
  const local = mapping.participantStudents.find((item) => item.nodeId === auth.state.node.nodeId);
  const peer = mapping.participantStudents.find((item) => item.nodeId === auth.sourceNodeId);
  if (!local?.studentId || !peer?.studentId) throw new Error('学生映射缺少双方精确学生 ID。');
  return { mapping, localStudentId: local.studentId, peerStudentId: peer.studentId };
}

function androidPullPackage(auth, studentMapId, manifestId = '') {
  const scope = androidPullStudentMapping(auth, studentMapId);
  const candidates = Object.values(readDirectDeliveryStore().deliveries || {})
    .filter((record) => (
      ['compatibility_queue', 'queued', 'retry_waiting'].includes(record.status)
      && record.targetNodeId === auth.sourceNodeId
      && record.packageRoot
      && (!manifestId || record.manifestId === manifestId)
    ))
    .map((record) => ({ record, manifest: safeReadJson(path.join(record.packageRoot, 'manifest.json'), null) }))
    .filter(({ manifest }) => (
      manifest?.manifestId
      && manifest.sourceNodeId === auth.state.node.nodeId
      && manifest.targetNodeId === auth.sourceNodeId
      && (manifest.files || []).some((file) => file.objectType === 'student_archive_publication')
      && (manifest.files || []).every((file) => !file.studentId || String(file.studentId) === String(scope.peerStudentId))
    ))
    .sort((left, right) => String(left.manifest.createdAt || '').localeCompare(String(right.manifest.createdAt || '')));
  const selected = candidates[0];
  if (!selected) return { ...scope, record: null, manifest: null };
  return { ...scope, ...selected };
}

async function handleCollaborationAndroidPullNext(request, response, pathname, studentMapId) {
  try {
    const auth = authenticateDirectRequest(request, pathname, sha256DirectContent(Buffer.alloc(0)));
    const selected = androidPullPackage(auth, studentMapId);
    if (!selected.manifest) {
      sendJson(response, 200, { ok: true, available: false });
      return;
    }
    const manifestJson = fs.readFileSync(path.join(selected.record.packageRoot, 'manifest.json'), 'utf8');
    const manifestSha256 = sha256DirectContent(Buffer.from(manifestJson, 'utf8'));
    const proof = crypto.createHmac('sha256', collaborationDirectSecret(auth.binding))
      .update([selected.manifest.manifestId, manifestSha256].join('\u001f'))
      .digest('hex');
    sendJson(response, 200, {
      ok: true,
      available: true,
      manifestJson,
      manifestSha256,
      proof,
      protocolVersion: DIRECT_PROTOCOL_VERSION,
      maxChunkBytes: 4 * 1024 * 1024,
    });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `读取 Android 协作清单失败：${error.message}` });
  }
}

async function handleCollaborationAndroidPullChunk(request, response, pathname, studentMapId, manifestId, fileIndex, url) {
  try {
    const auth = authenticateDirectRequest(request, pathname, sha256DirectContent(Buffer.alloc(0)));
    const selected = androidPullPackage(auth, studentMapId, manifestId);
    if (!selected.manifest) throw new Error('待拉取的协作包不存在或已完成。');
    const file = selected.manifest.files?.[Number(fileIndex)];
    if (!file) throw new Error('协作文件序号无效。');
    const contentRoot = path.resolve(selected.record.packageRoot, 'content');
    const relativePath = safeRelativePath(file.relativePath);
    const sourcePath = path.resolve(contentRoot, relativePath);
    if (!relativePath || !pathInside(sourcePath, contentRoot) || !fs.existsSync(sourcePath)) throw new Error('协作文件不存在或路径无效。');
    const size = fs.statSync(sourcePath).size;
    if (size !== Number(file.size)) throw new Error('协作文件大小与清单不一致。');
    const offset = Math.max(0, Number(url.searchParams.get('offset') || 0));
    const requested = Math.max(1, Math.min(4 * 1024 * 1024, Number(url.searchParams.get('length') || 1024 * 1024)));
    if (!Number.isSafeInteger(offset) || offset >= size) throw new Error('协作文件分块位置无效。');
    const length = Math.min(requested, size - offset);
    const handle = fs.openSync(sourcePath, 'r');
    let body;
    try {
      body = Buffer.allocUnsafe(length);
      if (fs.readSync(handle, body, 0, length, offset) !== length) throw new Error('读取协作文件分块不完整。');
    } finally {
      fs.closeSync(handle);
    }
    response.writeHead(200, {
      'Content-Type': 'application/octet-stream',
      'Content-Length': body.length,
      'X-Edu-Chunk-Sha256': sha256DirectContent(body),
      'X-Edu-File-Sha256': String(file.sha256 || ''),
      'X-Edu-Received-Offset': String(offset + body.length),
      'Access-Control-Allow-Origin': '*',
    });
    response.end(body);
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `下载 Android 协作分块失败：${error.message}` });
  }
}

async function handleCollaborationAndroidPullAck(request, response, pathname, studentMapId, manifestId) {
  try {
    const bodyBuffer = await readRequestBuffer(request, 1024 * 1024);
    const auth = authenticateDirectRequest(request, pathname, sha256DirectContent(bodyBuffer));
    const selected = androidPullPackage(auth, studentMapId, manifestId);
    const body = bodyBuffer.length ? JSON.parse(bodyBuffer.toString('utf8')) : {};
    if (!selected.manifest || body.manifestId !== manifestId || body.status !== 'materialized') throw new Error('协作包确认信息无效。');
    updateDirectDelivery(manifestId, {
      status: 'delivered',
      channel: 'android_pull',
      deliveredAt: new Date().toISOString(),
      nextAttemptAt: '',
      progress: null,
      error: '',
      receipt: { status: 'materialized', studentMapId, receivedBy: auth.sourceNodeId },
    });
    appendHostTimeline({ type: 'collaboration_android_pull_delivered', title: 'Android pulled collaboration package', detail: manifestId });
    notify('onNativeCollaborationChanged', JSON.stringify({ manifestId, status: 'delivered', channel: 'android_pull' }));
    sendJson(response, 200, { ok: true, manifestId });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `确认 Android 协作包失败：${error.message}` });
  }
}

function invokeIncomingTeamArchive(access, scoped) {
  const candidates = Array.from(new Set([
    ...(Array.isArray(scoped.searchQueries) ? scoped.searchQueries : []),
    scoped.query,
  ].map((item) => String(item || '').trim()).filter(Boolean))).slice(0, 6);
  if (!['search', 'context_bundle'].includes(scoped.queryType) || candidates.length <= 1) {
    return invokeLocalArchiveScopes(access, scoped, scoped.allowedScopes);
  }
  const resources = [];
  let baseResult = null;
  for (const candidate of candidates) {
    const result = invokeLocalArchiveScopes(access, { ...scoped, query: candidate }, scoped.allowedScopes);
    baseResult ||= result;
    resources.push(...(result.resources || []));
    if (resources.length >= scoped.limit * 2) break;
  }
  const deduped = Array.from(new Map(resources.map((resource) => [String(resource.uri || ''), resource])).values())
    .sort((left, right) => (
      Number(right.matchScore || 0) - Number(left.matchScore || 0)
      || String(right.modifiedAt || '').localeCompare(String(left.modifiedAt || ''))
    ))
    .slice(0, scoped.limit);
  return {
    ...(baseResult || { ok: true }),
    query: String(scoped.query || ''),
    resources: deduped,
    count: deduped.length,
  };
}

function annotateOutgoingTeamArchiveResult(result, sourceNodeId) {
  const catalog = teamKnowledgeCatalog();
  const resources = (result?.resources || []).map((resource) => annotateTeamKnowledgeResource(resource, catalog, {
    sourceNodeId,
    freshness: 'live',
  }));
  return { ...result, resources, count: resources.length };
}

async function handleRemoteArchiveQuery(request, response, pathname) {
  try {
    const bodyBuffer = await readRequestBuffer(request, 512 * 1024);
    const auth = authenticateDirectRequest(request, pathname, sha256DirectContent(bodyBuffer));
    const incoming = normalizeRemoteArchiveRequest(bodyBuffer.length ? JSON.parse(bodyBuffer.toString('utf8')) : {});
    if (incoming.bindingId && incoming.bindingId !== auth.binding.bindingId) throw new Error('远程知识请求与协作关系不匹配。');
    const scoped = resolveIncomingRemoteArchiveScope(incoming, auth);
    const rawResult = scoped.teamQuery
      ? invokeIncomingTeamArchive(currentArchiveAccess(), scoped)
      : invokeRelatedLocalArchive(currentArchiveAccess(), scoped);
    const result = scoped.teamQuery
      ? annotateOutgoingTeamArchiveResult(rawResult, auth.state.node.nodeId)
      : rawResult;
    const archiveResponse = normalizeRemoteArchiveResponse({
      sourceNodeId: auth.state.node.nodeId,
      requesterNodeId: auth.sourceNodeId,
      scope: { type: scoped.scopeType, id: incoming.scopeId, localId: scoped.localScopeId },
      queryType: scoped.queryType,
      freshness: 'live',
      result,
    }, incoming);
    appendHostTimeline({
      type: 'remote_archive_query',
      title: 'Remote archive query served',
      detail: `${auth.sourceNodeId}: ${scoped.scopeType}/${scoped.localScopeId} ${scoped.queryType}`,
    });
    sendJson(response, 200, { ok: true, schema: REMOTE_ARCHIVE_RESPONSE_SCHEMA, response: archiveResponse });
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `远程知识查询失败：${error.message}` });
  }
}

function resolveIncomingAgentKnowledgeScope(incoming = {}) {
  if (String(incoming.scopeType || 'student') !== 'team') {
    return resolveAgentKnowledgeStudentScope(incoming, readStudentsIndex().map(toHostStudent));
  }
  return { ...incoming, scopeType: 'team', scopeId: 'team', scopeName: '本机团队' };
}

async function handleAgentKnowledgeQuery(request, response) {
  try {
    if (!requireAuth(request, response)) return;
    if (request.authContext?.type === 'agent_grant' && !(request.authContext.capabilities || []).includes('knowledge:query')) {
      sendJson(response, 403, { ok: false, message: '当前 Agent 授权不包含知识查询能力。' });
      return;
    }
    const bodyBuffer = await readRequestBuffer(request, 512 * 1024);
    const incoming = bodyBuffer.length ? JSON.parse(bodyBuffer.toString('utf8')) : {};
    const scopedIncoming = resolveIncomingAgentKnowledgeScope(incoming);
    const query = normalizeAgentKnowledgeQuestion(scopedIncoming);
    if (query.scopeType === 'team' && request.authContext?.type !== 'admin') {
      sendJson(response, 403, { ok: false, message: '学生终端不能使用团队知识查询范围。' });
      return;
    }
    if (query.scopeType === 'student' && !isStudentAllowed(request, query.scopeId)) {
      sendJson(response, 403, { ok: false, message: '当前调用方没有访问该学生知识的权限。' });
      return;
    }
    const scopePlan = query.scopeType === 'student' && request.authContext?.type === 'agent_grant'
      ? agentKnowledgeScopePlan(request.authContext, query.scopeId, readProjects().map(normalizeProject))
      : null;
    if (scopePlan && !scopePlan.ok) { sendJson(response, 403, scopePlan); return; }
    if (query.scopeType === 'project' && request.authContext?.type !== 'admin') {
      const project = readProjects().map(normalizeProject).find((item) => String(item.id) === String(query.scopeId));
      if (!project || !projectAllowed(request, project) || (request.authContext?.type === 'agent_grant' && project.studentIds.map(String).filter(Boolean).length !== 1)) {
        sendJson(response, 403, { ok: false, message: '当前调用方没有访问该项目知识的权限。' });
        return;
      }
    }
    const result = parseJsonObject(await queryAgentKnowledge(JSON.stringify(scopedIncoming), scopePlan));
    sendJson(response, result.ok ? 200 : 202, result);
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `Agent 知识查询失败：${error.message}` });
  }
}

async function handleAgentConversationSubmission(request, response) {
  try {
    if (!requireAuth(request, response)) return;
    if (request.authContext?.type === 'agent_grant' && !(request.authContext.capabilities || []).includes('conversation:submit')) {
      sendJson(response, 403, { ok: false, message: '当前 Agent 授权不包含对话投递能力。' });
      return;
    }
    if (request.authContext?.type === 'agent_grant') { sendJson(response, 409, { ok: false, code: 'PREVIEW_REQUIRED', message: 'Agent 对话写入须先预览并由主机批准。' }); return; }
    const bodyBuffer = await readRequestBuffer(request, 5 * 1024 * 1024);
    const incoming = bodyBuffer.length ? JSON.parse(bodyBuffer.toString('utf8')) : {};
    const submission = normalizeAgentConversationSubmission(incoming);
    if (request.authContext?.type === 'agent_grant') {
      if (submission.targetNodeId) { sendJson(response, 403, { ok: false, code: 'CROSS_DEVICE_DENIED' }); return; }
      if (submission.targetProject) {
        const requested = String(submission.targetProject).trim().toLowerCase();
        const matches = readProjects().map(normalizeProject).filter((item) => String(item.id).toLowerCase() === requested || String(item.name || '').trim().toLowerCase() === requested);
        if (matches.length !== 1 || !projectAllowed(request, matches[0]) || matches[0].studentIds.map(String).filter(Boolean).length !== 1 || !matches[0].studentIds.map(String).includes(String(request.authContext.studentId))) {
          sendJson(response, 403, { ok: false, code: 'PROJECT_SCOPE_DENIED' }); return;
        }
      }
    }
    if (submission.scopeType === 'student' && !isStudentAllowed(request, submission.scopeId)) {
      sendJson(response, 403, { ok: false, message: '当前调用方不能向该学生档案投递对话。' });
      return;
    }
    if (submission.scopeType === 'project') {
      const project = readProjects().map(normalizeProject).find((item) => String(item.id) === String(submission.scopeId));
      if (!project || !projectAllowed(request, project) || (request.authContext?.type === 'agent_grant' && project.studentIds.map(String).filter(Boolean).length !== 1)) {
        sendJson(response, 403, { ok: false, message: '当前调用方不能向该学习项目投递对话。' });
        return;
      }
    }
    const result = parseJsonObject(await submitAgentConversation(JSON.stringify(submission)));
    appendHostTimeline({
      type: result.ok ? 'agent_conversation_submitted' : 'agent_conversation_submission_failed',
      title: result.ok ? 'Agent conversation submitted' : 'Agent conversation submission failed',
      detail: result.ok
        ? `${submission.sourceAgent}: ${submission.scopeType || 'unassigned'}/${submission.scopeId || 'pending'}; ${submission.messages.length} message(s)`
        : String(result.message || 'submission failed').slice(0, 500),
      studentId: submission.scopeType === 'student' ? submission.scopeId : '',
      projectId: submission.scopeType === 'project' ? submission.scopeId : '',
    });
    sendJson(response, result.ok ? 200 : 400, result);
  } catch (error) {
    sendJson(response, 400, { ok: false, message: `保存 Agent 对话失败：${error.message}` });
  }
}

const agentRequestRateAllowed = createAgentRateLimiter();

function agentCapabilityReceipt(name, input, result, outcome = '') {
  const scope = { studentId: input.studentId, projectId: input.projectId || '' };
  const source = `edu://student/${encodeURIComponent(input.studentId)}${input.projectId ? `/project/${encodeURIComponent(input.projectId)}` : ''}`;
  const evidence = (Array.isArray(result?.resources) ? result.resources : Array.isArray(result?.items) ? result.items : []).map((item) => String(item?.citation || item?.source || item?.uri || '')).filter((uri) => uri.startsWith('edu://')).slice(0, 20);
  return { ok: true, schema: CONTRACT_VERSION, capability: name, scope, source, evidence, freshness: name === 'knowledge.query' ? knowledgeCapabilityFreshness(result) : 'live', ...(outcome ? { outcome } : {}), at: new Date().toISOString(), result };
}

async function invokeAgentCapability(request, name, input) {
  const project = input?.projectId ? readProjects().map(normalizeProject).find((item) => String(item.id) === String(input.projectId)) : null;
  const authorization = authorizeCapability(request.authContext, name, input, project);
  if (!authorization.ok) return { ok: false, code: authorization.code };
  if (authorization.spec.risk !== 'read') return { ok: false, code: 'PREVIEW_REQUIRED' };
  const student = findStudent(input.studentId);
  if (!student) return { ok: false, code: 'STUDENT_NOT_FOUND' };
  let result;
  let outcome = '';
  if (name === 'knowledge.query') {
    const scopePlan = !input.projectId
      ? agentKnowledgeScopePlan(request.authContext, input.studentId, readProjects().map(normalizeProject))
      : null;
    if (scopePlan && !scopePlan.ok) return scopePlan;
    const queryInput = { scopeType: input.projectId ? 'project' : 'student', scopeId: input.projectId || input.studentId, question: input.question, limit: 8 };
    result = parseJsonObject(await queryAgentKnowledge(JSON.stringify(queryInput), scopePlan));
    const decision = knowledgeCapabilityDecision(result);
    if (!decision.ok) return { ok: false, code: decision.code, scope: { studentId: input.studentId, projectId: input.projectId || '' }, freshness: knowledgeCapabilityFreshness(result), result };
    outcome = decision.outcome;
  } else if (name === 'research.search') {
    const capability = planningGuidanceService().getResearchCapabilityStatus();
    return {
      ok: false,
      code: 'RESEARCH_CAPABILITY_UNAVAILABLE',
      scope: { studentId: input.studentId, projectId: '' },
      capability,
      message: capability.message,
    };
  } else if (name === 'archive.list') {
    const root = input.projectId ? project.knowledgeRootPath : (student.summaryPath || getSummaryDir(student.name));
    const files = [];
    if (root && fs.existsSync(root)) collectMarkdownFiles(root, root, files, 8);
    result = page(files.filter((file) => isPublicArchiveFile(file.path)).map(({ name: fileName, path: relativePath, modified }) => ({ name: fileName, path: relativePath, modifiedAt: new Date(modified).toISOString(), uri: `edu://student/${encodeURIComponent(input.studentId)}${input.projectId ? `/project/${encodeURIComponent(input.projectId)}` : ''}/archive/${encodeURIComponent(relativePath)}` })), input);
  } else if (name === 'task.status') {
    const allowedProjects = new Set(readProjects().map(normalizeProject).filter((item) => projectAllowed(request, item) && item.studentIds.map(String).filter(Boolean).length === 1 && item.studentIds.map(String).includes(input.studentId)).map((item) => String(item.id)));
    const tasks = readTaskStore().tasks.filter((task) => task.sourceType === 'student' && String(task.sourceId) === input.studentId && !input.projectId
      || task.sourceType === 'project' && allowedProjects.has(String(task.sourceId)) && (!input.projectId || String(task.sourceId) === input.projectId));
    result = page(tasks.map((task) => ({ id: task.id, title: task.title, kind: task.kind, status: task.status, riskLevel: task.riskLevel, updatedAt: task.updatedAt, sourceType: task.sourceType, sourceId: task.sourceId, uri: `edu://student/${encodeURIComponent(input.studentId)}/task/${encodeURIComponent(task.id)}` })), input);
  } else if (name === 'student.overview') {
    result = { id: String(student.id), name: student.name, linkedProjectIds: readProjects().map(normalizeProject).filter((item) => projectAllowed(request, item) && item.studentIds.map(String).includes(input.studentId)).map((item) => String(item.id)) };
  } else if (name === 'project.overview') {
    result = { id: String(project.id), name: project.name, status: project.status, studentId: input.studentId };
  } else if (name === 'report.list') {
    result = { reports: LEARNING_REPORTS.map((report) => ({ id: report.id, title: report.title, available: fs.existsSync(learningReportPathForStudent(student, report)) })) };
  } else if (name === 'report.read') {
    const report = LEARNING_REPORTS.find((item) => item.id === input.reportId);
    if (!report) return { ok: false, code: 'REPORT_NOT_FOUND' };
    const file = learningReportPathForStudent(student, report);
    if (!fs.existsSync(file)) return { ok: false, code: 'REPORT_NOT_FOUND' };
    const content = fs.readFileSync(file, 'utf8');
    const page = require('./agent-report-read.cjs').reportPage(content, input);
    if (!page.ok) return page;
    const { ok, ...reportContent } = page;
    result = { id: report.id, title: report.title, ...reportContent, uri: `edu://student/${encodeURIComponent(input.studentId)}/report/${encodeURIComponent(report.id)}` };
  }
  return agentCapabilityReceipt(name, input, result, outcome);
}

